export enum LabType {
  CHAT = 'chat',
  VISUAL = 'visual',
  MOTION = 'motion',
  VOICE = 'voice',
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
}

export interface GeneratedImage {
  id: string;
  url: string;
  prompt: string;
  timestamp: number;
}

export interface GeneratedVideo {
  id: string;
  url: string;
  prompt: string;
  timestamp: number;
}

import { GoogleGenAI, GenerateContentResponse, Modality } from "@google/genai";

export class GeminiService {
  private static getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  static async generateChatResponse(message: string, history: { role: string; parts: { text: string }[] }[]) {
    const ai = this.getAI();
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: 'You are Gemini OmniLab, a helpful and highly intelligent AI assistant designed to showcase the power of multimodal interaction.',
      },
    });

    // In a real app, we'd send history. For simplicity, we just send the message
    const response = await chat.sendMessage({ message });
    return response.text;
  }

  static async generateImage(prompt: string) {
    const ai = this.getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1",
        },
      },
    });

    for (const part of response.candidates?.[0]?.content.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data found in response");
  }

  static async generateVideo(prompt: string, onProgress?: (msg: string) => void) {
    const ai = this.getAI();
    onProgress?.("Initializing Veo video generation engine...");

    let operation = await ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt: prompt,
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: '16:9'
      }
    });

    onProgress?.("Dreaming up your video frames... This may take a moment.");

    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 5000));
      operation = await ai.operations.getVideosOperation({ operation });
      onProgress?.("Synthesizing motion vectors...");
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("Video generation failed");

    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }
}

// Audio Utilities for Live API
export function decodeBase64(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export function encodeBase64(bytes: Uint8Array): string {
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect } from 'react';
import { LabType } from './types';
import Sidebar from './components/Sidebar';
import ChatLab from './components/ChatLab';
import VisualLab from './components/VisualLab';
import MotionLab from './components/MotionLab';
import VoiceLab from './components/VoiceLab';

const App: React.FC = () => {
  const [activeLab, setActiveLab] = useState<LabType>(LabType.CHAT);

  const renderLab = () => {
    switch (activeLab) {
      case LabType.CHAT:
        return <ChatLab />;
      case LabType.VISUAL:
        return <VisualLab />;
      case LabType.MOTION:
        return <MotionLab />;
      case LabType.VOICE:
        return <VoiceLab />;
      default:
        return <ChatLab />;
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-950 text-slate-100 overflow-hidden">
      {/* Sidebar - Fixed on desktop, hidden/toggle on mobile potentially */}
      <Sidebar activeLab={activeLab} onLabChange={setActiveLab} />

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 glass flex items-center justify-between px-8 border-b border-white/5 z-10 shrink-0">
          <div className="flex items-center space-x-3">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-blue-600 to-purple-600 flex items-center justify-center shadow-lg shadow-blue-500/20">
              <span className="text-white font-bold text-xs">GO</span>
            </div>
            <h1 className="font-outfit font-semibold text-xl tracking-tight">
              Gemini <span className="text-blue-400">OmniLab</span>
            </h1>
          </div>
          <div className="flex items-center space-x-4 text-sm font-medium text-slate-400">
            <span className="hidden md:inline">Status: <span className="text-emerald-400">Operational</span></span>
            <div className="h-2 w-2 rounded-full bg-emerald-500 shadow-sm shadow-emerald-500/50"></div>
          </div>
        </header>

        <section className="flex-1 overflow-auto bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-slate-950">
          {renderLab()}
        </section>
      </main>
    </div>
  );
};

export default App;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: #f8fafc;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow: hidden; /* Prevent body scroll, handle scroll in panels */
}

/* Layout Containers */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
}

/* Ride Hailing Layout Utility */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
}

.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: white;
  border-top-left-radius: 2.5rem;
  border-top-right-radius: 2.5rem;
  box-shadow: 0 -10px 25px rgba(0, 0, 0, 0.1);
  max-height: 85vh;
  overflow-y: auto;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Responsive Overrides */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 2rem;
    left: 2rem;
    right: auto;
    width: 400px;
    border-radius: 2.5rem;
    max-height: calc(100vh - 10rem);
  }
}

@media (min-width: 1024px) {
  .rh-layout {
    flex-direction: row;
  }

  .rh-map-view {
    position: relative;
    flex: 1;
  }

  .rh-ui-panel {
    position: relative;
    bottom: auto;
    left: auto;
    right: auto;
    width: 420px;
    height: 100%;
    max-height: none;
    border-radius: 0;
    box-shadow: -5px 0 15px rgba(0,0,0,0.05);
    border-right: 1px solid #f1f5f9;
  }
}

/* Scrollbar Styling */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* UI Elements */
.bottom-sheet-grabber {
  width: 40px;
  height: 4px;
  background: #e2e8f0;
  border-radius: 2px;
  margin: 12px auto;
}

button:active {
  transform: scale(0.96);
  transition: transform 0.1s ease;
}

.glass-card {
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

/* Leaflet Map Customization */
.leaflet-container {
  font-family: 'Cairo', sans-serif;
  background: #f1f5f9;
  height: 100% !important;
  width: 100% !important;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
.animate-spin {
  animation: spin 1s linear infinite;
}

/* Mobile Optimizations */
@media (max-width: 768px) {
  input, select, textarea {
    font-size: 16px !important; /* Prevent iOS zoom */
  }
}

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, Link } from "react-router-dom";
import { User } from './types';
import Login from './Login';
import CustomerDashboard from './views/CustomerDashboard';
import CourierDashboard from './views/CourierDashboard';
import OperatorDashboard from './views/OperatorDashboard';
import SuperAdminDashboard from './views/SuperAdminDashboard';
import NotificationsView from './views/NotificationsView';
import SupportView from './views/SupportView';
import { LogOut, RefreshCcw, WifiOff, Loader2, Bell, HelpCircle, Clock } from 'lucide-react';
import { auth, db } from './firebase';
import { onAuthStateChanged, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, collection, query, where, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { stripFirestore } from './utils';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showSupport, setShowSupport] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    if ("Notification" in window && Notification.permission === "default") {
      Notification.requestPermission().catch(() => {});
    }

    const registerSW = async () => {
      if (!('serviceWorker' in navigator) || !window.isSecureContext) return;
      const hostname = window.location.hostname;
      const isCloudPreview = hostname.includes('usercontent.goog') || hostname.includes('webcontainer.io') || hostname.includes('stackblitz') || hostname.includes('github.dev') || hostname.includes('ai.studio');
      if (isCloudPreview) return;
      setTimeout(async () => {
        try {
          if (document.readyState !== 'complete') return;
          await navigator.serviceWorker.register('./firebase-messaging-sw.js', { scope: './' });
        } catch (err) {}
      }, 3000);
    };

    if (document.readyState === 'complete') registerSW();
    else window.addEventListener('load', registerSW);
  }, []);

  const fetchUserData = async (uid: string) => {
    try {
      setConnectionError(false);
      const userRef = doc(db, "users", uid);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        const data = userSnap.data();
        if (data && data.role) setUser(stripFirestore(data) as User);
        else setUser(null);
      } else setUser(null);
    } catch (error) {
      if (!navigator.onLine) setConnectionError(true);
      else setUser(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    const unsubscribeAuth = onAuthStateChanged(auth, async (fbUser) => {
      if (fbUser) await fetchUserData(fbUser.uid);
      else { setUser(null); setLoading(false); }
    });
    return () => { unsubscribeAuth(); clearInterval(timer); };
  }, []);

  useEffect(() => {
    if (!user) return;
    try {
      const q = query(collection(db, "notifications"), where("userId", "in", [user.id, "ALL", user.role]));
      return onSnapshot(q, (snapshot) => {
        const docs = snapshot.docs.map(d => stripFirestore(d.data()));
        const currentUnread = docs.filter((n: any) => !n.read).length;
        if (currentUnread > unreadCount) {
          try { new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {}); } catch (e) {}
        }
        setUnreadCount(currentUnread);
      });
    } catch (e) {}
  }, [user, unreadCount]);

  if (loading) return (
    <div className="min-h-screen bg-[#2D9469] flex flex-col items-center justify-center p-6 text-center">
      <div className="bg-white/20 p-10 rounded-[4rem] backdrop-blur-2xl mb-10 border border-white/30 shadow-2xl animate-pulse">
         <img src={APP_LOGO_ICON} alt="Loading..." className="h-28 w-28 object-contain" />
      </div>
      <h2 className="text-white font-black text-5xl tracking-tighter mb-8">وصلها أشمون</h2>
      <div className="flex items-center gap-4 bg-white/10 px-10 py-5 rounded-[2.5rem] backdrop-blur-md border border-white/20 shadow-xl">
        <Loader2 className="h-6 w-6 text-emerald-100 animate-spin" />
        <p className="text-emerald-100 font-black text-xs uppercase tracking-[0.3em]">تحميل بيانات المشوار...</p>
      </div>
    </div>
  );

  if (connectionError) return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center p-8 text-center">
      <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl border border-slate-100 max-w-md w-full">
        <WifiOff className="h-16 w-16 text-rose-500 mx-auto mb-8" />
        <h2 className="text-slate-800 font-black text-3xl mb-4">لا يوجد اتصال</h2>
        <button onClick={() => window.location.reload()} className="w-full bg-[#2D9469] text-white py-6 rounded-[2.5rem] font-black shadow-lg flex items-center justify-center gap-4 active:scale-95 transition-all">
          <RefreshCcw className="h-5 w-5" /> حاول مرة أخرى
        </button>
      </div>
    </div>
  );

  if (!user) return <Login onLogin={(u) => setUser(stripFirestore(u))} />;

  const getDashboard = () => {
    if (showNotifications) return <NotificationsView user={user} onBack={() => setShowNotifications(false)} />;
    if (showSupport) return <SupportView user={user} onBack={() => setShowSupport(false)} />;
    switch (user.role) {
      case 'ADMIN': return <SuperAdminDashboard user={user} />;
      case 'OPERATOR': return <OperatorDashboard user={user} />;
      case 'DRIVER': return <CourierDashboard user={user} />;
      case 'CUSTOMER': return <CustomerDashboard user={user} />;
      default: return <div className="p-12 text-center font-bold">دور غير معروف</div>;
    }
  };

  return (
    <HashRouter>
      <div className="app-container">
        {/* Compact Header for Dashboard View */}
        <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-[60] px-4 md:px-8 h-20 md:h-24 flex items-center shadow-sm">
          <div className="max-w-7xl mx-auto w-full flex items-center justify-between">
            <div className="flex items-center gap-3 md:gap-5">
              <Link to="/" onClick={() => { setShowNotifications(false); setShowSupport(false); }} className="flex items-center gap-3 md:gap-4 group">
                <div className="bg-[#2D9469] p-2 rounded-2xl shadow-lg transition-all">
                  <img src={APP_LOGO_ICON} alt="Logo" className="h-5 w-5 md:h-7 md:w-7 object-contain" />
                </div>
                <div className="hidden sm:block">
                  <h1 className="font-black text-lg md:text-xl text-slate-800 tracking-tighter leading-none">وصلها <span className="text-[#2D9469]">أشمون</span></h1>
                </div>
              </Link>
            </div>
            <div className="flex items-center gap-2 md:gap-3">
              <button onClick={() => setShowSupport(true)} className="p-2.5 md:p-3.5 bg-slate-50 text-slate-400 hover:text-[#2D9469] rounded-2xl border border-slate-100"><HelpCircle className="h-4 w-4 md:h-5 md:w-5" /></button>
              <button onClick={() => setShowNotifications(true)} className={`p-2.5 md:p-3.5 bg-slate-50 text-slate-400 hover:text-[#2D9469] rounded-2xl relative border border-slate-100 ${unreadCount > 0 ? 'animate-pulse ring-2 ring-emerald-500/20' : ''}`}>
                <Bell className={`h-4 w-4 md:h-5 md:w-5 ${unreadCount > 0 ? 'text-emerald-600' : ''}`} />
                {unreadCount > 0 && <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-4 h-4 rounded-full text-[8px] flex items-center justify-center border-2 border-white">{unreadCount}</span>}
              </button>
              <button onClick={() => signOut(auth)} className="p-2.5 md:p-3.5 bg-slate-50 text-slate-400 hover:text-rose-500 rounded-2xl border border-slate-100"><LogOut className="h-4 w-4 md:h-5 md:w-5 rotate-180" /></button>
            </div>
          </div>
        </header>

        <main className="main-content">
          <Routes>
            <Route path="/" element={getDashboard()} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

