          <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="رأيك يهمنا..." className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 text-slate-800 dark:text-white rounded-[2rem] p-6 font-bold text-sm outline-none focus:border-emerald-500 min-h-[100px]" />
