          <div className={`${iconBg} p-2.5 rounded-xl text-white shadow-md`}>{icon}</div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-900 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-800 z-[100] max-h-60 overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-3 border-b border-slate-50 dark:border-slate-800">
            <input autoFocus className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 text-slate-800 dark:text-white rounded-xl py-3 px-4 text-sm font-black outline-none" placeholder="ابحث..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-2">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-5 py-3 hover:bg-emerald-50 dark:hover:bg-emerald-900/30 rounded-xl flex justify-between items-center group transition-all">
                <span className="text-sm font-black text-slate-700 dark:text-slate-300">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-4 w-4 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'WALLET' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [orderNotes, setOrderNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [allVillages, setAllVillages] = useState<Village[]>(STATIC_VILLAGES);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) {
        const data = stripFirestore(snap.data());
        setLivePricing(data.pricing || DEFAULT_PRICING);
      }
    });
    onSnapshot(collection(db, "villages"), (snap) => {
      const dbVillages = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[];
      const merged = [...STATIC_VILLAGES];
      dbVillages.forEach(v => { if (!merged.some(sv => sv.id === v.id)) merged.push(v); });
      setAllVillages(merged);
    });
    const q = query(collection(db, "orders"), where("customerId", "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder && activeOrder.status === OrderStatus.WAITING_FOR_OFFERS) {
      const q = query(collection(db, "offers"), where("orderId", "==", activeOrder.id));
      return onSnapshot(q, (snapshot) => setIncomingOffers(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]));
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const base = livePricing.basePrice || 12;
      const perKm = livePricing.pricePerKm || 6;
      const min = livePricing.minPrice || 20;
      const price = Math.max(Math.round((base + (dist * perKm)) * mult), min);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        notes: orderNotes.trim()
      });
      setOrderNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ في قبول العرض.'); }
  };

  const handleCancelOrder = async () => {
    if (!activeOrder || !window.confirm('إلغاء المشوار؟')) return;
    try { await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED }); } catch (e) { }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  const categoryOptions: { id: OrderCategory, label: string, icon: React.ReactNode, color: string }[] = [
    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-5 w-5" />, color: 'emerald' },
    { id: 'FOOD', label: 'أكل', icon: <Coffee className="h-5 w-5" />, color: 'orange' },
    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-5 w-5" />, color: 'blue' }
  ];

  return (
    <div className="rh-layout transition-colors duration-300">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {activeOrder && activeOrder.status === OrderStatus.DELIVERED && (
        <RatingModal order={activeOrder} onClose={() => setActiveOrder(null)} />
      )}

      {/* Background Map Layer */}
      <div className="rh-map-view bg-slate-100 flex items-center justify-center">
        <div className="text-center opacity-40">
           <MapPin className="h-16 w-16 mx-auto mb-4 text-emerald-600 animate-bounce" />
           <p className="font-black text-slate-500 uppercase tracking-[0.4em]">Ashmoun Map Active</p>
        </div>
      </div>

      {/* Navigation Controls & Panels */}
      <div className="rh-ui-panel no-scrollbar">
        {/* Grabber for Mobile UI feel */}
        <div className="lg:hidden bottom-sheet-grabber"></div>

        <div className="p-6 md:p-8 space-y-8">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between mb-2">
                 <h2 className="text-2xl font-black text-slate-800 dark:text-white">اطلب مشوارك</h2>
                 <button onClick={() => setAiOpen(true)} className="p-3 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 rounded-2xl shadow-sm"><Bot className="h-6 w-6" /></button>
              </div>

              <div className="space-y-6">
                <div className="grid grid-cols-3 gap-2 md:gap-3">
                  {categoryOptions.map(cat => (
                    <button 
                       key={cat.id} 
                       onClick={() => setSelectedCategory(cat.id)}
                       className={`py-4 md:py-6 rounded-2xl flex flex-col items-center gap-2 border-2 transition-all ${
                         selectedCategory === cat.id 
                           ? `bg-${cat.color}-50 dark:bg-${cat.color}-900/20 border-${cat.color}-500 text-${cat.color}-600 shadow-md` 
                           : 'bg-slate-50 dark:bg-slate-800 border-transparent text-slate-300 dark:text-slate-600'
                       }`}
                    >
                       {cat.icon}
                       <span className="text-[10px] md:text-[11px] font-black">{cat.label}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-4">
                  <VillageInput label="منين؟" selectedVillage={pickupVillage} onSelect={setPickupVillage} icon={<MapPin className="h-4 w-4" />} iconBg="bg-emerald-500" placeholder="موقع الاستلام" availableVillages={allVillages} />
                  <VillageInput label="رايح فين؟" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} icon={<Check className="h-4 w-4" />} iconBg="bg-rose-500" placeholder="الوجهة" availableVillages={allVillages} />
                </div>

                <div className="grid grid-cols-3 gap-2">
                  {['TOKTOK', 'MOTORCYCLE', 'CAR'].map(v => (
                    <button key={v} onClick={() => setSelectedVehicle(v as VehicleType)} className={`py-4 rounded-2xl flex flex-col items-center gap-1 border-2 transition-all ${selectedVehicle === v ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-500 text-emerald-600 shadow-md' : 'bg-slate-50 dark:bg-slate-800 border-transparent text-slate-300 dark:text-slate-600'}`}>
                      {v === 'CAR' ? <Car className="h-5 w-5" /> : v === 'MOTORCYCLE' ? <Bike className="h-5 w-5" /> : <Zap className="h-5 w-5" />}
                      <span className="text-[9px] font-black uppercase">{v}</span>
                    </button>
                  ))}
                </div>

                <div className="relative">
                  <StickyNote className="absolute right-4 top-4 h-5 w-5 text-slate-300" />
                  <textarea 
                    value={orderNotes}
                    onChange={e => setOrderNotes(e.target.value)}
                    placeholder="ملاحظات للكابتن..."
                    className="w-full bg-slate-50 dark:bg-slate-800 text-slate-800 dark:text-white border-none rounded-2xl py-4 pr-12 pl-4 font-bold text-sm outline-none focus:ring-2 focus:ring-emerald-500 min-h-[80px]"
                  />
                </div>

                {tripStats && (
                  <div className="bg-slate-900 dark:bg-slate-800 text-white p-6 rounded-3xl flex justify-between items-center">
                    <div className="text-right">
                       <p className="text-[10px] font-black opacity-40 uppercase tracking-widest">التكلفة التقريبية</p>
                       <p className="text-3xl font-black">{tripStats.price} <span className="text-sm font-bold opacity-40">ج.م</span></p>
                    </div>
                    <DollarSign className="h-10 w-10 text-emerald-400 opacity-20" />
                  </div>
                )}

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-[#2D9469] text-white py-5 md:py-6 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin mx-auto" /> : 'طلب الكابتن الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-8 text-center">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-8">
                   <div className="relative py-6">
                      <div className="absolute inset-0 flex items-center justify-center"><div className="w-24 h-24 bg-emerald-500/10 rounded-full animate-ping"></div></div>
                      <div className="bg-white dark:bg-slate-800 p-6 rounded-full shadow-2xl relative z-10 inline-block"><Bot className="h-12 w-12 text-emerald-600" /></div>
                   </div>
                   <h2 className="text-xl font-black dark:text-white">جاري البحث عن كابتن...</h2>

                   <div className="space-y-4">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-slate-50 dark:bg-slate-800 p-5 rounded-2xl flex justify-between items-center border border-transparent hover:border-emerald-500 transition-all shadow-sm">
                           <div className="flex items-center gap-3">
                              <div className="w-10 h-10 bg-white dark:bg-slate-700 rounded-xl flex items-center justify-center font-black">{(offer.driverName || 'ك')[0]}</div>
                              <div className="text-right">
                                 <p className="font-black text-slate-800 dark:text-white text-sm">{offer.driverName}</p>
                                 <div className="flex items-center gap-1 text-amber-500 text-[9px] font-black"><Star className="h-3 w-3 fill-amber-400" /> {offer.driverRating}</div>
                              </div>
                           </div>
                           <div className="flex items-center gap-3">
                              <p className="text-lg font-black text-emerald-700">{offer.price} ج.م</p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-[#2D9469] text-white px-5 py-2 rounded-xl font-black text-xs shadow-md">قبول</button>
                           </div>
                        </div>
                      ))}
                      {incomingOffers.length === 0 && <p className="text-xs font-bold text-slate-400">بانتظار عروض الأسعار من الكباتن المتاحين</p>}
                   </div>
                   <button onClick={handleCancelOrder} className="text-rose-500 font-black text-xs uppercase tracking-widest">إلغاء الطلب</button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-8">
                   <div className="bg-emerald-600 p-6 rounded-3xl text-white flex justify-between items-center shadow-lg">
                      <div className="text-right">
                         <p className="text-[9px] font-black opacity-60 uppercase mb-1">حالة المشوار</p>
                         <h3 className="text-lg font-black">{activeOrder.status === OrderStatus.ACCEPTED ? 'الكابتن قادم إليك' : 'أنت في الطريق الآن'}</h3>
                      </div>
                      <Navigation2 className="h-8 w-8 animate-bounce" />
                   </div>

                   <div className="flex flex-col items-center gap-4">
                      <div className="w-24 h-24 bg-slate-100 dark:bg-slate-800 rounded-3xl flex items-center justify-center border-4 border-white dark:border-slate-800 shadow-xl">
                         <UserIcon className="h-12 w-12 text-slate-300" />
                      </div>
                      <div className="text-center">
                         <h4 className="text-xl font-black text-slate-800 dark:text-white">{activeOrder.driverName}</h4>
                         <p className="text-xs font-bold text-slate-400 mt-1 uppercase">كابتن {activeOrder.requestedVehicleType} • أشمون</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-3">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 dark:bg-slate-800 text-white py-5 rounded-2xl font-black text-xs flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-all"><PhoneCall className="h-5 w-5" /> اتصال</a>
                      <button onClick={() => setShowChat(true)} className="bg-white dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-700 text-slate-900 dark:text-white py-5 rounded-2xl font-black text-xs flex items-center justify-center gap-3 active:scale-95 transition-all"><MessageCircle className="h-5 w-5" /> محادثة</button>
                   </div>

                   <div className="bg-slate-50 dark:bg-slate-800 p-6 rounded-[2.5rem] text-right space-y-4">
                      <div className="flex items-center gap-3">
                         <MapPin className="h-4 w-4 text-emerald-500" />
                         <p className="text-xs font-black text-slate-700 dark:text-slate-300">{activeOrder.pickup.villageName} ← {activeOrder.dropoff.villageName}</p>
                      </div>
                      <div className="flex justify-between items-center pt-4 border-t border-slate-200 dark:border-slate-700">
                         <p className="text-xs font-black text-slate-400">القيمة الإجمالية</p>
                         <p className="text-xl font-black text-emerald-700">{activeOrder.price} ج.م</p>
                      </div>
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Persistent Bottom Nav */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white dark:bg-slate-900 border-t border-slate-50 dark:border-slate-800 px-6 md:px-10 py-4 md:py-6 flex justify-around items-center z-[110] shadow-2xl">
         {[
           {id: 'NEW', icon: <History className="rotate-180" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History />, label: 'سجلي'},
           {id: 'WALLET', icon: <WalletIcon />, label: 'محفظتي'},
           {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeView === tab.id ? 'text-[#2D9469]' : 'text-slate-300 dark:text-slate-700'}`}>
              <div className={`p-2 md:p-3 rounded-xl ${activeView === tab.id ? 'bg-emerald-50 dark:bg-emerald-900/20' : ''}`}>{React.cloneElement(tab.icon as React.ReactElement<any>, { className: 'h-6 w-6' })}</div>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: #f8fafc;
  -webkit-font-smoothing: antialiased;
  color: #0f172a; /* Slate-900 for better text visibility */
  overflow: hidden;
}

/* Base Layout Containers */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* Ride Hailing Layout Utility */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
}

/* Full screen map behind UI */
.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #f1f5f9;
}

/* Floating UI Panel (Bottom Sheet on Mobile) */
.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: white;
  border-top-left-radius: 2.5rem;
  border-top-right-radius: 2.5rem;
  box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.15);
  max-height: 85vh;
  overflow-y: auto;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  padding-bottom: 5rem; /* Space for bottom nav */
}

/* Grabber for Mobile UI */
.bottom-sheet-grabber {
  width: 48px;
  height: 6px;
  background: #cbd5e1; /* slate-300 */
  border-radius: 3px;
  margin: 16px auto;
}

/* Responsive Overrides - Tablet */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 6rem;
    left: 2rem;
    right: auto;
    width: 400px;
    border-radius: 2.5rem;
    max-height: calc(100vh - 12rem);
  }
}

/* Responsive Overrides - Desktop */
@media (min-width: 1024px) {
  .rh-layout {
    flex-direction: row-reverse; /* Panel on Right, Map on Left */
  }

  .rh-map-view {
    position: relative;
    flex: 1;
    z-index: 0;
  }

  .rh-ui-panel {
    position: relative;
    bottom: auto;
    left: auto;
    right: auto;
    width: 35%; /* Exact spec: 35% Panel */
    height: 100%;
    max-height: none;
    border-radius: 0;
    box-shadow: -5px 0 25px rgba(0,0,0,0.05);
    border-left: 1px solid #e2e8f0;
    padding-bottom: 2rem;
  }

  .bottom-sheet-grabber {
    display: none;
  }
}

/* Scrollbar Handling */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Typography Enhancements */
.label-strong {
  font-weight: 700;
  color: #1e293b; /* slate-800 */
  font-size: 0.95rem;
}

.helper-text {
  font-weight: 500;
  color: #64748b; /* slate-500 */
  font-size: 0.75rem;
}

/* Button & Interaction Sizing */
button {
  min-height: 48px; /* Minimum for accessibility */
}

.icon-large {
  width: 24px;
  height: 24px;
  stroke-width: 2.5px;
}

/* Map Overlays */
.map-placeholder-text {
  font-weight: 900;
  letter-spacing: 0.1em;
  color: #2D9469;
}

import React, { useState, useEffect } from 'react';
import { User, Order, OrderStatus, Village, VehicleType, Offer, OrderCategory } from '../types';
import { ASHMOUN_VILLAGES as STATIC_VILLAGES, DEFAULT_PRICING } from '../constants';
import { stripFirestore, calculateDistance } from '../utils';
import { 
  MapPin, Bike, Check, 
  ChevronDown, DollarSign, Star,
  User as UserIcon, Wallet as WalletIcon,
  Car, MessageCircle, Loader2,
  X, Bot, Heart, 
  Clock, XCircle, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall
} from 'lucide-react';
import { db } from '../firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc, setDoc, getDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import WalletView from './WalletView';
import ProfileView from './ProfileView';
import AIAssistant from './AIAssistant';
import ActivityView from './ActivityView';
import ChatView from './ChatView';

const RatingModal: React.FC<{ order: Order, onClose: () => void }> = ({ order, onClose }) => {
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmitRating = async () => {
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", order.id), {
        rating, feedback, status: OrderStatus.DELIVERED_RATED, ratedAt: Date.now()
      });
      onClose();
    } catch (e) { alert('فشل حفظ التقييم'); } finally { setIsSubmitting(false); }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[20000] flex items-center justify-center p-6 animate-in fade-in">
      <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-[3rem] overflow-hidden shadow-2xl animate-in zoom-in border border-transparent">
        <div className="bg-[#2D9469] p-10 text-center text-white">
          <Heart className="h-16 w-16 fill-white mx-auto mb-4" />
          <h3 className="text-3xl font-black mb-2">وصلنا بالسلامة!</h3>
          <p className="text-sm font-bold text-emerald-50">كيف كانت رحلتك مع الكابتن {order.driverName}؟</p>
        </div>
        <div className="p-8 space-y-6">
          <div className="flex justify-center gap-2">
            {[1, 2, 3, 4, 5].map(star => (
              <button key={star} onClick={() => setRating(star)} className="focus:outline-none transition-transform active:scale-90 p-1">
                <Star className={`h-12 w-12 ${star <= rating ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} />
              </button>
            ))}
          </div>
          <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="رأيك يهمنا..." className="w-full bg-slate-50 border border-slate-200 rounded-[1.5rem] p-6 font-bold text-sm outline-none focus:border-emerald-500 min-h-[100px]" />
          <button onClick={handleSubmitRating} disabled={isSubmitting} className="w-full bg-[#2D9469] text-white py-6 rounded-2xl font-black text-lg active:scale-95 transition-all shadow-xl flex items-center justify-center gap-3">
            {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin" /> : 'إرسال التقييم'}
          </button>
        </div>
      </div>
    </div>
  );
};

const VillageInput: React.FC<{
  label: string; selectedVillage: Village | null; onSelect: (v: Village) => void;
  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-2">
      <div className="flex flex-col px-1">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-2xl flex items-center justify-between cursor-pointer hover:border-emerald-100 transition-all shadow-sm">
        <ChevronDown className={`h-6 w-6 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-4">
          <span className={`text-lg font-bold ${selectedVillage ? 'text-slate-900' : 'text-slate-400'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-3 rounded-xl text-white shadow-md`}>
            {React.cloneElement(icon as React.ReactElement, { className: "icon-large" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[2rem] shadow-2xl border border-slate-100 z-[100] max-h-60 overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-3 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border border-slate-200 rounded-xl py-4 px-4 text-base font-bold outline-none" placeholder="ابحث..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-2">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-5 py-4 hover:bg-emerald-50 rounded-xl flex justify-between items-center group transition-all">
                <span className="text-base font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'WALLET' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [orderNotes, setOrderNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [allVillages, setAllVillages] = useState<Village[]>(STATIC_VILLAGES);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) {
        const data = stripFirestore(snap.data());
        setLivePricing(data.pricing || DEFAULT_PRICING);
      }
    });
    onSnapshot(collection(db, "villages"), (snap) => {
      const dbVillages = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[];
      const merged = [...STATIC_VILLAGES];
      dbVillages.forEach(v => { if (!merged.some(sv => sv.id === v.id)) merged.push(v); });
      setAllVillages(merged);
    });
    const q = query(collection(db, "orders"), where("customerId", "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder && activeOrder.status === OrderStatus.WAITING_FOR_OFFERS) {
      const q = query(collection(db, "offers"), where("orderId", "==", activeOrder.id));
      return onSnapshot(q, (snapshot) => setIncomingOffers(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]));
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const base = livePricing.basePrice || 12;
      const perKm = livePricing.pricePerKm || 6;
      const min = livePricing.minPrice || 20;
      const price = Math.max(Math.round((base + (dist * perKm)) * mult), min);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        notes: orderNotes.trim(), paymentMethod: 'CASH'
      });
      setOrderNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ في قبول العرض.'); }
  };

  const handleCancelOrder = async () => {
    if (!activeOrder || !window.confirm('إلغاء المشوار؟')) return;
    try { await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED }); } catch (e) { }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  const categoryOptions: { id: OrderCategory, label: string, icon: React.ReactNode, color: string }[] = [
    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-6 w-6" />, color: 'emerald' },
    { id: 'FOOD', label: 'أكل', icon: <Coffee className="h-6 w-6" />, color: 'orange' },
    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-6 w-6" />, color: 'blue' }
  ];

  return (
    <div className="rh-layout">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {activeOrder && activeOrder.status === OrderStatus.DELIVERED && (
        <RatingModal order={activeOrder} onClose={() => setActiveOrder(null)} />
      )}

      {/* Map Background Layer */}
      <div className="rh-map-view flex items-center justify-center">
        <div className="text-center opacity-30 select-none">
           <MapPin className="h-20 w-20 mx-auto mb-4 text-[#2D9469] animate-bounce" />
           <p className="map-placeholder-text uppercase tracking-[0.5em] text-lg">خريطة أشمون النشطة</p>
        </div>
      </div>

      {/* Persistent UI Layer */}
      <div className="rh-ui-panel no-scrollbar">
        <div className="bottom-sheet-grabber"></div>

        <div className="p-6 md:p-8 space-y-8">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between mb-4">
                 <h2 className="text-2xl font-black text-slate-900">إلى أين نذهب اليوم؟</h2>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl shadow-sm active:scale-95 transition-all">
                    <Bot className="h-8 w-8" />
                 </button>
              </div>

              <div className="space-y-8">
                {/* Order Category */}
                <div className="grid grid-cols-3 gap-3">
                  {categoryOptions.map(cat => (
                    <button 
                       key={cat.id} 
                       onClick={() => setSelectedCategory(cat.id)}
                       className={`py-6 rounded-2xl flex flex-col items-center gap-2 border-2 transition-all ${
                         selectedCategory === cat.id 
                           ? `bg-${cat.color}-50 border-${cat.color}-500 text-${cat.color}-600 shadow-lg` 
                           : 'bg-slate-50 border-transparent text-slate-400'
                       }`}
                    >
                       {React.cloneElement(cat.icon as React.ReactElement, { className: "h-7 w-7" })}
                       <span className="text-xs font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
                </div>

                {/* Location Inputs */}
                <div className="space-y-6">
                  <VillageInput 
                    label="نقطة الانطلاق" 
                    helper="أين سيتسلمك الكابتن؟"
                    selectedVillage={pickupVillage} 
                    onSelect={setPickupVillage} 
                    icon={<MapPin />} 
                    iconBg="bg-emerald-500" 
                    placeholder="اختر موقعك الحالي" 
                    availableVillages={allVillages} 
                  />
                  <VillageInput 
                    label="نقطة الوصول" 
                    helper="إلى أين نذهب؟"
                    selectedVillage={dropoffVillage} 
                    onSelect={setDropoffVillage} 
                    icon={<Check />} 
                    iconBg="bg-rose-500" 
                    placeholder="اختر وجهتك النهائية" 
                    availableVillages={allVillages} 
                  />
                </div>

                {/* Vehicle Selection */}
                <div className="space-y-3">
                  <div className="flex flex-col px-1">
                    <label className="label-strong">وسيلة النقل</label>
                    <span className="helper-text">اختر ما يناسب مشوارك</span>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    {[
                      { id: 'TOKTOK', icon: <Zap /> },
                      { id: 'MOTORCYCLE', icon: <Bike /> },
                      { id: 'CAR', icon: <Car /> }
                    ].map(v => (
                      <button 
                        key={v.id} 
                        onClick={() => setSelectedVehicle(v.id as VehicleType)} 
                        className={`py-5 rounded-2xl flex flex-col items-center gap-2 border-2 transition-all ${
                          selectedVehicle === v.id 
                            ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-lg' 
                            : 'bg-slate-50 border-transparent text-slate-400'
                        }`}
                      >
                        {React.cloneElement(v.icon as React.ReactElement, { className: "h-7 w-7" })}
                        <span className="text-[10px] font-black uppercase tracking-widest">{v.id}</span>
                      </button>
                    ))}
                  </div>
                </div>

                {/* Notes */}
                <div className="relative">
                  <StickyNote className="absolute right-4 top-4 h-6 w-6 text-slate-300" />
                  <textarea 
                    value={orderNotes}
                    onChange={e => setOrderNotes(e.target.value)}
                    placeholder="ملاحظات إضافية للكابتن..."
                    className="w-full bg-slate-50 text-slate-900 border-none rounded-2xl py-5 pr-14 pl-6 font-bold text-base outline-none focus:ring-4 focus:ring-emerald-500/10 min-h-[100px] shadow-inner"
                  />
                </div>

                {/* Pricing Summary */}
                {tripStats && (
                  <div className="bg-slate-900 text-white p-6 rounded-3xl flex justify-between items-center shadow-2xl">
                    <div className="text-right">
                       <p className="text-[11px] font-black text-emerald-400 uppercase tracking-widest mb-1">السعر التقريبي للمشوار</p>
                       <p className="text-4xl font-black">{tripStats.price} <span className="text-base font-bold opacity-40">ج.م</span></p>
                    </div>
                    <div className="bg-white/10 p-4 rounded-2xl">
                      <DollarSign className="h-8 w-8 text-emerald-400" />
                    </div>
                  </div>
                )}

                {/* Action Button */}
                <button 
                  onClick={handleCreateOrder} 
                  disabled={isSubmitting || !pickupVillage || !dropoffVillage} 
                  className="w-full bg-[#2D9469] text-white py-6 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all disabled:opacity-30 disabled:grayscale"
                >
                   {isSubmitting ? <Loader2 className="h-8 w-8 animate-spin mx-auto" /> : 'اطلب الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-10 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-8 text-center">
                   <div className="relative py-10">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-32 h-32 bg-emerald-500/20 rounded-full animate-ping"></div>
                      </div>
                      <div className="bg-white p-8 rounded-full shadow-2xl relative z-10 inline-block">
                        <Bot className="h-16 w-16 text-emerald-600" />
                      </div>
                   </div>
                   <div className="space-y-2">
                      <h2 className="text-2xl font-black text-slate-900">جاري التواصل مع الكباتن...</h2>
                      <p className="helper-text text-base">سوف تظهر العروض المتاحة هنا فوراً</p>
                   </div>

                   <div className="space-y-4 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-6 rounded-3xl flex justify-between items-center border-2 border-slate-100 hover:border-emerald-500 transition-all shadow-md animate-in slide-in-from-bottom">
                           <div className="flex items-center gap-4">
                              <div className="w-14 h-14 bg-slate-900 text-emerald-400 rounded-2xl flex items-center justify-center font-black text-xl">
                                {(offer.driverName || 'ك')[0]}
                              </div>
                              <div className="text-right">
                                 <p className="font-black text-slate-900 text-lg">{offer.driverName}</p>
                                 <div className="flex items-center gap-1 text-amber-500 font-bold text-xs">
                                   <Star className="h-4 w-4 fill-amber-400" /> {offer.driverRating}
                                 </div>
                              </div>
                           </div>
                           <div className="text-center space-y-2">
                              <p className="text-2xl font-black text-emerald-700">{offer.price} <span className="text-[10px]">ج.م</span></p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-[#2D9469] text-white px-6 py-2 rounded-xl font-black text-xs shadow-lg active:scale-95 transition-all">قبول</button>
                           </div>
                        </div>
                      ))}
                      {incomingOffers.length === 0 && (
                        <div className="py-10 opacity-20 flex flex-col items-center gap-2">
                           <Loader2 className="h-10 w-10 animate-spin" />
                           <p className="font-black text-xs uppercase tracking-widest">انتظار العروض</p>
                        </div>
                      )}
                   </div>
                   <button onClick={handleCancelOrder} className="text-rose-500 font-black text-sm uppercase tracking-widest py-4">إلغاء الطلب</button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-8">
                   <div className="bg-emerald-600 p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl">
                      <div className="text-right">
                         <p className="text-xs font-black opacity-60 uppercase mb-2 tracking-widest">تحديث مباشر</p>
                         <h3 className="text-2xl font-black">
                           {activeOrder.status === OrderStatus.ACCEPTED ? 'الكابتن في طريقه إليك' : 'أنت في الطريق للوجهة'}
                         </h3>
                      </div>
                      <div className="bg-white/20 p-4 rounded-full">
                        <Navigation2 className="h-10 w-10 animate-bounce" />
                      </div>
                   </div>

                   <div className="flex flex-col items-center gap-4">
                      <div className="w-28 h-28 bg-slate-100 rounded-[2.5rem] flex items-center justify-center border-4 border-white shadow-2xl relative overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                      </div>
                      <div className="text-center">
                         <h4 className="text-2xl font-black text-slate-900">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-1 uppercase tracking-widest text-[#2D9469]">كابتن {activeOrder.requestedVehicleType} • أشمون</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-4">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-6 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all">
                        <PhoneCall className="h-6 w-6" /> اتصال
                      </a>
                      <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-6 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-sm active:scale-95 transition-all">
                        <MessageCircle className="h-6 w-6" /> محادثة
                      </button>
                   </div>

                   <div className="bg-slate-50 p-8 rounded-[3rem] text-right space-y-6 shadow-inner border border-slate-100">
                      <div className="flex items-start gap-4">
                         <div className="bg-emerald-500 p-2 rounded-lg text-white mt-1 shadow-sm"><MapPin className="h-4 w-4" /></div>
                         <div className="flex-1">
                            <p className="helper-text uppercase mb-1">مسار الرحلة</p>
                            <p className="text-lg font-black text-slate-800">{activeOrder.pickup.villageName} ← {activeOrder.dropoff.villageName}</p>
                         </div>
                      </div>
                      <div className="flex justify-between items-end pt-6 border-t border-slate-200">
                         <div>
                            <p className="helper-text uppercase mb-1">إجمالي الحساب</p>
                            <p className="text-3xl font-black text-emerald-700">{activeOrder.price} ج.م</p>
                         </div>
                         <div className="bg-white p-3 rounded-2xl border border-slate-100">
                            <WalletIcon className="h-6 w-6 text-slate-400" />
                         </div>
                      </div>
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Persistent Bottom Nav */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 px-8 py-6 flex justify-around items-center z-[110] shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
         {[
           {id: 'NEW', icon: <History className="rotate-180" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History />, label: 'سجلي'},
           {id: 'WALLET', icon: <WalletIcon />, label: 'محفظتي'},
           {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 transition-all ${activeView === tab.id ? 'text-[#2D9469] scale-110' : 'text-slate-300'}`}>
              <div className={`p-2.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50' : ''}`}>
                {React.cloneElement(tab.icon as React.ReactElement, { className: "h-7 w-7" })}
              </div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: #f8fafc;
  -webkit-font-smoothing: antialiased;
  color: #0f172a; /* Slate-900 for better text visibility */
  overflow: hidden;
}

/* Base Layout Containers */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* Ride Hailing Layout Utility */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
}

/* Full screen map behind UI */
.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #f1f5f9;
}

/* Floating UI Panel (Bottom Sheet on Mobile) */
.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: white;
  border-top-left-radius: 2.5rem;
  border-top-right-radius: 2.5rem;
  box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.15);
  max-height: 85vh;
  overflow-y: auto;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  padding-bottom: 5rem; /* Space for bottom nav */
}

/* Grabber for Mobile UI */
.bottom-sheet-grabber {
  width: 48px;
  height: 6px;
  background: #cbd5e1; /* slate-300 */
  border-radius: 3px;
  margin: 16px auto;
}

/* Responsive Overrides - Tablet */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 6rem;
    left: 2rem;
    right: auto;
    width: 400px;
    border-radius: 2.5rem;
    max-height: calc(100vh - 12rem);
  }
}

/* Responsive Overrides - Desktop */
@media (min-width: 1024px) {
  .rh-layout {
    flex-direction: row-reverse; /* Panel on Right, Map on Left */
  }

  .rh-map-view {
    position: relative;
    flex: 1;
    z-index: 0;
  }

  .rh-ui-panel {
    position: relative;
    bottom: auto;
    left: auto;
    right: auto;
    width: 35%; /* Exact spec: 35% Panel */
    height: 100%;
    max-height: none;
    border-radius: 0;
    box-shadow: -5px 0 25px rgba(0,0,0,0.05);
    border-left: 1px solid #e2e8f0;
    padding-bottom: 2rem;
  }

  .bottom-sheet-grabber {
    display: none;
  }
}

/* Scrollbar Handling */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Typography Enhancements */
.label-strong {
  font-weight: 700;
  color: #1e293b; /* slate-800 */
  font-size: 0.95rem;
}

.helper-text {
  font-weight: 500;
  color: #64748b; /* slate-500 */
  font-size: 0.75rem;
}

/* Button & Interaction Sizing */
button {
  min-height: 48px; /* Minimum for accessibility */
}

.icon-large {
  width: 24px;
  height: 24px;
  stroke-width: 2.5px;
}

/* Map Overlays */
.map-placeholder-text {
  font-weight: 900;
  letter-spacing: 0.1em;
  color: #2D9469;
}

/* Footer Styling */
.app-footer {
  width: 100%;
  text-align: center;
  padding: 2.5rem 0 1.5rem;
  font-size: 13px;
  font-weight: 600;
  color: #94a3b8; /* slate-400 */
  direction: rtl;
}

import React, { useState, useEffect } from 'react';
import { User, Order, OrderStatus, Village, VehicleType, Offer, OrderCategory } from '../types';
import { ASHMOUN_VILLAGES as STATIC_VILLAGES, DEFAULT_PRICING } from '../constants';
import { stripFirestore, calculateDistance } from '../utils';
import { 
  MapPin, Bike, Check, 
  ChevronDown, DollarSign, Star,
  User as UserIcon, Wallet as WalletIcon,
  Car, MessageCircle, Loader2,
  X, Bot, Heart, 
  Clock, XCircle, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall
} from 'lucide-react';
import { db } from '../firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc, setDoc, getDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import WalletView from './WalletView';
import ProfileView from './ProfileView';
import AIAssistant from './AIAssistant';
import ActivityView from './ActivityView';
import ChatView from './ChatView';

const RatingModal: React.FC<{ order: Order, onClose: () => void }> = ({ order, onClose }) => {
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmitRating = async () => {
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", order.id), {
        rating, feedback, status: OrderStatus.DELIVERED_RATED, ratedAt: Date.now()
      });
      onClose();
    } catch (e) { alert('فشل حفظ التقييم'); } finally { setIsSubmitting(false); }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[20000] flex items-center justify-center p-6 animate-in fade-in">
      <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-[3rem] overflow-hidden shadow-2xl animate-in zoom-in border border-transparent">
        <div className="bg-[#2D9469] p-10 text-center text-white">
          <Heart className="h-16 w-16 fill-white mx-auto mb-4" />
          <h3 className="text-3xl font-black mb-2">وصلنا بالسلامة!</h3>
          <p className="text-sm font-bold text-emerald-50">كيف كانت رحلتك مع الكابتن {order.driverName}؟</p>
        </div>
        <div className="p-8 space-y-6">
          <div className="flex justify-center gap-2">
            {[1, 2, 3, 4, 5].map(star => (
              <button key={star} onClick={() => setRating(star)} className="focus:outline-none transition-transform active:scale-90 p-1">
                <Star className={`h-12 w-12 ${star <= rating ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} />
              </button>
            ))}
          </div>
          <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="رأيك يهمنا..." className="w-full bg-slate-50 border border-slate-200 rounded-[1.5rem] p-6 font-bold text-sm outline-none focus:border-emerald-500 min-h-[100px]" />
          <button onClick={handleSubmitRating} disabled={isSubmitting} className="w-full bg-[#2D9469] text-white py-6 rounded-2xl font-black text-lg active:scale-95 transition-all shadow-xl flex items-center justify-center gap-3">
            {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin" /> : 'إرسال التقييم'}
          </button>
        </div>
      </div>
    </div>
  );
};

const VillageInput: React.FC<{
  label: string; selectedVillage: Village | null; onSelect: (v: Village) => void;
  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-2">
      <div className="flex flex-col px-1">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-2xl flex items-center justify-between cursor-pointer hover:border-emerald-100 transition-all shadow-sm">
        <ChevronDown className={`h-6 w-6 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-4">
          <span className={`text-lg font-bold ${selectedVillage ? 'text-slate-900' : 'text-slate-400'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-3 rounded-xl text-white shadow-md`}>
            {React.cloneElement(icon as React.ReactElement, { className: "icon-large" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[2rem] shadow-2xl border border-slate-100 z-[100] max-h-60 overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-3 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border border-slate-200 rounded-xl py-4 px-4 text-base font-bold outline-none" placeholder="ابحث..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-2">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-5 py-4 hover:bg-emerald-50 rounded-xl flex justify-between items-center group transition-all">
                <span className="text-base font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'WALLET' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [orderNotes, setOrderNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [allVillages, setAllVillages] = useState<Village[]>(STATIC_VILLAGES);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) {
        const data = stripFirestore(snap.data());
        setLivePricing(data.pricing || DEFAULT_PRICING);
      }
    });
    onSnapshot(collection(db, "villages"), (snap) => {
      const dbVillages = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[];
      const merged = [...STATIC_VILLAGES];
      dbVillages.forEach(v => { if (!merged.some(sv => sv.id === v.id)) merged.push(v); });
      setAllVillages(merged);
    });
    const q = query(collection(db, "orders"), where("customerId", "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder && activeOrder.status === OrderStatus.WAITING_FOR_OFFERS) {
      const q = query(collection(db, "offers"), where("orderId", "==", activeOrder.id));
      return onSnapshot(q, (snapshot) => setIncomingOffers(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]));
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const base = livePricing.basePrice || 12;
      const perKm = livePricing.pricePerKm || 6;
      const min = livePricing.minPrice || 20;
      const price = Math.max(Math.round((base + (dist * perKm)) * mult), min);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        notes: orderNotes.trim(), paymentMethod: 'CASH'
      });
      setOrderNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ في قبول العرض.'); }
  };

  const handleCancelOrder = async () => {
    if (!activeOrder || !window.confirm('إلغاء المشوار؟')) return;
    try { await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED }); } catch (e) { }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  const categoryOptions: { id: OrderCategory, label: string, icon: React.ReactNode, color: string }[] = [
    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-6 w-6" />, color: 'emerald' },
    { id: 'FOOD', label: 'أكل', icon: <Coffee className="h-6 w-6" />, color: 'orange' },
    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-6 w-6" />, color: 'blue' }
  ];

  return (
    <div className="rh-layout">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {activeOrder && activeOrder.status === OrderStatus.DELIVERED && (
        <RatingModal order={activeOrder} onClose={() => setActiveOrder(null)} />
      )}

      {/* Map Background Layer */}
      <div className="rh-map-view flex items-center justify-center">
        <div className="text-center opacity-30 select-none">
           <MapPin className="h-20 w-20 mx-auto mb-4 text-[#2D9469] animate-bounce" />
           <p className="map-placeholder-text uppercase tracking-[0.5em] text-lg">خريطة أشمون النشطة</p>
        </div>
      </div>

      {/* Persistent UI Layer */}
      <div className="rh-ui-panel no-scrollbar">
        <div className="bottom-sheet-grabber"></div>

        <div className="p-6 md:p-8 space-y-8">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between mb-4">
                 <h2 className="text-2xl font-black text-slate-900">إلى أين نذهب اليوم؟</h2>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl shadow-sm active:scale-95 transition-all">
                    <Bot className="h-8 w-8" />
                 </button>
              </div>

              <div className="space-y-8">
                {/* Order Category */}
                <div className="grid grid-cols-3 gap-3">
                  {categoryOptions.map(cat => (
                    <button 
                       key={cat.id} 
                       onClick={() => setSelectedCategory(cat.id)}
                       className={`py-6 rounded-2xl flex flex-col items-center gap-2 border-2 transition-all ${
                         selectedCategory === cat.id 
                           ? `bg-${cat.color}-50 border-${cat.color}-500 text-${cat.color}-600 shadow-lg` 
                           : 'bg-slate-50 border-transparent text-slate-400'
                       }`}
                    >
                       {React.cloneElement(cat.icon as React.ReactElement, { className: "h-7 w-7" })}
                       <span className="text-xs font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
                </div>

                {/* Location Inputs */}
                <div className="space-y-6">
                  <VillageInput 
                    label="نقطة الانطلاق" 
                    helper="أين سيتسلمك الكابتن؟"
                    selectedVillage={pickupVillage} 
                    onSelect={setPickupVillage} 
                    icon={<MapPin />} 
                    iconBg="bg-emerald-500" 
                    placeholder="اختر موقعك الحالي" 
                    availableVillages={allVillages} 
                  />
                  <VillageInput 
                    label="نقطة الوصول" 
                    helper="إلى أين نذهب؟"
                    selectedVillage={dropoffVillage} 
                    onSelect={setDropoffVillage} 
                    icon={<Check />} 
                    iconBg="bg-rose-500" 
                    placeholder="اختر وجهتك النهائية" 
                    availableVillages={allVillages} 
                  />
                </div>

                {/* Vehicle Selection */}
                <div className="space-y-3">
                  <div className="flex flex-col px-1">
                    <label className="label-strong">وسيلة النقل</label>
                    <span className="helper-text">اختر ما يناسب مشوارك</span>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    {[
                      { id: 'TOKTOK', icon: <Zap /> },
                      { id: 'MOTORCYCLE', icon: <Bike /> },
                      { id: 'CAR', icon: <Car /> }
                    ].map(v => (
                      <button 
                        key={v.id} 
                        onClick={() => setSelectedVehicle(v.id as VehicleType)} 
                        className={`py-5 rounded-2xl flex flex-col items-center gap-2 border-2 transition-all ${
                          selectedVehicle === v.id 
                            ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-lg' 
                            : 'bg-slate-50 border-transparent text-slate-400'
                        }`}
                      >
                        {React.cloneElement(v.icon as React.ReactElement, { className: "h-7 w-7" })}
                        <span className="text-[10px] font-black uppercase tracking-widest">{v.id}</span>
                      </button>
                    ))}
                  </div>
                </div>

                {/* Notes */}
                <div className="relative">
                  <StickyNote className="absolute right-4 top-4 h-6 w-6 text-slate-300" />
                  <textarea 
                    value={orderNotes}
                    onChange={e => setOrderNotes(e.target.value)}
                    placeholder="ملاحظات إضافية للكابتن..."
                    className="w-full bg-slate-50 text-slate-900 border-none rounded-2xl py-5 pr-14 pl-6 font-bold text-base outline-none focus:ring-4 focus:ring-emerald-500/10 min-h-[100px] shadow-inner"
                  />
                </div>

                {/* Pricing Summary */}
                {tripStats && (
                  <div className="bg-slate-900 text-white p-6 rounded-3xl flex justify-between items-center shadow-2xl">
                    <div className="text-right">
                       <p className="text-[11px] font-black text-emerald-400 uppercase tracking-widest mb-1">السعر التقريبي للمشوار</p>
                       <p className="text-4xl font-black">{tripStats.price} <span className="text-base font-bold opacity-40">ج.م</span></p>
                    </div>
                    <div className="bg-white/10 p-4 rounded-2xl">
                      <DollarSign className="h-8 w-8 text-emerald-400" />
                    </div>
                  </div>
                )}

                {/* Action Button */}
                <button 
                  onClick={handleCreateOrder} 
                  disabled={isSubmitting || !pickupVillage || !dropoffVillage} 
                  className="w-full bg-[#2D9469] text-white py-6 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all disabled:opacity-30 disabled:grayscale"
                >
                   {isSubmitting ? <Loader2 className="h-8 w-8 animate-spin mx-auto" /> : 'اطلب الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-10 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-8 text-center">
                   <div className="relative py-10">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-32 h-32 bg-emerald-500/20 rounded-full animate-ping"></div>
                      </div>
                      <div className="bg-white p-8 rounded-full shadow-2xl relative z-10 inline-block">
                        <Bot className="h-16 w-16 text-emerald-600" />
                      </div>
                   </div>
                   <div className="space-y-2">
                      <h2 className="text-2xl font-black text-slate-900">جاري التواصل مع الكباتن...</h2>
                      <p className="helper-text text-base">سوف تظهر العروض المتاحة هنا فوراً</p>
                   </div>

                   <div className="space-y-4 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-6 rounded-3xl flex justify-between items-center border-2 border-slate-100 hover:border-emerald-500 transition-all shadow-md animate-in slide-in-from-bottom">
                           <div className="flex items-center gap-4">
                              <div className="w-14 h-14 bg-slate-900 text-emerald-400 rounded-2xl flex items-center justify-center font-black text-xl">
                                {(offer.driverName || 'ك')[0]}
                              </div>
                              <div className="text-right">
                                 <p className="font-black text-slate-900 text-lg">{offer.driverName}</p>
                                 <div className="flex items-center gap-1 text-amber-500 font-bold text-xs">
                                   <Star className="h-4 w-4 fill-amber-400" /> {offer.driverRating}
                                 </div>
                              </div>
                           </div>
                           <div className="text-center space-y-2">
                              <p className="text-2xl font-black text-emerald-700">{offer.price} <span className="text-[10px]">ج.م</span></p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-[#2D9469] text-white px-6 py-2 rounded-xl font-black text-xs shadow-lg active:scale-95 transition-all">قبول</button>
                           </div>
                        </div>
                      ))}
                      {incomingOffers.length === 0 && (
                        <div className="py-10 opacity-20 flex flex-col items-center gap-2">
                           <Loader2 className="h-10 w-10 animate-spin" />
                           <p className="font-black text-xs uppercase tracking-widest">انتظار العروض</p>
                        </div>
                      )}
                   </div>
                   <button onClick={handleCancelOrder} className="text-rose-500 font-black text-sm uppercase tracking-widest py-4">إلغاء الطلب</button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-8">
                   <div className="bg-emerald-600 p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl">
                      <div className="text-right">
                         <p className="text-xs font-black opacity-60 uppercase mb-2 tracking-widest">تحديث مباشر</p>
                         <h3 className="text-2xl font-black">
                           {activeOrder.status === OrderStatus.ACCEPTED ? 'الكابتن في طريقه إليك' : 'أنت في الطريق للوجهة'}
                         </h3>
                      </div>
                      <div className="bg-white/20 p-4 rounded-full">
                        <Navigation2 className="h-10 w-10 animate-bounce" />
                      </div>
                   </div>

                   <div className="flex flex-col items-center gap-4">
                      <div className="w-28 h-28 bg-slate-100 rounded-[2.5rem] flex items-center justify-center border-4 border-white shadow-2xl relative overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                      </div>
                      <div className="text-center">
                         <h4 className="text-2xl font-black text-slate-900">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-1 uppercase tracking-widest text-[#2D9469]">كابتن {activeOrder.requestedVehicleType} • أشمون</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-4">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-6 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all">
                        <PhoneCall className="h-6 w-6" /> اتصال
                      </a>
                      <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-6 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-sm active:scale-95 transition-all">
                        <MessageCircle className="h-6 w-6" /> محادثة
                      </button>
                   </div>

                   <div className="bg-slate-50 p-8 rounded-[3rem] text-right space-y-6 shadow-inner border border-slate-100">
                      <div className="flex items-start gap-4">
