  return (
    <div className="rh-layout">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {activeOrder && activeOrder.status === OrderStatus.DELIVERED && (
        <RatingModal order={activeOrder} onClose={() => setActiveOrder(null)} />
      )}

      <div className="rh-map-view flex items-center justify-center">
        <div className="text-center opacity-30 select-none">
           <MapPin className="h-20 w-20 mx-auto mb-4 text-[#2D9469] animate-bounce" />
