          <h3 className="text-3xl font-black mb-2">وصلنا بالسلامة!</h3>
          <p className="text-sm font-bold text-emerald-50">كيف كانت رحلتك مع الكابتن {order.driverName}؟</p>
        </div>
        <div className="p-8 space-y-6">
          <div className="flex justify-center gap-2">
            {[1, 2, 3, 4, 5].map(star => (
              <button key={star} onClick={() => setRating(star)} className="focus:outline-none transition-transform active:scale-90 p-1">
                <Star className={`h-12 w-12 ${star <= rating ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} />
              </button>
            ))}
          </div>
          <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="رأيك يهمنا..." className="w-full bg-slate-50 border border-slate-200 rounded-[1.5rem] p-6 font-bold text-sm outline-none focus:border-emerald-500 min-h-[100px]" />
          <button onClick={handleSubmitRating} disabled={isSubmitting} className="w-full bg-[#2D9469] text-white py-6 rounded-2xl font-black text-lg active:scale-95 transition-all shadow-xl flex items-center justify-center gap-3">
            {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin" /> : 'إرسال التقييم'}
          </button>
        </div>
      </div>
    </div>
  );
};

