                    <div>
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">ملاحظات العميل</p>
                       <p className="text-xs font-bold text-slate-700 leading-relaxed">{activeOrder.notes}</p>
                    </div>
                 </div>
               )}
            </div>

            <div className="grid grid-cols-2 gap-3 pt-4">
               <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-900 text-white py-5 rounded-[2rem] font-black text-[10px] text-center flex items-center justify-center gap-2 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-4 w-4" /> اتصال</a>
               <button onClick={() => setShowChat(true)} className="bg-white border border-slate-100 text-slate-900 py-5 rounded-[2rem] font-black text-[10px] flex items-center justify-center gap-2 shadow-sm active:scale-95 transition-all relative">
