               </button>
               {activeOrder.status === OrderStatus.ACCEPTED ? (
                  <button onClick={() => updateOrderStatus(OrderStatus.PICKED_UP)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-5 rounded-[2rem] font-black text-xs shadow-xl active:scale-95 transition-all">
                    {isSubmitting ? <Loader2 className="h-5 w-5 animate-spin mx-auto" /> : 'تم استلام الطلب'}
                  </button>
               ) : (
                  <button onClick={() => updateOrderStatus(OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-5 rounded-[2rem] font-black text-xs shadow-xl active:scale-95 transition-all">
                    {isSubmitting ? <Loader2 className="h-5 w-5 animate-spin mx-auto" /> : 'تأكيد التوصيل والتحصيل'}
                  </button>
               )}
            </div>
         </div>
      ) : (
         <div className="space-y-4">
            <div className="flex items-center justify-between px-4">
               <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">مشاوير متاحة الآن ({availableOrders.length})</h3>
            </div>
            {availableOrders.map(o => (
               <div key={o.id} className="bg-white p-8 rounded-[3rem] border border-slate-50 shadow-sm space-y-6 animate-in slide-in-from-bottom">
                  <div className="flex justify-between items-start">
                     <div className="space-y-1">
                        <p className="text-lg font-black text-slate-800">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p>
                        <div className="flex items-center gap-2 mt-1">
                           {(() => {
                              const badge = getCategoryBadge(o.category);
                              return <span className={`bg-${badge.color}-100 text-${badge.color}-600 px-3 py-1 rounded-full text-[9px] font-black flex items-center gap-1`}>{badge.icon} {badge.label}</span>
                           })()}
                           <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">{o.requestedVehicleType}</span>
                        </div>
                     </div>
                     <div className="bg-slate-50 p-4 rounded-2xl shadow-inner">
                        {o.category === 'FOOD' ? <Coffee className="h-6 w-6 text-orange-500" /> : o.category === 'PHARMACY' ? <Pill className="h-6 w-6 text-blue-500" /> : <Bike className="h-6 w-6 text-emerald-500" />}
                     </div>
                  </div>

                  {o.notes && (
                    <div className="flex items-start gap-3 bg-amber-50/50 p-4 rounded-2xl border border-amber-100/50">
                       <StickyNote className="h-4 w-4 text-amber-500 shrink-0" />
                       <p className="text-xs font-bold text-slate-600 line-clamp-2">{o.notes}</p>
                    </div>
                  )}

                  {showOfferInput === o.id ? (
                     <div className="flex gap-2 animate-in zoom-in">
                        <input type="number" autoFocus value={offerPrice} onChange={e => setOfferPrice(Number(e.target.value))} className="flex-1 bg-slate-50 rounded-2xl p-5 font-black outline-none border-2 border-emerald-500 shadow-inner" placeholder="0" />
                        <button onClick={() => handleSendOffer(o)} disabled={isSubmitting} className="bg-emerald-600 text-white px-8 rounded-2xl font-black text-xs">إرسال</button>
                        <button onClick={() => setShowOfferInput(null)} className="p-5 bg-slate-100 rounded-2xl"><X className="h-5 w-5 text-slate-400" /></button>
                     </div>
                  ) : (
                     <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price); }} className="w-full bg-slate-900 text-white py-5 rounded-[1.8rem] font-black text-xs shadow-xl active:scale-95 transition-all">تقديم عرض سعر</button>
                  )}
               </div>
            ))}
            {availableOrders.length === 0 && (
               <div className="py-24 text-center text-slate-300 font-black border-2 border-dashed border-slate-100 rounded-[3.5rem] bg-white/50">
                  <Bot className="h-10 w-10 mx-auto mb-4 opacity-20" />
                  بانتظار طلبات جديدة من أشمون...
               </div>
            )}
         </div>
      )}

      {/* Subtle Global Footer */}
      <footer className="app-footer">
        © جميع الحقوق محفوظة – M.R Mahmoud Khalifa
      </footer>

      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-50 p-6 flex justify-around items-center z-[100] shadow-2xl">
         {[
           {id: 'HOME', icon: <Home />, label: 'الرئيسية'},
           {id: 'ACTIVITY', icon: <History />, label: 'سجلي'},
           {id: 'WALLET', icon: <Wallet />, label: 'محفظتي'},
           {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeView === tab.id ? 'text-emerald-600' : 'text-slate-300 hover:text-slate-400'}`}>
              <div className={`p-2 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 scale-110' : ''}`}>
                 {React.cloneElement(tab.icon as React.ReactElement<any>, { className: 'h-6 w-6' })}
              </div>
              <span className="text-[8px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

