  useEffect(() => {
    const fetchData = async () => {
      try {
        const custSnap = await getDoc(doc(db, "users", order.customerId));
        if (custSnap.exists()) setCustomer(stripFirestore(custSnap.data()) as User);

        if (order.driverId) {
          const drivSnap = await getDoc(doc(db, "users", order.driverId));
          if (drivSnap.exists()) setDriver(stripFirestore(drivSnap.data()) as User);
        }
      } catch (e) { 
        console.error("Error fetching order participants:", e); 
