            <p className="text-[10px] font-bold text-emerald-100 uppercase tracking-[0.3em] mt-2">
              ID: {order.id.slice(-8)} • {order.status}
            </p>
          </div>
        </div>

        <div className="p-8 space-y-8 overflow-y-auto flex-1 no-scrollbar bg-slate-50/50 dark:bg-slate-950/50">
          <div className="bg-white dark:bg-slate-900 p-8 rounded-[3.5rem] shadow-sm border border-slate-100 dark:border-slate-800 space-y-6">
