const UserEditModal: React.FC<{ 
  user: User; 
  onClose: () => void;
}> = ({ user, onClose }) => {
  const [formData, setFormData] = useState({
    name: user.name || '',
    phone: user.phone || '',
    role: user.role || 'CUSTOMER',
    status: user.status || 'APPROVED',
    vehicleType: user.vehicleType || 'TOKTOK',
    tempPassword: ''
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    if (!formData.name || !formData.phone) return alert('يرجى ملء البيانات الأساسية');
    setIsSaving(true);
    try {
      const updatePayload: any = { ...formData };
      if (!formData.tempPassword) delete updatePayload.tempPassword;
      await updateDoc(doc(db, "users", user.id), updatePayload);
      alert('تم تحديث بيانات المستخدم بنجاح');
      onClose();
    } catch (e) { alert('حدث خطأ أثناء الحفظ'); } finally { setIsSaving(false); }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl z-[10000] flex items-center justify-center p-4 animate-in fade-in">
      <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-[3.5rem] overflow-hidden shadow-2xl animate-in zoom-in border border-transparent dark:border-slate-800">
        <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
          <div className="flex items-center gap-4">
             <div className="w-12 h-12 bg-[#2D9469] rounded-2xl flex items-center justify-center text-xl font-black">
                {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover rounded-2xl" /> : (formData.name[0] || 'U')}
             </div>
             <div>
                <h3 className="font-black text-lg">تعديل حساب</h3>
                <p className="text-[10px] text-slate-400 uppercase tracking-widest">{user.id.slice(-8)}</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl hover:bg-white/20 transition-all"><X className="h-5 w-5" /></button>
        </div>

        <div className="p-8 space-y-6 max-h-[70vh] overflow-y-auto no-scrollbar">
          <div className="grid grid-cols-1 gap-4">
             <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">الاسم بالكامل</label>
                <input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-50 dark:bg-slate-800 dark:text-white border-2 border-transparent focus:border-emerald-500 p-5 rounded-2xl font-black text-sm outline-none" />
             </div>
             <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">رقم الهاتف</label>
                <input value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-slate-50 dark:bg-slate-800 dark:text-white border-2 border-transparent focus:border-emerald-500 p-5 rounded-2xl font-black text-sm outline-none text-left" dir="ltr" />
             </div>
             <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">نوع الحساب</label>
                   <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as any})} className="w-full bg-slate-50 dark:bg-slate-800 dark:text-white border-2 border-transparent focus:border-emerald-500 p-5 rounded-2xl font-black text-sm outline-none appearance-none">
                      <option value="CUSTOMER">عميل</option>
                      <option value="DRIVER">كابتن</option>
                      <option value="OPERATOR">مشغل</option>
                      <option value="ADMIN">أدمن</option>
                   </select>
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">حالة الحساب</label>
                   <select value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})} className="w-full bg-slate-50 dark:bg-slate-800 dark:text-white border-2 border-transparent focus:border-emerald-500 p-5 rounded-2xl font-black text-sm outline-none appearance-none">
                      <option value="APPROVED">نشط</option>
                      <option value="PENDING_APPROVAL">بانتظار تفعيل</option>
                      <option value="SUSPENDED">محظور</option>
                   </select>
                </div>
             </div>

             {formData.role === 'DRIVER' && (
               <div className="space-y-2 animate-in zoom-in">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">نوع المركبة</label>
                  <div className="grid grid-cols-3 gap-2">
                     {['TOKTOK', 'MOTORCYCLE', 'CAR'].map(type => (
                       <button key={type} onClick={() => setFormData({...formData, vehicleType: type as any})} className={`py-4 rounded-2xl font-black text-[10px] border-2 transition-all ${formData.vehicleType === type ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-800 dark:text-slate-500 border-transparent'}`}>
                          {type}
                       </button>
                     ))}
                  </div>
               </div>
             )}

             <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">كلمة مرور جديدة (اختياري)</label>
                <input type="text" value={formData.tempPassword} onChange={e => setFormData({...formData, tempPassword: e.target.value})} placeholder="اتركه فارغاً لعدم التغيير" className="w-full bg-slate-50 dark:bg-slate-800 dark:text-white border-2 border-transparent focus:border-emerald-500 p-5 rounded-2xl font-black text-sm outline-none" />
             </div>
          </div>
        </div>

        <div className="p-8 bg-slate-50 dark:bg-slate-950 flex gap-3">
           <button onClick={onClose} className="flex-1 py-5 rounded-2xl font-black text-sm text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all">إلغاء</button>
           <button onClick={handleSave} disabled={isSaving} className="flex-[2] bg-[#2D9469] text-white py-5 rounded-2xl font-black text-sm shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all">
              {isSaving ? <Loader2 className="h-5 w-5 animate-spin" /> : <><Save className="h-5 w-5" /> حفظ البيانات</>}
           </button>
        </div>
      </div>
    </div>
  );
};

// --- المكون الرئيسي للسوبر أدمن ---
const SuperAdminDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'STATS' | 'USERS' | 'VILLAGES' | 'PRICING' | 'NOTIFICATIONS'>('STATS');
  const [users, setUsers] = useState<User[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [villages, setVillages] = useState<Village[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [activeChatOrder, setActiveChatOrder] = useState<Order | null>(null);

  // Pricing State
  const [pricing, setPricing] = useState(DEFAULT_PRICING);
  const [isSavingPricing, setIsSavingPricing] = useState(false);

  // Village Form State
  const [newVillage, setNewVillage] = useState({ name: '', lat: 30.298, lng: 30.975 });
  const [isAddingVillage, setIsAddingVillage] = useState(false);

  // Notification State
  const [notifData, setNotifData] = useState({ title: '', body: '', target: 'ALL', type: 'INFO' });
  const [isSendingNotif, setIsSendingNotif] = useState(false);

  useEffect(() => {
    const unsubUsers = onSnapshot(collection(db, "users"), (snap) => {
      setUsers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]);
    });
    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("createdAt", "desc"), limit(200)), (snap) => {
      setOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubVillages = onSnapshot(collection(db, "villages"), (snap) => {
      setVillages(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[]);
    });
    const unsubPricing = onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) {
        const data = stripFirestore(snap.data());
        setPricing(data.pricing || DEFAULT_PRICING);
      }
    });

    return () => { unsubUsers(); unsubOrders(); unsubVillages(); unsubPricing(); };
  }, []);

  const handleUpdatePricing = async () => {
    setIsSavingPricing(true);
    try {
      await setDoc(doc(db, "settings", "pricing"), { pricing });
      alert('تم تحديث قائمة الأسعار بنجاح');
    } catch (e) { alert('فشل تحديث الأسعار'); } finally { setIsSavingPricing(false); }
  };

  const handleAddVillage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newVillage.name.trim()) return alert('أدخل اسم القرية');
    setIsAddingVillage(true);
    try {
      const villageId = `v_dyn_${Date.now()}`;
      await setDoc(doc(db, "villages", villageId), {
        id: villageId,
        name: newVillage.name.trim(),
        center: { lat: Number(newVillage.lat), lng: Number(newVillage.lng) }
      });
      setNewVillage({ name: '', lat: 30.298, lng: 30.975 });
      alert('تم إضافة القرية الجديدة للمنظومة');
    } catch (e) { alert('فشل إضافة القرية'); } finally { setIsAddingVillage(false); }
  };

  const handleDeleteVillage = async (vid: string) => {
    if (!window.confirm('هل أنت متأكد من حذف هذه القرية؟')) return;
    try {
      await deleteDoc(doc(db, "villages", vid));
    } catch (e) { alert('فشل الحذف'); }
  };

  const handleSendBroadcast = async () => {
    if (!notifData.title || !notifData.body) return alert('أكمل بيانات التنبيه');
    setIsSendingNotif(true);
    try {
      await addDoc(collection(db, "notifications"), {
        ...notifData,
        userId: notifData.target,
        createdAt: Date.now(),
        read: false
      });
      setNotifData({ ...notifData, title: '', body: '' });
      alert('تم إرسال التنبيه بنجاح');
    } catch (e) { alert('فشل الإرسال'); } finally { setIsSendingNotif(false); }
  };

  const filteredUsers = users.filter(u => 
    u.name?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    u.phone?.includes(searchTerm)
  );

  const allVillages = [...STATIC_VILLAGES, ...villages];

  return (
    <div className="max-w-6xl mx-auto space-y-10 pb-32 animate-in fade-in transition-colors duration-300">
      {selectedUser && <UserEditModal user={selectedUser} onClose={() => setSelectedUser(null)} />}

      {selectedOrder && (
        <OrderManagementModal 
          order={selectedOrder} 
          onClose={() => setSelectedOrder(null)} 
          onOpenChat={(o) => { setActiveChatOrder(o); setSelectedOrder(null); }} 
        />
      )}

      {activeChatOrder && (
        <ChatView user={user} order={activeChatOrder} onBack={() => setActiveChatOrder(null)} />
      )}

      {/* Navigation Header */}
      <div className="bg-white dark:bg-slate-900 p-4 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 flex gap-2 overflow-x-auto no-scrollbar sticky top-28 z-40 backdrop-blur-xl">
        {[
          { id: 'STATS', label: 'الرئيسية', icon: <LayoutDashboard className="h-4 w-4" /> },
          { id: 'USERS', label: 'المستخدمين', icon: <Users2 className="h-4 w-4" /> },
          { id: 'VILLAGES', label: 'القرى', icon: <MapPin className="h-4 w-4" /> },
          { id: 'PRICING', label: 'الأسعار', icon: <Calculator className="h-4 w-4" /> },
          { id: 'NOTIFICATIONS', label: 'التنبيهات', icon: <Megaphone className="h-4 w-4" /> },
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex items-center gap-3 px-8 py-5 rounded-[1.8rem] text-[11px] font-black transition-all relative whitespace-nowrap ${activeTab === tab.id ? 'bg-slate-900 dark:bg-white dark:text-slate-900 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {/* --- تابة القرى (Villages Management) --- */}
      {activeTab === 'VILLAGES' && (
        <div className="space-y-8 animate-in slide-in-from-left">
           <div className="bg-white dark:bg-slate-900 p-10 rounded-[4rem] border border-slate-100 dark:border-slate-800 shadow-sm space-y-8">
              <div className="flex items-center gap-4">
                 <div className="bg-emerald-50 dark:bg-emerald-900/20 p-4 rounded-3xl"><Plus className="h-8 w-8 text-emerald-500" /></div>
                 <div>
                    <h3 className="text-2xl font-black dark:text-white">إضافة قرية جديدة</h3>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">أضف نجوع أو عزب جديدة لتظهر في قائمة العملاء</p>
                 </div>
              </div>

              <form onSubmit={handleAddVillage} className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                 <div className="md:col-span-2 space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4">اسم القرية/العزبة</label>
                    <input value={newVillage.name} onChange={e => setNewVillage({...newVillage, name: e.target.value})} placeholder="مثال: عزبة الكوم" className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-3xl p-6 font-black text-sm outline-none border-2 border-transparent focus:border-emerald-500" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4">خط العرض (Lat)</label>
                    <input type="number" step="0.0001" value={newVillage.lat} onChange={e => setNewVillage({...newVillage, lat: Number(e.target.value)})} className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-3xl p-6 font-black text-sm outline-none" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4">خط الطول (Lng)</label>
                    <input type="number" step="0.0001" value={newVillage.lng} onChange={e => setNewVillage({...newVillage, lng: Number(e.target.value)})} className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-3xl p-6 font-black text-sm outline-none" />
                 </div>
                 <button type="submit" disabled={isAddingVillage} className="md:col-span-4 bg-emerald-600 text-white py-6 rounded-3xl font-black text-sm shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all">
                    {isAddingVillage ? <Loader2 className="h-5 w-5 animate-spin" /> : <><ShieldCheck className="h-5 w-5" /> حفظ في قاعدة البيانات</>}
                 </button>
              </form>
           </div>

           <div className="bg-white dark:bg-slate-900 p-10 rounded-[4rem] border border-slate-100 dark:border-slate-800 shadow-sm">
              <h3 className="text-xl font-black dark:text-white mb-8 flex items-center gap-3"><GripVertical className="text-slate-300" /> كافة مناطق أشمون المسجلة</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                 {allVillages.map(v => (
                   <div key={v.id} className="p-6 bg-slate-50 dark:bg-slate-950 rounded-[2.5rem] flex justify-between items-center group hover:bg-white dark:hover:bg-slate-900 transition-all border border-transparent hover:border-slate-100 dark:hover:border-slate-800">
                      <div className="flex items-center gap-4">
                         <div className="bg-white dark:bg-slate-800 p-3 rounded-2xl shadow-sm"><MapPin className="h-5 w-5 text-emerald-500" /></div>
                         <div>
                            <p className="font-black text-sm dark:text-white">{v.name}</p>
                            <p className="text-[9px] font-bold text-slate-400" dir="ltr">{v.center.lat.toFixed(3)}, {v.center.lng.toFixed(3)}</p>
                         </div>
                      </div>
                      {v.id.startsWith('v_dyn_') && (
                        <button onClick={() => handleDeleteVillage(v.id)} className="p-3 text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                           <Trash2 className="h-4 w-4" />
                        </button>
                      )}
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* --- تابة الأسعار (Pricing Tab) --- */}
      {activeTab === 'PRICING' && (
        <div className="space-y-8 animate-in slide-in-from-bottom">
           <div className="bg-white dark:bg-slate-900 p-10 rounded-[4rem] border border-slate-100 dark:border-slate-800 shadow-sm space-y-10">
              <div className="flex items-center gap-4">
                 <div className="bg-amber-50 dark:bg-amber-900/20 p-4 rounded-3xl"><Calculator className="h-8 w-8 text-amber-500" /></div>
                 <div>
                    <h3 className="text-2xl font-black dark:text-white">إعدادات التسعيرة</h3>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">تتحكم هذه القيم في حساب تكلفة المشوار للعميل</p>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">فتحة العداد (Base Price)</label>
                    <input type="number" value={pricing.basePrice} onChange={e => setPricing({...pricing, basePrice: Number(e.target.value)})} className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-3xl p-6 font-black text-xl outline-none focus:border-emerald-500 border-2 border-transparent transition-all" />
                 </div>
                 <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">سعر الكيلومتر</label>
                    <input type="number" value={pricing.pricePerKm} onChange={e => setPricing({...pricing, pricePerKm: Number(e.target.value)})} className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-3xl p-6 font-black text-xl outline-none focus:border-emerald-500 border-2 border-transparent transition-all" />
                 </div>
                 <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">الحد الأدنى للمشوار</label>
                    <input type="number" value={pricing.minPrice} onChange={e => setPricing({...pricing, minPrice: Number(e.target.value)})} className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-3xl p-6 font-black text-xl outline-none focus:border-emerald-500 border-2 border-transparent transition-all" />
                 </div>
              </div>

              <button onClick={handleUpdatePricing} disabled={isSavingPricing} className="w-full bg-[#2D9469] text-white py-8 rounded-[3rem] font-black text-xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
                 {isSavingPricing ? <Loader2 className="h-7 w-7 animate-spin" /> : <><Save className="h-7 w-7" /> حفظ وتعميم التسعيرة</>}
              </button>
           </div>
        </div>
      )}

      {/* --- تابة التنبيهات (Notifications Tab) --- */}
      {activeTab === 'NOTIFICATIONS' && (
        <div className="space-y-8 animate-in slide-in-from-right">
           <div className="bg-white dark:bg-slate-900 p-10 rounded-[4rem] border border-slate-100 dark:border-slate-800 shadow-sm space-y-10">
              <div className="flex items-center gap-4">
                 <div className="bg-rose-50 dark:bg-rose-900/20 p-4 rounded-3xl"><Megaphone className="h-8 w-8 text-rose-500" /></div>
                 <div>
                    <h3 className="text-2xl font-black dark:text-white">إرسال تنبيه جماعي</h3>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">بث رسالة فورية لمستخدمي التطبيق في أشمون</p>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">الفئة المستهدفة</label>
                    <select value={notifData.target} onChange={e => setNotifData({...notifData, target: e.target.value})} className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-3xl p-6 font-black text-sm outline-none appearance-none border-2 border-transparent focus:border-rose-500">
                       <option value="ALL">الجميع (All Users)</option>
                       <option value="DRIVER">الكباتن فقط</option>
                       <option value="CUSTOMER">العملاء فقط</option>
                    </select>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">نوع الرسالة</label>
                    <select value={notifData.type} onChange={e => setNotifData({...notifData, type: e.target.value})} className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-3xl p-6 font-black text-sm outline-none appearance-none border-2 border-transparent focus:border-rose-500">
                       <option value="INFO">معلومة (زرقاء)</option>
                       <option value="SUCCESS">نجاح (خضراء)</option>
                       <option value="WARNING">تحذير (برتقالية)</option>
                       <option value="ALERT">خطير/هام (حمراء)</option>
                    </select>
                 </div>
              </div>

              <div className="space-y-6">
                 <input value={notifData.title} onChange={e => setNotifData({...notifData, title: e.target.value})} placeholder="عنوان التنبيه..." className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-3xl p-6 font-black text-md outline-none border-2 border-transparent focus:border-rose-500" />
                 <textarea value={notifData.body} onChange={e => setNotifData({...notifData, body: e.target.value})} placeholder="نص الرسالة بالتفصيل..." className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-[2.5rem] p-8 font-black text-sm outline-none border-2 border-transparent focus:border-rose-500 min-h-[150px]" />
              </div>

              <button onClick={handleSendBroadcast} disabled={isSendingNotif} className="w-full bg-rose-600 text-white py-7 rounded-[3rem] font-black text-xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
                 {isSendingNotif ? <Loader2 className="h-7 w-7 animate-spin" /> : <><Send className="h-7 w-7" /> إرسال التنبيه الآن</>}
              </button>
           </div>
        </div>
      )}

      {/* --- تابة المستخدمين (Users Tab) --- */}
      {activeTab === 'USERS' && (
        <div className="space-y-8 animate-in slide-in-from-left">
           <div className="bg-white dark:bg-slate-900 p-8 rounded-[3.5rem] shadow-sm border border-slate-100 dark:border-slate-800">
              <div className="relative mb-8">
                 <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                 <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="بحث عن اسم أو رقم موبايل..." className="w-full bg-slate-50 dark:bg-slate-950 dark:text-white rounded-[2rem] py-6 pr-14 pl-6 font-black text-sm outline-none focus:border-emerald-500 border-2 border-transparent transition-all" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                 {filteredUsers.map(u => (
                   <div key={u.id} onClick={() => setSelectedUser(u)} className="p-6 bg-slate-50 dark:bg-slate-950 rounded-[2.5rem] cursor-pointer flex justify-between items-center group hover:border-emerald-500 border-2 border-transparent transition-all shadow-sm">
