export type VehicleType = 'TOKTOK' | 'MOTORCYCLE' | 'CAR';
export type OrderCategory = 'TAXI' | 'FOOD' | 'PHARMACY' | 'GROCERY' | 'PARCEL';

export enum OrderStatus {
  PENDING = 'PENDING',
  WAITING_FOR_OFFERS = 'WAITING_FOR_OFFERS',
  ACCEPTED = 'ACCEPTED',
  PICKED_UP = 'PICKED_UP',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  DELIVERED_RATED = 'DELIVERED_RATED',
  CANCELLED = 'CANCELLED'
}

export interface Offer {
  id: string;
  orderId: string;
  driverId: string;
  driverName: string;
  driverPhone: string;
  driverRating: number;
  driverPhoto?: string;
  vehicleType: VehicleType;
  price: number;
  createdAt: number;
}

export interface Village {
  id: string;
  name: string;
  center: { lat: number, lng: number };
}

export interface Zone {
  id: string;
  name: string;
  operatorId: string;
  pricing: {
    basePrice: number;
    pricePerKm: number;
    minPrice: number;
    maxPrice: number;
    sameVillagePrice: number;
    multipliers: Record<VehicleType, number>;
  };
  center: { lat: number; lng: number };
}

export interface Order {
  id: string;
  customerId: string;
  customerPhone: string;
  driverId?: string;
  driverName?: string;
  driverPhone?: string;
  operatorId: string;
  zoneId: string;
  category: OrderCategory;
  pickup: { address: string; lat: number; lng: number; villageName?: string };
  dropoff: { address: string; lat: number; lng: number; villageName?: string };
  status: OrderStatus;
  price: number;
  distance: number;
  commission: number;
  operatorCut: number;
  driverCut: number;
  createdAt: number;
  acceptedAt?: number;
  deliveredAt?: number;
  cancelledAt?: number;
  ratedAt?: number;
  notes?: string;
  paymentMethod: PaymentMethod;
  requestedVehicleType: VehicleType;
  transactionId?: string;
  rating?: number;
  feedback?: string;
}

export interface User {
  id: string;
  email: string;
  phone: string;
  name: string;
  role: UserRole;
  status: UserStatus;
  photoURL?: string;
  vehicleType?: VehicleType;
  operatorId?: string; 
  zoneId?: string;     
  wallet: {
    balance: number;
    totalEarnings: number;
    withdrawn: number;
  };
  location?: {
    lat: number;
    lng: number;
    updatedAt: number;
  };
}

import type { Zone, Village } from '../types';

export const PLATFORM_COMMISSION_RATE = 0.15;

/**
 * القائمة الشاملة والنهائية لقرى وعزب مركز أشمون (المنوفية)
 * تم تجميعها بناءً على الوحدات المحلية لضمان التغطية الجغرافية الكاملة
 */
