import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, Link } from "react-router-dom";

// Types
import type { User } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { LogOut, RefreshCcw, WifiOff, Loader2, Bell, HelpCircle } from 'lucide-react';

// Services
import { auth, db } from '../services/firebase';
import { onAuthStateChanged, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, collection, query, where, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Pages
import Login from './Login';
import CustomerDashboard from './CustomerDashboard';
import CourierDashboard from './CourierDashboard';
import OperatorDashboard from './OperatorDashboard';
import SuperAdminDashboard from './SuperAdminDashboard';
import NotificationsView from './NotificationsView';
import SupportView from './SupportView';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showSupport, setShowSupport] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    if ("Notification" in window && Notification.permission === "default") {
      Notification.requestPermission().catch(() => {});
    }

    const registerSW = async () => {
      if (!('serviceWorker' in navigator) || !window.isSecureContext) return;
      const hostname = window.location.hostname;
      const isCloudPreview = hostname.includes('usercontent.goog') || hostname.includes('webcontainer.io') || hostname.includes('stackblitz') || hostname.includes('github.dev') || hostname.includes('ai.studio');
      if (isCloudPreview) return;
      setTimeout(async () => {
        try {
          if (document.readyState !== 'complete') return;
          await navigator.serviceWorker.register('../firebase-messaging-sw.js', { scope: '/' });
        } catch (err) {}
      }, 3000);
    };

    if (document.readyState === 'complete') registerSW();
    else window.addEventListener('load', registerSW);
  }, []);

  const fetchUserData = async (uid: string) => {
    try {
      setConnectionError(false);
      const userRef = doc(db, "users", uid);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        const data = userSnap.data();
        if (data && data.role) setUser(stripFirestore(data) as User);
        else setUser(null);
      } else setUser(null);
    } catch (error) {
      if (!navigator.onLine) setConnectionError(true);
      else setUser(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const unsubscribeAuth = onAuthStateChanged(auth, async (fbUser) => {
      if (fbUser) await fetchUserData(fbUser.uid);
      else { setUser(null); setLoading(false); }
    });
    return () => { unsubscribeAuth(); };
  }, []);

  useEffect(() => {
    if (!user) return;
    try {
      const q = query(collection(db, "notifications"), where("userId", "in", [user.id, "ALL", user.role]));
      return onSnapshot(q, (snapshot) => {
        const docs = snapshot.docs.map(d => stripFirestore(d.data()));
        const currentUnread = docs.filter((n: any) => !n.read).length;
        if (currentUnread > unreadCount) {
          try { new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {}); } catch (e) {}
        }
        setUnreadCount(currentUnread);
      });
    } catch (e) {}
  }, [user, unreadCount]);

  if (loading) return (
    <div className="min-h-screen bg-[#2D9469] flex flex-col items-center justify-center p-6 text-center">
      <div className="bg-white/20 p-10 rounded-[4rem] backdrop-blur-2xl mb-10 border border-white/30 shadow-2xl animate-pulse">
         <img src={APP_LOGO_ICON} alt="Loading..." className="h-28 w-28 object-contain" />
      </div>
      <h2 className="text-white font-black text-5xl tracking-tighter mb-8">وصلها أشمون</h2>
      <div className="flex items-center gap-4 bg-white/10 px-10 py-5 rounded-[2.5rem] backdrop-blur-md border border-white/20 shadow-xl">
        <Loader2 className="h-6 w-6 text-emerald-100 animate-spin" />
        <p className="text-emerald-100 font-black text-xs uppercase tracking-[0.3em]">تحميل بيانات المشوار...</p>
      </div>
    </div>
  );

  if (connectionError) return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center p-8 text-center">
      <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl border border-slate-100 max-w-md w-full">
        <WifiOff className="h-16 w-16 text-rose-500 mx-auto mb-8" />
        <h2 className="text-slate-800 font-black text-3xl mb-4">لا يوجد اتصال</h2>
        <button onClick={() => window.location.reload()} className="w-full bg-[#2D9469] text-white py-6 rounded-[2.5rem] font-black shadow-lg flex items-center justify-center gap-4 active:scale-95 transition-all">
          <RefreshCcw className="h-5 w-5" /> حاول مرة أخرى
        </button>
      </div>
    </div>
  );

  if (!user) return <Login onLogin={(u) => setUser(stripFirestore(u))} />;

  const getDashboard = () => {
    if (showNotifications) return <NotificationsView user={user} onBack={() => setShowNotifications(false)} />;
    if (showSupport) return <SupportView user={user} onBack={() => setShowSupport(false)} />;
    switch (user.role) {
      case 'ADMIN': return <SuperAdminDashboard user={user} />;
      case 'OPERATOR': return <OperatorDashboard user={user} />;
      case 'DRIVER': return <CourierDashboard user={user} />;
      case 'CUSTOMER': return <CustomerDashboard user={user} />;
      default: return <div className="p-12 text-center font-bold">دور غير معروف</div>;
    }
  };

  return (
    <HashRouter>
      <div className="app-container">
        <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-[60] px-4 md:px-8 h-20 md:h-24 flex items-center shadow-sm">
          <div className="max-w-7xl mx-auto w-full flex items-center justify-between">
            <div className="flex items-center gap-3 md:gap-5">
              <Link to="/" onClick={() => { setShowNotifications(false); setShowSupport(false); }} className="flex items-center gap-3 md:gap-4 group">
                <div className="bg-[#2D9469] p-2 rounded-2xl shadow-lg transition-all">
                  <img src={APP_LOGO_ICON} alt="Logo" className="h-5 w-5 md:h-7 md:w-7 object-contain" />
                </div>
                <div className="hidden sm:block">
                  <h1 className="font-black text-lg md:text-xl text-slate-800 tracking-tighter leading-none">وصلها <span className="text-[#2D9469]">أشمون</span></h1>
                </div>
              </Link>
            </div>
            <div className="flex items-center gap-2 md:gap-3">
              <button onClick={() => setShowSupport(true)} className="p-2.5 md:p-3.5 bg-slate-50 text-slate-400 hover:text-[#2D9469] rounded-2xl border border-slate-100"><HelpCircle className="h-4 w-4 md:h-5 md:w-5" /></button>
              <button onClick={() => setShowNotifications(true)} className={`p-2.5 md:p-3.5 bg-slate-50 text-slate-400 hover:text-[#2D9469] rounded-2xl relative border border-slate-100 ${unreadCount > 0 ? 'animate-pulse ring-2 ring-emerald-500/20' : ''}`}>
                <Bell className={`h-4 w-4 md:h-5 md:w-5 ${unreadCount > 0 ? 'text-emerald-600' : ''}`} />
                {unreadCount > 0 && <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-4 h-4 rounded-full text-[8px] flex items-center justify-center border-2 border-white">{unreadCount}</span>}
              </button>
              <button onClick={() => signOut(auth)} className="p-2.5 md:p-3.5 bg-slate-50 text-slate-400 hover:text-rose-500 rounded-2xl border border-slate-100"><LogOut className="h-4 w-4 md:h-5 md:w-5 rotate-180" /></button>
            </div>
          </div>
        </header>

        <main className="main-content">
          <Routes>
            <Route path="/" element={getDashboard()} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

