import React, { useState, useEffect, useRef } from 'react';
import type { User, Order } from '../types';
import { db } from '../services/firebase';
import { collection, query, where, onSnapshot, addDoc, limit } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { Send, ChevronRight, Image as ImageIcon, Smile, Loader2 } from 'lucide-react';
import { stripFirestore } from '../utils';

interface Message {
  id: string;
  senderId: string;
  text: string;
  createdAt: number;
}

const ChatView: React.FC<{ user: User, order: Order, onBack: () => void }> = ({ user, order, onBack }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const q = query(
      collection(db, "messages"),
      where("orderId", "==", order.id),
      limit(100)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const docs = snapshot.docs.map(d => ({ 
        id: d.id, 
        ...stripFirestore(d.data()) 
      })) as Message[];

      setMessages(docs.sort((a, b) => a.createdAt - b.createdAt));
      setLoading(false);
      setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });

    return () => unsubscribe();
  }, [order.id]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    const currentMsgText = newMessage.trim();
    const messageData = {
      orderId: order.id,
      senderId: user.id,
      text: currentMsgText,
      createdAt: Date.now()
    };

    setNewMessage('');
    try {
      await addDoc(collection(db, "messages"), messageData);
      const recipientId = user.id === order.customerId ? order.driverId : order.customerId;
      if (recipientId) {
        await addDoc(collection(db, "notifications"), {
          userId: recipientId,
          title: `رسالة جديدة من ${user.name}`,
          body: currentMsgText.length > 50 ? `${currentMsgText.substring(0, 50)}...` : currentMsgText,
          type: 'INFO',
          createdAt: Date.now(),
          read: false,
          orderId: order.id,
          url: '/'
        });
      }
    } catch (err) {
      console.error("Error sending message:", err);
    }
  };

  return (
    <div className="fixed inset-0 bg-white dark:bg-slate-950 z-[2000] flex flex-col animate-in slide-in-from-left duration-300 transition-colors">
      <div className="bg-slate-900 text-white p-6 pt-12 flex items-center justify-between shadow-xl">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center font-black text-xl">
            {user.role === 'DRIVER' ? order.customerPhone.slice(-2) : (order.driverName?.[0] || 'ك')}
          </div>
          <div>
            <h3 className="font-black text-sm">{user.role === 'DRIVER' ? 'العميل' : `الكابتن ${order.driverName || ''}`}</h3>
            <p className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest">مشوار نشط • أشمون</p>
          </div>
        </div>
        <button onClick={onBack} className="p-3 hover:bg-white/10 rounded-2xl transition-colors">
          <ChevronRight className="h-6 w-6" />
        </button>
      </div>
      <div className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar bg-slate-50 dark:bg-slate-950/50">
        {loading ? (
          <div className="flex justify-center items-center h-full opacity-20">
             <Loader2 className="h-8 w-8 animate-spin text-slate-900 dark:text-white" />
          </div>
        ) : messages.length === 0 ? (
          <div className="text-center py-20">
             <div className="bg-white dark:bg-slate-800 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm">
                <Smile className="h-10 w-10 text-slate-200 dark:text-slate-600" />
             </div>
             <p className="text-slate-400 font-black text-xs uppercase tracking-widest">ابدأ المحادثة مع الطرف الآخر</p>
          </div>
        ) : (
          messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.senderId === user.id ? 'justify-start' : 'justify-end'}`}>
              <div className={`max-w-[80%] p-4 rounded-[1.8rem] text-sm font-bold shadow-sm ${
                msg.senderId === user.id 
                  ? 'bg-slate-900 dark:bg-slate-800 text-white rounded-br-none' 
                  : 'bg-white dark:bg-slate-900 text-slate-800 dark:text-slate-200 rounded-bl-none border border-slate-100 dark:border-slate-800'
              }`}>
                {msg.text}
                <p className={`text-[8px] mt-1 opacity-40 ${msg.senderId === user.id ? 'text-right' : 'text-left'}`}>
                  {new Date(msg.createdAt).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}
                </p>
              </div>
            </div>
          ))
        )}
        <div ref={scrollRef} />
      </div>
      <div className="p-6 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 pb-10">
        <form onSubmit={handleSendMessage} className="flex gap-3">
          <div className="flex-1 relative">
            <input 
              type="text" 
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder="اكتب رسالتك هنا..."
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 text-slate-800 dark:text-white rounded-[2rem] py-4 pr-12 pl-6 font-bold text-sm outline-none focus:border-emerald-500 transition-all"
            />
            <ImageIcon className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300 dark:text-slate-600" />
          </div>
          <button type="submit" className="bg-emerald-600 text-white p-4 rounded-full shadow-lg active:scale-90 transition-all">
            <Send className="h-6 w-6" />
          </button>
        </form>
      </div>
    </div>
  );
};

export default ChatView;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, X, Loader2 } from 'lucide-react';

const AIAssistant: React.FC<{ isOpen: boolean, onClose: () => void }> = ({ isOpen, onClose }) => {
  const [messages, setMessages] = useState<{role: 'user' | 'ai', text: string}[]>([
    { role: 'ai', text: 'يا أهلاً بيك في أشمون! أنا مساعدك الذكي، أقدر أساعدك تعرف أسعار المشاوير، ترشيحات مطاعم، أو أماكن في أشمون. تحب تسأل عن إيه؟' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: {
          systemInstruction: "أنت 'وصلها'، المساعد الذكي لتطبيق 'وصلها أشمون'. أنت خبير بجغرافيا مركز أشمون وقراها (شما، سمادون، سنتريس، جريس، طهواي، إلخ). هدفك مساعدة المستخدمين في اقتراح مطاعم أو أماكن في أشمون وشرح كيفية استخدام التطبيق. تحدث بلهجة مصرية أشمونية ودودة ومختصرة.",
        },
      });

      const aiText = response.text || 'معلش يا بطل، الشبكة في أشمون مريحة شوية، جرب تسأل تاني.';
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: 'الظاهر الإنترنت واقع، جرب كمان دقيقة.' }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-900/40 backdrop-blur-md flex items-end sm:items-center justify-center p-4 animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-lg h-[80vh] sm:h-[650px] rounded-t-[3.5rem] sm:rounded-[3.5rem] shadow-2xl flex flex-col overflow-hidden animate-in slide-in-from-bottom">
        <div className="bg-slate-900 p-8 text-white flex justify-between items-center shadow-lg">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-3 rounded-2xl"><Sparkles className="h-6 w-6" /></div>
            <div>
              <h3 className="font-black text-sm">مساعد وصلها الذكي</h3>
              <p className="text-[10px] text-emerald-400 font-bold animate-pulse">متصل الآن</p>
            </div>
          </div>
          <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl"><X className="h-5 w-5" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar bg-slate-50/50">
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-start' : 'justify-end'}`}>
              <div className={`max-w-[85%] p-5 rounded-[2.2rem] text-sm font-bold shadow-sm ${m.role === 'user' ? 'bg-slate-900 text-white rounded-br-none' : 'bg-white text-slate-800 rounded-bl-none border border-slate-100'}`}>
                {m.text}
              </div>
            </div>
          ))}
          {isTyping && <div className="flex justify-end"><Loader2 className="h-6 w-6 text-emerald-500 animate-spin" /></div>}
          <div ref={scrollRef} />
        </div>
        <div className="p-6 bg-white border-t border-slate-100">
          <div className="flex gap-3 relative">
            <input value={input} onChange={e => setInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && handleSend()} placeholder="اسأل أي سؤال عن أشمون..." className="flex-1 bg-slate-50 rounded-[1.8rem] py-5 pr-6 pl-16 font-bold text-sm outline-none focus:border-emerald-500" />
            <button onClick={handleSend} disabled={isTyping} className="absolute left-2 top-1/2 -translate-y-1/2 bg-slate-900 text-white p-4 rounded-2xl shadow-xl active:scale-90"><Send className="h-5 w-5" /></button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AIAssistant;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

* {
