  color: #0f172a; /* Slate-900 for better text visibility */
  overflow: hidden;
}

/* Base Layout Containers */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* Ride Hailing Layout Utility */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
}

/* Full screen map behind UI */
.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #f1f5f9;
}

/* Floating UI Panel (Bottom Sheet on Mobile) */
.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: white;
  border-top-left-radius: 2.5rem;
  border-top-right-radius: 2.5rem;
  box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.15);
  max-height: 85vh;
  overflow-y: auto;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  padding-bottom: 5rem; /* Space for bottom nav */
}

/* Grabber for Mobile UI */
.bottom-sheet-grabber {
  width: 48px;
  height: 6px;
  background: #cbd5e1; /* slate-300 */
  border-radius: 3px;
  margin: 16px auto;
}

/* Responsive Overrides - Tablet */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 6rem;
    left: 2rem;
    right: auto;
    width: 400px;
    border-radius: 2.5rem;
    max-height: calc(100vh - 12rem);
  }
}

/* Responsive Overrides - Desktop */
@media (min-width: 1024px) {
  .rh-layout {
    flex-direction: row-reverse; /* Panel on Right, Map on Left */
  }

  .rh-map-view {
    position: relative;
    flex: 1;
    z-index: 0;
  }

  .rh-ui-panel {
    position: relative;
    bottom: auto;
    left: auto;
    right: auto;
    width: 35%; /* Exact spec: 35% Panel */
    height: 100%;
    max-height: none;
    border-radius: 0;
    box-shadow: -5px 0 25px rgba(0,0,0,0.05);
    border-left: 1px solid #e2e8f0;
    padding-bottom: 2rem;
  }

  .bottom-sheet-grabber {
    display: none;
  }
}

/* Scrollbar Handling */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Typography Enhancements */
.label-strong {
  font-weight: 700;
  color: #1e293b; /* slate-800 */
  font-size: 0.95rem;
}

.helper-text {
  font-weight: 500;
  color: #64748b; /* slate-500 */
  font-size: 0.75rem;
}

/* Button & Interaction Sizing */
button {
  min-height: 48px; /* Minimum for accessibility */
}

.icon-large {
  width: 24px;
  height: 24px;
  stroke-width: 2.5px;
}

/* Map Overlays */
.map-placeholder-text {
  font-weight: 900;
  letter-spacing: 0.1em;
  color: #2D9469;
}

/* Footer Styling */
.app-footer {
  width: 100%;
  text-align: center;
  padding: 2.5rem 0 1.5rem;
  font-size: 13px;
  font-weight: 600;
  color: #94a3b8; /* slate-400 */
  direction: rtl;
}

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, Link } from "react-router-dom";

// Types
import type { User } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { LogOut, RefreshCcw, WifiOff, Loader2, Bell, HelpCircle } from 'lucide-react';

// Services
import { auth, db } from '../services/firebase';
import { onAuthStateChanged, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, collection, query, where, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Pages
import Login from './Login';
import CustomerDashboard from './CustomerDashboard';
import CourierDashboard from './CourierDashboard';
import OperatorDashboard from './OperatorDashboard';
import SuperAdminDashboard from './SuperAdminDashboard';
import NotificationsView from './NotificationsView';
import SupportView from './SupportView';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showSupport, setShowSupport] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    if ("Notification" in window && Notification.permission === "default") {
      Notification.requestPermission().catch(() => {});
    }

    const registerSW = async () => {
      if (!('serviceWorker' in navigator) || !window.isSecureContext) return;
      const hostname = window.location.hostname;
      const isCloudPreview = hostname.includes('usercontent.goog') || hostname.includes('webcontainer.io') || hostname.includes('stackblitz') || hostname.includes('github.dev') || hostname.includes('ai.studio');
      if (isCloudPreview) return;
      setTimeout(async () => {
        try {
          if (document.readyState !== 'complete') return;
          await navigator.serviceWorker.register('../firebase-messaging-sw.js', { scope: '/' });
        } catch (err) {}
      }, 3000);
    };

    if (document.readyState === 'complete') registerSW();
    else window.addEventListener('load', registerSW);
  }, []);

  const fetchUserData = async (uid: string) => {
    try {
      setConnectionError(false);
      const userRef = doc(db, "users", uid);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        const data = userSnap.data();
        if (data && data.role) setUser(stripFirestore(data) as User);
        else setUser(null);
      } else setUser(null);
    } catch (error) {
      if (!navigator.onLine) setConnectionError(true);
      else setUser(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const unsubscribeAuth = onAuthStateChanged(auth, async (fbUser) => {
      if (fbUser) await fetchUserData(fbUser.uid);
      else { setUser(null); setLoading(false); }
    });
    return () => { unsubscribeAuth(); };
  }, []);

  useEffect(() => {
    if (!user) return;
    try {
      const q = query(collection(db, "notifications"), where("userId", "in", [user.id, "ALL", user.role]));
      return onSnapshot(q, (snapshot) => {
        const docs = snapshot.docs.map(d => stripFirestore(d.data()));
        const currentUnread = docs.filter((n: any) => !n.read).length;
        if (currentUnread > unreadCount) {
          try { new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {}); } catch (e) {}
        }
        setUnreadCount(currentUnread);
      });
    } catch (e) {}
  }, [user, unreadCount]);

  if (loading) return (
    <div className="min-h-screen bg-[#2D9469] flex flex-col items-center justify-center p-6 text-center">
      <div className="bg-white/20 p-10 rounded-[4rem] backdrop-blur-2xl mb-10 border border-white/30 shadow-2xl animate-pulse">
         <img src={APP_LOGO_ICON} alt="Loading..." className="h-28 w-28 object-contain" />
      </div>
      <h2 className="text-white font-black text-5xl tracking-tighter mb-8">وصلها أشمون</h2>
      <div className="flex items-center gap-4 bg-white/10 px-10 py-5 rounded-[2.5rem] backdrop-blur-md border border-white/20 shadow-xl">
        <Loader2 className="h-6 w-6 text-emerald-100 animate-spin" />
        <p className="text-emerald-100 font-black text-xs uppercase tracking-[0.3em]">تحميل بيانات المشوار...</p>
      </div>
    </div>
  );

  if (connectionError) return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center p-8 text-center">
      <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl border border-slate-100 max-w-md w-full">
        <WifiOff className="h-16 w-16 text-rose-500 mx-auto mb-8" />
        <h2 className="text-slate-800 font-black text-3xl mb-4">لا يوجد اتصال</h2>
        <button onClick={() => window.location.reload()} className="w-full bg-[#2D9469] text-white py-6 rounded-[2.5rem] font-black shadow-lg flex items-center justify-center gap-4 active:scale-95 transition-all">
          <RefreshCcw className="h-5 w-5" /> حاول مرة أخرى
        </button>
      </div>
    </div>
  );

  if (!user) return <Login onLogin={(u) => setUser(stripFirestore(u))} />;

  const getDashboard = () => {
    if (showNotifications) return <NotificationsView user={user} onBack={() => setShowNotifications(false)} />;
    if (showSupport) return <SupportView user={user} onBack={() => setShowSupport(false)} />;
    switch (user.role) {
      case 'ADMIN': return <SuperAdminDashboard user={user} />;
      case 'OPERATOR': return <OperatorDashboard user={user} />;
      case 'DRIVER': return <CourierDashboard user={user} />;
      case 'CUSTOMER': return <CustomerDashboard user={user} />;
      default: return <div className="p-12 text-center font-bold">دور غير معروف</div>;
    }
  };

  return (
    <HashRouter>
      <div className="app-container">
        <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-[60] px-4 md:px-8 h-20 md:h-24 flex items-center shadow-sm">
          <div className="max-w-7xl mx-auto w-full flex items-center justify-between">
            <div className="flex items-center gap-3 md:gap-5">
              <Link to="/" onClick={() => { setShowNotifications(false); setShowSupport(false); }} className="flex items-center gap-3 md:gap-4 group">
                <div className="bg-[#2D9469] p-2 rounded-2xl shadow-lg transition-all">
                  <img src={APP_LOGO_ICON} alt="Logo" className="h-5 w-5 md:h-7 md:w-7 object-contain" />
                </div>
                <div className="hidden sm:block">
                  <h1 className="font-black text-lg md:text-xl text-slate-800 tracking-tighter leading-none">وصلها <span className="text-[#2D9469]">أشمون</span></h1>
                </div>
              </Link>
            </div>
            <div className="flex items-center gap-2 md:gap-3">
              <button onClick={() => setShowSupport(true)} className="p-2.5 md:p-3.5 bg-slate-50 text-slate-400 hover:text-[#2D9469] rounded-2xl border border-slate-100"><HelpCircle className="h-4 w-4 md:h-5 md:w-5" /></button>
              <button onClick={() => setShowNotifications(true)} className={`p-2.5 md:p-3.5 bg-slate-50 text-slate-400 hover:text-[#2D9469] rounded-2xl relative border border-slate-100 ${unreadCount > 0 ? 'animate-pulse ring-2 ring-emerald-500/20' : ''}`}>
                <Bell className={`h-4 w-4 md:h-5 md:w-5 ${unreadCount > 0 ? 'text-emerald-600' : ''}`} />
                {unreadCount > 0 && <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-4 h-4 rounded-full text-[8px] flex items-center justify-center border-2 border-white">{unreadCount}</span>}
              </button>
              <button onClick={() => signOut(auth)} className="p-2.5 md:p-3.5 bg-slate-50 text-slate-400 hover:text-rose-500 rounded-2xl border border-slate-100"><LogOut className="h-4 w-4 md:h-5 md:w-5 rotate-180" /></button>
            </div>
          </div>
        </header>

        <main className="main-content">
          <Routes>
            <Route path="/" element={getDashboard()} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, OrderCategory } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, Wallet, User as UserIcon, Home, 
  ShieldAlert, StickyNote, Coffee, Pill, Bot
} from 'lucide-react';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import WalletView from './WalletView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'WALLET' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<number>(0);
  const [showChat, setShowChat] = useState(false);
  const previousOrdersCount = useRef(0);

  const playNotificationSound = () => {
    try {
      const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
      audio.play().catch(e => console.log('Audio play failed:', e));
    } catch (e) {}
  };

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;

    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      const newOrders = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[];
      if (newOrders.length > previousOrdersCount.current) {
        playNotificationSound();
        if (Notification.permission === 'granted') {
          new Notification('مشوار جديد متاح في أشمون! 🚕', {
            body: 'تحقق من قائمة الطلبات المتاحة الآن.',
            icon: 'https://img.icons8.com/fluency-systems-filled/192/2D9469/bicycle.png'
          });
        }
      }
      previousOrdersCount.current = newOrders.length;
      setAvailableOrders(newOrders);
    });

    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      const active = all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status));
      setActiveOrder(active || null);
    });

    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const sendNotification = async (userId: string, title: string, body: string, type: string = 'INFO') => {
    try {
      await addDoc(collection(db, "notifications"), {
        userId, title, body, type, createdAt: Date.now(), read: false
      });
    } catch (e) { console.error("Notification failed", e); }
  };

  const handleSendOffer = async (order: Order) => {
    if (offerPrice <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: order.id, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 4.8, vehicleType: user.vehicleType || 'TOKTOK', price: offerPrice, createdAt: Date.now()
      });
      await sendNotification(order.customerId, 'عرض سعر جديد!', `الكابتن ${user.name} أرسل عرضاً بقيمة ${offerPrice} ج.م لمشوارك.`, 'SUCCESS');
      setShowOfferInput(null);
    } catch (e) { alert('فشل إرسال العرض.'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
      if (status === OrderStatus.PICKED_UP) {
        await sendNotification(activeOrder.customerId, 'بدأ المشوار!', `الكابتن ${user.name} استلم الطلب وهو في الطريق للوجهة.`, 'INFO');
      } else if (status === OrderStatus.DELIVERED) {
        await sendNotification(activeOrder.customerId, 'وصلنا بالسلامة!', `تم إتمام مشوارك مع الكابتن ${user.name}. يرجى تقييم الخدمة.`, 'SUCCESS');
      }
    } catch (e) { alert('فشل التحديث.'); } finally { setIsSubmitting(false); }
  };

  const getCategoryBadge = (category: OrderCategory) => {
    switch(category) {
      case 'FOOD': return { label: 'أكل', color: 'orange', icon: <Coffee className="h-3 w-3" /> };
      case 'PHARMACY': return { label: 'صيدلية', color: 'blue', icon: <Pill className="h-3 w-3" /> };
      default: return { label: 'مشوار', color: 'emerald', icon: <Bike className="h-3 w-3" /> };
    }
  };

  if (user.status !== 'APPROVED') {
    return (
      <div className="max-w-md mx-auto min-h-[70vh] flex flex-col items-center justify-center p-8 text-center animate-in zoom-in">
        <div className="bg-white p-10 rounded-[3.5rem] border-2 border-emerald-100 shadow-2xl space-y-6">
          <div className="bg-emerald-50 w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto animate-bounce">
             <ShieldAlert className="h-12 w-12 text-emerald-600" />
          </div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">بانتظار تفعيل حسابك</h2>
          <div className="space-y-4 text-sm font-bold text-slate-400 leading-relaxed">
            <p>أهلاً بك يا كابتن {user.name} في عائلة وصلها أشمون.</p>
            <p className="text-slate-800">سيتم تفعيل حسابك في أقرب وقت ممكن بعد مراجعة بياناتك من قبل الإدارة.</p>
            <p className="bg-emerald-50 text-emerald-700 p-4 rounded-2xl border border-emerald-100">للإسراع في عملية التفعيل، يرجى التواصل مع الإدارة الآن.</p>
          </div>
          <div className="pt-4 space-y-3">
            <button onClick={() => window.open(`https://wa.me/201065019364?text=${encodeURIComponent('أنا الكابتن ' + user.name + '، أرغب في تفعيل حسابي على تطبيق وصلها أشمون.')}`)} className="w-full bg-[#25D366] text-white py-5 rounded-[2rem] font-black text-xs flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all">
              <MessageCircle className="h-5 w-5" /> تواصل مع الإدارة عبر واتساب
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="max-lg mx-auto space-y-6 pb-28 animate-in fade-in">
      <div className={`p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-500 ${isOnline ? 'bg-emerald-600' : 'bg-slate-900'}`}>
         <div>
            <h2 className="text-2xl font-black">{isOnline ? 'أنت جاهز للعمل' : 'أنت غير متصل'}</h2>
            <p className="text-[10px] font-bold opacity-60 mt-1 uppercase tracking-widest">تغطية مباشرة لأشمون</p>
         </div>
         <button onClick={() => setIsOnline(!isOnline)} className={`p-5 rounded-[2.2rem] shadow-xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}>
            <Power className="h-7 w-7" />
         </button>
      </div>
      {activeOrder ? (
         <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 p-8 space-y-8 animate-in zoom-in">
            <div className="flex justify-between items-center">
               <div className="flex items-center gap-2">
                 <span className="bg-emerald-500 text-white px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
               </div>
               <p className="text-3xl font-black">{activeOrder.price} <span className="text-xs opacity-50 font-bold">ج.م</span></p>
            </div>
            <div className="space-y-6">
               <div className="flex gap-5 items-start">
                  <div className="bg-emerald-50 p-4 rounded-2xl text-emerald-600 shadow-sm shrink-0"><MapPin className="h-6 w-6" /></div>
                  <div className="flex-1">
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">مسار الرحلة</p>
                     <p className="font-black text-sm text-slate-800">{activeOrder.pickup?.villageName} ← {activeOrder.dropoff?.villageName}</p>
                  </div>
               </div>
            </div>
            <div className="grid grid-cols-2 gap-3 pt-4">
               <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-900 text-white py-5 rounded-[2rem] font-black text-[10px] text-center flex items-center justify-center gap-2 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-4 w-4" /> اتصال</a>
               <button onClick={() => setShowChat(true)} className="bg-white border border-slate-100 text-slate-900 py-5 rounded-[2rem] font-black text-[10px] flex items-center justify-center gap-2 shadow-sm active:scale-95 transition-all relative"><MessageCircle className="h-4 w-4" /> محادثة</button>
               <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-5 rounded-[2rem] font-black text-xs shadow-xl active:scale-95 transition-all">
                  {isSubmitting ? <Loader2 className="h-5 w-5 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تم استلام الطلب' : 'تأكيد التوصيل'}
               </button>
            </div>
         </div>
      ) : (
         <div className="space-y-4">
            {availableOrders.map(o => (
               <div key={o.id} className="bg-white p-8 rounded-[3rem] border border-slate-50 shadow-sm space-y-6 animate-in slide-in-from-bottom">
                  <p className="text-lg font-black text-slate-800">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p>
                  {showOfferInput === o.id ? (
                     <div className="flex gap-2 animate-in zoom-in">
                        <input type="number" autoFocus value={offerPrice} onChange={e => setOfferPrice(Number(e.target.value))} className="flex-1 bg-slate-50 rounded-2xl p-5 font-black outline-none border-2 border-emerald-500 shadow-inner" placeholder="0" />
                        <button onClick={() => handleSendOffer(o)} disabled={isSubmitting} className="bg-emerald-600 text-white px-8 rounded-2xl font-black text-xs">إرسال</button>
                        <button onClick={() => setShowOfferInput(null)} className="p-5 bg-slate-100 rounded-2xl"><X className="h-5 w-5 text-slate-400" /></button>
                     </div>
                  ) : (
                     <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price); }} className="w-full bg-slate-900 text-white py-5 rounded-[1.8rem] font-black text-xs shadow-xl active:scale-95 transition-all">تقديم عرض سعر</button>
                  )}
               </div>
            ))}
            {availableOrders.length === 0 && (
