const ManualAssignModal: React.FC<{ order: Order, onClose: () => void }> = ({ order, onClose }) => {
  const [drivers, setDrivers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(collection(db, "users"), where("role", "==", "DRIVER"), where("status", "==", "APPROVED"), limit(30));
    getDocs(q).then(snap => {
      setDrivers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const assignDriver = async (driver: User) => {
    try {
      await updateDoc(doc(db, "orders", order.id), {
        driverId: driver.id,
        driverName: driver.name || 'كابتن',
        driverPhone: driver.phone || '',
        status: OrderStatus.ACCEPTED,
        acceptedAt: Date.now()
      });
      onClose();
    } catch (e) { alert('فشل التوجيه'); }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[11000] flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-10 flex flex-col max-h-[80vh]">
        <div className="flex justify-between items-center mb-8">
           <h3 className="text-xl font-black">توجيه كابتن يدوياً</h3>
           <button onClick={onClose} className="p-3 bg-slate-100 rounded-2xl"><X className="h-5 w-5" /></button>
        </div>
        <div className="flex-1 overflow-y-auto no-scrollbar space-y-3">
          {loading ? <Loader2 className="h-8 w-8 animate-spin mx-auto" /> : drivers.map(d => (
            <div key={d.id} onClick={() => assignDriver(d)} className="p-5 bg-slate-50 rounded-3xl flex justify-between items-center hover:bg-slate-100 cursor-pointer">
              <p className="font-black">{d.name}</p>
              <ChevronRight className="h-4 w-4" />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const OperatorDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeTab, setActiveTab] = useState<'LIVE' | 'MAP_VIEW' | 'DRIVERS' | 'HISTORY'>('LIVE');
