const ProfileView: React.FC<{ user: User, onUpdate: (u: User) => void, onBack: () => void }> = ({ user, onUpdate, onBack }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(user.name);
  const [phone, setPhone] = useState(user.phone);
  const [isSaving, setIsSaving] = useState(false);

  const handleUpdateProfile = async () => {
    setIsSaving(true);
    try {
      await updateDoc(doc(db, "users", user.id), { name, phone });
      onUpdate({ ...user, name, phone });
      setIsEditing(false);
    } catch (e) { alert('خطأ في التحديث'); } finally { setIsSaving(false); }
  };

  return (
    <div className="max-w-2xl mx-auto pb-20 space-y-8 p-4">
      <div className="flex items-center justify-between">
        <h2 className="text-3xl font-black text-slate-900">الصفحة الشخصية</h2>
        <button onClick={onBack} className="p-3.5 bg-white border border-slate-100 rounded-2xl"><ChevronRight /></button>
      </div>
      <div className="bg-[#2D9469] rounded-[4rem] p-10 text-white text-center">
        <div className="w-40 h-40 bg-white/20 rounded-[3.5rem] mx-auto flex items-center justify-center mb-6 overflow-hidden">
          {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : <UserIcon className="h-16 w-16" />}
        </div>
        <h3 className="text-2xl font-black">{user.name}</h3>
      </div>
      <div className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-slate-100 space-y-6">
        <input value={name} onChange={e => setName(e.target.value)} disabled={!isEditing} className="w-full bg-slate-50 rounded-2xl p-5 font-black" />
        <input value={phone} onChange={e => setPhone(e.target.value)} disabled={!isEditing} className="w-full bg-slate-50 rounded-2xl p-5 font-black" />
        <button onClick={() => isEditing ? handleUpdateProfile() : setIsEditing(true)} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black">
          {isSaving ? <Loader2 className="animate-spin mx-auto" /> : isEditing ? 'حفظ التغييرات' : 'تعديل البيانات'}
        </button>
      </div>
    </div>
  );
};

