      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 px-8 py-4 flex justify-around items-center z-[110] shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
         {[
           {id: 'NEW', icon: <History className="rotate-180" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History />, label: 'سجلي'},
