import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, OrderCategory } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, Wallet, User as UserIcon, Home, 
  ShieldAlert, StickyNote, Coffee, Pill, Bot
} from 'lucide-react';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import WalletView from './WalletView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'WALLET' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<number>(0);
  const [showChat, setShowChat] = useState(false);
  const previousOrdersCount = useRef(0);

  const playNotificationSound = () => {
    try {
      const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
      audio.play().catch(e => console.log('Audio play failed:', e));
    } catch (e) {}
  };

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;

    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      const newOrders = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[];
      if (newOrders.length > previousOrdersCount.current) {
        playNotificationSound();
        if (Notification.permission === 'granted') {
          new Notification('مشوار جديد متاح في أشمون! 🚕', {
            body: 'تحقق من قائمة الطلبات المتاحة الآن.',
            icon: 'https://img.icons8.com/fluency-systems-filled/192/2D9469/bicycle.png'
          });
        }
      }
      previousOrdersCount.current = newOrders.length;
      setAvailableOrders(newOrders);
    });

    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      const active = all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status));
      setActiveOrder(active || null);
    });

    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const sendNotification = async (userId: string, title: string, body: string, type: string = 'INFO') => {
    try {
      await addDoc(collection(db, "notifications"), {
        userId, title, body, type, createdAt: Date.now(), read: false
      });
    } catch (e) { console.error("Notification failed", e); }
  };

  const handleSendOffer = async (order: Order) => {
    if (offerPrice <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: order.id, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 4.8, vehicleType: user.vehicleType || 'TOKTOK', price: offerPrice, createdAt: Date.now()
      });
      await sendNotification(order.customerId, 'عرض سعر جديد!', `الكابتن ${user.name} أرسل عرضاً بقيمة ${offerPrice} ج.م لمشوارك.`, 'SUCCESS');
      setShowOfferInput(null);
    } catch (e) { alert('فشل إرسال العرض.'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
      if (status === OrderStatus.PICKED_UP) {
        await sendNotification(activeOrder.customerId, 'بدأ المشوار!', `الكابتن ${user.name} استلم الطلب وهو في الطريق للوجهة.`, 'INFO');
      } else if (status === OrderStatus.DELIVERED) {
        await sendNotification(activeOrder.customerId, 'وصلنا بالسلامة!', `تم إتمام مشوارك مع الكابتن ${user.name}. يرجى تقييم الخدمة.`, 'SUCCESS');
      }
    } catch (e) { alert('فشل التحديث.'); } finally { setIsSubmitting(false); }
  };

  const getCategoryBadge = (category: OrderCategory) => {
    switch(category) {
      case 'FOOD': return { label: 'أكل', color: 'orange', icon: <Coffee className="h-3 w-3" /> };
      case 'PHARMACY': return { label: 'صيدلية', color: 'blue', icon: <Pill className="h-3 w-3" /> };
      default: return { label: 'مشوار', color: 'emerald', icon: <Bike className="h-3 w-3" /> };
    }
  };

  if (user.status !== 'APPROVED') {
    return (
      <div className="max-w-md mx-auto min-h-[70vh] flex flex-col items-center justify-center p-8 text-center animate-in zoom-in">
        <div className="bg-white p-10 rounded-[3.5rem] border-2 border-emerald-100 shadow-2xl space-y-6">
          <div className="bg-emerald-50 w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto animate-bounce shadow-inner">
             <ShieldAlert className="h-12 w-12 text-emerald-600" />
          </div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight leading-none">بانتظار تفعيل حسابك</h2>
          <div className="space-y-4 text-sm font-bold text-slate-500 leading-relaxed">
            <p>أهلاً بك يا كابتن {user.name} في عائلة وصلها أشمون.</p>
            <p className="text-slate-900 font-black">سيتم تفعيل حسابك بعد مراجعة بياناتك من قبل الإدارة.</p>
            <p className="bg-emerald-50 text-emerald-700 p-5 rounded-2xl border border-emerald-100 shadow-sm">للإسراع في عملية التفعيل، يرجى التواصل مع الإدارة الآن.</p>
          </div>
          <div className="pt-4 space-y-3">
            <button onClick={() => window.open(`https://wa.me/201065019364?text=${encodeURIComponent('أنا الكابتن ' + user.name + '، أرغب في تفعيل حسابي على تطبيق وصلها أشمون.')}`)} className="w-full bg-[#25D366] text-white py-6 rounded-2xl font-black text-sm flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all">
              <MessageCircle className="h-6 w-6" /> تواصل مع الإدارة عبر واتساب
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout px-4 space-y-6 pb-28 pt-6 animate-in fade-in overflow-y-auto no-scrollbar">
      <div className={`p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl transition-all duration-500 ${isOnline ? 'bg-emerald-600 rh-glow-emerald' : 'bg-slate-900'}`}>
         <div>
            <h2 className="text-2xl font-black tracking-tight">{isOnline ? 'أنت جاهز للعمل' : 'أنت غير متصل'}</h2>
            <p className="text-[10px] font-black opacity-60 mt-1 uppercase tracking-[0.2em]">تغطية مباشرة لأشمون</p>
         </div>
         <button onClick={() => setIsOnline(!isOnline)} className={`p-4 rounded-[2rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}>
            <Power className="h-8 w-8" />
         </button>
      </div>

      {activeOrder ? (
         <div className="bg-white rounded-[3rem] shadow-2xl border border-slate-100 p-8 space-y-8 animate-in zoom-in border-t-4 border-t-emerald-500">
            <div className="flex justify-between items-center">
               <div className="flex items-center gap-2">
                 <span className="bg-emerald-500 text-white px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm">{activeOrder.status}</span>
               </div>
               <p className="text-3xl font-black text-slate-900">{activeOrder.price} <span className="text-xs opacity-50 font-bold">ج.م</span></p>
            </div>
            <div className="space-y-6">
               <div className="flex gap-5 items-start">
                  <div className="bg-emerald-50 p-4 rounded-2xl text-emerald-600 shadow-sm shrink-0"><MapPin className="h-6 w-6" /></div>
                  <div className="flex-1">
                     <p className="helper-text uppercase mb-1 tracking-wider">مسار الرحلة</p>
                     <p className="font-black text-lg text-slate-900 leading-tight">{activeOrder.pickup?.villageName} ← {activeOrder.dropoff?.villageName}</p>
                  </div>
               </div>
            </div>
            <div className="grid grid-cols-2 gap-4 pt-4">
               <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-900 text-white py-5 rounded-2xl font-black text-sm text-center flex items-center justify-center gap-2 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-5 w-5" /> اتصال</a>
               <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-5 rounded-2xl font-black text-sm flex items-center justify-center gap-2 shadow-sm active:scale-95 transition-all relative">
                  <MessageCircle className="h-5 w-5" /> محادثة
               </button>
               <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-6 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all rh-glow-emerald">
                  {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد استلام الطلب' : 'تأكيد توصيل الطلب والتحصيل'}
               </button>
            </div>
         </div>
      ) : (
         <div className="space-y-4">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] px-2">الطلبات المتاحة ({availableOrders.length})</h3>
            {availableOrders.map(o => (
               <div key={o.id} className="bg-white p-7 rounded-[3rem] border border-slate-100 shadow-md space-y-6 animate-in slide-in-from-bottom rh-card-interactive">
                  <div className="flex justify-between items-start">
                     <div>
                        <p className="text-lg font-black text-slate-900 leading-tight">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p>
                        <p className="text-[10px] font-black text-emerald-600 mt-2 bg-emerald-50 inline-block px-3 py-1 rounded-full uppercase tracking-wider">{o.requestedVehicleType}</p>
                     </div>
                     <div className="bg-slate-900 text-emerald-400 p-4 rounded-2xl font-black text-xl shadow-lg">
                        {o.price}
                     </div>
                  </div>
                  {showOfferInput === o.id ? (
                     <div className="flex gap-2 animate-in zoom-in">
                        <input type="number" autoFocus value={offerPrice} onChange={e => setOfferPrice(Number(e.target.value))} className="flex-1 bg-slate-50 rounded-2xl p-5 font-black text-xl outline-none border-2 border-emerald-500 shadow-inner" placeholder="السعر..." />
                        <button onClick={() => handleSendOffer(o)} disabled={isSubmitting} className="bg-emerald-600 text-white px-8 rounded-2xl font-black text-sm shadow-lg">إرسال</button>
                        <button onClick={() => setShowOfferInput(null)} className="p-5 bg-slate-100 rounded-2xl"><X className="h-6 w-6 text-slate-400" /></button>
                     </div>
                  ) : (
                     <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price); }} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-sm shadow-xl active:scale-95 transition-all">تقديم عرض سعر للمشوار</button>
                  )}
               </div>
            ))}
            {availableOrders.length === 0 && (
               <div className="py-24 text-center text-slate-300 font-black border-2 border-dashed border-slate-200 rounded-[3rem] bg-white/50 animate-in fade-in">
                  <Bot className="h-12 w-12 mx-auto mb-4 opacity-20" />
                  <p className="tracking-widest uppercase text-sm">بانتظار مشاوير جديدة من أشمون</p>
               </div>
            )}
         </div>
      )}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 p-6 flex justify-around items-center z-[100] shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
         {[
           {id: 'HOME', icon: <Home />, label: 'الرئيسية'},
           {id: 'ACTIVITY', icon: <History />, label: 'سجلي'},
           {id: 'WALLET', icon: <Wallet />, label: 'محفظتي'},
           {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-110' : 'text-slate-300'}`}>
              <div className={`p-2.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50' : ''}`}>
                 {React.cloneElement(tab.icon as React.ReactElement<any>, { className: 'h-6 w-6' })}
              </div>
              <span className="text-[9px] font-black uppercase tracking-wider">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

