  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-1">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-4 rounded-2xl flex items-center justify-between cursor-pointer hover:border-emerald-100 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-4">
          <span className={`text-lg font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-400'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-3 rounded-xl text-white shadow-md transition-transform group-hover:scale-110`}>
            {React.cloneElement(icon as React.ReactElement, { className: "h-6 w-6" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[2rem] shadow-2xl border border-slate-100 z-[100] max-h-60 overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-3 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border border-slate-200 rounded-xl py-4 px-4 text-base font-bold outline-none" placeholder="ابحث..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-2">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-5 py-4 hover:bg-emerald-50 rounded-xl flex justify-between items-center group transition-all">
                <span className="text-base font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'WALLET' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [orderNotes, setOrderNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [allVillages, setAllVillages] = useState<Village[]>(STATIC_VILLAGES);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) {
        const data = stripFirestore(snap.data());
        setLivePricing(data.pricing || DEFAULT_PRICING);
      }
    });
    onSnapshot(collection(db, "villages"), (snap) => {
      const dbVillages = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[];
      const merged = [...STATIC_VILLAGES];
      dbVillages.forEach(v => { if (!merged.some(sv => sv.id === v.id)) merged.push(v); });
      setAllVillages(merged);
    });
    const q = query(collection(db, "orders"), where("customerId", "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder && activeOrder.status === OrderStatus.WAITING_FOR_OFFERS) {
      const q = query(collection(db, "offers"), where("orderId", "==", activeOrder.id));
      return onSnapshot(q, (snapshot) => setIncomingOffers(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]));
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const base = livePricing.basePrice || 12;
      const perKm = livePricing.pricePerKm || 6;
      const min = livePricing.minPrice || 20;
      const price = Math.max(Math.round((base + (dist * perKm)) * mult), min);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      // 1. حفظ الطلب في Firestore
      const docRef = await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        notes: orderNotes.trim(), paymentMethod: 'CASH'
      });

      // 2. إرسال تفاصيل الطلب عبر الواتساب لسرعة التنسيق
      const vehicleEmoji = selectedVehicle === 'CAR' ? '🚗' : selectedVehicle === 'MOTORCYCLE' ? '🏍️' : '🛺';
      const whatsappMsg = `طلب مشوار جديد من تطبيق وصلها! ${vehicleEmoji}\n\n` +
                          `👤 العميل: ${user.name}\n` +
                          `📞 موبايل: ${user.phone}\n` +
                          `📍 من: ${pickupVillage.name}\n` +
                          `🏁 إلى: ${dropoffVillage.name}\n` +
                          `💰 السعر: ${tripStats.price} ج.م\n` +
                          `🚲 الوسيلة: ${selectedVehicle}\n` +
                          `📝 ملاحظات: ${orderNotes.trim() || 'لا يوجد'}\n\n` +
                          `رابط المتابعة: ${window.location.origin}`;

      window.open(`https://wa.me/201065019364?text=${encodeURIComponent(whatsappMsg)}`, '_blank');

      setOrderNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ في قبول العرض.'); }
  };

  const handleCancelOrder = async () => {
    if (!activeOrder || !window.confirm('إلغاء المشوار؟')) return;
    try { await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED }); } catch (e) { }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  const categoryOptions: { id: OrderCategory, label: string, icon: React.ReactNode, color: string }[] = [
    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-6 w-6" />, color: 'emerald' },
    { id: 'FOOD', label: 'أكل', icon: <Coffee className="h-6 w-6" />, color: 'orange' },
    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-6 w-6" />, color: 'blue' }
  ];

  return (
    <div className="rh-layout">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {activeOrder && activeOrder.status === OrderStatus.DELIVERED && (
        <RatingModal order={activeOrder} onClose={() => setActiveOrder(null)} />
      )}

      <div className="rh-map-view flex items-center justify-center">
        <div className="text-center opacity-30 select-none">
           <MapPin className="h-24 w-24 mx-auto mb-4 text-[#2D9469] animate-bounce" />
           <p className="font-black text-2xl tracking-widest text-[#2D9469] uppercase">خريطة أشمون</p>
        </div>
      </div>

      <div className="rh-ui-panel no-scrollbar">
        <div className="bottom-sheet-grabber"></div>

        <div className="p-6 md:p-8 space-y-8">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between mb-2">
                 <h2 className="text-2xl font-black text-slate-900 tracking-tight">إلى أين نذهب اليوم؟</h2>
                 <button onClick={() => setAiOpen(true)} className="p-3 bg-emerald-50 text-emerald-600 rounded-2xl shadow-sm active:scale-95 transition-all">
                    <Bot className="h-7 w-7" />
                 </button>
              </div>

              <div className="space-y-8">
                <div className="grid grid-cols-3 gap-3">
                  {categoryOptions.map(cat => (
                    <button 
                       key={cat.id} 
                       onClick={() => setSelectedCategory(cat.id)}
                       className={`py-5 rounded-2xl flex flex-col items-center gap-2 border-2 transition-all ${
                         selectedCategory === cat.id 
                           ? `bg-emerald-50 border-emerald-500 text-emerald-600 shadow-md` 
                           : 'bg-slate-50 border-transparent text-slate-400'
                       }`}
                    >
                       {React.cloneElement(cat.icon as React.ReactElement, { className: "h-6 w-6" })}
                       <span className="text-[10px] font-black uppercase tracking-wider">{cat.label}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-4 relative">
                  <VillageInput 
                    label="نقطة الانطلاق" 
                    helper="أين سيتسلمك الكابتن؟"
                    selectedVillage={pickupVillage} 
                    onSelect={setPickupVillage} 
                    icon={<MapPin />} 
                    iconBg="bg-emerald-500" 
                    placeholder="اختر موقعك الحالي" 
                    availableVillages={allVillages} 
                  />

                  {/* Decorative path line */}
                  <div className="absolute right-[43px] top-[95px] bottom-[45px] w-0.5 bg-slate-200 border-r-2 border-dashed z-0"></div>

                  <VillageInput 
                    label="نقطة الوصول" 
                    helper="إلى أين نذهب؟"
                    selectedVillage={dropoffVillage} 
                    onSelect={setDropoffVillage} 
                    icon={<Check />} 
                    iconBg="bg-rose-500" 
                    placeholder="اختر وجهتك النهائية" 
                    availableVillages={allVillages} 
                  />
                </div>

                <div className="space-y-3">
                  <div className="flex flex-col px-1">
                    <label className="label-strong">وسيلة النقل</label>
                    <span className="helper-text">اختر ما يناسب مشوارك</span>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button 
                        key={v.id} 
                        onClick={() => setSelectedVehicle(v.id as VehicleType)} 
                        className={`py-5 rounded-2xl flex flex-col items-center gap-2 border-2 transition-all ${
                          selectedVehicle === v.id 
                            ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-md' 
                            : 'bg-slate-50 border-transparent text-slate-400'
                        }`}
                      >
                        {React.cloneElement(v.icon as React.ReactElement, { className: "h-6 w-6" })}
                        <span className="text-[10px] font-black uppercase tracking-wider">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <div className="relative">
                  <StickyNote className="absolute right-4 top-4 h-5 w-5 text-slate-300" />
                  <textarea 
                    value={orderNotes}
                    onChange={e => setOrderNotes(e.target.value)}
                    placeholder="ملاحظات إضافية للكابتن (مثل: رقم البيت)..."
                    className="w-full bg-slate-50 text-slate-900 border-none rounded-2xl py-4 pr-12 pl-6 font-bold text-sm outline-none focus:ring-4 focus:ring-emerald-500/5 min-h-[100px] shadow-inner"
                  />
                </div>

                {tripStats && (
                  <div className="bg-slate-900 text-white p-6 rounded-3xl flex justify-between items-center shadow-xl animate-in zoom-in">
                    <div className="text-right">
                       <p className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em] mb-1">السعر التقريبي للمشوار</p>
                       <p className="text-4xl font-black">{tripStats.price} <span className="text-base font-bold opacity-40">ج.م</span></p>
                    </div>
                    <div className="bg-white/10 p-4 rounded-2xl">
                      <DollarSign className="h-8 w-8 text-emerald-400" />
                    </div>
                  </div>
                )}

                <button 
                  onClick={handleCreateOrder} 
                  disabled={isSubmitting || !pickupVillage || !dropoffVillage} 
                  className="w-full bg-[#2D9469] text-white py-6 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all disabled:opacity-40 disabled:grayscale rh-glow-emerald"
                >
                   {isSubmitting ? <Loader2 className="h-8 w-8 animate-spin mx-auto" /> : 'اطلب الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-10 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-8 text-center">
                   <div className="relative py-12">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-32 h-32 bg-emerald-500/20 rounded-full animate-ping"></div>
                      </div>
                      <div className="bg-white p-8 rounded-full shadow-2xl relative z-10 inline-block">
                        <Navigation2 className="h-16 w-16 text-emerald-600 animate-pulse" />
                      </div>
                   </div>
                   <div className="space-y-2">
                      <h2 className="text-2xl font-black text-slate-900 tracking-tight">جاري البحث عن كابتن...</h2>
                      <p className="helper-text text-base">سوف تظهر العروض المتاحة فوراً</p>
                   </div>

                   <div className="space-y-4 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-6 rounded-3xl flex justify-between items-center border-2 border-slate-100 hover:border-emerald-500 transition-all shadow-md animate-in slide-in-from-bottom rh-card-interactive">
                           <div className="flex items-center gap-4">
                              <div className="w-14 h-14 bg-slate-900 text-emerald-400 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg">
                                {(offer.driverName || 'ك')[0]}
                              </div>
                              <div className="text-right">
                                 <p className="font-black text-slate-900 text-lg">{offer.driverName}</p>
                                 <div className="flex items-center gap-1 text-amber-500 font-bold text-xs">
                                   <Star className="h-4 w-4 fill-amber-400" /> {offer.driverRating}
                                 </div>
                              </div>
                           </div>
                           <div className="text-center space-y-2">
                              <p className="text-2xl font-black text-emerald-700">{offer.price} <span className="text-xs">ج.م</span></p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-[#2D9469] text-white px-6 py-2 rounded-xl font-black text-xs shadow-lg">قبول</button>
                           </div>
                        </div>
                      ))}
                      {incomingOffers.length === 0 && (
                        <div className="py-12 opacity-20 flex flex-col items-center gap-3">
                           <Loader2 className="h-8 w-8 animate-spin text-slate-900" />
                           <p className="font-black text-xs uppercase tracking-widest">بانتظار العروض من أشمون</p>
                        </div>
                      )}
                   </div>
                   <button onClick={handleCancelOrder} className="text-rose-500 font-black text-sm uppercase tracking-widest py-4 hover:underline">إلغاء الطلب</button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-8">
                   <div className="bg-emerald-600 p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl rh-glow-emerald">
                      <div className="text-right">
                         <p className="text-[10px] font-black opacity-60 uppercase mb-2 tracking-[0.2em]">تحديث مباشر</p>
                         <h3 className="text-2xl font-black tracking-tight">
                           {activeOrder.status === OrderStatus.ACCEPTED ? 'الكابتن في طريقه إليك' : 'أنت في الطريق للوجهة'}
                         </h3>
                      </div>
                      <div className="bg-white/20 p-4 rounded-full">
                        <Navigation2 className="h-8 w-8 animate-bounce" />
                      </div>
                   </div>

                   <div className="flex flex-col items-center gap-4">
                      <div className="w-28 h-28 bg-slate-100 rounded-[2.8rem] flex items-center justify-center border-4 border-white shadow-2xl relative overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" alt="" /> : <UserIcon className="h-12 w-12 text-slate-300" />}
                      </div>
                      <div className="text-center">
                         <h4 className="text-2xl font-black text-slate-900 tracking-tight">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-1 uppercase tracking-widest text-[#2D9469]">كابتن {activeOrder.requestedVehicleType}</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-4">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-5 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all">
                        <PhoneCall className="h-6 w-6" /> اتصال
                      </a>
                      <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-5 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-sm active:scale-95 transition-all">
                        <MessageCircle className="h-6 w-6" /> محادثة
                      </button>
                   </div>

                   <div className="bg-slate-50 p-8 rounded-[3rem] text-right space-y-6 shadow-inner border border-slate-100">
                      <div className="flex items-start gap-4">
                         <div className="bg-emerald-500 p-2 rounded-lg text-white mt-1 shadow-md"><MapPin className="h-5 w-5" /></div>
                         <div className="flex-1">
                            <p className="helper-text uppercase mb-1 tracking-wider">مسار الرحلة</p>
                            <p className="text-lg font-black text-slate-800">{activeOrder.pickup.villageName} ← {activeOrder.dropoff.villageName}</p>
                         </div>
                      </div>
                      <div className="flex justify-between items-end pt-6 border-t border-slate-200">
                         <div>
                            <p className="helper-text uppercase mb-1 tracking-wider">إجمالي الحساب</p>
                            <p className="text-3xl font-black text-emerald-700 tracking-tighter">{activeOrder.price} ج.م</p>
                         </div>
                         <div className="bg-white p-3 rounded-2xl border border-slate-100 shadow-sm">
                            <WalletIcon className="h-6 w-6 text-slate-400" />
                         </div>
                      </div>
                   </div>
                </div>
              )}
            </div>
          )}

          <footer className="app-footer">
            © جميع الحقوق محفوظة – M.R Mahmoud Khalifa
          </footer>
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 px-8 py-4 flex justify-around items-center z-[110] shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
         {[
           {id: 'NEW', icon: <History className="rotate-180" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History />, label: 'سجلي'},
           {id: 'WALLET', icon: <WalletIcon />, label: 'محفظتي'},
           {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 transition-all ${activeView === tab.id ? 'text-[#2D9469] scale-110' : 'text-slate-300'}`}>
              <div className={`p-2.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50' : ''}`}>
                {React.cloneElement(tab.icon as React.ReactElement, { className: "h-6 w-6" })}
              </div>
              <span className="text-[10px] font-black uppercase tracking-wider">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --emerald-primary: #2D9469;
  --emerald-light: #ecfdf5;
  --slate-dark: #0f172a;
  --slate-body: #64748b;
  --safe-area-inset-top: env(safe-area-inset-top);
  --safe-area-inset-bottom: env(safe-area-inset-bottom);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: #f8fafc;
  -webkit-font-smoothing: antialiased;
  color: var(--slate-dark);
  overflow: hidden;
  line-height: 1.6;
}

/* الهيكل الرئيسي المحسن */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100%;
  z-index: 1;
}

/* نظام الخريطة واللوحة العائمة (Uber Style) */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
}

.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #f1f5f9;
}

.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: white;
  border-top-left-radius: 2.5rem;
  border-top-right-radius: 2.5rem;
  box-shadow: 0 -20px 60px -10px rgba(0, 0, 0, 0.2);
  max-height: 88vh;
  overflow-y: auto;
  padding-bottom: calc(6rem + var(--safe-area-inset-bottom));
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* مقابض السحب للهواتف */
.bottom-sheet-grabber {
  width: 44px;
  height: 6px;
  background: #cbd5e1;
  border-radius: 99px;
  margin: 14px auto 10px;
}

/* تحسين الأزرار التفاعلية */
button:active {
  transform: scale(0.95);
  transition: transform 0.1s ease;
}

.rh-card-interactive {
  background: white;
  border: 1px solid #f1f5f9;
  border-radius: 2.2rem;
  padding: 1.5rem;
  transition: all 0.2s ease;
}

.rh-card-interactive:active {
  background: #f8fafc;
  border-color: var(--emerald-primary);
}

/* الطباعة والهيكل البصري */
.label-strong {
  font-weight: 800;
  color: var(--slate-dark);
  font-size: 0.95rem;
  display: block;
}

.helper-text {
  font-weight: 600;
  color: var(--slate-body);
  font-size: 0.75rem;
  margin-top: 2px;
}

/* التجاوب (Responsive) */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 7rem;
    left: auto;
    right: 2.5rem;
    width: 440px;
    border-radius: 2.5rem;
    max-height: calc(100vh - 14rem);
  }
}

@media (min-width: 1024px) {
  .rh-layout { flex-direction: row; }
  .rh-map-view { position: relative; flex: 65; }
  .rh-ui-panel {
    position: relative;
    width: 35%;
    height: 100%;
    max-height: none;
    border-radius: 0;
    box-shadow: -10px 0 40px rgba(0,0,0,0.03);
    border-left: 1px solid #f1f5f9;
  }
  .bottom-sheet-grabber { display: none; }
}

.no-scrollbar::-webkit-scrollbar { display: none; }

/* تأثيرات الوهج والنجاح */
.glow-emerald {
  box-shadow: 0 10px 30px -5px rgba(45, 148, 105, 0.3);
}

.app-footer {
  text-align: center;
  padding: 2rem 0;
  font-size: 11px;
  font-weight: 800;
  color: #cbd5e1;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

import React, { useState, useEffect } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory } from '../types';
import { OrderStatus, VehicleType } from '../types';

// Config
import { ASHMOUN_VILLAGES as STATIC_VILLAGES, DEFAULT_PRICING } from '../config/constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, DollarSign, Star,
  User as UserIcon, Wallet as WalletIcon,
  Car, MessageCircle, Loader2,
  Bot, Heart, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall, ShieldCheck
} from 'lucide-react';

// Components
import WalletView from './WalletView';
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import ChatView from '../components/ChatView';
import AIAssistant from '../components/AIAssistant';

const RatingModal: React.FC<{ order: Order, onClose: () => void }> = ({ order, onClose }) => {
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmitRating = async () => {
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", order.id), {
        rating, feedback, status: OrderStatus.DELIVERED_RATED, ratedAt: Date.now()
      });
      onClose();
    } catch (e) { alert('فشل حفظ التقييم'); } finally { setIsSubmitting(false); }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[20000] flex items-center justify-center p-6 animate-in fade-in">
      <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-[3.5rem] overflow-hidden shadow-2xl animate-in zoom-in">
        <div className="bg-[#2D9469] p-10 text-center text-white">
          <div className="bg-white/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6 backdrop-blur-md">
            <Heart className="h-12 w-12 fill-white" />
          </div>
          <h3 className="text-3xl font-black mb-2">وصلنا بالسلامة!</h3>
          <p className="text-sm font-bold text-emerald-50">كيف كان مشوارك مع الكابتن {order.driverName}؟</p>
        </div>
        <div className="p-8 space-y-6">
          <div className="flex justify-center gap-2">
            {[1, 2, 3, 4, 5].map(star => (
              <button key={star} onClick={() => setRating(star)} className="focus:outline-none transition-transform active:scale-90 p-1">
                <Star className={`h-12 w-12 ${star <= rating ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} />
              </button>
            ))}
          </div>
          <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="رأيك يهمنا لتطوير خدمتنا..." className="w-full bg-slate-50 border border-slate-200 rounded-3xl p-6 font-bold text-sm outline-none focus:ring-4 focus:ring-emerald-500/10 min-h-[120px] transition-all" />
          <button onClick={handleSubmitRating} disabled={isSubmitting} className="w-full bg-[#2D9469] text-white py-6 rounded-3xl font-black text-lg active:scale-95 transition-all shadow-xl flex items-center justify-center gap-3 glow-emerald">
            {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin" /> : 'إرسال التقييم'}
          </button>
        </div>
      </div>
    </div>
  );
};

const VillageInput: React.FC<{
  label: string; selectedVillage: Village | null; onSelect: (v: Village) => void;
  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-4 rounded-[1.8rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-4">
          <span className={`text-lg font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-3 rounded-2xl text-white shadow-lg transition-transform group-active:scale-90`}>
            {React.cloneElement(icon as React.ReactElement, { className: "h-6 w-6" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 z-[100] max-h-72 overflow-hidden flex flex-col animate-in zoom-in duration-200">
          <div className="p-4 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 px-6 text-base font-black outline-none focus:border-emerald-500" placeholder="ابحث عن اسم القرية..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-3">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-6 py-4 hover:bg-emerald-50 rounded-2xl flex justify-between items-center group transition-all mb-1">
                <span className="text-base font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'WALLET' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [orderNotes, setOrderNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [allVillages, setAllVillages] = useState<Village[]>(STATIC_VILLAGES);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) {
        const data = stripFirestore(snap.data());
        setLivePricing(data.pricing || DEFAULT_PRICING);
      }
    });
    onSnapshot(collection(db, "villages"), (snap) => {
      const dbVillages = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[];
      const merged = [...STATIC_VILLAGES];
      dbVillages.forEach(v => { if (!merged.some(sv => sv.id === v.id)) merged.push(v); });
      setAllVillages(merged);
    });
    const q = query(collection(db, "orders"), where("customerId", "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder && activeOrder.status === OrderStatus.WAITING_FOR_OFFERS) {
      const q = query(collection(db, "offers"), where("orderId", "==", activeOrder.id));
      return onSnapshot(q, (snapshot) => setIncomingOffers(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]));
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const base = livePricing.basePrice || 12;
      const perKm = livePricing.pricePerKm || 6;
      const min = livePricing.minPrice || 20;
      const price = Math.max(Math.round((base + (dist * perKm)) * mult), min);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      // 1. تسجيل الطلب في قاعدة البيانات
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        notes: orderNotes.trim(), paymentMethod: 'CASH'
      });

      // 2. إرسال تنبيه فوري عبر الواتساب للإدارة/الكباتن
      const vehicleEmoji = selectedVehicle === 'CAR' ? '🚗' : selectedVehicle === 'MOTORCYCLE' ? '🏍️' : '🛺';
      const whatsappMsg = `*🚨 طلب مشوار جديد في أشمون!* ${vehicleEmoji}\n\n` +
                          `👤 *العميل:* ${user.name}\n` +
                          `📞 *الموبايل:* ${user.phone}\n` +
                          `📍 *من:* ${pickupVillage.name}\n` +
                          `🏁 *إلى:* ${dropoffVillage.name}\n` +
                          `💰 *السعر المقترح:* ${tripStats.price} ج.م\n` +
                          `🚲 *نوع المركبة:* ${selectedVehicle}\n` +
                          `📝 *ملاحظات العميل:* ${orderNotes.trim() || 'لا يوجد'}\n\n` +
                          `_تم الإرسال عبر تطبيق وصلها أشمون_ 🚕`;

      // فتح الواتساب (رقم الإدارة الموحد)
      window.open(`https://wa.me/201065019364?text=${encodeURIComponent(whatsappMsg)}`, '_blank');

      setOrderNotes('');
    } catch (e) { alert('عذراً، فشل في إرسال طلبك. تأكد من اتصال الإنترنت.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ في قبول العرض.'); }
  };

  const handleCancelOrder = async () => {
    if (!activeOrder || !window.confirm('هل أنت متأكد من إلغاء هذا الطلب؟')) return;
    try { await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED }); } catch (e) { }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  const categoryOptions: { id: OrderCategory, label: string, icon: React.ReactNode, color: string }[] = [
    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-6 w-6" />, color: 'emerald' },
    { id: 'FOOD', label: 'أكل', icon: <Coffee className="h-6 w-6" />, color: 'orange' },
    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-6 w-6" />, color: 'blue' }
  ];

  return (
    <div className="rh-layout">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {activeOrder && activeOrder.status === OrderStatus.DELIVERED && (
        <RatingModal order={activeOrder} onClose={() => setActiveOrder(null)} />
      )}

      {/* خلفية الخريطة التفاعلية */}
      <div className="rh-map-view flex items-center justify-center">
        <div className="text-center opacity-30 select-none animate-pulse">
           <MapPin className="h-28 w-28 mx-auto mb-6 text-[#2D9469]" />
           <p className="font-black text-3xl tracking-widest text-[#2D9469] uppercase">خريطة أشمون النشطة</p>
        </div>
      </div>

      {/* لوحة التحكم السفلية */}
      <div className="rh-ui-panel no-scrollbar">
        <div className="bottom-sheet-grabber"></div>

        <div className="p-7 md:p-10 space-y-10">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div className="space-y-1">
                    <h2 className="text-3xl font-black text-slate-900 tracking-tighter">إلى أين نذهب اليوم؟</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">تغطية لكافة قرى مركز أشمون</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-[1.8rem] shadow-sm active:scale-95 transition-all">
                    <Bot className="h-8 w-8" />
                 </button>
              </div>

              <div className="space-y-10">
                {/* اختيار التصنيف */}
                <div className="grid grid-cols-3 gap-4">
                  {categoryOptions.map(cat => (
                    <button 
                       key={cat.id} 
                       onClick={() => setSelectedCategory(cat.id)}
                       className={`py-6 rounded-[2rem] flex flex-col items-center gap-2 border-2 transition-all ${
                         selectedCategory === cat.id 
                           ? `bg-emerald-50 border-emerald-500 text-emerald-600 shadow-xl` 
                           : 'bg-slate-50 border-transparent text-slate-400'
                       }`}
                    >
                       {React.cloneElement(cat.icon as React.ReactElement, { className: "h-7 w-7" })}
                       <span className="text-[10px] font-black uppercase tracking-wider">{cat.label}</span>
                    </button>
                  ))}
                </div>

                {/* مدخلات القرى مع خط المسار */}
                <div className="space-y-6 relative">
                  <VillageInput 
                    label="نقطة الانطلاق" 
                    helper="أين سيتسلمك الكابتن؟"
                    selectedVillage={pickupVillage} 
                    onSelect={setPickupVillage} 
                    icon={<MapPin />} 
                    iconBg="bg-emerald-500" 
                    placeholder="اختر موقعك الحالي" 
                    availableVillages={allVillages} 
                  />

                  {/* خط المسار الديكوري */}
                  <div className="absolute right-[43px] top-[105px] bottom-[50px] w-0.5 bg-slate-100 border-r-2 border-dashed z-0"></div>

                  <VillageInput 
                    label="نقطة الوصول" 
                    helper="إلى أين نذهب؟"
                    selectedVillage={dropoffVillage} 
                    onSelect={setDropoffVillage} 
                    icon={<Check />} 
                    iconBg="bg-rose-500" 
                    placeholder="اختر وجهتك النهائية" 
                    availableVillages={allVillages} 
                  />
                </div>

                {/* وسيلة النقل */}
                <div className="space-y-4">
                  <div className="flex flex-col px-2">
                    <label className="label-strong">وسيلة النقل</label>
                    <span className="helper-text">اختر ما يناسب مشوارك وميزانيتك</span>
                  </div>
                  <div className="grid grid-cols-3 gap-4">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button 
                        key={v.id} 
                        onClick={() => setSelectedVehicle(v.id as VehicleType)} 
                        className={`py-6 rounded-[1.8rem] flex flex-col items-center gap-2 border-2 transition-all ${
                          selectedVehicle === v.id 
                            ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-xl scale-105' 
                            : 'bg-slate-50 border-transparent text-slate-400 opacity-60'
                        }`}
                      >
                        {React.cloneElement(v.icon as React.ReactElement, { className: "h-7 w-7" })}
                        <span className="text-[10px] font-black uppercase tracking-wider">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <div className="relative group">
                  <StickyNote className="absolute right-5 top-5 h-5 w-5 text-slate-300 group-focus-within:text-emerald-500 transition-colors" />
                  <textarea 
                    value={orderNotes}
                    onChange={e => setOrderNotes(e.target.value)}
                    placeholder="ملاحظات إضافية للكابتن (مثل: رقم العمارة، علامة مميزة)..."
                    className="w-full bg-slate-50 text-slate-900 border-none rounded-[2rem] py-5 pr-14 pl-6 font-bold text-sm outline-none focus:ring-4 focus:ring-emerald-500/5 min-h-[110px] shadow-inner"
                  />
                </div>

                {tripStats && (
                  <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] flex justify-between items-center shadow-2xl animate-in zoom-in border border-white/5 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 blur-3xl"></div>
                    <div className="relative z-10 text-right">
                       <p className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em] mb-2">السعر التقريبي للمشوار</p>
                       <p className="text-5xl font-black">{tripStats.price} <span className="text-lg font-bold opacity-30">ج.م</span></p>
                    </div>
                    <div className="relative z-10 bg-white/10 p-5 rounded-3xl backdrop-blur-md">
                      <DollarSign className="h-9 w-9 text-emerald-400" />
                    </div>
                  </div>
                )}

                <button 
                  onClick={handleCreateOrder} 
                  disabled={isSubmitting || !pickupVillage || !dropoffVillage} 
                  className="w-full bg-[#2D9469] text-white py-7 rounded-[2rem] font-black text-2xl shadow-xl active:scale-95 transition-all disabled:opacity-40 disabled:grayscale glow-emerald flex items-center justify-center gap-4"
                >
                   {isSubmitting ? <Loader2 className="h-9 w-9 animate-spin" /> : 'اطلب مشوارك الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-10 text-center">
                   <div className="relative py-16">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-40 h-40 bg-emerald-500/10 rounded-full animate-ping"></div>
                        <div className="w-60 h-60 bg-emerald-500/5 rounded-full animate-ping delay-300"></div>
                      </div>
                      <div className="bg-white p-10 rounded-full shadow-2xl relative z-10 inline-block border border-slate-50">
                        <Navigation2 className="h-20 w-20 text-emerald-600 animate-pulse" />
                      </div>
                   </div>
                   <div className="space-y-3 px-4">
                      <h2 className="text-3xl font-black text-slate-900 tracking-tighter">جاري البحث عن كابتن...</h2>
                      <p className="helper-text text-lg">سوف تظهر العروض المتاحة من الكباتن فوراً</p>
                   </div>

                   <div className="space-y-5 px-2">
                      <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b pb-4">العروض المستلمة ({incomingOffers.length})</h4>
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-7 rounded-[2.5rem] flex justify-between items-center border-2 border-slate-100 hover:border-emerald-500 transition-all shadow-lg animate-in slide-in-from-bottom-6 rh-card-interactive">
                           <div className="flex items-center gap-5">
                              <div className="w-16 h-16 bg-slate-900 text-emerald-400 rounded-3xl flex items-center justify-center font-black text-2xl shadow-xl">
                                {(offer.driverName || 'ك')[0]}
                              </div>
                              <div className="text-right">
                                 <p className="font-black text-slate-900 text-xl leading-none mb-2">{offer.driverName}</p>
                                 <div className="flex items-center gap-1 text-amber-500 font-bold text-sm bg-amber-50 px-3 py-1 rounded-full w-fit">
                                   <Star className="h-4 w-4 fill-amber-400" /> {offer.driverRating}
                                 </div>
                              </div>
                           </div>
                           <div className="text-center space-y-3">
                              <p className="text-3xl font-black text-emerald-700 leading-none">{offer.price} <span className="text-xs">ج.م</span></p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-[#2D9469] text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول العرض</button>
                           </div>
                        </div>
                      ))}
                      {incomingOffers.length === 0 && (
                        <div className="py-16 opacity-30 flex flex-col items-center gap-4">
                           <Loader2 className="h-10 w-10 animate-spin text-slate-900" />
                           <p className="font-black text-xs uppercase tracking-widest">انتظار كباتن أشمون</p>
                        </div>
                      )}
                   </div>
                   <button onClick={handleCancelOrder} className="text-rose-500 font-black text-sm uppercase tracking-widest py-6 hover:bg-rose-50 rounded-full w-full transition-colors">إلغاء الطلب نهائياً</button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-10">
                   <div className="bg-emerald-600 p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl glow-emerald">
                      <div className="text-right">
                         <p className="text-[11px] font-black opacity-60 uppercase mb-2 tracking-[0.2em]">تتبع مباشر للمشوار</p>
                         <h3 className="text-2xl font-black tracking-tight leading-none">
                           {activeOrder.status === OrderStatus.ACCEPTED ? 'الكابتن قادم لموقعك الآن' : 'أنت الآن في الطريق لوجهتك'}
                         </h3>
                      </div>
                      <div className="bg-white/20 p-5 rounded-full backdrop-blur-md">
                        <Navigation2 className="h-9 w-9 animate-bounce" />
                      </div>
                   </div>

                   <div className="flex flex-col items-center gap-5">
                      <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-4 border-white shadow-2xl relative overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" alt="" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                        <div className="absolute bottom-2 right-2 bg-emerald-500 p-1.5 rounded-full border-2 border-white shadow-lg"><ShieldCheck className="h-3 w-3 text-white" /></div>
                      </div>
                      <div className="text-center">
                         <h4 className="text-3xl font-black text-slate-900 tracking-tighter">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-2 uppercase tracking-[0.1em] text-[#2D9469] bg-emerald-50 px-5 py-1.5 rounded-full inline-block">كابتن {activeOrder.requestedVehicleType}</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-5">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all">
                        <PhoneCall className="h-7 w-7" /> اتصال مباشر
                      </a>
                      <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-sm active:scale-95 transition-all">
                        <MessageCircle className="h-7 w-7" /> محادثة فورية
                      </button>
                   </div>

                   <div className="bg-slate-50 p-10 rounded-[3.5rem] text-right space-y-8 shadow-inner border border-slate-100">
                      <div className="flex items-start gap-5">
                         <div className="bg-emerald-500 p-3 rounded-2xl text-white mt-1 shadow-xl"><MapPin className="h-6 w-6" /></div>
                         <div className="flex-1">
                            <p className="helper-text uppercase mb-2 tracking-wider">تفاصيل مسار الرحلة</p>
                            <p className="text-xl font-black text-slate-800 leading-tight">{activeOrder.pickup.villageName} ← {activeOrder.dropoff.villageName}</p>
                         </div>
                      </div>
                      <div className="flex justify-between items-end pt-8 border-t border-slate-200/60">
                         <div className="space-y-1">
                            <p className="helper-text uppercase mb-1 tracking-wider">إجمالي التكلفة</p>
                            <p className="text-4xl font-black text-emerald-700 tracking-tighter">{activeOrder.price} <span className="text-sm font-bold opacity-40">ج.م</span></p>
                         </div>
                         <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-lg">
                            <WalletIcon className="h-8 w-8 text-slate-400" />
                         </div>
                      </div>
                   </div>
                </div>
              )}
            </div>
          )}

          <footer className="app-footer">
            <div className="flex items-center justify-center gap-4 mb-2 grayscale opacity-40">
               <ShieldCheck className="h-4 w-4" />
               <Zap className="h-4 w-4" />
               <Heart className="h-4 w-4" />
            </div>
            © تطبيق وصلها أشمون 2025 – M.R Mahmoud Khalifa
          </footer>
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-xl border-t border-slate-100 px-8 py-5 flex justify-around items-center z-[110] shadow-[0_-15px_40px_rgba(0,0,0,0.08)]">
         {[
           {id: 'NEW', icon: <History className="rotate-180" />, label: 'اطلب'},
           {id: 'ACTIVITY', icon: <History />, label: 'مشاويري'},
           {id: 'WALLET', icon: <WalletIcon />, label: 'محفظتي'},
           {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 transition-all ${activeView === tab.id ? 'text-[#2D9469] scale-110' : 'text-slate-300'}`}>
              <div className={`p-3 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 border border-emerald-100 shadow-sm' : ''}`}>
                {React.cloneElement(tab.icon as React.ReactElement, { className: "h-6 w-6" })}
              </div>
              <span className="text-[10px] font-black uppercase tracking-wider">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --emerald-primary: #10b981;
  --emerald-deep: #065f46;
  --slate-dark: #020617;
  --slate-body: #475569;
  --glass-bg: rgba(255, 255, 255, 0.9);
  --safe-area-top: env(safe-area-inset-top);
  --safe-area-bottom: env(safe-area-inset-bottom);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: #f8fafc;
  color: var(--slate-dark);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  line-height: 1.6;
}

/* Layout Architecture */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100%;
  z-index: 1;
}

/* Ride Hailing Layout */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
}

.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #f1f5f9;
}

/* Bottom Sheet System */
.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: white;
  border-top-left-radius: 3.5rem;
  border-top-right-radius: 3.5rem;
  box-shadow: 0 -25px 80px -15px rgba(0, 0, 0, 0.15);
  max-height: 88vh;
  overflow-y: auto;
  padding-bottom: calc(6.5rem + var(--safe-area-bottom));
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.bottom-sheet-grabber {
  width: 50px;
  height: 6px;
  background: #e2e8f0;
  border-radius: 99px;
  margin: 18px auto 12px;
}

/* Responsive Overrides */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 7rem;
    left: auto;
    right: 2.5rem;
    width: 420px;
    border-radius: 3.5rem;
    max-height: calc(100vh - 14rem);
    border: 1px solid #f1f5f9;
  }
  .bottom-sheet-grabber { display: none; }
}

@media (min-width: 1024px) {
  .rh-layout { display: flex; flex-direction: row; }
  .rh-map-view { position: relative; flex: 65; }
  .rh-ui-panel {
    position: relative;
    width: 35%;
    height: 100%;
    max-height: none;
    border-radius: 0;
    box-shadow: -10px 0 50px rgba(0,0,0,0.02);
    border-left: 1px solid #f1f5f9;
    padding-bottom: 2rem;
  }
}

/* UI Elements */
.label-strong {
  font-weight: 900;
  color: var(--slate-dark);
  font-size: 0.95rem;
}

.helper-text {
  font-weight: 600;
  color: var(--slate-body);
  font-size: 0.75rem;
}

button:active {
  transform: scale(0.96);
  transition: transform 0.1s ease;
}

.glow-emerald {
  box-shadow: 0 15px 35px -5px rgba(16, 185, 129, 0.3);
}

.no-scrollbar::-webkit-scrollbar { display: none; }

.app-footer {
  text-align: center;
  padding: 3rem 0;
  font-size: 11px;
  font-weight: 900;
  color: #cbd5e1;
  text-transform: uppercase;
  letter-spacing: 0.15em;
}

import React, { useState, useEffect } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory } from '../types';
import { OrderStatus, VehicleType } from '../types';

// Config
import { ASHMOUN_VILLAGES as STATIC_VILLAGES, DEFAULT_PRICING } from '../config/constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, DollarSign, Star,
  User as UserIcon, Wallet as WalletIcon,
  Car, MessageCircle, Loader2,
  Bot, Heart, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall, ShieldCheck
} from 'lucide-react';

// Components
import WalletView from './WalletView';
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import ChatView from '../components/ChatView';
import AIAssistant from '../components/AIAssistant';

const RatingModal: React.FC<{ order: Order, onClose: () => void }> = ({ order, onClose }) => {
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmitRating = async () => {
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", order.id), {
        rating, feedback, status: OrderStatus.DELIVERED_RATED, ratedAt: Date.now()
      });
      onClose();
    } catch (e) { alert('فشل التقييم'); } finally { setIsSubmitting(false); }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-3xl z-[20000] flex items-center justify-center p-6 animate-in fade-in">
      <div className="bg-white w-full max-w-md rounded-[4rem] overflow-hidden shadow-2xl animate-in zoom-in">
        <div className="bg-[#10b981] p-12 text-center text-white relative overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 blur-3xl -mr-16 -mt-16"></div>
          <Heart className="h-20 w-20 fill-white mx-auto mb-6 drop-shadow-xl animate-bounce" />
          <h3 className="text-3xl font-black mb-2">رحلة سعيدة!</h3>
          <p className="text-sm font-bold opacity-80">قيم تجربتك مع الكابتن {order.driverName}</p>
        </div>
        <div className="p-10 space-y-8">
          <div className="flex justify-center gap-3">
            {[1, 2, 3, 4, 5].map(star => (
              <button key={star} onClick={() => setRating(star)} className="transition-transform active:scale-75">
                <Star className={`h-12 w-12 ${star <= rating ? 'fill-amber-400 text-amber-400' : 'text-slate-100'}`} />
              </button>
            ))}
          </div>
          <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="رأيك يساعدنا في التطور..." className="w-full bg-slate-50 border-none rounded-3xl p-6 font-bold text-sm outline-none focus:ring-4 focus:ring-emerald-500/10 min-h-[120px] shadow-inner" />
          <button onClick={handleSubmitRating} disabled={isSubmitting} className="w-full bg-slate-900 text-white py-6 rounded-3xl font-black text-lg active:scale-95 transition-all shadow-xl flex items-center justify-center gap-3">
            {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin" /> : 'إرسال التقييم'}
          </button>
        </div>
      </div>
    </div>
  );
};

const VillageInput: React.FC<{
  label: string; selectedVillage: Village | null; onSelect: (v: Village) => void;
  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-[2rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-5">
          <span className={`text-xl font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl group-active:scale-90 transition-transform`}>
            {React.cloneElement(icon as React.ReactElement, { className: "h-6 w-6" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[100] max-h-80 overflow-hidden flex flex-col animate-in zoom-in duration-300">
          <div className="p-5 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-5 px-6 text-base font-black outline-none focus:ring-4 focus:ring-emerald-500/5" placeholder="ابحث عن اسم القرية..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-6 py-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center group transition-all mb-2">
                <span className="text-lg font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'WALLET' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [orderNotes, setOrderNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [allVillages, setAllVillages] = useState<Village[]>(STATIC_VILLAGES);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    onSnapshot(collection(db, "villages"), (snap) => {
      const dbVillages = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[];
      const merged = [...STATIC_VILLAGES];
      dbVillages.forEach(v => { if (!merged.some(sv => sv.id === v.id)) merged.push(v); });
      setAllVillages(merged);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        notes: orderNotes.trim(), paymentMethod: 'CASH'
      });

      const whatsappMsg = `*🚨 طلب مشوار جديد - وصلها أشمون*\n\n` +
                          `👤 *العميل:* ${user.name}\n` +
                          `📍 *من:* ${pickupVillage.name}\n` +
                          `🏁 *إلى:* ${dropoffVillage.name}\n` +
                          `💰 *السعر:* ${tripStats.price} ج.م\n` +
                          `🚲 *الوسيلة:* ${selectedVehicle}\n` +
                          `📝 *ملاحظات:* ${orderNotes.trim() || 'لا يوجد'}`;

      window.open(`https://wa.me/201065019364?text=${encodeURIComponent(whatsappMsg)}`, '_blank');
      setOrderNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ'); }
  };

  const handleCancelOrder = async () => {
    if (activeOrder && window.confirm('إلغاء المشوار؟')) {
      await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED });
    }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {activeOrder?.status === OrderStatus.DELIVERED && <RatingModal order={activeOrder} onClose={() => setActiveOrder(null)} />}

      <div className="rh-map-view flex items-center justify-center">
        <div className="text-center opacity-30 select-none animate-pulse">
           <MapPin className="h-32 w-32 mx-auto mb-6 text-[#10b981]" />
           <p className="font-black text-4xl tracking-widest text-[#10b981] uppercase">أشمون الذكية</p>
        </div>
      </div>

      <div className="rh-ui-panel no-scrollbar">
        <div className="bottom-sheet-grabber"></div>
        <div className="p-8 md:p-12 space-y-12">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <h2 className="text-4xl font-black text-slate-900 tracking-tighter">إلى أين؟</h2>
                 <button onClick={() => setAiOpen(true)} className="p-5 bg-emerald-50 text-emerald-600 rounded-[2rem] shadow-sm active:scale-95 transition-all">
                    <Bot className="h-8 w-8" />
