                        {React.cloneElement(v.icon as React.ReactElement, { className: "h-8 w-8" })}
                        <span className="text-[11px] font-black uppercase tracking-wider">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                {tripStats && (
                  <div className="bg-slate-950 text-white p-10 rounded-[3rem] flex justify-between items-center shadow-2xl animate-in zoom-in border border-white/5 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 blur-3xl"></div>
                    <div className="relative z-10">
                       <p className="text-[11px] font-black text-emerald-400 uppercase tracking-widest mb-2">التكلفة المتوقعة</p>
                       <p className="text-6xl font-black">{tripStats.price} <span className="text-xl font-bold opacity-30">ج.م</span></p>
                    </div>
                    <div className="bg-white/10 p-6 rounded-3xl backdrop-blur-md">
                      <DollarSign className="h-10 w-10 text-emerald-400" />
                    </div>
                  </div>
                )}

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-slate-900 text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 glow-emerald">
