                      ))}
                   </div>
                   <button onClick={handleCancelOrder} className="text-rose-500 font-black text-sm uppercase tracking-widest py-8 hover:underline">إلغاء الحجز</button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-12">
                   <div className="bg-emerald-600 p-10 rounded-[4rem] text-white flex justify-between items-center shadow-2xl glow-emerald">
                      <div className="text-right">
                         <p className="text-[11px] font-black opacity-60 uppercase mb-2 tracking-[0.2em]">تتبع الرحلة</p>
                         <h3 className="text-3xl font-black tracking-tight leading-none">
                           {activeOrder.status === OrderStatus.ACCEPTED ? 'الكابتن في الطريق' : 'أنت الآن في رحلتك'}
                         </h3>
                      </div>
                      <div className="bg-white/20 p-6 rounded-full backdrop-blur-xl">
                        <Navigation2 className="h-10 w-10 animate-bounce" />
                      </div>
                   </div>

                   <div className="flex flex-col items-center gap-6">
                      <div className="w-36 h-36 bg-slate-100 rounded-[3.5rem] flex items-center justify-center border-8 border-white shadow-2xl relative overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-16 w-16 text-slate-300" />}
                        <div className="absolute bottom-3 right-3 bg-emerald-500 p-2 rounded-full border-4 border-white shadow-xl"><ShieldCheck className="h-4 w-4 text-white" /></div>
                      </div>
                      <div className="text-center">
                         <h4 className="text-4xl font-black text-slate-900 tracking-tighter">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-3 uppercase tracking-widest text-emerald-600 bg-emerald-50 px-6 py-2 rounded-full inline-block">كابتن {activeOrder.requestedVehicleType}</p>
