                      <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-7 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 shadow-sm active:scale-95 transition-all">
                        <MessageCircle className="h-8 w-8" /> دردشة
