            </div>
          )}

          <footer className="app-footer">
            © وصلها أشمون 2025 – M.R Mahmoud Khalifa
          </footer>
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-[0_-20px_50px_rgba(0,0,0,0.1)]">
         {[
           {id: 'NEW', icon: <History className="rotate-180" />, label: 'حجز'},
           {id: 'ACTIVITY', icon: <History />, label: 'نشاطي'},
