import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, OrderCategory } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, Wallet, User as UserIcon, Home, 
  ShieldAlert, StickyNote, Coffee, Pill, Bot, Zap, Car
} from 'lucide-react';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import WalletView from './WalletView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'WALLET' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<number>(0);
  const [showChat, setShowChat] = useState(false);
  const previousOrdersCount = useRef(0);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;

    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      const newOrders = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[];
      if (newOrders.length > previousOrdersCount.current) {
        new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {});
      }
      previousOrdersCount.current = newOrders.length;
      setAvailableOrders(newOrders);
    });

    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });

    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const handleSendOffer = async (order: Order) => {
    if (offerPrice <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: order.id, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 4.9, vehicleType: user.vehicleType || 'TOKTOK', price: offerPrice, createdAt: Date.now()
      });
      setShowOfferInput(null);
    } catch (e) { alert('فشل'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') {
    return (
      <div className="max-w-md mx-auto min-h-[70vh] flex flex-col items-center justify-center p-10 text-center animate-in zoom-in">
        <div className="bg-white p-12 rounded-[4rem] shadow-2xl border-4 border-emerald-100 space-y-8">
          <div className="bg-emerald-50 w-32 h-32 rounded-[3.5rem] flex items-center justify-center mx-auto animate-bounce shadow-inner">
             <ShieldAlert className="h-16 w-16 text-emerald-600" />
          </div>
          <h2 className="text-3xl font-black text-slate-900 leading-none">بانتظار تفعيل الحساب</h2>
          <p className="text-slate-500 font-bold leading-relaxed">أهلاً بك كابتن {user.name}. يرجى التواصل مع الإدارة لتفعيل حسابك والبدء في العمل.</p>
          <button onClick={() => window.open(`https://wa.me/201065019364`)} className="w-full bg-[#25D366] text-white py-6 rounded-3xl font-black text-lg flex items-center justify-center gap-3 shadow-2xl active:scale-95 transition-all">
            <MessageCircle className="h-7 w-7" /> تواصل الآن
          </button>
        </div>
      </div>
    );
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout px-6 space-y-8 pb-32 pt-8 animate-in fade-in overflow-y-auto no-scrollbar bg-slate-50">
      <div className={`p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600 glow-emerald' : 'bg-slate-950'}`}>
         <div>
            <h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'أنت نشط الآن' : 'أنت أوفلاين'}</h2>
            <p className="text-[10px] font-black opacity-60 mt-2 uppercase tracking-[0.3em]">مركبات أشمون النشطة</p>
         </div>
         <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2.5rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}>
            <Power className="h-10 w-10" />
         </button>
      </div>

      {activeOrder ? (
         <div className="bg-white rounded-[4rem] shadow-2xl border border-slate-100 p-10 space-y-10 animate-in zoom-in border-t-8 border-t-emerald-500">
            <div className="flex justify-between items-center">
               <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
               <p className="text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-lg opacity-30 font-bold uppercase">ج.م</span></p>
            </div>
            <div className="space-y-8">
               <div className="flex gap-6 items-start">
                  <div className="bg-slate-50 p-5 rounded-3xl text-emerald-600 shadow-inner shrink-0"><MapPin className="h-8 w-8" /></div>
                  <div className="flex-1">
                     <p className="helper-text uppercase mb-2 tracking-widest">مسار الرحلة</p>
                     <p className="font-black text-2xl text-slate-950 leading-tight">{activeOrder.pickup?.villageName} ← {activeOrder.dropoff?.villageName}</p>
                  </div>
               </div>
            </div>
            <div className="grid grid-cols-2 gap-5 pt-4">
               <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
               <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-50 text-slate-900 py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 active:scale-95 transition-all relative">
                  <MessageCircle className="h-7 w-7" /> دردشة
               </button>
               <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 transition-all glow-emerald">
                  {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد استلام الطلب' : 'تأكيد التوصيل والتحصيل'}
               </button>
            </div>
         </div>
      ) : (
         <div className="space-y-6">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.4em] px-4">مشاوير بانتظارك ({availableOrders.length})</h3>
            {availableOrders.map(o => (
               <div key={o.id} className="bg-white p-10 rounded-[4rem] border-2 border-slate-50 shadow-xl space-y-8 animate-in slide-in-from-bottom rh-card-interactive">
                  <div className="flex justify-between items-start">
                     <div className="space-y-2">
                        <p className="text-2xl font-black text-slate-950 leading-none">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p>
                        <p className="text-[11px] font-black text-emerald-600 mt-2 bg-emerald-50 inline-block px-4 py-1.5 rounded-full uppercase tracking-wider">كابتن {o.requestedVehicleType}</p>
                     </div>
                     <div className="bg-slate-950 text-emerald-400 p-6 rounded-3xl font-black text-3xl shadow-2xl shadow-emerald-500/10">
                        {o.price}
                     </div>
                  </div>
                  {showOfferInput === o.id ? (
                     <div className="flex gap-4 animate-in zoom-in">
                        <input type="number" autoFocus value={offerPrice} onChange={e => setOfferPrice(Number(e.target.value))} className="flex-1 bg-slate-50 rounded-[2rem] p-6 font-black text-3xl outline-none border-4 border-emerald-500 shadow-inner" />
                        <button onClick={() => handleSendOffer(o)} disabled={isSubmitting} className="bg-emerald-600 text-white px-10 rounded-3xl font-black text-lg shadow-xl">إرسال</button>
                        <button onClick={() => setShowOfferInput(null)} className="p-6 bg-slate-100 rounded-3xl"><X className="h-8 w-8 text-slate-400" /></button>
                     </div>
                  ) : (
                     <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price); }} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                        <Zap className="h-6 w-6 text-emerald-400" /> تقديم عرض سعر
                     </button>
                  )}
               </div>
            ))}
            {availableOrders.length === 0 && (
               <div className="py-32 text-center text-slate-300 font-black border-4 border-dashed border-slate-100 rounded-[4rem] bg-white animate-in fade-in">
                  <Bot className="h-16 w-16 mx-auto mb-6 opacity-20" />
                  <p className="tracking-widest uppercase text-lg">بانتظار مشاوير جديدة من أشمون</p>
               </div>
            )}
         </div>
      )}

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 p-8 flex justify-around items-center z-[200] shadow-[0_-20px_50px_rgba(0,0,0,0.1)]">
         {[
           {id: 'HOME', icon: <Home />, label: 'الرئيسية'},
           {id: 'ACTIVITY', icon: <History />, label: 'سجلي'},
           {id: 'WALLET', icon: <Wallet />, label: 'محفظتي'},
           {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-[1.5rem] transition-all ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>
                 {React.cloneElement(tab.icon as React.ReactElement<any>, { className: 'h-7 w-7' })}
              </div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CourierDashboard;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --emerald-primary: #10b981;
  --emerald-deep: #065f46;
  --slate-dark: #020617;
  --slate-muted: #64748b;
  --bg-main: #f8fafc;
  --safe-top: env(safe-area-inset-top);
  --safe-bottom: env(safe-area-inset-bottom);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: var(--bg-main);
  color: var(--slate-dark);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  height: 100vh;
  width: 100vw;
}

/* Base Layout Containers */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100%;
  z-index: 1;
}

/* Professional Ride-Hailing Layout */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
}

.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #f1f5f9;
}

/* Floating UI Panel (Responsive Bottom Sheet) */
.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: white;
  border-top-left-radius: 3rem;
  border-top-right-radius: 3rem;
  box-shadow: 0 -25px 80px -15px rgba(0, 0, 0, 0.2);
  max-height: 85vh;
  overflow-y: auto;
  padding-bottom: calc(7rem + var(--safe-bottom));
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.bottom-sheet-grabber {
  width: 44px;
  height: 6px;
  background: #e2e8f0;
  border-radius: 99px;
  margin: 16px auto 10px;
}

/* Responsive Adaptive Classes */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 7rem;
    left: auto;
    right: 2.5rem;
    width: 440px;
    border-radius: 3rem;
    max-height: calc(100vh - 14rem);
    border: 1px solid #f1f5f9;
  }
  .bottom-sheet-grabber { display: none; }
}

@media (min-width: 1024px) {
  .rh-layout { display: flex; flex-direction: row; }
  .rh-map-view { position: relative; flex: 65; border-radius: 0 4rem 4rem 0; overflow: hidden; margin: 1.5rem; }
  .rh-ui-panel {
    position: relative;
    width: 35%;
    height: 100%;
    max-height: none;
    border-radius: 0;
    box-shadow: -15px 0 50px rgba(0,0,0,0.03);
    border-left: 1px solid #f1f5f9;
    padding-bottom: 2rem;
  }
}

/* Typography & Interactive UI */
.label-strong { font-weight: 900; color: var(--slate-dark); font-size: 0.9rem; }
.helper-text { font-weight: 600; color: var(--slate-muted); font-size: 0.75rem; }

button:active { transform: scale(0.96); transition: transform 0.1s ease; }

.glow-emerald {
  box-shadow: 0 15px 35px -5px rgba(16, 185, 129, 0.3);
}

.no-scrollbar::-webkit-scrollbar { display: none; }

.app-footer {
  text-align: center;
  padding: 2rem 0;
  font-size: 10px;
  font-weight: 900;
  color: #cbd5e1;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

