const VillageInput: React.FC<{
  label: string; selectedVillage: Village | null; onSelect: (v: Village) => void;
  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-[1.8rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-5">
          <span className={`text-xl font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-3.5 rounded-2xl text-white shadow-xl transition-transform group-active:scale-90`}>
            {React.cloneElement(icon as React.ReactElement, { className: "h-6 w-6" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 z-[100] max-h-72 overflow-hidden flex flex-col animate-in zoom-in duration-200">
          <div className="p-5 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-base font-black outline-none focus:ring-4 focus:ring-emerald-500/5" placeholder="ابحث عن اسم القرية..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
