                    className="w-full bg-slate-50 text-slate-900 border-none rounded-[1.8rem] py-5 pr-14 pl-6 font-bold text-sm outline-none focus:ring-4 focus:ring-emerald-500/5 min-h-[110px] shadow-inner"
                  />
