import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, Link } from "react-router-dom";

// Types
import type { User } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { LogOut, RefreshCcw, WifiOff, Loader2, Bell, HelpCircle } from 'lucide-react';

// Services
import { auth, db } from '../services/firebase';
import { onAuthStateChanged, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, collection, query, where, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Pages
import Login from './Login';
import CustomerDashboard from './CustomerDashboard';
import CourierDashboard from './CourierDashboard';
import OperatorDashboard from './OperatorDashboard';
import SuperAdminDashboard from './SuperAdminDashboard';
import NotificationsView from './NotificationsView';
import SupportView from './SupportView';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showSupport, setShowSupport] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    const unsubscribeAuth = onAuthStateChanged(auth, async (fbUser) => {
      if (fbUser) await fetchUserData(fbUser.uid);
      else { setUser(null); setLoading(false); }
    });
    return unsubscribeAuth;
  }, []);

  const fetchUserData = async (uid: string) => {
    try {
      const userSnap = await getDoc(doc(db, "users", uid));
      if (userSnap.exists()) setUser(stripFirestore(userSnap.data()) as User);
    } catch (error) {
      if (!navigator.onLine) setConnectionError(true);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return (
    <div className="min-h-screen bg-[#10b981] flex flex-col items-center justify-center p-6 text-center">
      <div className="bg-white/20 p-10 rounded-[4rem] backdrop-blur-2xl mb-10 border border-white/30 shadow-2xl animate-pulse">
         <img src={APP_LOGO_ICON} alt="Loading..." className="h-24 w-24 object-contain" />
      </div>
      <h2 className="text-white font-black text-4xl tracking-tighter">وصلها أشمون</h2>
    </div>
  );

  if (!user) return <Login onLogin={(u) => setUser(stripFirestore(u))} />;

  const getDashboard = () => {
    if (showNotifications) return <NotificationsView user={user} onBack={() => setShowNotifications(false)} />;
    if (showSupport) return <SupportView user={user} onBack={() => setShowSupport(false)} />;
    switch (user.role) {
      case 'ADMIN': return <SuperAdminDashboard user={user} />;
      case 'OPERATOR': return <OperatorDashboard user={user} />;
      case 'DRIVER': return <CourierDashboard user={user} />;
      case 'CUSTOMER': return <CustomerDashboard user={user} />;
      default: return <div className="p-12 text-center font-bold">دور غير معروف</div>;
    }
  };

  return (
    <HashRouter>
      <div className="app-container">
        <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-[60] px-5 h-20 md:h-24 flex items-center shadow-sm">
          <div className="max-w-7xl mx-auto w-full flex items-center justify-between">
            <Link to="/" onClick={() => { setShowNotifications(false); setShowSupport(false); }} className="flex items-center gap-3">
              <div className="bg-[#10b981] p-2.5 rounded-2xl shadow-lg">
                <img src={APP_LOGO_ICON} alt="Logo" className="h-5 w-5 md:h-7 md:w-7" />
              </div>
              <h1 className="font-black text-lg md:text-xl text-slate-800 tracking-tighter leading-none">وصلها <span className="text-[#10b981]">أشمون</span></h1>
            </Link>
            <div className="flex items-center gap-2 md:gap-4">
              <button onClick={() => setShowNotifications(true)} className={`p-3 bg-slate-50 text-slate-400 rounded-2xl relative border border-slate-100`}>
                <Bell className="h-5 w-5" />
                {unreadCount > 0 && <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-4 h-4 rounded-full text-[8px] flex items-center justify-center border-2 border-white">{unreadCount}</span>}
              </button>
              <button onClick={() => signOut(auth)} className="p-3 bg-slate-50 text-slate-400 hover:text-rose-500 rounded-2xl border border-slate-100 transition-colors"><LogOut className="h-5 w-5 rotate-180" /></button>
            </div>
          </div>
        </header>
        <main className="main-content">
          <Routes>
            <Route path="/" element={getDashboard()} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  /* Premium Palette */
  --brand-emerald: #10b981;
  --brand-emerald-deep: #065f46;
  --brand-emerald-light: #ecfdf5;
  --slate-950: #020617;
  --slate-900: #0f172a;
  --slate-600: #475569;
  --slate-100: #f1f5f9;

  /* System Vars */
  --safe-top: env(safe-area-inset-top);
  --safe-bottom: env(safe-area-inset-bottom);
  --glass-bg: rgba(255, 255, 255, 0.95);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: var(--slate-100);
  color: var(--slate-900);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  height: 100vh;
  width: 100vw;
  line-height: 1.5;
}

/* Base App Layout */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100%;
  z-index: 1;
}

/* Professional Map & Panel Layout */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
}

.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #e5ebee;
  transition: all 0.5s ease;
}

/* Floating Bottom Sheet (Responsive) */
.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: white;
  border-top-left-radius: 3.5rem;
  border-top-right-radius: 3.5rem;
  box-shadow: 0 -20px 80px -15px rgba(0, 0, 0, 0.2);
  max-height: 88vh;
  overflow-y: auto;
  padding-bottom: calc(7.5rem + var(--safe-bottom));
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
  border-top: 1px solid rgba(0,0,0,0.03);
}

.bottom-sheet-grabber {
  width: 44px;
  height: 6px;
  background: #e2e8f0;
  border-radius: 99px;
  margin: 18px auto 10px;
}

/* Desktop & Tablet Adaptability */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 7rem;
    left: auto;
    right: 2.5rem;
    width: 440px;
    border-radius: 3.5rem;
    max-height: calc(100vh - 14rem);
    border: 1px solid var(--slate-100);
  }
  .bottom-sheet-grabber { display: none; }
}

@media (min-width: 1024px) {
  .rh-layout { display: flex; flex-direction: row; }
  .rh-map-view { position: relative; flex: 65; margin: 1.5rem; border-radius: 3rem; overflow: hidden; box-shadow: inset 0 0 40px rgba(0,0,0,0.05); }
  .rh-ui-panel {
    position: relative;
    width: 35%;
    height: 100%;
    max-height: none;
    border-radius: 0;
    box-shadow: -15px 0 50px rgba(0,0,0,0.03);
    border-left: 1px solid var(--slate-100);
    padding-bottom: 3rem;
  }
}

/* Enhanced UI Elements */
.btn-primary {
  background: linear-gradient(135deg, var(--brand-emerald) 0%, var(--brand-emerald-deep) 100%);
  color: white;
  box-shadow: 0 15px 35px -5px rgba(16, 185, 129, 0.4);
  transition: all 0.3s ease;
}

.btn-primary:active {
  transform: scale(0.96);
  filter: brightness(1.1);
}

.card-luxury {
  background: white;
  border: 1px solid var(--slate-100);
  border-radius: 2.5rem;
  padding: 1.5rem;
  transition: all 0.3s ease;
}

.label-strong { font-weight: 900; color: var(--slate-950); font-size: 0.9rem; }
.helper-text { font-weight: 600; color: var(--slate-600); font-size: 0.75rem; }

.no-scrollbar::-webkit-scrollbar { display: none; }

.app-footer {
  text-align: center;
  padding: 2.5rem 0;
  font-size: 10px;
  font-weight: 900;
  color: #cbd5e1;
  text-transform: uppercase;
  letter-spacing: 0.15em;
}

/* Animations */
@keyframes pulse-emerald {
  0% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.4); }
  70% { box-shadow: 0 0 0 20px rgba(16, 185, 129, 0); }
  100% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }
}

.animate-status-active {
  animation: pulse-emerald 2s infinite;
}

import React, { useState, useEffect } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory } from '../types';
import { OrderStatus, VehicleType } from '../types';

// Config
import { ASHMOUN_VILLAGES as STATIC_VILLAGES, DEFAULT_PRICING } from '../config/constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, DollarSign, Star,
  User as UserIcon, Wallet as WalletIcon,
  Car, MessageCircle, Loader2,
  Bot, Heart, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall, ShieldCheck,
  CreditCard
} from 'lucide-react';

// Components
import WalletView from './WalletView';
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import ChatView from '../components/ChatView';
import AIAssistant from '../components/AIAssistant';

const VillageInput: React.FC<{
  label: string; selectedVillage: Village | null; onSelect: (v: Village) => void;
  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-[2.2rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-5">
          <span className={`text-xl font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl transition-transform group-active:scale-90`}>
            {React.cloneElement(icon as React.ReactElement, { className: "h-6 w-6" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[100] max-h-80 overflow-hidden flex flex-col animate-in zoom-in duration-300">
          <div className="p-5 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-5 px-6 text-base font-black outline-none focus:ring-4 focus:ring-emerald-500/5" placeholder="ابحث عن اسم القرية..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-6 py-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center group transition-all mb-2">
                <span className="text-lg font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'WALLET' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [orderNotes, setOrderNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [allVillages, setAllVillages] = useState<Village[]>(STATIC_VILLAGES);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    onSnapshot(collection(db, "villages"), (snap) => {
      const dbVillages = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[];
      const merged = [...STATIC_VILLAGES];
      dbVillages.forEach(v => { if (!merged.some(sv => sv.id === v.id)) merged.push(v); });
      setAllVillages(merged);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        notes: orderNotes.trim(), paymentMethod: 'CASH'
      });

      // إشعار واتساب احترافي شامل
      const vehicleEmoji = selectedVehicle === 'CAR' ? '🚗' : selectedVehicle === 'MOTORCYCLE' ? '🏍️' : '🛺';
      const whatsappMsg = `*🚨 طلب مشوار جديد في أشمون!* ${vehicleEmoji}\n\n` +
                          `👤 *العميل:* ${user.name}\n` +
                          `📞 *الموبايل:* ${user.phone}\n` +
                          `📍 *من:* ${pickupVillage.name}\n` +
                          `🏁 *إلى:* ${dropoffVillage.name}\n` +
                          `💰 *السعر المقترح:* ${tripStats.price} ج.م\n` +
                          `🚲 *نوع المركبة:* ${selectedVehicle}\n` +
                          `📝 *ملاحظات:* ${orderNotes.trim() || 'لا يوجد'}\n\n` +
                          `_تطبيق وصلها أشمون 🚕_`;

      window.open(`https://wa.me/201065019364?text=${encodeURIComponent(whatsappMsg)}`, '_blank');
      setOrderNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div className="rh-map-view flex items-center justify-center">
        <div className="text-center opacity-30 select-none animate-pulse">
           <MapPin className="h-32 w-32 mx-auto mb-6 text-[#10b981]" />
           <p className="font-black text-4xl tracking-widest text-[#10b981] uppercase">أشمون الذكية</p>
        </div>
      </div>

      <div className="rh-ui-panel no-scrollbar">
        <div className="bottom-sheet-grabber"></div>
        <div className="p-8 md:p-12 space-y-12">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div className="space-y-1">
                    <h2 className="text-4xl font-black text-slate-950 tracking-tighter">إلى أين نذهب؟</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">كافة قرى مركز أشمون</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-5 bg-emerald-50 text-emerald-600 rounded-[2.2rem] shadow-sm active:scale-95 transition-all">
                    <Bot className="h-9 w-9" />
                 </button>
              </div>

              <div className="space-y-12">
                {/* Category Selector */}
                <div className="grid grid-cols-3 gap-5">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <Coffee /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-2xl scale-110' : 'bg-slate-50 border-transparent text-slate-400 opacity-60'}`}>
                       {React.cloneElement(cat.icon as React.ReactElement, { className: "h-8 w-8" })}
                       <span className="text-[11px] font-black uppercase tracking-wider">{cat.label}</span>
                    </button>
                  ))}
                </div>

                {/* Village Inputs */}
                <div className="space-y-6 relative">
                  <VillageInput label="نقطة الانطلاق" helper="أين سيتسلمك الكابتن؟" selectedVillage={pickupVillage} onSelect={setPickupVillage} icon={<MapPin />} iconBg="bg-emerald-500" placeholder="موقعك الحالي" availableVillages={allVillages} />

                  {/* Visual Route Line */}
                  <div className="absolute right-[45px] top-[115px] bottom-[55px] w-0.5 bg-slate-100 border-r-2 border-dashed z-0"></div>

                  <VillageInput label="نقطة الوصول" helper="أين وجهتك النهائية؟" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} icon={<Check />} iconBg="bg-rose-500" placeholder="الوجهة" availableVillages={allVillages} />
                </div>

                {/* Vehicle Choice */}
                <div className="space-y-5">
                  <label className="label-strong px-2">وسيلة النقل</label>
                  <div className="grid grid-cols-3 gap-4">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v.id as VehicleType)} className={`py-7 rounded-[2.2rem] flex flex-col items-center gap-3 border-2 transition-all ${selectedVehicle === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-xl scale-110' : 'bg-slate-50 border-transparent text-slate-300 opacity-60'}`}>
                        {React.cloneElement(v.icon as React.ReactElement, { className: "h-7 w-7" })}
                        <span className="text-[10px] font-black uppercase tracking-widest">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                {tripStats && (
                  <div className="bg-slate-950 text-white p-10 rounded-[3rem] flex justify-between items-center shadow-2xl animate-in zoom-in border border-white/5 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-40 h-40 bg-emerald-500/10 blur-[80px]"></div>
                    <div className="relative z-10">
                       <p className="text-[11px] font-black text-emerald-400 uppercase tracking-widest mb-1">التكلفة التقريبية</p>
                       <p className="text-6xl font-black">{tripStats.price} <span className="text-xl font-bold opacity-30">ج.م</span></p>
                    </div>
                    <div className="bg-white/10 p-6 rounded-3xl backdrop-blur-xl border border-white/10">
                      <DollarSign className="h-10 w-10 text-emerald-400" />
                    </div>
                  </div>
                )}

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full btn-primary py-8 rounded-[2.8rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                   {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin" /> : 'اطلب مشوارك الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-12 text-center">
                   <div className="relative py-20">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div>
                        <div className="w-64 h-64 bg-emerald-500/5 rounded-full animate-ping delay-500"></div>
                      </div>
                      <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block border-8 border-slate-50">
                        <Navigation2 className="h-24 w-24 text-emerald-600 animate-pulse" />
                      </div>
                   </div>
                   <div className="space-y-4">
                      <h2 className="text-4xl font-black text-slate-950 tracking-tighter">جاري البحث عن كابتن...</h2>
                      <p className="helper-text text-xl">سوف تظهر العروض من كباتن أشمون هنا</p>
                   </div>
                   <div className="space-y-6 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-8 rounded-[3.5rem] flex justify-between items-center border-4 border-slate-100 hover:border-emerald-500 transition-all shadow-xl rh-card-interactive">
                           <div className="flex items-center gap-6">
                              <div className="w-20 h-20 bg-slate-950 text-emerald-400 rounded-3xl flex items-center justify-center font-black text-3xl shadow-2xl">
                                {(offer.driverName || 'ك')[0]}
                              </div>
                              <div className="text-right">
                                 <p className="font-black text-slate-950 text-2xl leading-none mb-2">{offer.driverName}</p>
                                 <div className="flex items-center gap-2 text-amber-500 font-bold text-base bg-amber-50 px-4 py-1.5 rounded-full">
                                   <Star className="h-5 w-5 fill-amber-400" /> {offer.driverRating}
                                 </div>
                              </div>
                           </div>
                           <div className="text-center space-y-3">
                              <p className="text-4xl font-black text-emerald-700">{offer.price} <span className="text-xs font-bold">ج.م</span></p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول</button>
