                            <p className="text-5xl font-black text-emerald-700 tracking-tighter">{activeOrder.price} <span className="text-lg font-bold opacity-30">ج.م</span></p>
                         </div>
                         <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-xl">
                            <CreditCard className="h-9 w-9 text-slate-300" />
