@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --brand-emerald: #10b981;
  --brand-emerald-deep: #065f46;
  --brand-emerald-glow: rgba(16, 185, 129, 0.15);
  --slate-950: #020617;
  --slate-900: #0f172a;
  --slate-800: #1e293b;
  --slate-400: #94a3b8;
  --slate-100: #f1f5f9;
  --bg-app: #f8fafc;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: var(--bg-app);
  color: var(--slate-900);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  height: 100vh;
  width: 100vw;
}

.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
}

.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #e2e8f0;
}

.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: white;
  border-top-left-radius: 3.5rem;
  border-top-right-radius: 3.5rem;
  box-shadow: 0 -25px 80px -15px rgba(0, 0, 0, 0.15);
  max-height: 88vh;
  overflow-y: auto;
  padding-bottom: calc(7rem + env(safe-area-inset-bottom));
  border-top: 1px solid rgba(0,0,0,0.02);
}

.bottom-sheet-grabber {
  width: 45px;
  height: 6px;
  background: #e2e8f0;
  border-radius: 99px;
  margin: 18px auto 10px;
}

@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 7rem;
    left: auto;
    right: 2.5rem;
    width: 420px;
    border-radius: 3.5rem;
    max-height: calc(100vh - 14rem);
    border: 1px solid var(--slate-100);
  }
  .bottom-sheet-grabber { display: none; }
}

@media (min-width: 1024px) {
  .rh-layout { display: flex; }
  .rh-map-view { position: relative; flex: 65; margin: 1.5rem; border-radius: 3.5rem; overflow: hidden; }
  .rh-ui-panel {
    position: relative;
    width: 35%;
    height: 100%;
    max-height: none;
    border-radius: 0;
    border-left: 1px solid var(--slate-100);
  }
}

.btn-premium {
  background: linear-gradient(135deg, var(--brand-emerald) 0%, var(--brand-emerald-deep) 100%);
  color: white;
  box-shadow: 0 15px 30px -5px rgba(16, 185, 129, 0.3);
  transition: all 0.3s ease;
}

.btn-dark {
  background: var(--slate-950);
  color: white;
  box-shadow: 0 15px 30px -5px rgba(2, 6, 23, 0.2);
}

.card-luxury {
  background: white;
  border-radius: 2.5rem;
  border: 1px solid var(--slate-100);
  padding: 1.5rem;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.02);
}

.label-strong { font-weight: 900; color: var(--slate-950); font-size: 0.9rem; }
.helper-text { font-weight: 600; color: var(--slate-400); font-size: 0.75rem; }

.no-scrollbar::-webkit-scrollbar { display: none; }

.animate-pulse-emerald {
  animation: emerald-glow 2s infinite;
}

@keyframes emerald-glow {
  0% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.4); }
  70% { box-shadow: 0 0 0 15px rgba(16, 185, 129, 0); }
  100% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }
}

.app-footer {
  text-align: center;
  padding: 2.5rem 0;
  font-size: 10px;
  font-weight: 900;
  color: #cbd5e1;
  text-transform: uppercase;
  letter-spacing: 0.15em;
