  /* Glass Effects */
  --glass-white: rgba(255, 255, 255, 0.85);
  --glass-dark: rgba(2, 6, 23, 0.85);
  --blur-md: blur(12px);
  --blur-lg: blur(24px);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
  outline: none !important;
}

body {
