}

.bottom-sheet-grabber {
  width: 44px;
  height: 6px;
  background: #cbd5e1;
  border-radius: 99px;
  margin: 20px auto 10px;
}

@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 7rem;
    left: auto;
    right: 2.5rem;
    width: 440px;
    border-radius: 4rem;
    max-height: calc(100vh - 14rem);
    border: 1px solid rgba(255,255,255,0.5);
  }
}

@media (min-width: 1024px) {
  .rh-layout { flex-direction: row; }
  .rh-map-view { position: relative; flex: 65; margin: 1.5rem; border-radius: 3.5rem; overflow: hidden; }
  .rh-ui-panel {
    position: relative;
    width: 35%;
    height: 100%;
    max-height: none;
    border-radius: 0;
    border-left: 1px solid var(--slate-100);
