const Login: React.FC<{ onLogin: (user: User) => void }> = ({ onLogin }) => {
  const [showOnboarding, setShowOnboarding] = useState(true);
  const [isRegistering, setIsRegistering] = useState(false);
  const [step, setStep] = useState<'INPUT' | 'OTP'>('INPUT');
  const [role, setRole] = useState<'CUSTOMER' | 'DRIVER'>('CUSTOMER');
  const [vehicleType, setVehicleType] = useState<VehicleType>('TOKTOK');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    if (isRegistering && step === 'INPUT') {
      if (name.split(' ').length < 3) return setErrorMsg('يرجى إدخال اسمك الحقيقي ثلاثياً على الأقل');
      if (phone.length < 11) return setErrorMsg('رقم الهاتف غير صحيح');

      setLoading(true);
      const whatsappMsg = `أنا ${name}\nرقم هاتفي: ${phone}\nأريد تفعيل حسابي كـ ${role === 'DRIVER' ? 'كابتن' : 'عميل'} في تطبيق وصلها أشمون.`;
      window.open(`https://wa.me/201065019364?text=${encodeURIComponent(whatsappMsg)}`, '_blank');

      setTimeout(() => { setStep('OTP'); setLoading(false); }, 1500);
      return;
    }

    setLoading(true);
    try {
      if (isRegistering) {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        const userData: User = {
          id: userCredential.user.uid, email, name, phone, role,
          status: role === 'DRIVER' ? 'PENDING_APPROVAL' : 'APPROVED',
          vehicleType: role === 'DRIVER' ? vehicleType : undefined,
          wallet: { balance: 0, totalEarnings: 0, withdrawn: 0 }
        };
        await setDoc(doc(db, "users", userCredential.user.uid), userData);
        onLogin(userData);
      } else {
        const userCredential = await signInWithEmailAndPassword(auth, email, password);
        const userSnap = await getDoc(doc(db, "users", userCredential.user.uid));
        if (userSnap.exists()) onLogin(stripFirestore(userSnap.data()) as User);
      }
    } catch (err: any) { 
      setErrorMsg('خطأ في البيانات أو مشكلة في الاتصال');
    } finally { setLoading(false); }
  };

  if (showOnboarding) return <Onboarding onComplete={() => setShowOnboarding(false)} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative overflow-hidden">
      {/* Decorative background gradients */}
      <div className="absolute -top-32 -left-32 w-96 h-96 bg-emerald-500/5 blur-[120px] rounded-full"></div>
      <div className="absolute -bottom-32 -right-32 w-96 h-96 bg-emerald-600/5 blur-[120px] rounded-full"></div>

      <div className="w-full max-w-xl bg-white rounded-[5rem] shadow-2xl border border-slate-100 overflow-hidden animate-in zoom-in duration-700 relative z-10">
        <div className="bg-slate-950 p-16 text-center relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/10 blur-[100px]"></div>
          <div className="relative z-10">
             <div className="bg-emerald-500 p-6 rounded-[2.5rem] inline-block mb-6 emerald-glow animate-float">
                <img src={APP_LOGO_ICON} alt="Logo" className="h-10 w-10" />
             </div>
             <h1 className="text-5xl font-black text-white tracking-tighter">وصلها <span className="text-emerald-400">أشمون</span></h1>
             <p className="text-white/40 text-[10px] font-black uppercase tracking-[0.4em] mt-2">التطبيق الأول في المنوفية</p>
          </div>
        </div>

