import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order } from '../types';
import { OrderStatus } from '../types';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, onSnapshot, orderBy, doc, 
  updateDoc, where, getDocs, limit 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Activity, Bike, X, MapPin, Phone, ChevronRight, Clock, 
  Zap, Loader2, XCircle, StickyNote, Map as MapIcon,
  ShieldCheck, Smartphone, Search, AlertCircle
} from 'lucide-react';

const ManualAssignModal: React.FC<{ order: Order, onClose: () => void }> = ({ order, onClose }) => {
  const [drivers, setDrivers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(collection(db, "users"), where("role", "==", "DRIVER"), where("status", "==", "APPROVED"), limit(30));
    getDocs(q).then(snap => {
      setDrivers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const assignDriver = async (driver: User) => {
    try {
      await updateDoc(doc(db, "orders", order.id), {
        driverId: driver.id,
        driverName: driver.name || 'كابتن',
        driverPhone: driver.phone || '',
        status: OrderStatus.ACCEPTED,
        acceptedAt: Date.now()
      });
      onClose();
    } catch (e) { alert('فشل التوجيه'); }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[11000] flex items-center justify-center p-4 animate-in fade-in">
      <div className="bg-white w-full max-w-xl rounded-[4rem] p-10 flex flex-col max-h-[85vh] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 blur-3xl"></div>
        <div className="flex justify-between items-center mb-10 relative z-10">
           <div className="space-y-1">
              <h3 className="text-2xl font-black text-slate-900">توجيه كابتن يدوياً</h3>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">تغطية مركز أشمون المباشرة</p>
           </div>
           <button onClick={onClose} className="p-4 bg-slate-50 rounded-3xl hover:bg-rose-50 hover:text-rose-500 transition-all"><X className="h-6 w-6" /></button>
        </div>
        <div className="flex-1 overflow-y-auto no-scrollbar space-y-4 relative z-10 px-2">
          {loading ? <Loader2 className="h-12 w-12 animate-spin mx-auto text-emerald-500 mt-20" /> : drivers.length === 0 ? (
            <div className="py-20 text-center opacity-30">
               <Smartphone className="h-16 w-16 mx-auto mb-4" />
               <p className="font-black">لا يوجد كباتن نشطين حالياً</p>
            </div>
          ) : drivers.map(d => (
            <div key={d.id} onClick={() => assignDriver(d)} className="p-7 bg-slate-50 rounded-[2.5rem] flex justify-between items-center border-2 border-transparent hover:border-emerald-500 hover:bg-white cursor-pointer transition-all shadow-sm group">
              <div className="flex items-center gap-6">
                 <div className="w-16 h-16 bg-slate-900 text-emerald-400 rounded-2xl flex items-center justify-center font-black text-2xl group-hover:scale-110 transition-transform">
                    {(d.name || 'ك')[0]}
                 </div>
                 <div>
                    <p className="font-black text-slate-900 text-lg">{d.name}</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">كابتن {d.vehicleType || 'توكتوك'}</p>
                 </div>
              </div>
              <div className="bg-emerald-100 p-3 rounded-2xl group-hover:bg-emerald-500 group-hover:text-white transition-all">
                <ChevronRight className="h-5 w-5" />
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const OperatorDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeTab, setActiveTab] = useState<'LIVE' | 'MAP' | 'DRIVERS'>('LIVE');
