  const liveOrders = orders.filter(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status));

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-32 p-6 animate-in fade-in transition-all">
      {assignTarget && <ManualAssignModal order={assignTarget} onClose={() => setAssignTarget(null)} />}

      <div className="bg-white p-8 rounded-[4rem] shadow-2xl border border-slate-100 flex flex-col lg:flex-row justify-between items-center gap-8 relative overflow-hidden">
         <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/5 blur-[100px]"></div>
         <div className="flex items-center gap-6 relative z-10">
            <div className="bg-slate-950 p-6 rounded-[2.5rem] shadow-xl text-emerald-400 emerald-glow">
               <Activity className="h-10 w-10 animate-pulse" />
            </div>
            <div>
              <h2 className="text-4xl font-black text-slate-900 tracking-tighter">تحكم أشمون</h2>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mt-1">Local Operator Node</p>
            </div>
         </div>
         <div className="flex gap-2 bg-slate-100 p-2.5 rounded-[2.5rem] relative z-10">
            {[
              { id: 'LIVE', label: 'النشاط الحي', icon: <Zap /> },
              { id: 'MAP', label: 'الخريطة', icon: <MapIcon /> },
              { id: 'DRIVERS', label: 'الكباتن', icon: <Bike /> }
