      </div>

      {activeTab === 'LIVE' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
           {liveOrders.map(order => (
             <div key={order.id} className="bg-white rounded-[3.5rem] border-2 border-transparent hover:border-emerald-500 shadow-xl overflow-hidden group transition-all duration-500 hover:-translate-y-2">
                <div className="bg-slate-50 p-7 flex justify-between items-center border-b border-slate-100 group-hover:bg-slate-950 group-hover:text-white transition-all">
