             </div>
           ))}
           {liveOrders.length === 0 && (
             <div className="col-span-full py-40 text-center bg-white rounded-[5rem] border-4 border-dashed border-slate-100 shadow-inner">
                <Smartphone className="h-20 w-20 mx-auto mb-6 text-slate-200" />
