export default OperatorDashboard;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, X, Loader2, Bot, Info, MapPin } from 'lucide-react';

const AIAssistant: React.FC<{ isOpen: boolean, onClose: () => void }> = ({ isOpen, onClose }) => {
  const [messages, setMessages] = useState<{role: 'user' | 'ai', text: string}[]>([
    { role: 'ai', text: 'يا أهلاً بيك في أشمون! أنا مساعدك الذكي، أقدر أساعدك تعرف أسعار المشاوير، ترشيحات مطاعم، أو أماكن في أشمون. تحب تسأل عن إيه؟' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: {
          systemInstruction: "أنت 'وصلها'، المساعد الذكي لتطبيق 'وصلها أشمون'. أنت خبير بجغرافيا مركز أشمون وقراها. هدفك مساعدة المستخدمين بلهجة مصرية أشمونية ودودة ومختصرة.",
        },
      });

      const aiText = response.text || 'معلش يا بطل، الشبكة مريحة، جرب تاني.';
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: 'الظاهر الإنترنت واقع، جرب كمان دقيقة.' }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-950/60 backdrop-blur-xl flex items-end sm:items-center justify-center p-4 animate-in fade-in duration-500">
      <div className="bg-white w-full max-w-xl h-[85vh] sm:h-[700px] rounded-t-[5rem] sm:rounded-[4.5rem] shadow-2xl flex flex-col overflow-hidden animate-in slide-in-from-bottom border border-white/20">
        <div className="bg-slate-950 p-10 text-white flex justify-between items-center relative overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/20 blur-[80px]"></div>
          <div className="flex items-center gap-6 relative z-10">
            <div className="bg-emerald-500 p-4 rounded-[1.8rem] shadow-xl emerald-glow animate-float"><Sparkles className="h-8 w-8" /></div>
            <div>
              <h3 className="font-black text-xl tracking-tight leading-none">مساعد وصلها الذكي</h3>
              <p className="text-[10px] text-emerald-400 font-black uppercase tracking-[0.3em] mt-2 animate-pulse">تغطية أشمون المباشرة</p>
            </div>
          </div>
          <button onClick={onClose} className="p-4 bg-white/5 rounded-[1.8rem] hover:bg-rose-500 transition-all group active:scale-90 relative z-10"><X className="h-6 w-6 group-hover:rotate-90 transition-transform" /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-10 no-scrollbar bg-slate-50/50">
          <div className="flex justify-center gap-3">
             <div className="bg-white px-5 py-2 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-2">
                <MapPin className="h-3 w-3 text-emerald-500" />
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">أشمون - المنوفية</span>
             </div>
             <div className="bg-white px-5 py-2 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-2">
                <Info className="h-3 w-3 text-amber-500" />
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">دعم فوري</span>
             </div>
          </div>

          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-start' : 'justify-end'}`}>
              <div className={`max-w-[85%] p-7 rounded-[3rem] text-sm font-bold shadow-xl leading-relaxed ${m.role === 'user' ? 'bg-slate-900 text-white rounded-br-none border-4 border-slate-800' : 'bg-white text-slate-800 rounded-bl-none border border-slate-100'}`}>
                {m.text}
              </div>
            </div>
          ))}
          {isTyping && (
            <div className="flex justify-end pr-6">
              <div className="bg-emerald-50 p-4 rounded-3xl animate-bounce">
                <Loader2 className="h-6 w-6 text-emerald-600 animate-spin" />
              </div>
            </div>
          )}
          <div ref={scrollRef} />
        </div>

        <div className="p-8 bg-white border-t border-slate-100">
          <div className="flex gap-4 relative">
            <input value={input} onChange={e => setInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && handleSend()} placeholder="اسأل أي شيء عن مركز أشمون..." className="flex-1 bg-slate-50 border-2 border-transparent focus:border-emerald-500 focus:bg-white rounded-[2.5rem] py-7 pr-8 pl-24 font-black text-md shadow-inner transition-all" />
            <button onClick={handleSend} disabled={isTyping} className="absolute left-3 top-1/2 -translate-y-1/2 bg-slate-950 text-white p-5 rounded-[2rem] shadow-2xl active:scale-90 transition-all hover:bg-emerald-600 group disabled:opacity-50">
               <Send className="h-7 w-7 group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AIAssistant;

