import React, { useState } from 'react';

// Types
import type { User, VehicleType } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Services
import { auth, db } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, setDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  Bike, Mail, Lock, User as UserIcon, 
  Smartphone, ShieldCheck,
  ChevronLeft, Car, Globe, Trophy, 
  Loader2, ArrowRight, MessageCircle, Zap,
  Sparkles, ShieldAlert
} from 'lucide-react';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const Onboarding: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const slides = [
    { title: "أهلاً بك في أشمون", body: "تطبيق التوصيل المخصص لخدمة مركز أشمون وقراه بأعلى جودة وأفضل سعر.", icon: <Globe className="h-20 w-20 text-emerald-400" />, color: "from-emerald-600 to-emerald-900" },
    { title: "كباتن ثقة وأمان", body: "كل رحلاتك مراقبة ومؤمنة، كباتننا هم أهلك من قلب أشمون.", icon: <ShieldCheck className="h-20 w-20 text-emerald-400" />, color: "from-slate-900 to-slate-950" },
    { title: "وفر وقتك وفلوسك", body: "أفضل تسعيرة في المنوفية، مع نظام مكافآت لكل مشوار بتمشي معانا فيه.", icon: <Trophy className="h-20 w-20 text-amber-400" />, color: "from-slate-800 to-emerald-900" }
  ];

  return (
    <div className={`fixed inset-0 z-[5000] flex flex-col transition-all duration-1000 bg-gradient-to-br ${slides[step].color}`}>
       <div className="flex-1 flex flex-col items-center justify-center p-12 text-center text-white space-y-12">
          <div className="bg-white/10 p-16 rounded-[5rem] backdrop-blur-3xl animate-in zoom-in duration-700 shadow-2xl border border-white/20">
             {slides[step].icon}
          </div>
          <div className="space-y-6 animate-in slide-in-from-bottom duration-1000 max-w-sm">
             <h2 className="text-5xl font-black tracking-tighter leading-tight">{slides[step].title}</h2>
             <p className="text-white/70 font-bold leading-relaxed text-lg">{slides[step].body}</p>
          </div>
       </div>
       <div className="p-12 pb-24 space-y-12 bg-black/10 backdrop-blur-sm">
          <div className="flex justify-center gap-4">
             {slides.map((_, i) => (
               <div key={i} className={`h-2.5 rounded-full transition-all duration-500 ${i === step ? 'w-20 bg-emerald-400' : 'w-2.5 bg-white/20'}`}></div>
             ))}
          </div>
