               <button onClick={() => setStep(step - 1)} className="p-8 bg-white/10 text-white rounded-[2.5rem] backdrop-blur-md active:scale-90 transition-all">
                 <ArrowRight className="h-7 w-7" />
               </button>
             )}
             <button onClick={() => step < slides.length - 1 ? setStep(step + 1) : onComplete()} className="flex-1 bg-white text-slate-900 py-8 rounded-[3rem] font-black text-2xl flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all">
                {step === slides.length - 1 ? 'ابدأ مشوارك الآن' : 'استمر'}
