const Login: React.FC<{ onLogin: (user: User) => void }> = ({ onLogin }) => {
  const [showOnboarding, setShowOnboarding] = useState(true);
  const [isRegistering, setIsRegistering] = useState(false);
  const [step, setStep] = useState<'INPUT' | 'OTP'>('INPUT');
  const [role, setRole] = useState<'CUSTOMER' | 'DRIVER'>('CUSTOMER');
  const [vehicleType, setVehicleType] = useState<VehicleType>('TOKTOK');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    if (isRegistering && step === 'INPUT') {
      if (name.split(' ').length < 3) return setErrorMsg('يرجى إدخال اسمك الحقيقي ثلاثياً على الأقل');
      if (phone.length < 11) return setErrorMsg('رقم الهاتف غير صحيح');

      setLoading(true);
      const whatsappMsg = `أنا ${name}\nرقم هاتفي: ${phone}\nأريد تفعيل حسابي كـ ${role === 'DRIVER' ? 'كابتن' : 'عميل'} في تطبيق وصلها أشمون.`;
      window.open(`https://wa.me/201065019364?text=${encodeURIComponent(whatsappMsg)}`, '_blank');

      setTimeout(() => { setStep('OTP'); setLoading(false); }, 1500);
      return;
    }

    setLoading(true);
    try {
      if (isRegistering) {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        const userData: User = {
          id: userCredential.user.uid, email, name, phone, role,
          status: role === 'DRIVER' ? 'PENDING_APPROVAL' : 'APPROVED',
          vehicleType: role === 'DRIVER' ? vehicleType : undefined,
          wallet: { balance: 0, totalEarnings: 0, withdrawn: 0 }
        };
        await setDoc(doc(db, "users", userCredential.user.uid), userData);
        onLogin(userData);
      } else {
        const userCredential = await signInWithEmailAndPassword(auth, email, password);
        const userSnap = await getDoc(doc(db, "users", userCredential.user.uid));
        if (userSnap.exists()) onLogin(stripFirestore(userSnap.data()) as User);
      }
    } catch (err: any) { 
      setErrorMsg('خطأ في البيانات أو مشكلة في الاتصال');
    } finally { setLoading(false); }
  };

  if (showOnboarding) return <Onboarding onComplete={() => setShowOnboarding(false)} />;

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center p-6 relative overflow-hidden">
      <div className="absolute top-0 right-0 w-full h-full bg-[radial-gradient(circle_at_center,rgba(16,185,129,0.05)_0%,transparent_70%)]"></div>

      <div className="w-full max-w-xl bg-white rounded-[4.5rem] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.1)] border border-slate-100 overflow-hidden animate-in zoom-in duration-700 relative z-10">
        <div className="bg-slate-950 p-12 text-center relative">
          <div className="bg-emerald-500 p-5 rounded-[2rem] inline-block mb-6 shadow-emerald animate-pulse">
            <img src={APP_LOGO_ICON} alt="Logo" className="h-10 w-10" />
          </div>
          <h1 className="text-4xl font-black text-white tracking-tighter">وصلها <span className="text-emerald-400">أشمون</span></h1>
          <p className="text-white/40 text-[10px] font-black uppercase tracking-[0.4em] mt-2">التطبيق الأول في المنوفية</p>
        </div>

        <div className="p-10 md:p-14">
          {errorMsg && <div className="mb-8 p-5 bg-rose-50 text-rose-600 rounded-[2rem] text-xs font-black border-2 border-rose-100 flex items-center gap-3"><ShieldAlert className="h-5 w-5" /> {errorMsg}</div>}

          <form onSubmit={handleAuth} className="space-y-8">
            {isRegistering ? (
              step === 'INPUT' ? (
                <div className="space-y-6">
                  <div className="flex bg-slate-50 p-2 rounded-[2.5rem] border border-slate-100">
                    <button type="button" onClick={() => setRole('CUSTOMER')} className={`flex-1 py-4 rounded-[2.2rem] font-black text-xs transition-all ${role === 'CUSTOMER' ? 'bg-white text-emerald-600 shadow-md' : 'text-slate-400'}`}>عميل</button>
                    <button type="button" onClick={() => setRole('DRIVER')} className={`flex-1 py-4 rounded-[2.2rem] font-black text-xs transition-all ${role === 'DRIVER' ? 'bg-white text-emerald-600 shadow-md' : 'text-slate-400'}`}>كابتن</button>
                  </div>

                  {role === 'DRIVER' && (
                    <div className="grid grid-cols-3 gap-3 animate-in slide-in-from-top duration-300">
                      {[
                        { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                        { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                        { id: 'CAR', icon: <Car />, label: 'سيارة' }
                      ].map(v => (
                        <button key={v.id} type="button" onClick={() => setVehicleType(v.id as VehicleType)} className={`py-5 rounded-[2rem] flex flex-col items-center gap-2 border-2 transition-all ${vehicleType === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-sm' : 'bg-slate-50 border-transparent text-slate-300'}`}>
                          {React.cloneElement(v.icon as React.ReactElement, { className: "h-5 w-5" })}
                          <span className="text-[9px] font-black uppercase tracking-widest">{v.label}</span>
                        </button>
                      ))}
                    </div>
                  )}

                  <div className="space-y-4">
                     <div className="relative group">
                        <UserIcon className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-500 transition-colors h-5 w-5" />
                        <input type="text" placeholder="الاسم الرباعي الحقيقي" value={name} onChange={e => setName(e.target.value)} required className="lux-input pr-14" />
                     </div>
                     <div className="relative group">
                        <Smartphone className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-500 transition-colors h-5 w-5" />
                        <input type="tel" placeholder="رقم الموبايل (واتساب)" value={phone} onChange={e => setPhone(e.target.value)} required className="lux-input pr-14 text-left" dir="ltr" />
                     </div>
                     <div className="relative group">
                        <Mail className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-500 transition-colors h-5 w-5" />
                        <input type="email" placeholder="البريد الإلكتروني" value={email} onChange={e => setEmail(e.target.value)} required className="lux-input pr-14 text-left" dir="ltr" />
                     </div>
                     <div className="relative group">
                        <Lock className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-500 transition-colors h-5 w-5" />
                        <input type="password" placeholder="كلمة المرور" value={password} onChange={e => setPassword(e.target.value)} required className="lux-input pr-14 text-left" dir="ltr" />
                     </div>
                  </div>

                  <button type="submit" disabled={loading} className="w-full btn-premium py-7 rounded-[2.5rem] text-xl active:scale-95">
                    {loading ? <Loader2 className="h-8 w-8 animate-spin" /> : 'إنشاء الحساب الآن'}
                  </button>
                </div>
              ) : (
                <div className="space-y-10 text-center animate-in zoom-in">
                  <div className="bg-emerald-50 p-10 rounded-[4rem] inline-block mb-4 shadow-inner">
                     <ShieldCheck className="h-16 w-16 text-emerald-600" />
                  </div>
                  <div className="space-y-2">
                    <h2 className="text-3xl font-black text-slate-900">أثبت هويتك</h2>
                    <p className="text-sm font-bold text-slate-400">أدخل الرمز الذي أرسلته لك الإدارة للمتابعة</p>
                  </div>
                  <input type="text" maxLength={6} placeholder="000000" value={otp} onChange={e => setOtp(e.target.value)} className="w-full bg-slate-50 border-4 border-emerald-100 rounded-[3rem] py-10 text-center text-6xl font-black tracking-[0.5em] text-emerald-700 shadow-inner" />
                  <button type="submit" disabled={loading} className="w-full btn-premium py-7 rounded-[2.5rem] text-xl active:scale-95">
                    {loading ? <Loader2 className="h-8 w-8 animate-spin" /> : 'تأكيد الرمز والدخول'}
                  </button>
                </div>
              )
            ) : (
              <div className="space-y-6">
                <div className="relative group">
                   <Mail className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                   <input type="email" placeholder="البريد الإلكتروني" value={email} onChange={e => setEmail(e.target.value)} required className="lux-input pr-14 text-left" dir="ltr" />
                </div>
                <div className="relative group">
                   <Lock className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                   <input type="password" placeholder="كلمة المرور" value={password} onChange={e => setPassword(e.target.value)} required className="lux-input pr-14 text-left" dir="ltr" />
                </div>
                <button type="submit" disabled={loading} className="w-full btn-premium py-7 rounded-[2.5rem] text-xl active:scale-95 mt-4">
                  {loading ? <Loader2 className="h-8 w-8 animate-spin" /> : 'دخول'}
                </button>
              </div>
            )}

            <button type="button" onClick={() => { setIsRegistering(!isRegistering); setStep('INPUT'); setErrorMsg(null); }} className="w-full text-slate-400 font-black text-xs py-4 uppercase tracking-[0.2em] hover:text-emerald-600 transition-colors">
              {isRegistering ? 'لديك حساب؟ سجل دخولك' : 'جديد في أشمون؟ انضم إلينا'}
            </button>
          </form>
        </div>
      </div>

      <p className="mt-12 text-slate-400 font-black text-[10px] uppercase tracking-[0.5em] animate-pulse">
        وصلها أشمون 2025 – M.R Mahmoud Khalifa
      </p>
    </div>
  );
};

