@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  /* Core Colors */
  --primary: #10b981;
  --primary-dark: #065f46;
  --primary-light: #d1fae5;
  --secondary: #0f172a; /* Slate 900 */
  --accent: #f59e0b; /* Amber 500 */

  /* Neutral Palette */
  --bg-main: #f8fafc;
  --bg-card: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #f1f5f9;

  /* Shadows & Effects */
  --shadow-sm: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 10px 15px -3px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 25px 50px -12px rgba(0, 0, 0, 0.12);
  --shadow-primary: 0 10px 25px -5px rgba(16, 185, 129, 0.3);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
  outline: none !important;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: var(--bg-main);
  color: var(--text-main);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  line-height: 1.6;
}

/* --- Layout Components --- */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.rh-ui-panel {
  background: var(--bg-card);
  border-top-left-radius: 3rem;
  border-top-right-radius: 3rem;
  box-shadow: 0 -15px 40px rgba(0, 0, 0, 0.06);
  padding-bottom: 7rem;
}

/* --- Professional Buttons --- */
.btn-main {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: white;
  font-weight: 800;
  padding: 1.25rem 2rem;
  border-radius: 1.5rem;
  border: none;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  box-shadow: var(--shadow-primary);
}

.btn-main:hover {
  transform: translateY(-2px);
  filter: brightness(1.1);
  box-shadow: 0 15px 30px -5px rgba(16, 185, 129, 0.4);
}

.btn-main:active { transform: scale(0.96); }

.btn-secondary {
  background: var(--secondary);
  color: white;
  font-weight: 700;
  padding: 1rem 1.5rem;
  border-radius: 1.25rem;
  box-shadow: var(--shadow-md);
}

/* --- Modern Input Styling --- */
.input-lux {
  background: #f8fafc;
  border: 2px solid transparent;
  border-radius: 1.25rem;
  padding: 1.1rem 1.5rem;
  font-family: 'Cairo', sans-serif;
  font-weight: 600;
  color: var(--secondary);
  width: 100%;
  transition: all 0.3s ease;
}

.input-lux:focus {
  background: white;
  border-color: var(--primary);
  box-shadow: 0 10px 20px -10px rgba(16, 185, 129, 0.1);
}

.input-lux::placeholder { color: #94a3b8; }

/* --- Cards & Containers --- */
.card-pro {
  background: white;
  border-radius: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  transition: all 0.3s ease;
}

.card-pro:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--primary-light);
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in { animation: fadeIn 0.5s ease forwards; }

.pulse-primary {
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.4); }
  70% { transform: scale(1.05); box-shadow: 0 0 0 15px rgba(16, 185, 129, 0); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }
}

/* --- Scrollbar Customization --- */
.no-scrollbar::-webkit-scrollbar { display: none; }

