const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'WALLET' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickup, setPickup] = useState<Village | null>(null);
  const [dropoff, setDropoff] = useState<Village | null>(null);
  const [category, setCategory] = useState<OrderCategory>('TAXI');
  const [vehicle, setVehicle] = useState<VehicleType>('TOKTOK');
  const [notes, setNotes] = useState('');
  const [loading, setLoading] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [aiOpen, setAiOpen] = useState(false);
  const [price, setPrice] = useState(0);

  useEffect(() => {
    if (pickup && dropoff) {
      const dist = calculateDistance(pickup.center.lat, pickup.center.lng, dropoff.center.lat, dropoff.center.lng);
      const mult = DEFAULT_PRICING.multipliers?.[vehicle] || 1;
      const calculated = Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * mult), DEFAULT_PRICING.minPrice);
      setPrice(calculated);
    }
  }, [pickup, dropoff, vehicle]);

  useEffect(() => {
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  const handleOrder = async () => {
    if (!pickup || !dropoff) return;
    setLoading(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category,
        pickup: { address: pickup.name, villageName: pickup.name, lat: pickup.center.lat, lng: pickup.center.lng },
        dropoff: { address: dropoff.name, villageName: dropoff.name, lat: dropoff.center.lat, lng: dropoff.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: vehicle,
        price, distance: 0, notes: notes.trim(), paymentMethod: 'CASH', operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full'
      });
      setNotes('');
    } catch (e) { alert('حدث خطأ في الاتصال'); } finally { setLoading(false); }
  };

  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="app-container">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div className="flex-1 bg-slate-100 flex flex-col relative overflow-hidden">
        <div className="absolute inset-0 opacity-20 flex items-center justify-center pointer-events-none">
          <MapPin className="h-64 w-64 text-emerald-500 animate-pulse" />
        </div>

        <div className="mt-auto rh-ui-panel p-8 space-y-10 animate-in no-scrollbar overflow-y-auto">
          <div className="bottom-sheet-grabber"></div>

          {!activeOrder ? (
            <div className="space-y-10 pb-10">
              <div className="flex justify-between items-center">
                 <div>
