                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-16 w-16 text-slate-300" />}
                        <div className="absolute bottom-3 right-3 bg-emerald-500 p-2 rounded-full border-4 border-white shadow-xl"><ShieldCheck className="h-4 w-4 text-white" /></div>
                      </div>
                      <div className="text-center">
                         <h4 className="text-4xl font-black text-slate-950 tracking-tighter">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-3 uppercase tracking-widest text-emerald-600 bg-emerald-50 px-8 py-2 rounded-full inline-block border border-emerald-100">كابتن {activeOrder.requestedVehicleType} • أشمون</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-6">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all">
                        <PhoneCall className="h-8 w-8" /> اتصال
                      </a>
                      <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-4 shadow-sm active:scale-95 transition-all">
                        <MessageCircle className="h-8 w-8" /> دردشة
                      </button>
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-[0_-20px_50px_rgba(0,0,0,0.12)]">
         {[
           {id: 'NEW', icon: <History className="rotate-180" />, label: 'طلب جديد'},
           {id: 'ACTIVITY', icon: <History />, label: 'نشاطي'},
           {id: 'MAP', icon: <MapIcon />, label: 'تتبع الخريطة'},
           {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 border border-emerald-100 shadow-inner' : ''}`}>
                {React.cloneElement(tab.icon as React.ReactElement, { className: "h-7 w-7" })}
              </div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, OrderCategory } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, Map as MapIcon, User as UserIcon, Home, 
  ShieldAlert, StickyNote, Coffee, Pill, Bot, Zap, Car,
  Plus, Minus, Crosshair
} from 'lucide-react';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

// Leaflet Global Access
declare var L: any;

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<number>(0);
  const [showChat, setShowChat] = useState(false);

  // Map Refs
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const watchId = useRef<number | null>(null);
  const driverMarker = useRef<any>(null);

  // تهيئة الخريطة
  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.298, 30.975], 13);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }
  }, []);

  // تتبع الموقع
  useEffect(() => {
    if (isOnline) {
      if ("geolocation" in navigator) {
        watchId.current = navigator.geolocation.watchPosition(
          (pos) => {
            const { latitude, longitude } = pos.coords;
            updateDoc(doc(db, "users", user.id), {
              location: { lat: latitude, lng: longitude, updatedAt: Date.now() }
            });

            if (mapInstance.current) {
               if (!driverMarker.current) {
                  const icon = L.divIcon({
                    html: `<div class="bg-slate-900 p-2 rounded-full border-4 border-white shadow-xl"><img src="https://img.icons8.com/fluency-systems-filled/48/10b981/bicycle.png" style="width:24px;height:24px;"/></div>`,
                    className: '', iconSize: [44,44], iconAnchor: [22,44]
                  });
                  driverMarker.current = L.marker([latitude, longitude], { icon }).addTo(mapInstance.current);
               } else {
                  driverMarker.current.setLatLng([latitude, longitude]);
               }
            }
          },
          (err) => console.error(err),
          { enableHighAccuracy: true }
        );
      }
    } else {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const handleSendOffer = async (order: Order) => {
    if (offerPrice <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: order.id, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 4.9, vehicleType: user.vehicleType || 'TOKTOK', price: offerPrice, createdAt: Date.now()
      });
      setShowOfferInput(null);
    } catch (e) { alert('فشل'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') {
     return <div className="p-12 text-center font-black">حسابك بانتظار التفعيل...</div>;
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout bg-slate-50">
      <div ref={mapContainerRef} className="rh-map-view">
         <div className="absolute top-8 right-8 z-50 flex flex-col gap-4">
            <button onClick={() => mapInstance.current.zoomIn()} className="map-control-btn"><Plus className="h-6 w-6" /></button>
            <button onClick={() => mapInstance.current.zoomOut()} className="map-control-btn"><Minus className="h-6 w-6" /></button>
            <button onClick={() => {
              if (driverMarker.current) mapInstance.current.setView(driverMarker.current.getLatLng(), 16, { animate: true });
            }} className="map-control-btn primary"><Crosshair className="h-6 w-6" /></button>
         </div>
      </div>

      <div className={`rh-ui-panel no-scrollbar px-6 space-y-8 pb-32 pt-8 animate-in fade-in overflow-y-auto ${activeView === 'MAP' ? 'translate-y-full' : ''}`}>
        <div className="bottom-sheet-grabber"></div>

        <div className={`p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
           <div>
              <h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'أنت نشط الآن' : 'أنت أوفلاين'}</h2>
              <p className="text-[10px] font-black opacity-60 mt-2 uppercase tracking-[0.3em]">مركبات أشمون النشطة</p>
           </div>
           <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2.5rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}>
              <Power className="h-10 w-10" />
           </button>
        </div>

        {activeOrder ? (
           <div className="bg-white rounded-[4rem] shadow-2xl border border-slate-100 p-10 space-y-10 animate-in zoom-in border-t-8 border-t-emerald-500">
              <div className="flex justify-between items-center">
                 <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
                 <p className="text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-lg opacity-30 font-bold uppercase">ج.م</span></p>
              </div>
              <div className="space-y-8">
                 <div className="flex gap-6 items-start">
                    <div className="bg-slate-50 p-5 rounded-3xl text-emerald-600 shadow-inner shrink-0"><MapPin className="h-8 w-8" /></div>
                    <div className="flex-1">
                       <p className="helper-text uppercase mb-2 tracking-widest">مسار الرحلة</p>
                       <p className="font-black text-2xl text-slate-950 leading-tight">{activeOrder.pickup?.villageName} ← {activeOrder.dropoff?.villageName}</p>
                    </div>
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-5 pt-4">
                 <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                 <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-50 text-slate-900 py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 active:scale-95 transition-all relative">
                    <MessageCircle className="h-7 w-7" /> دردشة
                 </button>
                 <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 transition-all">
                    {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد استلام الطلب' : 'تأكيد التوصيل والتحصيل'}
                 </button>
              </div>
           </div>
        ) : (
           <div className="space-y-6">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.4em] px-4">مشاوير بانتظارك ({availableOrders.length})</h3>
              {availableOrders.map(o => (
                 <div key={o.id} className="bg-white p-10 rounded-[4rem] border-2 border-slate-50 shadow-xl space-y-8 animate-in slide-in-from-bottom">
                    <div className="flex justify-between items-start">
                       <div className="space-y-2">
                          <p className="text-2xl font-black text-slate-950 leading-none">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p>
                       </div>
                       <div className="bg-slate-950 text-emerald-400 p-6 rounded-3xl font-black text-3xl shadow-2xl">
                          {o.price}
                       </div>
                    </div>
                    <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price); }} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                        <Zap className="h-6 w-6 text-emerald-400" /> تقديم عرض سعر
                    </button>
                 </div>
              ))}
           </div>
        )}
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 p-8 flex justify-around items-center z-[200] shadow-[0_-20px_50px_rgba(0,0,0,0.1)]">
         {[
           {id: 'HOME', icon: <Home />, label: 'الرئيسية'},
           {id: 'ACTIVITY', icon: <History />, label: 'سجلي'},
           {id: 'MAP', icon: <MapIcon />, label: 'الخريطة'},
           {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-[1.5rem] transition-all ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>
                 {React.cloneElement(tab.icon as React.ReactElement<any>, { className: 'h-7 w-7' })}
              </div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CourierDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory } from '../types';
import { OrderStatus, VehicleType } from '../types';

// Config
import { ASHMOUN_VILLAGES as STATIC_VILLAGES, DEFAULT_PRICING } from '../config/constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, DollarSign, Star,
  User as UserIcon, Map as MapIcon,
  Car, MessageCircle, Loader2,
  Bot, Heart, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall, ShieldCheck,
  Plus, Minus, Crosshair
} from 'lucide-react';

// Components
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import ChatView from '../components/ChatView';
import AIAssistant from '../components/AIAssistant';

// Leaflet Global Access
declare var L: any;

const VillageInput: React.FC<{
  label: string; selectedVillage: Village | null; onSelect: (v: Village) => void;
  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-[2.2rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-5">
          <span className={`text-xl font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl transition-transform group-active:scale-90`}>
            {React.cloneElement(icon as React.ReactElement, { className: "h-6 w-6" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[100] max-h-80 overflow-hidden flex flex-col animate-in zoom-in duration-300">
          <div className="p-5 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-5 px-6 text-base font-black outline-none focus:ring-4 focus:ring-emerald-500/5" placeholder="ابحث عن اسم القرية..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-6 py-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center group transition-all mb-2">
                <span className="text-lg font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [orderNotes, setOrderNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [allVillages, setAllVillages] = useState<Village[]>(STATIC_VILLAGES);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const driverMarker = useRef<any>(null);
  const pickupMarker = useRef<any>(null);
  const dropoffMarker = useRef<any>(null);
  const routeLine = useRef<any>(null);

  // مراقبة موقع الكابتن
  useEffect(() => {
    if (activeOrder && activeOrder.driverId && ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(activeOrder.status)) {
      const unsubDriver = onSnapshot(doc(db, "users", activeOrder.driverId), (docSnap) => {
        if (docSnap.exists()) {
          const driverData = docSnap.data() as User;
          if (driverData.location && mapInstance.current) {
            const { lat, lng } = driverData.location;
            if (!driverMarker.current) {
              const icon = L.divIcon({
                html: `<div class="bg-emerald-600 p-2 rounded-full border-4 border-white shadow-xl driver-marker animate-bounce"><img src="https://img.icons8.com/fluency-systems-filled/48/FFFFFF/bicycle.png" style="width:24px;height:24px;"/></div>`,
                className: 'custom-div-icon',
                iconSize: [44, 44],
                iconAnchor: [22, 44]
              });
              driverMarker.current = L.marker([lat, lng], { icon }).addTo(mapInstance.current);
            } else {
              driverMarker.current.setLatLng([lat, lng]);
            }
            if (activeOrder.status === OrderStatus.ACCEPTED || activeView === 'MAP') {
              mapInstance.current.panTo([lat, lng], { animate: true });
            }
          }
        }
      });
      return () => unsubDriver();
    } else if (driverMarker.current && mapInstance.current) {
      mapInstance.current.removeLayer(driverMarker.current);
      driverMarker.current = null;
    }
  }, [activeOrder?.id, activeOrder?.driverId, activeOrder?.status, activeView]);

  // تهيئة الخريطة
  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.298, 30.975], 13);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }

    if (mapInstance.current) {
        const markers: any[] = [];
        if (pickupMarker.current) mapInstance.current.removeLayer(pickupMarker.current);
        if (dropoffMarker.current) mapInstance.current.removeLayer(dropoffMarker.current);
        if (routeLine.current) mapInstance.current.removeLayer(routeLine.current);

        const currentPickup = activeOrder ? activeOrder.pickup : (pickupVillage ? { lat: pickupVillage.center.lat, lng: pickupVillage.center.lng } : null);
        const currentDropoff = activeOrder ? activeOrder.dropoff : (dropoffVillage ? { lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng } : null);

        if (currentPickup) {
            const icon = L.divIcon({ html: `<div class="bg-emerald-500 w-4 h-4 rounded-full border-4 border-white shadow-lg"></div>`, className: '', iconSize: [16,16] });
            pickupMarker.current = L.marker([currentPickup.lat, currentPickup.lng], { icon }).addTo(mapInstance.current);
            markers.push([currentPickup.lat, currentPickup.lng]);
        }
        if (currentDropoff) {
            const icon = L.divIcon({ html: `<div class="bg-rose-500 w-6 h-6 rounded-full border-4 border-white shadow-lg flex items-center justify-center text-white"><img src="https://img.icons8.com/material-rounded/24/FFFFFF/marker.png" style="width:12px;height:12px;"/></div>`, className: '', iconSize: [24,24] });
            dropoffMarker.current = L.marker([currentDropoff.lat, currentDropoff.lng], { icon }).addTo(mapInstance.current);
            markers.push([currentDropoff.lat, currentDropoff.lng]);
        }

        if (currentPickup && currentDropoff) {
            routeLine.current = L.polyline([
                [currentPickup.lat, currentPickup.lng],
                [currentDropoff.lat, currentDropoff.lng]
            ], { color: '#10b981', weight: 4, dashArray: '10, 10', opacity: 0.6 }).addTo(mapInstance.current);
        }

        if (markers.length > 1) {
            mapInstance.current.fitBounds(markers, { padding: [80, 80], animate: true });
        } else if (markers.length === 1) {
            mapInstance.current.setView(markers[0], 15, { animate: true });
        }
    }
  }, [activeOrder, pickupVillage, dropoffVillage, activeView]);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleLocateMe = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        const { latitude, longitude } = pos.coords;
        mapInstance.current.setView([latitude, longitude], 16, { animate: true });
      });
    }
  };

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        notes: orderNotes.trim(), paymentMethod: 'CASH'
      });
      setOrderNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div ref={mapContainerRef} className="rh-map-view absolute inset-0 z-0">
         <div className="absolute top-8 right-8 z-50 flex flex-col gap-4">
            <button onClick={() => mapInstance.current.zoomIn()} className="map-control-btn"><Plus className="h-6 w-6" /></button>
            <button onClick={() => mapInstance.current.zoomOut()} className="map-control-btn"><Minus className="h-6 w-6" /></button>
            <button onClick={handleLocateMe} className="map-control-btn primary"><Crosshair className="h-6 w-6" /></button>
         </div>

         <div className="absolute top-8 left-8 z-50">
            <button onClick={() => setAiOpen(true)} className="map-control-btn">
               <Bot className="h-6 w-6 text-emerald-600 animate-pulse" />
            </button>
         </div>
      </div>

      {/* اللوحة السفلية (Panel) - تختفي عند عرض الخريطة بالكامل */}
      <div className={`rh-ui-panel no-scrollbar transition-transform duration-500 ${activeView === 'MAP' ? 'translate-y-full' : 'translate-y-0'}`}>
        <div className="bottom-sheet-grabber"></div>
        <div className="p-8 md:p-12 space-y-12">
          {!activeOrder ? (
            <>
              <div className="space-y-1">
                 <h2 className="text-4xl font-black text-slate-950 tracking-tighter">إلى أين نذهب؟</h2>
                 <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">تغطية شاملة لكافة قرى أشمون</p>
              </div>

              <div className="space-y-12">
                <div className="grid grid-cols-3 gap-5">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <Coffee /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-2xl scale-110' : 'bg-slate-50 border-transparent text-slate-400 opacity-60'}`}>
                       {React.cloneElement(cat.icon as React.ReactElement, { className: "h-8 w-8" })}
                       <span className="text-[11px] font-black uppercase tracking-wider">{cat.label}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-6 relative">
                  <VillageInput label="نقطة الانطلاق" helper="أين سيتسلمك الكابتن؟" selectedVillage={pickupVillage} onSelect={setPickupVillage} icon={<MapPin />} iconBg="bg-emerald-500" placeholder="موقعك الحالي" availableVillages={STATIC_VILLAGES} />
                  <div className="absolute right-[45px] top-[115px] bottom-[55px] w-0.5 bg-slate-100 border-r-2 border-dashed z-0"></div>
                  <VillageInput label="نقطة الوصول" helper="أين وجهتك النهائية؟" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} icon={<Check />} iconBg="bg-rose-500" placeholder="الوجهة" availableVillages={STATIC_VILLAGES} />
                </div>

                <div className="space-y-5">
                  <label className="label-strong px-2">وسيلة النقل</label>
                  <div className="grid grid-cols-3 gap-4">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v.id as VehicleType)} className={`py-7 rounded-[2.2rem] flex flex-col items-center gap-3 border-2 transition-all ${selectedVehicle === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-xl scale-110' : 'bg-slate-50 border-transparent text-slate-300 opacity-60'}`}>
                        {React.cloneElement(v.icon as React.ReactElement, { className: "h-7 w-7" })}
                        <span className="text-[10px] font-black uppercase tracking-widest">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-[#10b981] text-white py-8 rounded-[2.8rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                   {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin" /> : 'اطلب مشوارك الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-12 text-center">
                   <div className="relative py-10">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div>
                      </div>
                      <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block">
                        <Navigation2 className="h-24 w-24 text-emerald-600 animate-pulse" />
                      </div>
                   </div>
                   <div className="space-y-4">
                      <h2 className="text-4xl font-black text-slate-950 tracking-tighter">جاري البحث عن كابتن...</h2>
                      <p className="helper-text text-xl">سوف تظهر العروض من كباتن أشمون هنا</p>
                   </div>
                   <div className="space-y-6 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-8 rounded-[3.5rem] flex justify-between items-center border-4 border-slate-100 hover:border-emerald-500 transition-all shadow-xl">
                           <div className="flex items-center gap-6">
                              <div className="w-20 h-20 bg-slate-950 text-emerald-400 rounded-3xl flex items-center justify-center font-black text-3xl shadow-2xl">
                                {(offer.driverName || 'ك')[0]}
                              </div>
                              <div className="text-right">
                                 <p className="font-black text-slate-950 text-2xl leading-none mb-2">{offer.driverName}</p>
                                 <div className="flex items-center gap-2 text-amber-500 font-bold text-base bg-amber-50 px-4 py-1.5 rounded-full">
                                   <Star className="h-5 w-5 fill-amber-400" /> {offer.driverRating}
                                 </div>
                              </div>
                           </div>
                           <div className="text-center space-y-3">
                              <p className="text-4xl font-black text-emerald-700">{offer.price} <span className="text-xs font-bold">ج.م</span></p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول</button>
                           </div>
                        </div>
                      ))}
                   </div>
                   <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-sm uppercase tracking-widest py-8 hover:underline">إلغاء الطلب</button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-12 text-right">
                   <div className="bg-emerald-600 p-10 rounded-[4rem] text-white flex justify-between items-center shadow-2xl animate-status-active">
                      <div className="text-right">
                         <p className="text-[11px] font-black opacity-60 uppercase mb-2 tracking-[0.2em]">تتبع مباشر للرحلة</p>
                         <h3 className="text-3xl font-black tracking-tight leading-none">الكابتن في طريقه إليك</h3>
                      </div>
                      <div className="bg-white/20 p-6 rounded-full backdrop-blur-xl">
                        <Navigation2 className="h-10 w-10 animate-bounce" />
                      </div>
                   </div>

                   <div className="flex flex-col items-center gap-8">
                      <div className="w-36 h-36 bg-slate-100 rounded-[3.5rem] flex items-center justify-center border-8 border-white shadow-2xl relative overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-16 w-16 text-slate-300" />}
                        <div className="absolute bottom-3 right-3 bg-emerald-500 p-2 rounded-full border-4 border-white shadow-xl"><ShieldCheck className="h-4 w-4 text-white" /></div>
                      </div>
                      <div className="text-center">
                         <h4 className="text-4xl font-black text-slate-950 tracking-tighter">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-3 uppercase tracking-widest text-emerald-600 bg-emerald-50 px-8 py-2 rounded-full inline-block border border-emerald-100">كابتن {activeOrder.requestedVehicleType} • أشمون</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-6">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all">
                        <PhoneCall className="h-8 w-8" /> اتصال
                      </a>
                      <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-4 shadow-sm active:scale-95 transition-all">
                        <MessageCircle className="h-8 w-8" /> دردشة
                      </button>
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-[0_-20px_50px_rgba(0,0,0,0.12)]">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب جديد'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'تتبع الخريطة'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 border border-emerald-100 shadow-inner' : ''}`}>
                {tab.icon}
              </div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, OrderCategory } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, Map as MapIcon, User as UserIcon, Home, 
  ShieldAlert, StickyNote, Coffee, Pill, Bot, Zap, Car,
  Plus, Minus, Crosshair
} from 'lucide-react';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

// Leaflet Global Access
declare var L: any;

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<number>(0);
  const [showChat, setShowChat] = useState(false);

  // Map Refs
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const watchId = useRef<number | null>(null);
  const driverMarker = useRef<any>(null);

  // تهيئة الخريطة
  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.298, 30.975], 13);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }
  }, []);

  // تتبع الموقع المباشر في Firestore
  useEffect(() => {
    if (isOnline) {
      if ("geolocation" in navigator) {
        watchId.current = navigator.geolocation.watchPosition(
          (pos) => {
            const { latitude, longitude } = pos.coords;
            updateDoc(doc(db, "users", user.id), {
              location: { lat: latitude, lng: longitude, updatedAt: Date.now() }
            });

            if (mapInstance.current) {
               if (!driverMarker.current) {
                  const icon = L.divIcon({
                    html: `<div class="bg-slate-900 p-2 rounded-full border-4 border-white shadow-xl"><img src="https://img.icons8.com/fluency-systems-filled/48/10b981/bicycle.png" style="width:24px;height:24px;"/></div>`,
                    className: '', iconSize: [44,44], iconAnchor: [22,44]
                  });
                  driverMarker.current = L.marker([latitude, longitude], { icon }).addTo(mapInstance.current);
               } else {
                  driverMarker.current.setLatLng([latitude, longitude]);
               }
               // إذا كان الكابتن يفتح تبويب الخريطة، نركز الخريطة عليه
               if (activeView === 'MAP') {
                 mapInstance.current.panTo([latitude, longitude], { animate: true });
               }
            }
          },
          (err) => console.error("Geolocation error:", err),
          { enableHighAccuracy: true }
        );
      }
    } else {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id, activeView]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const handleSendOffer = async (order: Order) => {
    if (offerPrice <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: order.id, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 4.9, vehicleType: user.vehicleType || 'TOKTOK', price: offerPrice, createdAt: Date.now()
      });
      setShowOfferInput(null);
    } catch (e) { alert('فشل'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') {
     return (
       <div className="p-12 text-center font-black space-y-4">
         <ShieldAlert className="h-16 w-16 mx-auto text-emerald-600 animate-bounce" />
         <h2 className="text-2xl">حسابك بانتظار التفعيل...</h2>
         <p className="text-slate-400">يرجى التواصل مع الإدارة للبدء في العمل.</p>
       </div>
     );
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <div ref={mapContainerRef} className="rh-map-view absolute inset-0 z-0">
         <div className="absolute top-8 right-8 z-50 flex flex-col gap-4">
            <button onClick={() => mapInstance.current.zoomIn()} className="map-control-btn"><Plus className="h-6 w-6" /></button>
            <button onClick={() => mapInstance.current.zoomOut()} className="map-control-btn"><Minus className="h-6 w-6" /></button>
            <button onClick={() => {
              if (driverMarker.current) mapInstance.current.setView(driverMarker.current.getLatLng(), 16, { animate: true });
            }} className="map-control-btn primary"><Crosshair className="h-6 w-6" /></button>
         </div>
      </div>

      <div className={`rh-ui-panel no-scrollbar px-6 space-y-8 pb-32 pt-8 animate-in fade-in overflow-y-auto transition-transform duration-500 ${activeView === 'MAP' ? 'translate-y-full' : 'translate-y-0'}`}>
        <div className="bottom-sheet-grabber"></div>

        <div className={`p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
           <div>
              <h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'أنت نشط الآن' : 'أنت أوفلاين'}</h2>
              <p className="text-[10px] font-black opacity-60 mt-2 uppercase tracking-[0.3em]">مركبات أشمون النشطة</p>
           </div>
           <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2.5rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}>
              <Power className="h-10 w-10" />
           </button>
        </div>

        {activeOrder ? (
           <div className="bg-white rounded-[4rem] shadow-2xl border border-slate-100 p-10 space-y-10 animate-in zoom-in border-t-8 border-t-emerald-500">
              <div className="flex justify-between items-center">
                 <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
                 <p className="text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-lg opacity-30 font-bold uppercase">ج.م</span></p>
              </div>
              <div className="space-y-8">
                 <div className="flex gap-6 items-start">
                    <div className="bg-slate-50 p-5 rounded-3xl text-emerald-600 shadow-inner shrink-0"><MapPin className="h-8 w-8" /></div>
                    <div className="flex-1">
                       <p className="helper-text uppercase mb-2 tracking-widest">مسار الرحلة</p>
                       <p className="font-black text-2xl text-slate-950 leading-tight">{activeOrder.pickup?.villageName} ← {activeOrder.dropoff?.villageName}</p>
                    </div>
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-5 pt-4">
                 <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                 <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-50 text-slate-900 py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 active:scale-95 transition-all relative">
                    <MessageCircle className="h-7 w-7" /> دردشة
                 </button>
                 <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 transition-all">
                    {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد استلام الطلب' : 'تأكيد التوصيل والتحصيل'}
                 </button>
              </div>
           </div>
        ) : (
           <div className="space-y-6">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.4em] px-4">مشاوير بانتظارك ({availableOrders.length})</h3>
              {availableOrders.map(o => (
                 <div key={o.id} className="bg-white p-10 rounded-[4rem] border-2 border-slate-50 shadow-xl space-y-8 animate-in slide-in-from-bottom">
                    <div className="flex justify-between items-start">
                       <div className="space-y-2">
                          <p className="text-2xl font-black text-slate-950 leading-none">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p>
                          <p className="text-[10px] font-black text-emerald-600 mt-2 bg-emerald-50 inline-block px-4 py-1.5 rounded-full">{o.requestedVehicleType}</p>
                       </div>
                       <div className="bg-slate-950 text-emerald-400 p-6 rounded-3xl font-black text-3xl shadow-2xl">
                          {o.price}
                       </div>
                    </div>
                    <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price); }} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                        <Zap className="h-6 w-6 text-emerald-400" /> تقديم عرض سعر
                    </button>
                 </div>
              ))}
              {availableOrders.length === 0 && (
                 <div className="py-24 text-center text-slate-300 font-black border-4 border-dashed border-slate-100 rounded-[4rem] bg-white">
                    <Bot className="h-16 w-16 mx-auto mb-6 opacity-20" />
                    <p className="tracking-widest uppercase">بانتظار مشاوير جديدة...</p>
                 </div>
              )}
           </div>
        )}
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 p-8 flex justify-around items-center z-[200] shadow-[0_-20px_50px_rgba(0,0,0,0.1)]">
         {[
           {id: 'HOME', icon: <Home className="h-7 w-7" />, label: 'الرئيسية'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'سجلي'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'الخريطة'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-[1.5rem] transition-all ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>
                 {tab.icon}
              </div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CourierDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory } from '../types';
import { OrderStatus, VehicleType } from '../types';

// Config
import { ASHMOUN_VILLAGES as STATIC_VILLAGES, DEFAULT_PRICING } from '../config/constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, DollarSign, Star,
  User as UserIcon, Map as MapIcon,
  Car, MessageCircle, Loader2,
  Bot, Heart, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall, ShieldCheck,
  Plus, Minus, Crosshair
} from 'lucide-react';

// Components
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import ChatView from '../components/ChatView';
import AIAssistant from '../components/AIAssistant';

// Leaflet Global Access
declare var L: any;

const VillageInput: React.FC<{
  label: string; selectedVillage: Village | null; onSelect: (v: Village) => void;
  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-[2.2rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-5">
          <span className={`text-xl font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl transition-transform group-active:scale-90`}>
            {React.cloneElement(icon as React.ReactElement, { className: "h-6 w-6" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[100] max-h-80 overflow-hidden flex flex-col animate-in zoom-in duration-300">
          <div className="p-5 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-5 px-6 text-base font-black outline-none focus:ring-4 focus:ring-emerald-500/5" placeholder="ابحث عن اسم القرية..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-6 py-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center group transition-all mb-2">
                <span className="text-lg font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [orderNotes, setOrderNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const driverMarker = useRef<any>(null);
  const pickupMarker = useRef<any>(null);
  const dropoffMarker = useRef<any>(null);
  const routeLine = useRef<any>(null);

  // تتبع موقع الكابتن المباشر
  useEffect(() => {
    if (activeOrder && activeOrder.driverId && ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(activeOrder.status)) {
      const unsubDriver = onSnapshot(doc(db, "users", activeOrder.driverId), (docSnap) => {
        if (docSnap.exists()) {
          const driverData = docSnap.data() as User;
          if (driverData.location && mapInstance.current) {
            const { lat, lng } = driverData.location;
            if (!driverMarker.current) {
              const icon = L.divIcon({
                html: `<div class="bg-emerald-600 p-2 rounded-full border-4 border-white shadow-xl driver-marker animate-bounce"><img src="https://img.icons8.com/fluency-systems-filled/48/FFFFFF/bicycle.png" style="width:24px;height:24px;"/></div>`,
                className: 'custom-div-icon',
                iconSize: [44, 44],
                iconAnchor: [22, 44]
              });
              driverMarker.current = L.marker([lat, lng], { icon }).addTo(mapInstance.current);
            } else {
              driverMarker.current.setLatLng([lat, lng]);
            }
            if (activeView === 'MAP') {
              mapInstance.current.panTo([lat, lng], { animate: true });
            }
          }
        }
      });
      return () => unsubDriver();
    } else if (driverMarker.current && mapInstance.current) {
      mapInstance.current.removeLayer(driverMarker.current);
      driverMarker.current = null;
    }
  }, [activeOrder?.id, activeOrder?.driverId, activeOrder?.status, activeView]);

  // تهيئة الخريطة ورسم المسارات
  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.298, 30.975], 13);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }

    if (mapInstance.current) {
        const markers: any[] = [];
        if (pickupMarker.current) mapInstance.current.removeLayer(pickupMarker.current);
        if (dropoffMarker.current) mapInstance.current.removeLayer(dropoffMarker.current);
        if (routeLine.current) mapInstance.current.removeLayer(routeLine.current);

        const currentPickup = activeOrder ? activeOrder.pickup : (pickupVillage ? { lat: pickupVillage.center.lat, lng: pickupVillage.center.lng } : null);
        const currentDropoff = activeOrder ? activeOrder.dropoff : (dropoffVillage ? { lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng } : null);

        if (currentPickup) {
            const icon = L.divIcon({ html: `<div class="bg-emerald-500 w-4 h-4 rounded-full border-4 border-white shadow-lg"></div>`, className: '', iconSize: [16,16] });
            pickupMarker.current = L.marker([currentPickup.lat, currentPickup.lng], { icon }).addTo(mapInstance.current);
            markers.push([currentPickup.lat, currentPickup.lng]);
        }
        if (currentDropoff) {
            const icon = L.divIcon({ html: `<div class="bg-rose-500 w-6 h-6 rounded-full border-4 border-white shadow-lg flex items-center justify-center text-white"><img src="https://img.icons8.com/material-rounded/24/FFFFFF/marker.png" style="width:12px;height:12px;"/></div>`, className: '', iconSize: [24,24] });
            dropoffMarker.current = L.marker([currentDropoff.lat, currentDropoff.lng], { icon }).addTo(mapInstance.current);
            markers.push([currentDropoff.lat, currentDropoff.lng]);
        }

        if (currentPickup && currentDropoff) {
            routeLine.current = L.polyline([
                [currentPickup.lat, currentPickup.lng],
                [currentDropoff.lat, currentDropoff.lng]
            ], { color: '#10b981', weight: 4, dashArray: '10, 10', opacity: 0.6 }).addTo(mapInstance.current);
        }

        if (markers.length > 1) {
            mapInstance.current.fitBounds(markers, { padding: [80, 80], animate: true });
        } else if (markers.length === 1) {
            mapInstance.current.setView(markers[0], 15, { animate: true });
        }
    }
  }, [activeOrder, pickupVillage, dropoffVillage, activeView]);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleLocateMe = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        const { latitude, longitude } = pos.coords;
        mapInstance.current.setView([latitude, longitude], 16, { animate: true });
      });
    }
  };

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        notes: orderNotes.trim(), paymentMethod: 'CASH'
      });
      setOrderNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div ref={mapContainerRef} className="rh-map-view absolute inset-0 z-0">
         <div className="absolute top-8 right-8 z-50 flex flex-col gap-4">
            <button onClick={() => mapInstance.current.zoomIn()} className="map-control-btn"><Plus className="h-6 w-6" /></button>
            <button onClick={() => mapInstance.current.zoomOut()} className="map-control-btn"><Minus className="h-6 w-6" /></button>
            <button onClick={handleLocateMe} className="map-control-btn primary"><Crosshair className="h-6 w-6" /></button>
         </div>

         <div className="absolute top-8 left-8 z-50">
            <button onClick={() => setAiOpen(true)} className="map-control-btn">
               <Bot className="h-6 w-6 text-emerald-600 animate-pulse" />
            </button>
         </div>
      </div>

      {/* اللوحة السفلية: تختفي بالكامل عند اختيار تبويب الخريطة (MAP) لرؤية تتبع المشوار بوضوح */}
      <div className={`rh-ui-panel no-scrollbar transition-transform duration-500 z-[100] ${activeView === 'MAP' ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>
        <div className="bottom-sheet-grabber"></div>
        <div className="p-8 md:p-12 space-y-12">
          {!activeOrder ? (
            <>
              <div className="space-y-1">
                 <h2 className="text-4xl font-black text-slate-950 tracking-tighter">إلى أين نذهب؟</h2>
                 <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">تغطية شاملة لكافة قرى أشمون</p>
              </div>

              <div className="space-y-12">
                <div className="grid grid-cols-3 gap-5">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <Coffee /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-2xl scale-110' : 'bg-slate-50 border-transparent text-slate-400 opacity-60'}`}>
                       {React.cloneElement(cat.icon as React.ReactElement, { className: "h-8 w-8" })}
                       <span className="text-[11px] font-black uppercase tracking-wider">{cat.label}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-6 relative">
                  <VillageInput label="نقطة الانطلاق" helper="أين سيتسلمك الكابتن؟" selectedVillage={pickupVillage} onSelect={setPickupVillage} icon={<MapPin />} iconBg="bg-emerald-500" placeholder="موقعك الحالي" availableVillages={STATIC_VILLAGES} />
                  <div className="absolute right-[45px] top-[115px] bottom-[55px] w-0.5 bg-slate-100 border-r-2 border-dashed z-0"></div>
                  <VillageInput label="نقطة الوصول" helper="أين وجهتك النهائية؟" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} icon={<Check />} iconBg="bg-rose-500" placeholder="الوجهة" availableVillages={STATIC_VILLAGES} />
                </div>

                <div className="space-y-5">
                  <label className="label-strong px-2">وسيلة النقل</label>
                  <div className="grid grid-cols-3 gap-4">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v.id as VehicleType)} className={`py-7 rounded-[2.2rem] flex flex-col items-center gap-3 border-2 transition-all ${selectedVehicle === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-xl scale-110' : 'bg-slate-50 border-transparent text-slate-300 opacity-60'}`}>
                        {React.cloneElement(v.icon as React.ReactElement, { className: "h-7 w-7" })}
                        <span className="text-[10px] font-black uppercase tracking-widest">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-[#10b981] text-white py-8 rounded-[2.8rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                   {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin" /> : 'اطلب مشوارك الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-12 text-center">
                   <div className="relative py-10">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div>
                      </div>
                      <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block">
                        <Navigation2 className="h-24 w-24 text-emerald-600 animate-pulse" />
                      </div>
                   </div>
                   <div className="space-y-4">
                      <h2 className="text-4xl font-black text-slate-950 tracking-tighter">جاري البحث عن كابتن...</h2>
                      <p className="helper-text text-xl">سوف تظهر العروض من كباتن أشمون هنا</p>
                   </div>
                   <div className="space-y-6 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-8 rounded-[3.5rem] flex justify-between items-center border-4 border-slate-100 hover:border-emerald-500 transition-all shadow-xl">
                           <div className="flex items-center gap-6">
                              <div className="w-20 h-20 bg-slate-950 text-emerald-400 rounded-3xl flex items-center justify-center font-black text-3xl shadow-2xl">
                                {(offer.driverName || 'ك')[0]}
                              </div>
                              <div className="text-right">
                                 <p className="font-black text-slate-950 text-2xl leading-none mb-2">{offer.driverName}</p>
                                 <div className="flex items-center gap-2 text-amber-500 font-bold text-base bg-amber-50 px-4 py-1.5 rounded-full">
                                   <Star className="h-5 w-5 fill-amber-400" /> {offer.driverRating}
                                 </div>
                              </div>
                           </div>
                           <div className="text-center space-y-3">
                              <p className="text-4xl font-black text-emerald-700">{offer.price} <span className="text-xs font-bold">ج.م</span></p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول</button>
                           </div>
                        </div>
                      ))}
                   </div>
                   <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-sm uppercase tracking-widest py-8 hover:underline">إلغاء الطلب</button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-12 text-right">
                   <div className="bg-emerald-600 p-10 rounded-[4rem] text-white flex justify-between items-center shadow-2xl animate-status-active">
                      <div className="text-right">
                         <p className="text-[11px] font-black opacity-60 uppercase mb-2 tracking-[0.2em]">تتبع مباشر للرحلة</p>
                         <h3 className="text-3xl font-black tracking-tight leading-none">الكابتن في طريقه إليك</h3>
                      </div>
                      <div className="bg-white/20 p-6 rounded-full backdrop-blur-xl">
                        <Navigation2 className="h-10 w-10 animate-bounce" />
                      </div>
                   </div>

                   <div className="flex flex-col items-center gap-8">
                      <div className="w-36 h-36 bg-slate-100 rounded-[3.5rem] flex items-center justify-center border-8 border-white shadow-2xl relative overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-16 w-16 text-slate-300" />}
                        <div className="absolute bottom-3 right-3 bg-emerald-500 p-2 rounded-full border-4 border-white shadow-xl"><ShieldCheck className="h-4 w-4 text-white" /></div>
                      </div>
                      <div className="text-center">
                         <h4 className="text-4xl font-black text-slate-950 tracking-tighter">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-3 uppercase tracking-widest text-emerald-600 bg-emerald-50 px-8 py-2 rounded-full inline-block border border-emerald-100">كابتن {activeOrder.requestedVehicleType} • أشمون</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-6">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all">
                        <PhoneCall className="h-8 w-8" /> اتصال
                      </a>
                      <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-4 shadow-sm active:scale-95 transition-all">
                        <MessageCircle className="h-8 w-8" /> دردشة
                      </button>
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-[0_-20px_50px_rgba(0,0,0,0.12)]">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب جديد'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'خريطة التتبع'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 border border-emerald-100 shadow-inner' : ''}`}>
                {tab.icon}
              </div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, OrderCategory } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, Map as MapIcon, User as UserIcon, Home, 
  ShieldAlert, StickyNote, Coffee, Pill, Bot, Zap, Car,
  Plus, Minus, Crosshair
} from 'lucide-react';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

// Leaflet Global Access
declare var L: any;

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<number>(0);
  const [showChat, setShowChat] = useState(false);

  // Map Refs
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const watchId = useRef<number | null>(null);
  const driverMarker = useRef<any>(null);

  // تهيئة الخريطة
  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.298, 30.975], 13);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }
  }, []);

  // تتبع الموقع المباشر وتحديثه في Firestore
  useEffect(() => {
    if (isOnline) {
      if ("geolocation" in navigator) {
        watchId.current = navigator.geolocation.watchPosition(
          (pos) => {
            const { latitude, longitude } = pos.coords;
            updateDoc(doc(db, "users", user.id), {
              location: { lat: latitude, lng: longitude, updatedAt: Date.now() }
            });

            if (mapInstance.current) {
               if (!driverMarker.current) {
                  const icon = L.divIcon({
                    html: `<div class="bg-slate-900 p-2 rounded-full border-4 border-white shadow-xl"><img src="https://img.icons8.com/fluency-systems-filled/48/10b981/bicycle.png" style="width:24px;height:24px;"/></div>`,
                    className: '', iconSize: [44,44], iconAnchor: [22,44]
                  });
                  driverMarker.current = L.marker([latitude, longitude], { icon }).addTo(mapInstance.current);
               } else {
                  driverMarker.current.setLatLng([latitude, longitude]);
               }
               // إذا كان الكابتن في تبويب الخريطة، نركز العرض عليه
               if (activeView === 'MAP') {
                 mapInstance.current.panTo([latitude, longitude], { animate: true });
               }
            }
          },
          (err) => console.error("Geolocation error:", err),
          { enableHighAccuracy: true }
        );
      }
    } else {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id, activeView]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const handleSendOffer = async (order: Order) => {
    if (offerPrice <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: order.id, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 4.9, vehicleType: user.vehicleType || 'TOKTOK', price: offerPrice, createdAt: Date.now()
      });
      setShowOfferInput(null);
    } catch (e) { alert('فشل'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') {
     return (
       <div className="p-12 text-center font-black space-y-4">
         <ShieldAlert className="h-16 w-16 mx-auto text-emerald-600 animate-bounce" />
         <h2 className="text-2xl">حسابك بانتظار التفعيل...</h2>
         <p className="text-slate-400">يرجى التواصل مع الإدارة للبدء في العمل.</p>
       </div>
     );
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <div ref={mapContainerRef} className="rh-map-view absolute inset-0 z-0">
         <div className="absolute top-8 right-8 z-50 flex flex-col gap-4">
            <button onClick={() => mapInstance.current.zoomIn()} className="map-control-btn"><Plus className="h-6 w-6" /></button>
            <button onClick={() => mapInstance.current.zoomOut()} className="map-control-btn"><Minus className="h-6 w-6" /></button>
            <button onClick={() => {
              if (driverMarker.current) mapInstance.current.setView(driverMarker.current.getLatLng(), 16, { animate: true });
            }} className="map-control-btn primary"><Crosshair className="h-6 w-6" /></button>
         </div>
      </div>

      <div className={`rh-ui-panel no-scrollbar px-6 space-y-8 pb-32 pt-8 animate-in fade-in overflow-y-auto transition-transform duration-500 z-[100] ${activeView === 'MAP' ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>
        <div className="bottom-sheet-grabber"></div>

        <div className={`p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
           <div>
              <h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'أنت نشط الآن' : 'أنت أوفلاين'}</h2>
              <p className="text-[10px] font-black opacity-60 mt-2 uppercase tracking-[0.3em]">مركبات أشمون النشطة</p>
           </div>
           <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2.5rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}>
              <Power className="h-10 w-10" />
           </button>
        </div>

        {activeOrder ? (
           <div className="bg-white rounded-[4rem] shadow-2xl border border-slate-100 p-10 space-y-10 animate-in zoom-in border-t-8 border-t-emerald-500">
              <div className="flex justify-between items-center">
                 <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
                 <p className="text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-lg opacity-30 font-bold uppercase">ج.م</span></p>
              </div>
              <div className="space-y-8">
                 <div className="flex gap-6 items-start">
                    <div className="bg-slate-50 p-5 rounded-3xl text-emerald-600 shadow-inner shrink-0"><MapPin className="h-8 w-8" /></div>
                    <div className="flex-1">
                       <p className="helper-text uppercase mb-2 tracking-widest">مسار الرحلة</p>
                       <p className="font-black text-2xl text-slate-950 leading-tight">{activeOrder.pickup?.villageName} ← {activeOrder.dropoff?.villageName}</p>
                    </div>
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-5 pt-4">
                 <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                 <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-50 text-slate-900 py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 active:scale-95 transition-all relative">
                    <MessageCircle className="h-7 w-7" /> دردشة
                 </button>
                 <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 transition-all">
                    {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد استلام الطلب' : 'تأكيد التوصيل والتحصيل'}
                 </button>
              </div>
           </div>
        ) : (
           <div className="space-y-6">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.4em] px-4">مشاوير بانتظارك ({availableOrders.length})</h3>
              {availableOrders.map(o => (
                 <div key={o.id} className="bg-white p-10 rounded-[4rem] border-2 border-slate-50 shadow-xl space-y-8 animate-in slide-in-from-bottom">
                    <div className="flex justify-between items-start">
                       <div className="space-y-2">
                          <p className="text-2xl font-black text-slate-950 leading-none">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p>
                          <p className="text-[10px] font-black text-emerald-600 mt-2 bg-emerald-50 inline-block px-4 py-1.5 rounded-full">{o.requestedVehicleType}</p>
                       </div>
                       <div className="bg-slate-950 text-emerald-400 p-6 rounded-3xl font-black text-3xl shadow-2xl">
                          {o.price}
                       </div>
                    </div>
                    <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price); }} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                        <Zap className="h-6 w-6 text-emerald-400" /> تقديم عرض سعر
                    </button>
                 </div>
              ))}
              {availableOrders.length === 0 && (
                 <div className="py-24 text-center text-slate-300 font-black border-4 border-dashed border-slate-100 rounded-[4rem] bg-white">
                    <Bot className="h-16 w-16 mx-auto mb-6 opacity-20" />
                    <p className="tracking-widest uppercase">بانتظار مشاوير جديدة...</p>
                 </div>
              )}
           </div>
        )}
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 p-8 flex justify-around items-center z-[200] shadow-[0_-20px_50px_rgba(0,0,0,0.1)]">
         {[
           {id: 'HOME', icon: <Home className="h-7 w-7" />, label: 'الرئيسية'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'سجلي'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'الخريطة'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-[1.5rem] transition-all ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>
                 {tab.icon}
              </div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CourierDashboard;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --brand-emerald: #10b981;
  --brand-emerald-deep: #065f46;
  --brand-emerald-light: #ecfdf5;
  --slate-950: #020617;
  --slate-900: #0f172a;
  --slate-600: #475569;
  --slate-100: #f1f5f9;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: var(--slate-100);
  color: var(--slate-900);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  height: 100vh;
  width: 100vw;
}

.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100%;
  z-index: 1;
}

.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
}

.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #e5ebee;
}

/* --- Map Interface Controls --- */
.map-control-btn {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.3);
  width: 54px;
  height: 54px;
  border-radius: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--slate-900);
  box-shadow: 0 12px 24px -6px rgba(0,0,0,0.15);
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  cursor: pointer;
}

.map-control-btn:active {
  transform: scale(0.9);
  background: white;
}

.map-control-btn.primary {
  background: var(--brand-emerald);
  color: white;
  box-shadow: 0 12px 24px -6px rgba(16, 185, 129, 0.4);
}

.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: white;
  border-top-left-radius: 3.5rem;
  border-top-right-radius: 3.5rem;
  box-shadow: 0 -20px 80px -15px rgba(0, 0, 0, 0.2);
  max-height: 88vh;
  overflow-y: auto;
  padding-bottom: calc(7.5rem + env(safe-area-inset-bottom));
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.4s ease;
}

.bottom-sheet-grabber {
  width: 44px;
  height: 6px;
  background: #e2e8f0;
  border-radius: 99px;
  margin: 18px auto 10px;
}

@media (min-width: 1024px) {
  .rh-layout { display: flex; flex-direction: row; }
  .rh-map-view { position: relative; flex: 65; margin: 1.5rem; border-radius: 3rem; overflow: hidden; }
  .rh-ui-panel {
    position: relative;
    width: 35%;
    height: 100%;
    max-height: none;
    border-radius: 0;
    box-shadow: -15px 0 50px rgba(0,0,0,0.03);
    border-left: 1px solid var(--slate-100);
  }
}

.label-strong { font-weight: 900; color: var(--slate-950); font-size: 0.9rem; }
.helper-text { font-weight: 600; color: var(--slate-600); font-size: 0.75rem; }
.no-scrollbar::-webkit-scrollbar { display: none; }

/* Custom Marker Animations */
@keyframes marker-bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
.driver-marker {
  animation: marker-bounce 2s infinite ease-in-out;
}

