                   <div className="grid grid-cols-2 gap-6">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all">
                        <PhoneCall className="h-8 w-8" /> اتصال
