// Icons
import { Clock, Loader2, ChevronRight, CheckCircle2, XCircle, Bike, Car, MapPin, StickyNote } from 'lucide-react';

const ActivityView: React.FC<{ user: User, onBack: () => void }> = ({ user, onBack }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const field = user.role === 'DRIVER' ? 'driverId' : 'customerId';
    const q = query(collection(db, "orders"), where(field, "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const docs = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[];
      setOrders(docs.sort((a, b) => a.createdAt - b.createdAt));
      setLoading(false);
    });
  }, [user.id, user.role]);

  const getStatusStyle = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.DELIVERED:
      case OrderStatus.DELIVERED_RATED:
        return 'bg-emerald-100 text-emerald-600';
      case OrderStatus.CANCELLED:
        return 'bg-rose-100 text-rose-600';
      default:
        return 'bg-slate-100 text-slate-400';
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8 pb-10 p-6 animate-in slide-in-from-right duration-500 h-full overflow-y-auto no-scrollbar">
      <div className="flex justify-between items-center">
        <h2 className="text-3xl font-black text-slate-900 tracking-tighter">تاريخ مشاويري</h2>
        <button onClick={onBack} className="p-3.5 bg-white border border-slate-100 rounded-[1.5rem] shadow-sm active:scale-90 transition-all"><ChevronRight /></button>
      </div>

      <div className="space-y-6">
        {loading ? (
          <div className="py-20 flex justify-center"><Loader2 className="h-10 w-10 animate-spin text-emerald-500" /></div>
        ) : orders.length === 0 ? (
          <div className="py-32 text-center text-slate-300 font-bold border-4 border-dashed border-slate-100 rounded-[4rem]">
            لا يوجد سجل مشاوير حتى الآن
          </div>
        ) : orders.map(order => (
          <div key={order.id} className="bg-white p-8 rounded-[3.5rem] border border-slate-50 shadow-sm flex flex-col gap-6 hover:shadow-xl transition-all group">
            <div className="flex justify-between items-start">
               <div className="flex items-center gap-4">
                  <div className="bg-slate-50 p-4 rounded-2xl text-slate-400 group-hover:bg-slate-950 group-hover:text-emerald-400 transition-all">
                    {order.requestedVehicleType === 'CAR' ? <Car className="h-6 w-6" /> : <Bike className="h-6 w-6" />}
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{new Date(order.createdAt).toLocaleDateString('ar-EG')}</p>
                    <span className={`inline-block mt-1 px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${getStatusStyle(order.status)}`}>{order.status}</span>
                  </div>
               </div>
               <p className="text-2xl font-black text-slate-900">{order.price} <span className="text-xs font-bold opacity-30">ج.م</span></p>
            </div>

            <div className="space-y-4 px-2">
               <div className="flex gap-4 items-start">
                  <MapPin className="h-4 w-4 text-emerald-500 mt-1 shrink-0" />
                  <div className="text-right">
                    <p className="text-sm font-black text-slate-800">{order.pickup?.villageName} ← {order.dropoff?.villageName}</p>
                    {order.pickupNotes && <p className="text-[10px] font-bold text-slate-400 mt-1">🏠 {order.pickupNotes}</p>}
                  </div>
               </div>
            </div>

            <div className="pt-4 border-t border-slate-50 flex justify-between items-center text-[10px] font-bold text-slate-300 uppercase tracking-widest">
               <span>رقم الطلب: #{order.id.slice(-6)}</span>
               <button className="text-emerald-600 hover:underline">عرض التفاصيل</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

