export default SuperAdminDashboard;

export type UserRole = 'ADMIN' | 'OPERATOR' | 'DRIVER' | 'CUSTOMER';
export type UserStatus = 'PENDING_APPROVAL' | 'APPROVED' | 'SUSPENDED';
export type PaymentMethod = 'CASH' | 'WALLET';
export type VehicleType = 'TOKTOK' | 'MOTORCYCLE' | 'CAR';
export type OrderCategory = 'TAXI' | 'FOOD' | 'PHARMACY' | 'GROCERY' | 'PARCEL';

export enum OrderStatus {
  PENDING = 'PENDING',
  WAITING_FOR_OFFERS = 'WAITING_FOR_OFFERS',
  ACCEPTED = 'ACCEPTED',
  PICKED_UP = 'PICKED_UP',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  DELIVERED_RATED = 'DELIVERED_RATED',
  CANCELLED = 'CANCELLED'
}

export interface Offer {
  id: string;
  orderId: string;
  driverId: string;
  driverName: string;
  driverPhone: string;
  driverRating: number;
  driverPhoto?: string;
  vehicleType: VehicleType;
  price: number;
  createdAt: number;
}

export interface Village {
  id: string;
  name: string;
  center: { lat: number, lng: number };
}

export interface Zone {
  id: string;
  name: string;
  operatorId: string;
  pricing: {
    basePrice: number;
    pricePerKm: number;
    minPrice: number;
    maxPrice: number;
    sameVillagePrice: number;
    multipliers: Record<VehicleType, number>;
  };
  center: { lat: number; lng: number };
}

export interface Order {
  id: string;
  customerId: string;
  customerPhone: string;
  driverId?: string;
  driverName?: string;
  driverPhone?: string;
  operatorId: string;
  zoneId: string;
  category: OrderCategory;
  pickup: { address: string; lat: number; lng: number; villageName?: string };
  dropoff: { address: string; lat: number; lng: number; villageName?: string };
  status: OrderStatus;
  price: number;
  distance: number;
  commission: number;
  operatorCut: number;
  driverCut: number;
  createdAt: number;
  acceptedAt?: number;
  deliveredAt?: number;
  cancelledAt?: number;
  ratedAt?: number;
  notes?: string;
  pickupNotes?: string;
  dropoffNotes?: string;
  paymentMethod: PaymentMethod;
  requestedVehicleType: VehicleType;
  transactionId?: string;
  rating?: number;
  feedback?: string;
}

export interface User {
  id: string;
  email: string;
  phone: string;
  name: string;
  role: UserRole;
  status: UserStatus;
  photoURL?: string;
  vehicleType?: VehicleType;
  operatorId?: string; 
  zoneId?: string;     
  wallet: {
    balance: number;
    totalEarnings: number;
    withdrawn: number;
  };
  location?: {
    lat: number;
    lng: number;
    updatedAt: number;
  };
}

import React, { useState, useEffect } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory } from '../types';
import { OrderStatus, VehicleType } from '../types';

// Constants & Config
import { ASHMOUN_VILLAGES as STATIC_VILLAGES, DEFAULT_PRICING } from '../constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, DollarSign, Star,
  User as UserIcon, Wallet as WalletIcon,
  Car, MessageCircle, Loader2,
  Bot, Heart, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall
} from 'lucide-react';

// Firebase
import { db } from '../firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import WalletView from './WalletView';
import ProfileView from './ProfileView';
import AIAssistant from './AIAssistant';
import ActivityView from './ActivityView';
import ChatView from './ChatView';

const VillageInput: React.FC<{
  label: string; selectedVillage: Village | null; onSelect: (v: Village) => void;
  icon: React.ReactNode; iconBg: string; placeholder: string; helper: string; availableVillages: Village[];
}> = ({ label, selectedVillage, onSelect, icon, iconBg, placeholder, helper, availableVillages }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const filtered = availableVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-2">
      <div className="flex flex-col px-1">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-3xl flex items-center justify-between cursor-pointer hover:border-emerald-100 transition-all shadow-sm">
        <ChevronDown className={`h-6 w-6 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-4">
          <span className={`text-lg font-bold ${selectedVillage ? 'text-slate-900' : 'text-slate-400'}`}>
            {selectedVillage?.name || placeholder}
          </span>
          <div className={`${iconBg} p-3 rounded-xl text-white shadow-md`}>
            {React.cloneElement(icon as React.ReactElement, { className: "w-6 h-6" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 z-[100] max-h-64 overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-4 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-4 px-4 text-base font-bold outline-none" placeholder="ابحث عن القرية..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-3">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-5 py-4 hover:bg-emerald-50 rounded-2xl flex justify-between items-center group transition-all">
                <span className="text-base font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'WALLET' | 'PROFILE' | 'ACTIVITY'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      const orderData = {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_ashmoun_main', zoneId: 'zone_ashmoun_full',
        pickupNotes: pickupNotes.trim(), dropoffNotes: dropoffNotes.trim(), paymentMethod: 'CASH'
      };

      await addDoc(collection(db, "orders"), orderData);

      // WhatsApp Notification to Coordinator/Driver Group
      const whatsappMsg = `*طلب مشوار جديد - وصلها أشمون*\n\n` +
        `📍 *من:* ${pickupVillage.name}\n` +
        `🏠 *الوصف:* ${pickupNotes.trim() || 'بدون وصف'}\n\n` +
        `🏁 *إلى:* ${dropoffVillage.name}\n` +
        `🏢 *الوصف:* ${dropoffNotes.trim() || 'بدون وصف'}\n\n` +
        `💰 *السعر:* ${tripStats.price} ج.م\n` +
        `🚗 *المركبة:* ${selectedVehicle}\n\n` +
        `يرجى فتح التطبيق لتقديم العرض.`;

      window.open(`https://wa.me/201065019364?text=${encodeURIComponent(whatsappMsg)}`, '_blank');

      setPickupNotes(''); setDropoffNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div className="rh-map-view absolute inset-0 z-0 flex items-center justify-center bg-slate-100">
         <div className="text-center opacity-30">
            <MapPin className="h-16 w-16 mx-auto mb-4 text-[#2D9469] animate-bounce" />
            <p className="font-black tracking-[0.4em] uppercase">خريطة أشمون النشطة</p>
         </div>
      </div>

      <div className="rh-ui-panel no-scrollbar z-50">
        <div className="bottom-sheet-grabber"></div>
        <div className="p-8 space-y-10 pb-32">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <h2 className="text-3xl font-black text-slate-900 tracking-tighter">إلى أين نذهب؟</h2>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl active:scale-90 transition-all shadow-sm">
                    <Bot className="h-7 w-7" />
                 </button>
              </div>

              <div className="space-y-10">
                <div className="grid grid-cols-3 gap-3">
                  {['TAXI', 'FOOD', 'PHARMACY'].map(id => (
                    <button key={id} onClick={() => setSelectedCategory(id as OrderCategory)} className={`py-6 rounded-3xl flex flex-col items-center gap-2 border-2 transition-all ${selectedCategory === id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-lg scale-105' : 'bg-slate-50 border-transparent text-slate-400 opacity-60'}`}>
                       {id === 'TAXI' ? <Bike className="h-6 w-6" /> : id === 'FOOD' ? <Coffee className="h-6 w-6" /> : <Pill className="h-6 w-6" />}
                       <span className="text-[10px] font-black uppercase tracking-widest">{id === 'TAXI' ? 'مشوار' : id === 'FOOD' ? 'أكل' : 'صيدلية'}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-6 relative">
                  <div className="absolute right-[31px] top-[110px] bottom-[50px] w-0.5 border-r-2 border-dashed border-slate-200 z-0"></div>

                  <div className="space-y-4 relative z-10">
                    <VillageInput label="نقطة الانطلاق" helper="أين سيتسلمك الكابتن؟" selectedVillage={pickupVillage} onSelect={setPickupVillage} icon={<MapPin />} iconBg="bg-emerald-500" placeholder="اختر القرية" availableVillages={STATIC_VILLAGES} />
                    {pickupVillage && (
                      <input value={pickupNotes} onChange={e => setPickupNotes(e.target.value)} placeholder="وصف دقيق للموقع (مثلاً: بجوار صيدلية كذا)..." className="w-full bg-emerald-50/50 border-2 border-emerald-100 rounded-2xl p-4 font-bold text-sm outline-none focus:border-emerald-500 shadow-inner" />
                    )}
                  </div>

                  <div className="space-y-4 relative z-10">
                    <VillageInput label="نقطة الوصول" helper="الوجهة النهائية" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} icon={<Check />} iconBg="bg-rose-500" placeholder="إلى أين نذهب؟" availableVillages={STATIC_VILLAGES} />
                    {dropoffVillage && (
                      <input value={dropoffNotes} onChange={e => setDropoffNotes(e.target.value)} placeholder="وصف دقيق للوجهة (مثلاً: أمام محل كذا)..." className="w-full bg-rose-50/50 border-2 border-rose-100 rounded-2xl p-4 font-bold text-sm outline-none focus:border-rose-500 shadow-inner" />
                    )}
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="label-strong px-2">وسيلة النقل</label>
                  <div className="grid grid-cols-3 gap-3">
                    {['TOKTOK', 'MOTORCYCLE', 'CAR'].map(v => (
                      <button key={v} onClick={() => setSelectedVehicle(v as VehicleType)} className={`py-5 rounded-3xl flex flex-col items-center gap-2 border-2 transition-all ${selectedVehicle === v ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-md scale-105' : 'bg-slate-50 border-transparent text-slate-300'}`}>
                        {v === 'CAR' ? <Car className="h-6 w-6" /> : v === 'MOTORCYCLE' ? <Bike className="h-6 w-6" /> : <Zap className="h-6 w-6" />}
                        <span className="text-[9px] font-black uppercase">{v}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-[#10b981] text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                   {isSubmitting ? <Loader2 className="h-8 w-8 animate-spin" /> : 'اطلب مشوارك الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-10 text-center">
                   <div className="relative py-10">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-40 h-40 bg-emerald-500/10 rounded-full animate-ping"></div>
                      </div>
                      <div className="bg-white p-10 rounded-full shadow-2xl relative z-10 inline-block">
                        <Navigation2 className="h-16 w-16 text-emerald-600 animate-pulse" />
                      </div>
                   </div>
                   <div className="space-y-2">
                      <h2 className="text-3xl font-black text-slate-900 tracking-tight">جاري البحث عن كابتن...</h2>
                      <p className="helper-text text-lg">ستصلك العروض من كباتن أشمون هنا</p>
                   </div>
                   <div className="space-y-4 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-7 rounded-[3rem] flex justify-between items-center border-4 border-slate-100 hover:border-emerald-500 transition-all shadow-xl">
                           <div className="flex items-center gap-5">
                              <div className="w-16 h-16 bg-slate-950 text-emerald-400 rounded-2xl flex items-center justify-center font-black text-2xl shadow-xl">
                                {(offer.driverName || 'ك')[0]}
                              </div>
                              <div className="text-right">
                                 <p className="font-black text-slate-950 text-xl">{offer.driverName}</p>
                                 <div className="flex items-center gap-2 text-amber-500 font-bold text-sm bg-amber-50 px-3 py-1 rounded-full">
                                   <Star className="h-4 w-4 fill-amber-400" /> {offer.driverRating}
                                 </div>
                              </div>
                           </div>
                           <div className="text-center space-y-2">
                              <p className="text-3xl font-black text-emerald-700">{offer.price} <span className="text-xs font-bold opacity-30">ج.م</span></p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-2.5 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول</button>
                           </div>
                        </div>
                      ))}
                   </div>
                   <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-sm uppercase tracking-widest py-8 hover:underline">إلغاء الطلب</button>
