                          <input type="number" step="0.05" value={pricing.multipliers[type]} onChange={e => setPricing({...pricing, multipliers: {...pricing.multipliers, [type]: Number(e.target.value)}})} className="w-20 bg-white rounded-xl p-2 text-center font-black outline-none border border-slate-200" />
                       </div>
                    ))}
                 </div>
              </div>

              <button onClick={handleUpdatePricing} disabled={isSaving} className="w-full bg-[#2D9469] text-white py-8 rounded-[3rem] font-black text-xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
                 {isSaving ? <Loader2 className="h-7 w-7 animate-spin" /> : <><Save className="h-7 w-7" /> حفظ وتعميم السياسة السعرية</>}
              </button>
           </div>
        </div>
      )}

      {/* قسم التنبيهات (Notifs) */}
      {activeTab === 'NOTIFS' && (
