              </div>
           </div>

           <div className="space-y-6">
              <div className="grid grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">الفئة المستهدفة</label>
                    <select value={notif.target} onChange={e => setNotif({...notif, target: e.target.value})} className="w-full bg-slate-50 border-none rounded-3xl p-6 font-black text-sm outline-none appearance-none cursor-pointer">
                       <option value="ALL">الجميع</option>
                       <option value="DRIVER">الكباتن فقط</option>
                       <option value="CUSTOMER">العملاء فقط</option>
                    </select>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">عنوان التنبيه</label>
                    <input value={notif.title} onChange={e => setNotif({...notif, title: e.target.value})} placeholder="مثال: تحديث جديد للأسعار..." className="w-full bg-slate-50 border-none rounded-3xl p-6 font-black text-sm outline-none" />
                 </div>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">نص الرسالة</label>
                 <textarea value={notif.body} onChange={e => setNotif({...notif, body: e.target.value})} placeholder="اكتب تفاصيل التنبيه هنا..." className="w-full bg-slate-50 border-none rounded-[2.5rem] p-8 font-bold text-sm outline-none focus:ring-4 focus:ring-rose-500/5 min-h-[150px] transition-all" />
              </div>

              <button onClick={handleSendBroadcast} disabled={isSaving} className="w-full bg-rose-600 text-white py-7 rounded-[3rem] font-black text-xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
                 {isSaving ? <Loader2 className="h-7 w-7 animate-spin" /> : <><Send className="h-7 w-7" /> إرسال التنبيه الآن</>}
              </button>
           </div>
        </div>
      )}

      {/* قسم الآراء (Feedback) */}
      {activeTab === 'FEEDBACK' && (
        <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-sm space-y-10 animate-in slide-in-from-right">
           <h3 className="text-2xl font-black text-slate-800 px-2 flex items-center gap-4"><MessageSquare className="h-7 w-7 text-[#2D9469]" /> آراء ومقترحات المستخدمين</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {feedbacks.map(f => (
                <div key={f.id} className="p-8 bg-slate-50 rounded-[3rem] space-y-4 border border-transparent hover:border-emerald-500 transition-all">
                   <div className="flex justify-between items-start">
                      <div className="flex gap-4 items-center">
                         <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-slate-300 font-black">{(f.userName || 'م')[0]}</div>
                         <div>
                            <p className="font-black text-slate-800">{f.userName}</p>
                            <p className="text-[10px] font-bold text-slate-400">{f.userPhone}</p>
                         </div>
                      </div>
                      <div className="flex gap-1">
                         {[...Array(5)].map((_, i) => <Star key={i} className={`h-3 w-3 ${i < f.rating ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} />)}
                      </div>
                   </div>
                   <p className="text-xs font-bold text-slate-600 leading-relaxed bg-white p-5 rounded-2xl border border-slate-100">{f.opinion}</p>
                   <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest text-left">{new Date(f.createdAt).toLocaleDateString('ar-EG')}</p>
                </div>
              ))}
              {feedbacks.length === 0 && <div className="col-span-full py-20 text-center text-slate-400 font-bold">لا يوجد تعليقات مرسلة حالياً</div>}
           </div>
        </div>
      )}
    </div>
  );
};

