// --- المكون الرئيسي للسوبر أدمن ---
const SuperAdminDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'STATS' | 'USERS' | 'PRICING' | 'VILLAGES' | 'NOTIFS' | 'FEEDBACK'>('STATS');
  const [users, setUsers] = useState<User[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [villages, setVillages] = useState<Village[]>([]);
  const [feedbacks, setFeedbacks] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [activeChatOrder, setActiveChatOrder] = useState<Order | null>(null);

  // Pricing & Settings
  const [pricing, setPricing] = useState(DEFAULT_PRICING);
  const [isSaving, setIsSaving] = useState(false);
  const [notif, setNotif] = useState({ title: '', body: '', target: 'ALL' });

  // Village Adding State
  const [newVillage, setNewVillage] = useState({ name: '', lat: 30.298, lng: 30.975 });

  useEffect(() => {
    const unsubUsers = onSnapshot(collection(db, "users"), (snap) => setUsers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]));
    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("createdAt", "desc"), limit(100)), (snap) => setOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]));
    const unsubVillages = onSnapshot(collection(db, "villages"), (snap) => setVillages(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[]));
    const unsubFeedback = onSnapshot(query(collection(db, "feedback"), orderBy("createdAt", "desc"), limit(20)), (snap) => setFeedbacks(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) }))));
    const unsubPricing = onSnapshot(doc(db, "settings", "pricing"), (snap) => {
        if(snap.exists()) setPricing(snap.data().pricing || DEFAULT_PRICING);
    });

    return () => { unsubUsers(); unsubOrders(); unsubVillages(); unsubFeedback(); unsubPricing(); };
  }, []);

  const handleUpdatePricing = async () => {
    setIsSaving(true);
    try {
      await setDoc(doc(db, "settings", "pricing"), { pricing });
      alert('تم تحديث السياسة السعرية بنجاح');
    } catch (e) { alert('خطأ'); } finally { setIsSaving(false); }
  };

  const handleSendBroadcast = async () => {
    if (!notif.title || !notif.body) return;
    setIsSaving(true);
    try {
      await addDoc(collection(db, "notifications"), {
        ...notif, userId: notif.target, createdAt: Date.now(), read: false, type: 'ALERT'
      });
      setNotif({ title: '', body: '', target: 'ALL' });
      alert('تم إرسال التنبيه الجماعي');
    } catch (e) { alert('خطأ'); } finally { setIsSaving(false); }
  };

  const handleAddVillage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newVillage.name) return;
    setIsSaving(true);
    try {
      const vid = `v_dyn_${Date.now()}`;
      await setDoc(doc(db, "villages", vid), { ...newVillage, id: vid });
      setNewVillage({ name: '', lat: 30.298, lng: 30.975 });
      alert('تم إضافة القرية');
    } catch (e) { alert('فشل'); } finally { setIsSaving(false); }
  };

  const updateUserStatus = async (uid: string, status: UserStatus) => {
    try {
      await updateDoc(doc(db, "users", uid), { status });
      alert('تم تحديث حالة المستخدم');
    } catch (e) { alert('فشل'); }
  };

  const filteredUsers = users.filter(u => u.name?.includes(searchTerm) || u.phone?.includes(searchTerm));

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-32 p-6 animate-in fade-in">
      {selectedOrder && <OrderAdminModal order={selectedOrder} onClose={() => setSelectedOrder(null)} onOpenChat={(o) => { setActiveChatOrder(o); setSelectedOrder(null); }} />}
      {activeChatOrder && <ChatView user={user} order={activeChatOrder} onBack={() => setActiveChatOrder(null)} />}

      {/* Tabs Navigation */}
      <div className="bg-white dark:bg-slate-900 p-4 rounded-[2.8rem] shadow-sm border border-slate-100 flex gap-2 overflow-x-auto no-scrollbar sticky top-2 z-[400] backdrop-blur-xl">
        {[
          { id: 'STATS', label: 'الإحصائيات', icon: <BarChart3 className="h-4 w-4" /> },
          { id: 'USERS', label: 'المستخدمين', icon: <Users2 className="h-4 w-4" /> },
          { id: 'PRICING', label: 'الأسعار', icon: <DollarSign className="h-4 w-4" /> },
          { id: 'VILLAGES', label: 'القرى', icon: <MapPin className="h-4 w-4" /> },
          { id: 'NOTIFS', label: 'بث تنبيه', icon: <Megaphone className="h-4 w-4" /> },
          { id: 'FEEDBACK', label: 'الآراء', icon: <MessageSquare className="h-4 w-4" /> },
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex items-center gap-3 px-8 py-4 rounded-[1.8rem] text-[11px] font-black transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-slate-950 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-50'}`}>
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {/* Stats Tab */}
      {activeTab === 'STATS' && (
        <div className="space-y-10 animate-in slide-in-from-bottom duration-500">
           <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-emerald-600 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden group">
                 <TrendingUp className="absolute -bottom-4 -left-4 h-24 w-24 opacity-10" />
                 <p className="text-[10px] font-black opacity-60 uppercase mb-2">إجمالي دخل المحافظ</p>
                 <h3 className="text-4xl font-black">{users.reduce((acc, curr) => acc + (curr.wallet?.balance || 0), 0).toLocaleString()} <span className="text-xs opacity-60">ج.م</span></h3>
              </div>
              <div className="bg-slate-900 p-10 rounded-[3.5rem] text-white shadow-sm">
                 <p className="text-[10px] font-black opacity-40 uppercase mb-2">المستخدمين</p>
                 <h3 className="text-4xl font-black">{users.length}</h3>
              </div>
              <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-sm">
                 <p className="text-[10px] font-black text-slate-400 uppercase mb-2">الكباتن النشطين</p>
                 <h3 className="text-4xl font-black text-emerald-600">{users.filter(u => u.role === 'DRIVER' && u.status === 'APPROVED').length}</h3>
              </div>
              <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-sm">
                 <p className="text-[10px] font-black text-slate-400 uppercase mb-2">المشاوير المسجلة</p>
                 <h3 className="text-4xl font-black text-slate-900">{orders.length}</h3>
              </div>
           </div>

           <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-sm space-y-8">
              <h3 className="text-xl font-black text-slate-800 px-2 text-right">آخر 10 عمليات منفذة</h3>
              <div className="space-y-4">
                 {orders.slice(0, 10).map(order => (
                   <div key={order.id} onClick={() => setSelectedOrder(order)} className="p-6 bg-slate-50 rounded-[2.5rem] flex justify-between items-center hover:bg-emerald-50 transition-all cursor-pointer group">
                      <div className="flex items-center gap-5">
                         <div className="bg-white p-4 rounded-2xl shadow-sm text-slate-400 group-hover:bg-slate-900 group-hover:text-emerald-400 transition-all">
                            {order.requestedVehicleType === 'CAR' ? <Car className="h-6 w-6" /> : <Bike className="h-6 w-6" />}
                         </div>
                         <div className="text-right">
                            <p className="font-black text-sm text-slate-800 leading-none mb-1">{order.pickup?.villageName} ← {order.dropoff?.villageName}</p>
                            <p className="text-[9px] font-bold text-slate-400 uppercase">{order.status} • {new Date(order.createdAt).toLocaleTimeString('ar-EG')}</p>
                         </div>
                      </div>
                      <div className="flex items-center gap-4">
                         <p className="text-xl font-black text-slate-900">{order.price} ج.م</p>
                         <ChevronRight className="h-5 w-5 text-slate-300" />
                      </div>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* Users Tab */}
      {activeTab === 'USERS' && (
        <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-sm space-y-10 animate-in slide-in-from-left">
           <div className="relative">
              <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300" />
              <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="بحث عن كابتن أو عميل بالاسم أو الرقم..." className="w-full bg-slate-50 border-none rounded-3xl p-6 pr-14 font-black text-sm outline-none focus:ring-4 focus:ring-emerald-500/5 transition-all" />
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredUsers.map(u => (
                <div key={u.id} className="p-8 bg-slate-50 rounded-[3rem] border border-transparent hover:border-emerald-500 transition-all group text-right">
                   <div className="flex items-center gap-5 mb-6">
                      <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center font-black text-slate-300 text-2xl shadow-sm overflow-hidden">
                        {u.photoURL ? <img src={u.photoURL} className="w-full h-full object-cover" /> : (u.name || 'ع')[0]}
                      </div>
                      <div>
                         <p className="font-black text-slate-900">{u.name}</p>
                         <p className="text-xs font-bold text-slate-400" dir="ltr">{u.phone}</p>
                         <p className="text-[10px] font-black text-emerald-600 uppercase tracking-tighter mt-1">{u.role} • {u.status}</p>
                      </div>
                   </div>
                   <div className="flex gap-2">
                      {u.status === 'PENDING_APPROVAL' ? (
                         <button onClick={() => updateUserStatus(u.id, 'APPROVED')} className="flex-1 bg-emerald-600 text-white py-3 rounded-xl font-black text-[10px] shadow-lg">تفعيل الحساب</button>
                      ) : u.status === 'APPROVED' ? (
                         <button onClick={() => updateUserStatus(u.id, 'SUSPENDED')} className="flex-1 bg-rose-50 text-rose-500 py-3 rounded-xl font-black text-[10px]">حظر مؤقت</button>
                      ) : (
                         <button onClick={() => updateUserStatus(u.id, 'APPROVED')} className="flex-1 bg-slate-900 text-white py-3 rounded-xl font-black text-[10px]">فك الحظر</button>
                      )}
                      <button onClick={() => window.open(`tel:${u.phone}`)} className="p-3 bg-white rounded-xl text-slate-400 hover:text-blue-500 transition-all shadow-sm"><PhoneCall className="h-4 w-4" /></button>
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* Pricing Tab */}
      {activeTab === 'PRICING' && (
        <div className="space-y-8 animate-in slide-in-from-right">
           <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-sm space-y-10">
              <div className="flex items-center gap-4 text-right">
                 <div className="bg-amber-50 p-4 rounded-3xl text-amber-600 shrink-0"><Calculator className="h-8 w-8" /></div>
                 <div>
                    <h3 className="text-2xl font-black text-slate-800">سياسة التسعير</h3>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">تحكم كامل في أسعار الرحلات في أشمون وقراها</p>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                 <div className="space-y-2 text-center">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">فتحة العداد (ج.م)</label>
                    <input type="number" value={pricing.basePrice} onChange={e => setPricing({...pricing, basePrice: Number(e.target.value)})} className="w-full bg-slate-50 border-none rounded-3xl p-6 font-black text-2xl outline-none focus:ring-4 focus:ring-amber-500/5 transition-all text-center" />
