  if (activeOrder?.status === OrderStatus.DELIVERED) {
     return <RatingScreen order={activeOrder} onComplete={() => setActiveOrder(null)} />;
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('PROFILE')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div ref={mapContainerRef} className="rh-map-view absolute inset-0 z-0">
         <div className="absolute top-8 right-8 z-50 flex flex-col gap-4">
            <button onClick={() => mapInstance.current.zoomIn()} className="map-control-btn shadow-2xl"><Plus className="h-6 w-6" /></button>
            <button onClick={() => mapInstance.current.zoomOut()} className="map-control-btn shadow-2xl"><Minus className="h-6 w-6" /></button>
            <button onClick={handleLocateMe} className="map-control-btn primary shadow-2xl"><Crosshair className="h-6 w-6" /></button>
         </div>
         <div className="absolute top-8 left-8 z-50">
            <button onClick={() => setAiOpen(true)} className="map-control-btn shadow-2xl"><Bot className="h-6 w-6 text-emerald-600 animate-pulse" /></button>
