                   <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest text-left">{new Date(f.createdAt).toLocaleDateString('ar-EG')}</p>
                </div>
              ))}
              {feedbacks.length === 0 && <div className="col-span-full py-20 text-center text-slate-400 font-bold">لا توجد رسائل حالياً</div>}
           </div>
        </div>
      )}
    </div>
  );
};

