// --- مكون تعديل المستخدمين الشامل (User Edit Modal) ---
const UserEditModal: React.FC<{ user: User; onClose: () => void }> = ({ user, onClose }) => {
  const [formData, setFormData] = useState({
    name: user.name || '',
    phone: user.phone || '',
    role: user.role || 'CUSTOMER',
    status: user.status || 'PENDING_APPROVAL',
    vehicleType: user.vehicleType || 'TOKTOK'
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    if (!formData.name || !formData.phone) return alert('يرجى ملء الاسم والرقم');
    setIsSaving(true);
    try {
      await updateDoc(doc(db, "users", user.id), formData);
      alert('تم تحديث بيانات المستخدم بنجاح');
      onClose();
    } catch (e) {
      alert('حدث خطأ أثناء الحفظ');
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!window.confirm('هل أنت متأكد من حذف هذا الحساب نهائياً؟ لا يمكن التراجع عن هذا الإجراء.')) return;
    setIsSaving(true);
    try {
      await deleteDoc(doc(db, "users", user.id));
      alert('تم حذف المستخدم بنجاح');
      onClose();
    } catch (e) {
      alert('فشل الحذف');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-xl z-[11000] flex items-center justify-center p-4 animate-in fade-in">
      <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-[3.5rem] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        <div className="bg-slate-900 p-8 text-white flex justify-between items-center shrink-0">
          <div className="flex items-center gap-4">
             <div className="w-14 h-14 bg-[#10b981] rounded-2xl flex items-center justify-center text-2xl font-black shadow-lg overflow-hidden">
                {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : (formData.name[0] || 'U')}
             </div>
             <div>
                <h3 className="text-xl font-black">تعديل بيانات المستخدم</h3>
                <p className="text-[10px] text-slate-400 uppercase tracking-widest">ID: {user.id.slice(-10)}</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl hover:bg-white/20 transition-all"><X className="h-5 w-5" /></button>
        </div>

        <div className="p-8 space-y-6 overflow-y-auto no-scrollbar">
          <div className="space-y-4">
             <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">الاسم الكامل</label>
                <input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-50 dark:bg-slate-800 border-2 border-transparent focus:border-[#10b981] rounded-3xl p-5 font-black text-sm outline-none transition-all" />
             </div>
             <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">رقم الهاتف</label>
                <input value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-slate-50 dark:bg-slate-800 border-2 border-transparent focus:border-[#10b981] rounded-3xl p-5 font-black text-sm outline-none text-left" dir="ltr" />
             </div>

             <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">الدور الوظيفي</label>
                   <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as any})} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl p-4 font-black text-xs outline-none appearance-none cursor-pointer">
                      <option value="CUSTOMER">عميل</option>
                      <option value="DRIVER">كابتن</option>
                      <option value="OPERATOR">مشغل نظام</option>
                      <option value="ADMIN">مدير (Admin)</option>
                   </select>
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">حالة الحساب</label>
                   <select value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl p-4 font-black text-xs outline-none appearance-none cursor-pointer">
                      <option value="APPROVED">نشط (Approved)</option>
                      <option value="PENDING_APPROVAL">بانتظار تفعيل</option>
                      <option value="SUSPENDED">محظور (Suspended)</option>
                   </select>
                </div>
             </div>

             {formData.role === 'DRIVER' && (
               <div className="space-y-2 animate-in zoom-in">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">نوع المركبة</label>
                  <div className="grid grid-cols-3 gap-2">
                    {['TOKTOK', 'MOTORCYCLE', 'CAR'].map(v => (
                       <button key={v} onClick={() => setFormData({...formData, vehicleType: v as any})} className={`py-4 rounded-2xl font-black text-[9px] border-2 transition-all ${formData.vehicleType === v ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-slate-50 border-transparent text-slate-400'}`}>
                         {v}
                       </button>
                    ))}
                  </div>
               </div>
             )}
          </div>
        </div>

        <div className="p-8 bg-slate-50 dark:bg-slate-950 flex flex-col gap-3">
           <button onClick={handleSave} disabled={isSaving} className="w-full bg-[#10b981] text-white py-6 rounded-3xl font-black shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all">
              {isSaving ? <Loader2 className="h-6 w-6 animate-spin" /> : <><Save className="h-6 w-6" /> حفظ التغييرات</>}
           </button>
           <button onClick={handleDelete} disabled={isSaving} className="w-full bg-white text-rose-500 py-4 rounded-2xl font-black text-xs border border-rose-100 hover:bg-rose-50 transition-all flex items-center justify-center gap-2">
              <UserX className="h-4 w-4" /> حذف الحساب نهائياً
           </button>
        </div>
      </div>
    </div>
  );
};

