                </div>
             </div>
          </div>
        </div>

        {/* Footer Buttons */}
        <div className="p-8 bg-white border-t border-slate-100 flex flex-col gap-3">
           <button onClick={handleSave} disabled={isSaving} className="w-full bg-[#10b981] text-white py-6 rounded-3xl font-black shadow-xl shadow-emerald-500/20 flex items-center justify-center gap-3 active:scale-95 transition-all">
              {isSaving ? <Loader2 className="h-6 w-6 animate-spin" /> : <><Save className="h-6 w-6" /> حفظ كافة التعديلات</>}
           </button>
           <button onClick={handleDeleteUser} disabled={isSaving} className="w-full py-4 text-rose-500 font-black text-xs hover:bg-rose-50 rounded-2xl transition-all flex items-center justify-center gap-2">
              <UserX className="h-4 w-4" /> حذف الحساب نهائياً
           </button>
        </div>
      </div>
    </div>
  );
};

