             <div>
                <h3 className="text-xl font-black">إدارة الحساب الشاملة</h3>
                <p className="text-[10px] text-slate-400 uppercase tracking-widest mt-1 opacity-60">UserID: {user.id.slice(-12)}</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl hover:bg-white/20 transition-all"><X className="h-6 w-6" /></button>
        </div>

        {/* Content */}
        <div className="p-8 space-y-10 overflow-y-auto no-scrollbar flex-1 bg-slate-50/50">
          {/* Section 1: Identity */}
          <div className="space-y-4">
