             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                   <label className="text-[10px] font-bold text-slate-500 mr-4">الاسم بالكامل</label>
                   <input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-white border border-slate-200 rounded-2xl p-4 font-bold text-sm outline-none focus:ring-4 focus:ring-emerald-500/5 transition-all" />
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-bold text-slate-500 mr-4">رقم الموبايل</label>
                   <input value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-white border border-slate-200 rounded-2xl p-4 font-bold text-sm outline-none text-left" dir="ltr" />
                </div>
             </div>
          </div>

          {/* Section 2: Roles & Status */}
          <div className="space-y-4">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-2 flex items-center gap-2"><Shield className="h-3 w-3" /> الصلاحيات والوصول</h4>
