                      <option value="APPROVED">نشط (Approved)</option>
                      <option value="PENDING_APPROVAL">بانتظار تفعيل</option>
                      <option value="SUSPENDED">محظور (Suspended)</option>
                   </select>
                </div>
             </div>
             {formData.role === 'DRIVER' && (
               <div className="bg-white p-5 rounded-3xl border border-slate-100 space-y-3 animate-in zoom-in">
