                  <div className="grid grid-cols-3 gap-2">
                     {['TOKTOK', 'MOTORCYCLE', 'CAR'].map(v => (
                       <button key={v} onClick={() => setFormData({...formData, vehicleType: v as any})} className={`py-4 rounded-xl font-black text-[9px] border-2 transition-all ${formData.vehicleType === v ? 'bg-slate-900 border-slate-900 text-white' : 'bg-slate-50 border-transparent text-slate-400'}`}>{v}</button>
                     ))}
                  </div>
               </div>
             )}
          </div>

          {/* Section 3: Financials (Wallet) */}
          <div className="space-y-4">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-2 flex items-center gap-2"><WalletIcon className="h-3 w-3" /> الإدارة المالية (المحفظة)</h4>
             <div className="bg-slate-900 rounded-[2.5rem] p-8 space-y-6 text-white shadow-xl">
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-2">
                      <label className="text-[9px] font-black text-emerald-400 uppercase tracking-widest">الرصيد الحالي (ج.م)</label>
                      <input type="number" value={formData.walletBalance} onChange={e => setFormData({...formData, walletBalance: Number(formData.walletBalance)})} className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 font-black text-2xl outline-none focus:border-emerald-500 transition-all" />
                   </div>
                   <div className="space-y-2">
                      <label className="text-[9px] font-black text-amber-400 uppercase tracking-widest">إجمالي الأرباح (ج.م)</label>
                      <input type="number" value={formData.totalEarnings} onChange={e => setFormData({...formData, totalEarnings: Number(formData.totalEarnings)})} className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 font-black text-2xl outline-none focus:border-amber-500 transition-all" />
