// --- مكون تعديل المستخدم الشامل (Full User Management Modal) ---
const UserEditModal: React.FC<{ user: User; onClose: () => void }> = ({ user, onClose }) => {
  const [formData, setFormData] = useState({
    name: user.name || '',
    phone: user.phone || '',
    role: user.role || 'CUSTOMER',
    status: user.status || 'PENDING_APPROVAL',
    vehicleType: user.vehicleType || 'TOKTOK',
    walletBalance: user.wallet?.balance || 0,
    totalEarnings: user.wallet?.totalEarnings || 0
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    if (!formData.name || !formData.phone) return alert('يرجى ملء الاسم والرقم');
    setIsSaving(true);
    try {
      const updatePayload = {
        name: formData.name,
        phone: formData.phone,
        role: formData.role,
        status: formData.status,
        vehicleType: formData.role === 'DRIVER' ? formData.vehicleType : null,
        wallet: {
          ...user.wallet,
          balance: Number(formData.walletBalance),
          totalEarnings: Number(formData.totalEarnings)
        }
      };
      await updateDoc(doc(db, "users", user.id), updatePayload);
      alert('تم تحديث كافة بيانات المستخدم بنجاح');
      onClose();
    } catch (e) {
      alert('حدث خطأ أثناء حفظ التعديلات');
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteUser = async () => {
    if (!window.confirm('🚨 تحذير: هل أنت متأكد من حذف هذا الحساب نهائياً؟ سيتم حذف كافة سجلاته ولا يمكن التراجع.')) return;
    setIsSaving(true);
    try {
      await deleteDoc(doc(db, "users", user.id));
      alert('تم حذف المستخدم بنجاح');
      onClose();
    } catch (e) { alert('فشل الحذف'); } finally { setIsSaving(false); }
  };

  return (
    <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-xl z-[11000] flex items-center justify-center p-4 animate-in fade-in duration-300">
      <div className="bg-white dark:bg-slate-900 w-full max-w-xl rounded-[4rem] overflow-hidden shadow-2xl flex flex-col max-h-[92vh] border border-white/10">
        <div className="bg-slate-900 p-8 text-white flex justify-between items-center shrink-0">
          <div className="flex items-center gap-5">
             <div className="w-16 h-16 bg-emerald-500 rounded-3xl flex items-center justify-center text-3xl font-black shadow-lg shadow-emerald-500/20">
                {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover rounded-3xl" /> : (formData.name[0] || 'U')}
             </div>
             <div>
                <h3 className="text-xl font-black">إدارة الحساب الشاملة</h3>
                <p className="text-[10px] text-slate-400 uppercase tracking-widest mt-1 opacity-60">UserID: {user.id.slice(-12)}</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl hover:bg-white/10 transition-all"><X className="h-6 w-6" /></button>
        </div>

        <div className="p-8 space-y-10 overflow-y-auto no-scrollbar flex-1 bg-slate-50/50 dark:bg-slate-950/20">
          <div className="space-y-4">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-2 flex items-center gap-2"><UserIcon className="h-3 w-3" /> البيانات الأساسية</h4>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                   <label className="text-[10px] font-bold text-slate-500 mr-4">الاسم بالكامل</label>
                   <input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl p-4 font-bold text-sm outline-none focus:ring-4 focus:ring-emerald-500/5 transition-all dark:text-white" />
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-bold text-slate-500 mr-4">رقم الموبايل</label>
                   <input value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl p-4 font-bold text-sm outline-none text-left dark:text-white" dir="ltr" />
                </div>
             </div>
          </div>

          <div className="space-y-4">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-2 flex items-center gap-2"><Shield className="h-3 w-3" /> الصلاحيات والوصول</h4>
             <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                   <label className="text-[10px] font-bold text-slate-500 mr-4">نوع الحساب</label>
                   <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as any})} className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl p-4 font-black text-xs outline-none appearance-none cursor-pointer dark:text-white">
                      <option value="CUSTOMER">عميل</option>
                      <option value="DRIVER">كابتن</option>
                      <option value="OPERATOR">مشغل</option>
                      <option value="ADMIN">مدير</option>
                   </select>
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-bold text-slate-500 mr-4">حالة الحساب</label>
                   <select value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})} className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl p-4 font-black text-xs outline-none appearance-none cursor-pointer dark:text-white">
                      <option value="APPROVED">نشط</option>
                      <option value="PENDING_APPROVAL">بانتظار تفعيل</option>
                      <option value="SUSPENDED">محظور</option>
                   </select>
                </div>
             </div>
             {formData.role === 'DRIVER' && (
               <div className="bg-white dark:bg-slate-800 p-5 rounded-3xl border border-slate-100 dark:border-slate-700 space-y-3 animate-in zoom-in">
                  <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest px-1 block">نوع مركبة الكابتن</label>
                  <div className="grid grid-cols-3 gap-2">
                     {['TOKTOK', 'MOTORCYCLE', 'CAR'].map(v => (
                       <button key={v} onClick={() => setFormData({...formData, vehicleType: v as any})} className={`py-4 rounded-xl font-black text-[9px] border-2 transition-all ${formData.vehicleType === v ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-900 border-transparent text-slate-400'}`}>{v}</button>
                     ))}
                  </div>
               </div>
             )}
          </div>

          <div className="space-y-4">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-2 flex items-center gap-2"><WalletIcon className="h-3 w-3" /> الإدارة المالية (المحفظة)</h4>
             <div className="bg-slate-900 rounded-[2.5rem] p-8 space-y-6 text-white shadow-xl">
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-2">
                      <label className="text-[9px] font-black text-emerald-400 uppercase tracking-widest">الرصيد الحالي (ج.م)</label>
                      <input type="number" value={formData.walletBalance} onChange={e => setFormData({...formData, walletBalance: Number(e.target.value)})} className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 font-black text-2xl outline-none focus:border-emerald-500 transition-all" />
                   </div>
                   <div className="space-y-2">
                      <label className="text-[9px] font-black text-amber-400 uppercase tracking-widest">إجمالي الأرباح (ج.م)</label>
                      <input type="number" value={formData.totalEarnings} onChange={e => setFormData({...formData, totalEarnings: Number(e.target.value)})} className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 font-black text-2xl outline-none focus:border-amber-500 transition-all" />
                   </div>
                </div>
                <div className="p-4 bg-white/5 rounded-2xl flex items-center gap-3">
                   <AlertCircle className="h-4 w-4 text-amber-400" />
