                   {order.dropoffNotes && <p className="text-xs font-bold text-slate-600 dark:text-slate-400"><span className="text-rose-500 ml-2">●</span> {order.dropoffNotes}</p>}
                </div>
             )}
          </div>

          <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex justify-between items-center shadow-xl">
             <div className="text-right">
                <p className="text-[10px] font-black opacity-40 uppercase mb-1">الحالة</p>
                <span className="text-emerald-400 font-black text-lg uppercase tracking-widest">{order.status}</span>
             </div>
             <div className="text-left">
                <p className="text-[10px] font-black opacity-40 uppercase mb-1">التكلفة</p>
                <p className="text-4xl font-black">{order.price} <span className="text-sm">ج.م</span></p>
             </div>
          </div>

          <div className="flex gap-4">
             <button onClick={() => onOpenChat(order)} className="flex-1 bg-emerald-600 text-white py-6 rounded-3xl font-black flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-all">
                <MessageCircle className="h-6 w-6" /> مراقبة الدردشة
             </button>
             <button onClick={() => { if(window.confirm('إلغاء هذا الطلب نهائياً؟')) updateDoc(doc(db, "orders", order.id), { status: OrderStatus.CANCELLED }); onClose(); }} className="px-8 bg-rose-50 text-rose-500 rounded-3xl hover:bg-rose-100 transition-all">
                <Trash2 className="h-6 w-6" />
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

