          <div className="p-5 border-b border-slate-50">
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-5 px-6 text-base font-black outline-none focus:ring-4 focus:ring-emerald-500/5 text-right" dir="rtl" placeholder="ابحث عن اسم القرية..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
            {filtered.map(v => (
              <div key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="px-6 py-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center group transition-all mb-2 flex-row-reverse">
                <span className="text-lg font-bold text-slate-700">{v.name}</span>
                {selectedVillage?.id === v.id && <Check className="h-6 w-6 text-emerald-500" />}
