          <div className="flex items-center gap-5">
             <div className="w-16 h-16 bg-emerald-500 rounded-3xl flex items-center justify-center text-3xl font-black shadow-lg">
                {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover rounded-3xl" /> : (formData.name[0] || 'U')}
             </div>
             <div>
                <h3 className="text-xl font-black">إدارة المستخدم بالكامل</h3>
                <p className="text-[10px] text-slate-400 uppercase tracking-widest mt-1 opacity-60">ID: {user.id.slice(-12)}</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl hover:bg-white/10 transition-all"><X className="h-6 w-6" /></button>
        </div>

        {/* Modal Content */}
        <div className="p-8 space-y-10 overflow-y-auto no-scrollbar flex-1 bg-slate-50/50 dark:bg-slate-950/30">
