import React, { useState, useRef, useEffect } from 'react';

// Types
import type { User, Order } from '../types';
import { OrderStatus } from '../types';

// Services
import { db } from '../services/firebase';
import { doc, updateDoc, collection, query, where, getDocs } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  User as UserIcon, Smartphone, Edit3, Camera, Loader2, ChevronRight, 
  Bike, Car, Star, ShieldCheck, Zap, Wallet as WalletIcon, ArrowRight
} from 'lucide-react';

const ProfileView: React.FC<{ user: User, onUpdate: (u: User) => void, onBack: () => void, onOpenWallet?: () => void }> = ({ user, onUpdate, onBack, onOpenWallet }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(user.name);
  const [phone, setPhone] = useState(user.phone);
  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleUpdateProfile = async () => {
    setIsSaving(true);
    try {
      await updateDoc(doc(db, "users", user.id), { name, phone });
      onUpdate({ ...user, name, phone });
      setIsEditing(false);
    } catch (e) { 
      alert('خطأ في التحديث'); 
    } finally { 
      setIsSaving(false); 
    }
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) return alert('يرجى اختيار ملف صورة صحيح');
    if (file.size > 2 * 1024 * 1024) return alert('حجم الصورة كبير جداً، يرجى اختيار صورة أقل من 2 ميجابايت');

    setIsUploading(true);
    const reader = new FileReader();

    reader.onload = async () => {
      const base64Image = reader.result as string;
      try {
        await updateDoc(doc(db, "users", user.id), { photoURL: base64Image });
        onUpdate({ ...user, photoURL: base64Image });
      } catch (err) {
        alert('فشل في حفظ الصورة');
      } finally {
        setIsUploading(false);
      }
    };

    reader.onerror = () => {
      alert('حدث خطأ أثناء قراءة الملف');
      setIsUploading(false);
    };

    reader.readAsDataURL(file);
  };

  return (
    <div className="max-w-2xl mx-auto pb-32 space-y-8 p-6 animate-in slide-in-from-bottom duration-500 overflow-y-auto h-full no-scrollbar">
      <div className="flex items-center justify-between">
        <h2 className="text-3xl font-black text-slate-900 tracking-tighter">حسابي الشخصي</h2>
        <button onClick={onBack} className="p-3.5 bg-white border border-slate-100 rounded-[1.5rem] shadow-sm active:scale-90 transition-all"><ChevronRight /></button>
      </div>

      <div className="bg-[#2D9469] rounded-[4rem] p-12 text-white text-center shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full blur-3xl"></div>

        <div className="relative inline-block group">
          <div className="w-40 h-40 bg-white/20 backdrop-blur-xl rounded-[3.5rem] mx-auto flex items-center justify-center mb-8 overflow-hidden border-8 border-white/10 shadow-2xl relative">
            {isUploading ? (
              <div className="absolute inset-0 bg-black/20 flex items-center justify-center z-10">
                <Loader2 className="h-10 w-10 animate-spin text-white" />
              </div>
            ) : null}

            {user.photoURL ? (
              <img src={user.photoURL} className="w-full h-full object-cover" alt="Profile" />
            ) : (
              <UserIcon className="h-20 w-20 text-white/50" />
            )}
          </div>

          <button 
            onClick={() => fileInputRef.current?.click()}
            className="absolute bottom-6 -right-2 bg-white text-[#2D9469] p-4 rounded-3xl shadow-xl active:scale-75 transition-all border-4 border-[#2D9469] hover:rotate-12"
          >
            <Camera className="h-6 w-6" />
          </button>

          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImageChange} 
            className="hidden" 
            accept="image/*" 
          />
        </div>

        <h3 className="text-3xl font-black tracking-tight">{user.name}</h3>
        <div className="flex items-center justify-center gap-2 mt-3">
          {user.status === 'APPROVED' && <ShieldCheck className="h-4 w-4 text-emerald-300" />}
          <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60">عضو نشط في وصلها</p>
        </div>
      </div>

      <div className="space-y-6">
        {onOpenWallet && (
           <button onClick={onOpenWallet} className="w-full bg-slate-950 text-white p-10 rounded-[3.5rem] flex justify-between items-center shadow-2xl group active:scale-95 transition-all">
              <div className="flex items-center gap-6 text-right">
                 <div className="bg-emerald-500 p-5 rounded-[2.5rem] group-hover:scale-110 transition-transform shadow-xl">
                    <WalletIcon className="h-8 w-8 text-white" />
                 </div>
                 <div>
                    <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">رصيدي الحالي</p>
                    <p className="text-4xl font-black">{(user.wallet?.balance || 0).toFixed(2)} <span className="text-sm opacity-40 font-bold">ج.م</span></p>
                 </div>
              </div>
              <ArrowRight className="h-8 w-8 text-slate-700" />
           </button>
        )}

        <div className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-slate-100 space-y-8">
           <div className="flex justify-between items-center">
              <h4 className="font-black text-slate-800 text-lg">تعديل البيانات</h4>
              <button 
                onClick={() => isEditing ? handleUpdateProfile() : setIsEditing(true)} 
                disabled={isSaving}
                className={`font-black text-xs uppercase tracking-widest px-6 py-2 rounded-xl transition-all ${isEditing ? 'bg-emerald-500 text-white shadow-lg' : 'text-[#2D9469]'}`}
              >
                {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : isEditing ? 'حفظ' : 'تعديل'}
              </button>
           </div>
           <div className="space-y-4">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">الاسم</label>
                 <input value={name} onChange={e => setName(e.target.value)} disabled={!isEditing} className="w-full bg-slate-50 rounded-3xl p-6 font-black text-sm outline-none focus:ring-4 focus:ring-emerald-500/10 border-none transition-all" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">رقم الموبايل</label>
                 <input value={phone} onChange={e => setPhone(e.target.value)} disabled={!isEditing} className="w-full bg-slate-50 rounded-3xl p-6 font-black text-sm outline-none focus:ring-4 focus:ring-emerald-500/10 border-none transition-all text-left" dir="ltr" />
              </div>
           </div>
