      </div>

      <div className="p-10 text-center opacity-30 grayscale pointer-events-none">
         <img src="https://img.icons8.com/fluency-systems-filled/512/000000/bicycle.png" className="h-12 w-12 mx-auto mb-4" />
         <p className="text-[10px] font-black uppercase tracking-[0.5em]">وصلها</p>
      </div>
    </div>
  );
};

