          </button>

          <button onClick={onComplete} className="text-slate-300 font-black text-[10px] uppercase tracking-widest hover:text-slate-500 py-2">تخطي التقييم الآن</button>
        </div>
      </div>
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');

  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffNotes, setDropoffNotes] = useState('');

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const driverMarker = useRef<any>(null);
  const pickupMarker = useRef<any>(null);
  const dropoffMarker = useRef<any>(null);
  const routeLine = useRef<any>(null);

  useEffect(() => {
    if (activeOrder && activeOrder.driverId && ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(activeOrder.status)) {
      const unsubDriver = onSnapshot(doc(db, "users", activeOrder.driverId), (docSnap) => {
        if (docSnap.exists()) {
          const driverData = docSnap.data() as User;
          if (driverData.location && mapInstance.current) {
            const { lat, lng } = driverData.location;
            if (!driverMarker.current) {
              const icon = L.divIcon({
                html: `<div class="bg-emerald-600 p-2 rounded-full border-4 border-white shadow-xl driver-marker animate-bounce"><img src="https://img.icons8.com/fluency-systems-filled/48/FFFFFF/bicycle.png" style="width:24px;height:24px;"/></div>`,
                className: 'custom-div-icon',
                iconSize: [44, 44],
                iconAnchor: [22, 44]
              });
              driverMarker.current = L.marker([lat, lng], { icon }).addTo(mapInstance.current);
            } else {
              driverMarker.current.setLatLng([lat, lng]);
            }
            if (activeView === 'MAP') mapInstance.current.panTo([lat, lng], { animate: true });
          }
        }
      });
      return () => unsubDriver();
    } else if (driverMarker.current && mapInstance.current) {
      mapInstance.current.removeLayer(driverMarker.current);
      driverMarker.current = null;
    }
  }, [activeOrder?.id, activeOrder?.driverId, activeOrder?.status, activeView]);

  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.298, 30.975], 13);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }

    if (mapInstance.current) {
        const markers: any[] = [];
        if (pickupMarker.current) mapInstance.current.removeLayer(pickupMarker.current);
        if (dropoffMarker.current) mapInstance.current.removeLayer(dropoffMarker.current);
        if (routeLine.current) mapInstance.current.removeLayer(routeLine.current);

        const currentPickup = activeOrder ? activeOrder.pickup : (pickupVillage ? { lat: pickupVillage.center.lat, lng: pickupVillage.center.lng } : null);
        const currentDropoff = activeOrder ? activeOrder.dropoff : (dropoffVillage ? { lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng } : null);

        if (currentPickup) {
            const icon = L.divIcon({ html: `<div class="bg-emerald-500 w-4 h-4 rounded-full border-4 border-white shadow-lg"></div>`, className: '', iconSize: [16,16] });
            pickupMarker.current = L.marker([currentPickup.lat, currentPickup.lng], { icon }).addTo(mapInstance.current);
            markers.push([currentPickup.lat, currentPickup.lng]);
        }
        if (currentDropoff) {
            const icon = L.divIcon({ html: `<div class="bg-rose-500 w-6 h-6 rounded-full border-4 border-white shadow-lg flex items-center justify-center text-white"><img src="https://img.icons8.com/material-rounded/24/FFFFFF/marker.png" style="width:12px;height:12px;"/></div>`, className: '', iconSize: [24,24] });
            dropoffMarker.current = L.marker([currentDropoff.lat, currentDropoff.lng], { icon }).addTo(mapInstance.current);
            markers.push([currentDropoff.lat, currentDropoff.lng]);
        }

        if (currentPickup && currentDropoff) {
            routeLine.current = L.polyline([
                [currentPickup.lat, currentPickup.lng],
                [currentDropoff.lat, currentDropoff.lng]
            ], { color: '#10b981', weight: 4, dashArray: '10, 10', opacity: 0.6 }).addTo(mapInstance.current);
        }

        if (markers.length > 1) {
            mapInstance.current.fitBounds(markers, { padding: [80, 80], animate: true });
        } else if (markers.length === 1) {
            mapInstance.current.setView(markers[0], 15, { animate: true });
        }
    }
  }, [activeOrder, pickupVillage, dropoffVillage, activeView]);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleLocateMe = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        const { latitude, longitude } = pos.coords;
        mapInstance.current.setView([latitude, longitude], 16, { animate: true });
      });
    }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ'); }
  };

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      const orderData = {
        customerId: user.id, 
        customerPhone: user.phone, 
        category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, 
        createdAt: Date.now(), 
        requestedVehicleType: selectedVehicle,
        price: tripStats.price, 
        distance: tripStats.distance, 
        operatorId: 'op_ashmoun_main', 
        zoneId: 'zone_ashmoun_full',
        pickupNotes: pickupNotes.trim(),
        dropoffNotes: dropoffNotes.trim(),
        notes: `الاستلام: ${pickupNotes.trim()} | الوجهة: ${dropoffNotes.trim()}`,
        paymentMethod: 'CASH'
      };

      await addDoc(collection(db, "orders"), orderData);

      const coordinatorPhone = "201065019364"; 
      const whatsappMsg = `*طلب مشوار جديد - وصـــلــهــا*\n\n📍 *من:* ${pickupVillage.name}\n🏠 *وصف الموقع:* ${pickupNotes.trim() || 'لا يوجد'}\n\n🏁 *إلى:* ${dropoffVillage.name}\n🏢 *وصف الوجهة:* ${dropoffNotes.trim() || 'لا يوجد'}\n\n💰 *السعر المقترح:* ${tripStats.price} ج.م\n🚗 *المركبة المطلوبة:* ${selectedVehicle}`;

      window.open(`https://wa.me/${coordinatorPhone}?text=${encodeURIComponent(whatsappMsg)}`, '_blank');
      setPickupNotes('');
      setDropoffNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  if (activeOrder?.status === OrderStatus.DELIVERED) {
     return <RatingScreen order={activeOrder} onComplete={() => setActiveOrder(null)} />;
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('PROFILE')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      {/* الخريطة لا تظهر إلا في واجهتها الخاصة */}
      <div 
        ref={mapContainerRef} 
        className={`rh-map-view absolute inset-0 z-0 transition-opacity duration-500 ${activeView === 'MAP' ? 'opacity-100 visible' : 'opacity-0 invisible pointer-events-none'}`}
      >
         <div className="absolute top-8 right-8 z-50 flex flex-col gap-4">
            <button onClick={() => mapInstance.current.zoomIn()} className="map-control-btn shadow-2xl"><Plus className="h-6 w-6" /></button>
            <button onClick={() => mapInstance.current.zoomOut()} className="map-control-btn shadow-2xl"><Minus className="h-6 w-6" /></button>
            <button onClick={handleLocateMe} className="map-control-btn primary shadow-2xl"><Crosshair className="h-6 w-6" /></button>
         </div>
         <div className="absolute top-8 left-8 z-50">
            <button onClick={() => setAiOpen(true)} className="map-control-btn shadow-2xl"><Bot className="h-6 w-6 text-emerald-600 animate-pulse" /></button>
         </div>
      </div>

      {/* لوحة الواجهة تغطي الشاشة بالكامل عند الحاجة */}
      <div className={`rh-ui-panel no-scrollbar transition-all duration-500 z-[100] ${activeView === 'MAP' ? 'translate-y-full opacity-0 invisible pointer-events-none' : 'translate-y-0 opacity-100 visible bg-slate-50'}`}>
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-8 md:p-12 space-y-12 pb-32 max-w-2xl mx-auto h-full">
          {!activeOrder ? (
            <>
              <div className="space-y-1 text-right">
                 <h2 className="text-4xl font-black text-slate-950 tracking-tighter">إلى أين نذهب؟</h2>
                 <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">خدمة التوصيل الذكية</p>
              </div>

              <div className="space-y-12">
                <div className="grid grid-cols-3 gap-5">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <Coffee /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-400 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as React.ReactElement<any>, { className: "h-8 w-8" }) : cat.icon}
                       <span className="text-[11px] font-black uppercase tracking-wider">{cat.label}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-6 relative">
                  <VillageInput label="نقطة الانطلاق" helper="موقعك الحالي" selectedVillage={pickupVillage} onSelect={setPickupVillage} icon={<MapPin />} iconBg="bg-emerald-500" placeholder="موقعك" availableVillages={STATIC_VILLAGES} />
                  {pickupVillage && (
                    <input value={pickupNotes} onChange={e => setPickupNotes(e.target.value)} dir="rtl" placeholder="وصف دقيق للمكان..." className="w-full bg-emerald-50/50 text-slate-900 border-2 border-emerald-100 rounded-3xl py-5 px-6 font-bold text-sm outline-none focus:border-emerald-500 shadow-inner" />
                  )}
                  <div className="absolute right-[45px] top-[115px] bottom-[55px] w-0.5 bg-slate-100 border-r-2 border-dashed z-0"></div>
                  <VillageInput label="نقطة الوصول" helper="الوجهة النهائية" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} icon={<Check />} iconBg="bg-rose-500" placeholder="الوجهة" availableVillages={STATIC_VILLAGES} />
                  {dropoffVillage && (
                    <input value={dropoffNotes} onChange={e => setDropoffNotes(e.target.value)} dir="rtl" placeholder="وصف دقيق للوجهة..." className="w-full bg-rose-50/50 text-slate-900 border-2 border-rose-100 rounded-3xl py-5 px-6 font-bold text-sm outline-none focus:border-rose-500 shadow-inner" />
                  )}
                </div>

                <div className="space-y-5">
                  <label className="label-strong px-2 block text-right">وسيلة النقل</label>
                  <div className="grid grid-cols-3 gap-4">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v.id as VehicleType)} className={`py-7 rounded-[2.2rem] flex flex-col items-center gap-3 border-2 transition-all ${selectedVehicle === v.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-transparent text-slate-300 opacity-60'}`}>
                        {React.isValidElement(v.icon) ? React.cloneElement(v.icon as React.ReactElement<any>, { className: "h-7 w-7" }) : v.icon}
                        <span className="text-[10px] font-black uppercase tracking-widest">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-[#10b981] text-white py-8 rounded-[2.8rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                   {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin" /> : 'اطلب مشوارك الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-12 text-center">
                   <div className="relative py-10">
                      <div className="absolute inset-0 flex items-center justify-center"><div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div></div>
                      <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block"><Navigation2 className="h-24 w-24 text-emerald-600 animate-pulse" /></div>
                   </div>
                   <div className="space-y-4">
                      <h2 className="text-4xl font-black text-slate-950 tracking-tighter">جاري البحث عن كابتن...</h2>
                      <p className="helper-text text-xl">سوف تظهر العروض من الكباتن هنا</p>
                   </div>
                   <div className="space-y-6 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-8 rounded-[3.5rem] flex justify-between items-center border-4 border-slate-100 hover:border-emerald-500 transition-all shadow-xl flex-row-reverse">
                           <div className="flex items-center gap-6 flex-row-reverse">
                              <div className="w-20 h-20 bg-slate-950 text-emerald-400 rounded-3xl flex items-center justify-center font-black text-3xl shadow-2xl overflow-hidden">
                                {offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : (offer.driverName || 'ك')[0]}
                              </div>
                              <div className="text-right">
                                 <p className="font-black text-slate-950 text-2xl leading-none mb-2">{offer.driverName}</p>
                                 <div className="flex items-center gap-2 text-amber-500 font-bold text-base bg-amber-50 px-4 py-1.5 rounded-full justify-end flex-row-reverse"><Star className="h-5 w-5 fill-amber-400" /> {offer.driverRating}</div>
                              </div>
                           </div>
                           <div className="text-center space-y-3">
                              <p className="text-4xl font-black text-emerald-700">{offer.price} <span className="text-xs font-bold">ج.م</span></p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول</button>
                           </div>
                        </div>
                      ))}
                   </div>
                   <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-sm uppercase tracking-widest py-8 hover:underline">إلغاء الطلب</button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-12 text-right">
                   <div className="bg-emerald-600 p-10 rounded-[4rem] text-white flex justify-between items-center shadow-2xl">
                      <div className="text-right"><p className="text-[11px] font-black opacity-60 uppercase mb-2 tracking-[0.2em]">تتبع مباشر</p><h3 className="text-3xl font-black tracking-tight leading-none">الكابتن في طريقه إليك</h3></div>
                      <div className="bg-white/20 p-6 rounded-full backdrop-blur-xl"><Navigation2 className="h-10 w-10 animate-bounce" /></div>
                   </div>
                   <div className="flex flex-col items-center gap-8">
                      <div className="w-36 h-36 bg-white rounded-[3.5rem] flex items-center justify-center border-8 border-slate-100 shadow-2xl relative overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-16 w-16 text-slate-300" />}
                        <div className="absolute bottom-3 right-3 bg-emerald-500 p-2 rounded-full border-4 border-white shadow-xl"><ShieldCheck className="h-4 w-4 text-white" /></div>
                      </div>
                      <div className="text-center">
                         <h4 className="text-4xl font-black text-slate-950 tracking-tighter">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-3 uppercase tracking-widest text-emerald-600 bg-emerald-50 px-8 py-2 rounded-full inline-block border border-emerald-100">كابتن {activeOrder.requestedVehicleType} • وصـــلــهــا</p>
                      </div>
                   </div>
                   <div className="grid grid-cols-2 gap-6">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all"><PhoneCall className="h-8 w-8" /> اتصال</a>
                      <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-4 shadow-sm active:scale-95 transition-all"><MessageCircle className="h-8 w-8" /> دردشة</button>
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-[0_-20px_50px_rgba(0,0,0,0.12)] flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب جديد'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'الخريطة'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 border border-emerald-100 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, OrderCategory } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, Map as MapIcon, User as UserIcon, Home, 
  ShieldAlert, StickyNote, Coffee, Pill, Bot, Zap, Car,
  Plus, Minus, Crosshair, Check, DollarSign
} from 'lucide-react';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

// Leaflet Global Access
declare var L: any;

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<string>('');
  const [showChat, setShowChat] = useState(false);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const watchId = useRef<number | null>(null);
  const driverMarker = useRef<any>(null);

  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.298, 30.975], 13);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }
  }, []);

  useEffect(() => {
    if (isOnline) {
      if ("geolocation" in navigator) {
        watchId.current = navigator.geolocation.watchPosition(
          (pos) => {
            const { latitude, longitude } = pos.coords;
            updateDoc(doc(db, "users", user.id), {
              location: { lat: latitude, lng: longitude, updatedAt: Date.now() }
            });
            if (mapInstance.current) {
               if (!driverMarker.current) {
                  const icon = L.divIcon({
                    html: `<div class="bg-slate-900 p-2 rounded-full border-4 border-white shadow-xl"><img src="https://img.icons8.com/fluency-systems-filled/48/10b981/bicycle.png" style="width:24px;height:24px;"/></div>`,
                    className: '', iconSize: [44,44], iconAnchor: [22,44]
                  });
                  driverMarker.current = L.marker([latitude, longitude], { icon }).addTo(mapInstance.current);
               } else {
                  driverMarker.current.setLatLng([latitude, longitude]);
               }
               if (activeView === 'MAP') mapInstance.current.panTo([latitude, longitude], { animate: true });
            }
          },
          (err) => console.error(err),
          { enableHighAccuracy: true }
        );
      }
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id, activeView]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const handleSendOffer = async (orderId: string) => {
    const price = parseFloat(offerPrice);
    if (!price || price <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: orderId,
        driverId: user.id,
        driverName: user.name,
        driverPhone: user.phone,
        driverRating: 5.0,
        vehicleType: user.vehicleType || 'TOKTOK',
        price: price,
        createdAt: Date.now()
      });
      setShowOfferInput(null);
      setOfferPrice('');
    } catch (e) { 
      alert('حدث خطأ أثناء إرسال العرض'); 
    } finally { 
      setIsSubmitting(false); 
    }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') {
     return (
       <div className="p-12 text-center font-black space-y-6">
         <ShieldAlert className="h-20 w-20 mx-auto text-emerald-600 animate-bounce" />
         <h2 className="text-3xl tracking-tighter">حسابك بانتظار التفعيل</h2>
         <p className="text-slate-400 text-sm">يرجى التواصل مع الإدارة للبدء في استقبال طلبات وصـــلــهــا.</p>
         <button onClick={() => window.open('https://wa.me/201065019364')} className="w-full bg-[#25D366] text-white py-6 rounded-[2rem] font-black shadow-xl">تواصل عبر واتساب</button>
       </div>
     );
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      {/* الخريطة لا تظهر إلا عند طلبها */}
      <div 
        ref={mapContainerRef} 
        className={`rh-map-view absolute inset-0 z-0 transition-opacity duration-500 ${activeView === 'MAP' ? 'opacity-100 visible' : 'opacity-0 invisible pointer-events-none'}`}
      ></div>

      <div className={`rh-ui-panel no-scrollbar px-6 space-y-8 pb-32 pt-8 animate-in fade-in overflow-y-auto transition-all duration-500 z-[100] ${activeView === 'MAP' ? 'translate-y-full opacity-0 invisible pointer-events-none' : 'translate-y-0 opacity-100 visible bg-slate-50'}`}>
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="max-w-2xl mx-auto space-y-8 h-full">
            <div className={`p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
               <div>
                  <h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'أنت نشط' : 'متوقف'}</h2>
                  <p className="text-[10px] font-black opacity-60 mt-2 uppercase tracking-[0.3em]">استلام طلبات وصـــلــهــا</p>
               </div>
               <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2.5rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}>
                  <Power className="h-10 w-10" />
               </button>
            </div>

            {activeOrder ? (
               <div className="bg-white rounded-[4rem] shadow-2xl border border-slate-100 p-10 space-y-10 animate-in zoom-in border-t-8 border-t-emerald-500">
                  <div className="flex justify-between items-center">
                     <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
                     <p className="text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-lg opacity-30 font-bold">ج.م</span></p>
                  </div>
                  <div className="space-y-8 text-right">
                     <div className="flex gap-6 items-start">
                        <div className="bg-slate-50 p-5 rounded-3xl text-emerald-600 shadow-inner shrink-0"><MapPin className="h-8 w-8" /></div>
                        <div className="flex-1">
                           <p className="helper-text uppercase mb-2 tracking-widest">المسار</p>
                           <p className="font-black text-2xl text-slate-950 leading-tight mb-4">{activeOrder.pickup?.villageName} ← {activeOrder.dropoff?.villageName}</p>
                           {(activeOrder.pickupNotes || activeOrder.dropoffNotes) && (
                             <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 space-y-4">
                               {activeOrder.pickupNotes && <div><p className="text-[9px] font-black text-emerald-600 uppercase mb-1">الاستلام:</p><p className="text-xs font-bold text-slate-700">{activeOrder.pickupNotes}</p></div>}
                               {activeOrder.dropoffNotes && <div className="pt-3 border-t border-slate-200"><p className="text-[9px] font-black text-rose-600 uppercase mb-1">الوجهة:</p><p className="text-xs font-bold text-slate-700">{activeOrder.dropoffNotes}</p></div>}
                             </div>
                           )}
                        </div>
                     </div>
                  </div>
                  <div className="grid grid-cols-2 gap-5 pt-4">
                     <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                     <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-50 text-slate-900 py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 relative"><MessageCircle className="h-7 w-7" /> دردشة</button>
                     <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 transition-all">
                        {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد الاستلام' : 'تم التوصيل والتحصيل'}
                     </button>
                  </div>
               </div>
            ) : (
               <div className="space-y-6">
                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.4em] px-4 text-right">مشاوير متاحة الآن ({availableOrders.length})</h3>
                  {availableOrders.map(o => (
                     <div key={o.id} className="bg-white p-10 rounded-[4rem] border-2 border-slate-50 shadow-xl space-y-8 animate-in slide-in-from-bottom">
                        {showOfferInput === o.id ? (
                          <div className="space-y-8 animate-in zoom-in">
                             <div className="text-center space-y-2">
                                <h4 className="text-xl font-black">تقديم عرض سعر</h4>
                                <p className="text-xs font-bold text-slate-400">السعر المقترح من التطبيق: {o.price} ج.م</p>
                             </div>
                             <div className="relative">
                                <input autoFocus type="number" value={offerPrice} onChange={e => setOfferPrice(e.target.value)} placeholder={o.price.toString()} className="w-full bg-slate-50 border-none rounded-3xl p-8 text-5xl font-black text-center outline-none focus:ring-4 focus:ring-emerald-500/10" />
                                <DollarSign className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-200 h-10 w-10" />
                             </div>
                             <div className="flex gap-4">
                                <button onClick={() => setShowOfferInput(null)} className="flex-1 py-6 rounded-[2rem] font-black text-slate-400">إلغاء</button>
                                <button onClick={() => handleSendOffer(o.id)} disabled={isSubmitting} className="flex-[2] bg-emerald-600 text-white py-6 rounded-[2rem] font-black shadow-xl flex items-center justify-center gap-3">
                                   {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin" /> : <><Check className="h-6 w-6" /> إرسال العرض</>}
                                </button>
                             </div>
                          </div>
                        ) : (
                          <>
                            <div className="flex justify-between items-start text-right">
                               <div className="space-y-2">
