import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, Link } from "react-router-dom";

// Types
import type { User } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { LogOut, RefreshCcw, WifiOff, Loader2, Bell, MessageCircle } from 'lucide-react';

// Services
import { auth, db } from '../services/firebase';
import { onAuthStateChanged, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, collection, query, where, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Pages
import Login from './Login';
import CustomerDashboard from './CustomerDashboard';
import CourierDashboard from './CourierDashboard';
import OperatorDashboard from './OperatorDashboard';
import SuperAdminDashboard from './SuperAdminDashboard';
import NotificationsView from './NotificationsView';
import SupportView from './SupportView';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showSupport, setShowSupport] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    const unsubscribeAuth = onAuthStateChanged(auth, async (fbUser) => {
      if (fbUser) {
        await fetchUserData(fbUser.uid);
      } else {
        setUser(null);
        setLoading(false);
      }
    });
    return unsubscribeAuth;
  }, []);

  const fetchUserData = async (uid: string) => {
    try {
      const userSnap = await getDoc(doc(db, "users", uid));
      if (userSnap.exists()) {
        const data = stripFirestore(userSnap.data()) as User;
        setUser(data);

        const q = query(collection(db, "notifications"), where("userId", "in", [data.id, "ALL", data.role]));
        onSnapshot(q, (snap) => {
          const unread = snap.docs.filter(d => !d.data().read).length;
          setUnreadCount(unread);
        });
      }
    } catch (error) {
      if (!navigator.onLine) setConnectionError(true);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return (
    <div className="min-h-screen bg-[#10b981] flex flex-col items-center justify-center p-6 text-center">
      <div className="bg-white/20 p-12 rounded-[5rem] backdrop-blur-3xl mb-12 border border-white/30 shadow-2xl animate-pulse">
         <img src={APP_LOGO_ICON} alt="Loading..." className="h-32 w-32 object-contain" />
      </div>
      <h2 className="text-white font-black text-5xl tracking-tighter mb-4">وصـــلــهــا</h2>
      <div className="flex items-center gap-3 bg-black/10 px-8 py-3 rounded-full backdrop-blur-md border border-white/10">
        <Loader2 className="h-5 w-5 text-white animate-spin" />
        <p className="text-white/80 font-bold text-[10px] uppercase tracking-widest">تحميل بيانات المنوفية...</p>
      </div>
    </div>
  );

  if (connectionError) return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-10 text-center">
       <WifiOff className="h-20 w-20 text-rose-500 mb-6" />
       <h2 className="text-2xl font-black text-slate-800 mb-2">عذراً، لا يوجد اتصال</h2>
       <p className="text-slate-500 mb-8 font-bold">تأكد من باقة الإنترنت أو شبكة الواي فاي</p>
       <button onClick={() => window.location.reload()} className="bg-[#10b981] text-white px-10 py-5 rounded-[2rem] font-black shadow-xl flex items-center gap-3"><RefreshCcw className="h-5 w-5" /> إعادة المحاولة</button>
    </div>
  );

  if (!user) return <Login onLogin={(u) => setUser(stripFirestore(u))} />;

  const getDashboard = () => {
    if (showNotifications) return <NotificationsView user={user} onBack={() => setShowNotifications(false)} />;
    if (showSupport) return <SupportView user={user} onBack={() => setShowSupport(false)} />;
    switch (user.role) {
      case 'ADMIN': return <SuperAdminDashboard user={user} />;
      case 'OPERATOR': return <OperatorDashboard user={user} />;
      case 'DRIVER': return <CourierDashboard user={user} />;
      case 'CUSTOMER': return <CustomerDashboard user={user} />;
      default: return <div className="p-20 text-center font-black">الدور الوظيفي غير مفعّل</div>;
    }
  };

  return (
    <HashRouter>
      <div className="app-container">
        <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-[60] px-5 h-24 md:h-28 flex items-center shadow-sm">
          <div className="max-w-7xl mx-auto w-full flex items-center justify-between">
            <Link to="/" onClick={() => { setShowNotifications(false); setShowSupport(false); }} className="flex items-center gap-5">
              <div className="bg-[#10b981] p-3.5 rounded-[1.8rem] shadow-xl border-4 border-emerald-50 relative overflow-hidden group">
                <img src={APP_LOGO_ICON} alt="Logo" className="h-8 w-8 md:h-11 md:w-11 relative z-10" />
              </div>
              <div className="flex flex-col">
                <h1 className="font-black text-xl md:text-3xl text-slate-800 tracking-tighter leading-none mb-1">وصـــلــهــا</h1>
                <span className="text-[8px] md:text-[10px] font-black text-slate-300 uppercase tracking-widest">محافظة المنوفية • خدمة 24 ساعة</span>
              </div>
            </Link>
            <div className="flex items-center gap-2 md:gap-4">
              <button onClick={() => setShowSupport(true)} className="p-4 bg-slate-50 text-slate-400 rounded-2xl border border-slate-100 transition-all active:scale-90"><MessageCircle className="h-6 w-6" /></button>
              <button onClick={() => setShowNotifications(true)} className={`p-4 bg-slate-50 text-slate-400 rounded-2xl relative border border-slate-100 transition-all active:scale-90`}><Bell className="h-6 w-6" />{unreadCount > 0 && <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-6 h-6 rounded-full text-[10px] flex items-center justify-center border-2 border-white font-black animate-bounce">{unreadCount}</span>}</button>
              <button onClick={() => signOut(auth)} className="p-4 bg-rose-50 text-rose-500 rounded-2xl border border-rose-100 transition-all active:scale-90 hover:bg-rose-100"><LogOut className="h-6 w-6 rotate-180" /></button>
            </div>
          </div>
        </header>
        <main className="main-content"><Routes><Route path="/" element={getDashboard()} /><Route path="*" element={<Navigate to="/" replace />} /></Routes></main>
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory } from '../types';
import { OrderStatus, VehicleType } from '../types';
import { District, MENOFIA_DATA } from '../config/constants';

// Config
import { DEFAULT_PRICING } from '../config/constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, ChevronRight, DollarSign, Star,
  User as UserIcon, Map as MapIcon,
  Car, MessageCircle, Loader2,
  Bot, Heart, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall, ShieldCheck,
  Plus, Minus, Crosshair, Wallet as WalletIcon,
  Award, ThumbsUp, X, Building2
} from 'lucide-react';

// Components
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import WalletView from './WalletView';
import ChatView from '../components/ChatView';
import AIAssistant from '../components/AIAssistant';

// Leaflet Global Access
declare var L: any;

const HierarchicalLocationPicker: React.FC<{
  label: string;
  helper: string;
  icon: React.ReactNode;
  iconBg: string;
  selectedVillage: Village | null;
  onSelect: (v: Village) => void;
}> = ({ label, helper, icon, iconBg, selectedVillage, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedDistrict, setSelectedDistrict] = useState<District | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredDistricts = MENOFIA_DATA.filter(d => d.name.includes(searchTerm));
  const filteredVillages = selectedDistrict?.villages.filter(v => v.name.includes(searchTerm)) || [];

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2 text-right">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-[2.2rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-5 flex-row-reverse text-right">
          <div className="flex flex-col">
            <span className={`text-lg font-black leading-none ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>
              {selectedVillage?.name || "اختر الموقع"}
            </span>
            {selectedVillage && <span className="text-[9px] font-bold text-emerald-600 uppercase mt-1">مركز {MENOFIA_DATA.find(d => d.villages.some(v => v.id === selectedVillage.id))?.name}</span>}
          </div>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl transition-transform group-active:scale-90`}>
            {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: "h-6 w-6" }) : icon}
          </div>
        </div>
      </div>

      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[200] max-h-[450px] overflow-hidden flex flex-col animate-in zoom-in duration-300">
          <div className="p-5 border-b border-slate-50 flex flex-col gap-3">
            <div className="flex justify-between items-center px-2">
              <button onClick={() => setIsOpen(false)} className="p-2 text-slate-300 hover:text-slate-500"><X className="h-5 w-5" /></button>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{selectedDistrict ? `قرى مركز ${selectedDistrict.name}` : "اختر المركز أولاً"}</span>
            </div>
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-black outline-none text-right" dir="rtl" placeholder="ابحث..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>

          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
            {!selectedDistrict ? (
              <div className="grid grid-cols-1 gap-2">
                {filteredDistricts.map(d => (
                  <button key={d.id} onClick={() => { setSelectedDistrict(d); setSearchTerm(''); }} className="w-full p-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse border border-transparent hover:border-emerald-100">
                    <div className="flex items-center gap-4 flex-row-reverse text-right">
                      <div className="p-2.5 bg-white rounded-xl shadow-sm text-slate-400"><Building2 className="h-5 w-5" /></div>
                      <span className="font-black text-slate-700">مركز {d.name}</span>
                    </div>
                    {/* Added ChevronRight to icons import above to fix "Cannot find name 'ChevronRight'" error */}
                    <ChevronRight className="h-4 w-4 text-slate-300 rotate-180" />
                  </button>
                ))}
              </div>
            ) : (
              <div className="space-y-2">
                <button onClick={() => setSelectedDistrict(null)} className="w-full p-4 bg-slate-50 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 mb-4 hover:bg-slate-100">
                  <X className="h-4 w-4" /> العودة لاختيار مركز آخر
                </button>
                {filteredVillages.map(v => (
                  <button key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="w-full p-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse border border-transparent hover:border-emerald-100">
                    <span className="font-bold text-slate-700">{v.name}</span>
                    {selectedVillage?.id === v.id && <Check className="h-5 w-5 text-emerald-500" />}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const driverMarker = useRef<any>(null);
  const pickupMarker = useRef<any>(null);
  const dropoffMarker = useRef<any>(null);
  const routeLine = useRef<any>(null);

  useEffect(() => {
    if (activeOrder && activeOrder.driverId && ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(activeOrder.status)) {
      const unsubDriver = onSnapshot(doc(db, "users", activeOrder.driverId), (docSnap) => {
        if (docSnap.exists()) {
          const driverData = docSnap.data() as User;
          if (driverData.location && mapInstance.current) {
            const { lat, lng } = driverData.location;
            if (!driverMarker.current) {
              const icon = L.divIcon({
                html: `<div class="bg-emerald-600 p-2 rounded-full border-4 border-white shadow-xl driver-marker animate-bounce"><img src="https://img.icons8.com/fluency-systems-filled/48/FFFFFF/bicycle.png" style="width:24px;height:24px;"/></div>`,
                className: 'custom-div-icon',
                iconSize: [44, 44],
                iconAnchor: [22, 44]
              });
              driverMarker.current = L.marker([lat, lng], { icon }).addTo(mapInstance.current);
            } else {
              driverMarker.current.setLatLng([lat, lng]);
            }
            if (activeView === 'MAP') mapInstance.current.panTo([lat, lng], { animate: true });
          }
        }
      });
      return () => unsubDriver();
    }
  }, [activeOrder?.driverId, activeOrder?.status, activeView]);

  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.556, 31.008], 11);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }
  }, []);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      const orderData = {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_monofia_main', zoneId: 'zone_monofia_full',
        pickupNotes: pickupNotes.trim(), dropoffNotes: dropoffNotes.trim(), paymentMethod: 'CASH'
      };
      await addDoc(collection(db, "orders"), orderData);
      setPickupNotes(''); setDropoffNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('خطأ'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div ref={mapContainerRef} className={`rh-map-view absolute inset-0 z-0 transition-opacity duration-500 ${activeView === 'MAP' ? 'opacity-100 block' : 'opacity-0 hidden'}`}>
         <div className="absolute top-8 right-8 z-50 flex flex-col gap-4">
            <button onClick={() => mapInstance.current?.zoomIn()} className="map-control-btn shadow-2xl"><Plus className="h-6 w-6" /></button>
            <button onClick={() => mapInstance.current?.zoomOut()} className="map-control-btn shadow-2xl"><Minus className="h-6 w-6" /></button>
            <button onClick={() => {}} className="map-control-btn primary shadow-2xl"><Crosshair className="h-6 w-6" /></button>
         </div>
      </div>

      <div className={`rh-ui-panel no-scrollbar transition-all duration-500 z-[100] ${activeView === 'MAP' ? 'translate-y-full opacity-0 invisible' : 'translate-y-0 opacity-100 bg-slate-50'}`}>
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-8 md:p-12 space-y-12 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar">
          {!activeOrder ? (
            <>
              <div className="space-y-1 text-right">
                 <h2 className="text-4xl font-black text-slate-950 tracking-tighter">المنوفية بين يديك</h2>
                 <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">اختر المركز ثم القرية للبدء</p>
              </div>

              <div className="space-y-12">
                <div className="grid grid-cols-3 gap-5">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <Coffee /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-400 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as React.ReactElement<any>, { className: "h-8 w-8" }) : cat.icon}
                       <span className="text-[11px] font-black uppercase tracking-wider">{cat.label}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-6 relative">
                  <HierarchicalLocationPicker label="نقطة الانطلاق" helper="أين سيتسلمك الكابتن؟" icon={<MapPin />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                  {pickupVillage && (
                    <input value={pickupNotes} onChange={e => setPickupNotes(e.target.value)} dir="rtl" placeholder="وصف دقيق للمكان..." className="w-full bg-emerald-50/50 text-slate-900 border-2 border-emerald-100 rounded-3xl py-5 px-6 font-bold text-sm outline-none focus:border-emerald-500 shadow-inner animate-in slide-in-from-top" />
                  )}

                  <div className="absolute right-[45px] top-[115px] bottom-[55px] w-0.5 bg-slate-100 border-r-2 border-dashed z-0"></div>

                  <HierarchicalLocationPicker label="نقطة الوصول" helper="الوجهة النهائية" icon={<Check />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                  {dropoffVillage && (
                    <input value={dropoffNotes} onChange={e => setDropoffNotes(e.target.value)} dir="rtl" placeholder="وصف دقيق للوجهة..." className="w-full bg-rose-50/50 text-slate-900 border-2 border-rose-100 rounded-3xl py-5 px-6 font-bold text-sm outline-none focus:border-rose-500 shadow-inner animate-in slide-in-from-top" />
                  )}
                </div>

                <div className="space-y-5">
                  <label className="label-strong px-2 block text-right">وسيلة النقل</label>
                  <div className="grid grid-cols-3 gap-4">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v.id as VehicleType)} className={`py-7 rounded-[2.2rem] flex flex-col items-center gap-3 border-2 transition-all ${selectedVehicle === v.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-transparent text-slate-300 opacity-60'}`}>
                        {React.isValidElement(v.icon) ? React.cloneElement(v.icon as React.ReactElement<any>, { className: "h-7 w-7" }) : v.icon}
                        <span className="text-[10px] font-black uppercase tracking-widest">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-[#10b981] text-white py-8 rounded-[2.8rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                   {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin" /> : 'اطلب مشوارك الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 py-4">
              {/* تفاصيل الطلب النشط تظل كما هي في الكود السابق */}
              <div className="animate-in zoom-in space-y-12 text-center">
                 <div className="relative py-10">
                    <div className="absolute inset-0 flex items-center justify-center"><div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div></div>
                    <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block"><Navigation2 className="h-24 w-24 text-emerald-600 animate-pulse" /></div>
                 </div>
                 <h2 className="text-4xl font-black text-slate-950 tracking-tighter">جاري البحث في المنوفية...</h2>
                 <p className="helper-text text-xl">ستظهر عروض الكباتن فور توفرها</p>
                 <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-sm uppercase tracking-widest py-8 hover:underline">إلغاء الطلب</button>
              </div>
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-[0_-20px_50px_rgba(0,0,0,0.12)] flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب جديد'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'الخريطة'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 border border-emerald-100 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

