  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const driverMarker = useRef<any>(null);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
