      `🏁 *إلى:* مركز ${dropoffDistrict} - ${order.dropoff?.villageName}\n` +
      `🏢 *الوصف:* ${order.dropoffNotes || 'لا توجد ملاحظات'}\n\n` +
      `💰 *السعر المقترح:* ${order.price} ج.م\n` +
      `🛵 *المركبة:* ${order.requestedVehicleType === 'TOKTOK' ? 'توكتوك' : order.requestedVehicleType === 'MOTORCYCLE' ? 'موتوسيكل' : 'سيارة'}\n\n` +
      `📱 *رقم العميل:* ${order.customerPhone}\n\n` +
      `_يرجى فتح التطبيق لتقديم عرضك الآن_`;

    window.open(`https://wa.me/201065019364?text=${encodeURIComponent(message)}`, '_blank');
  };

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
