import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory } from '../types';
import { OrderStatus, VehicleType } from '../types';
import { District, MENOFIA_DATA } from '../config/constants';

// Config
import { DEFAULT_PRICING } from '../config/constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, ChevronRight, DollarSign, Star,
  User as UserIcon, Map as MapIcon,
  Car, MessageCircle, Loader2,
  Bot, Heart, History,
  Navigation2, Zap, Coffee, Pill,
  StickyNote, PhoneCall, ShieldCheck,
  Plus, Minus, Crosshair, Wallet as WalletIcon,
  Award, ThumbsUp, X, Building2
} from 'lucide-react';

// Components
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import WalletView from './WalletView';
import ChatView from '../components/ChatView';
import AIAssistant from '../components/AIAssistant';

// Leaflet Global Access
declare var L: any;

const HierarchicalLocationPicker: React.FC<{
  label: string;
  helper: string;
  icon: React.ReactNode;
  iconBg: string;
  selectedVillage: Village | null;
  onSelect: (v: Village) => void;
}> = ({ label, helper, icon, iconBg, selectedVillage, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedDistrict, setSelectedDistrict] = useState<District | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredDistricts = MENOFIA_DATA.filter(d => d.name.includes(searchTerm));
  const filteredVillages = selectedDistrict?.villages.filter(v => v.name.includes(searchTerm)) || [];

  const districtName = selectedVillage 
    ? MENOFIA_DATA.find(d => d.villages.some(v => v.id === selectedVillage.id))?.name 
    : null;

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2 text-right">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-slate-50 border-2 border-transparent p-5 rounded-[2.2rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-5 flex-row-reverse text-right">
          <div className="flex flex-col">
            <span className={`text-lg font-black leading-none ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>
              {selectedVillage?.name || "اختر الموقع"}
            </span>
            {selectedVillage && <span className="text-[9px] font-bold text-emerald-600 uppercase mt-1">مركز {districtName}</span>}
          </div>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl transition-transform group-active:scale-90`}>
            {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: "h-6 w-6" }) : icon}
          </div>
        </div>
      </div>

      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[200] max-h-[450px] overflow-hidden flex flex-col animate-in zoom-in duration-300">
          <div className="p-5 border-b border-slate-50 flex flex-col gap-3">
            <div className="flex justify-between items-center px-2">
              <button onClick={() => setIsOpen(false)} className="p-2 text-slate-300 hover:text-slate-500"><X className="h-5 w-5" /></button>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{selectedDistrict ? `قرى مركز ${selectedDistrict.name}` : "اختر المركز أولاً"}</span>
            </div>
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-black outline-none text-right" dir="rtl" placeholder="ابحث..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>

          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
            {!selectedDistrict ? (
              <div className="grid grid-cols-1 gap-2">
                {filteredDistricts.map(d => (
                  <button key={d.id} onClick={() => { setSelectedDistrict(d); setSearchTerm(''); }} className="w-full p-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse border border-transparent hover:border-emerald-100">
                    <div className="flex items-center gap-4 flex-row-reverse text-right">
                      <div className="p-2.5 bg-white rounded-xl shadow-sm text-slate-400"><Building2 className="h-5 w-5" /></div>
                      <span className="font-black text-slate-700">مركز {d.name}</span>
                    </div>
                    <ChevronRight className="h-4 w-4 text-slate-300 rotate-180" />
                  </button>
                ))}
              </div>
            ) : (
              <div className="space-y-2">
                <button onClick={() => setSelectedDistrict(null)} className="w-full p-4 bg-slate-50 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 mb-4 hover:bg-slate-100">
                  <X className="h-4 w-4" /> العودة لاختيار مركز آخر
                </button>
                {filteredVillages.map(v => (
                  <button key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="w-full p-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse border border-transparent hover:border-emerald-100">
                    <span className="font-bold text-slate-700">{v.name}</span>
                    {selectedVillage?.id === v.id && <Check className="h-5 w-5 text-emerald-500" />}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);

  const mapContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const sendWhatsAppNotification = (order: Partial<Order>) => {
    const pickupDist = MENOFIA_DATA.find(d => d.villages.some(v => v.name === order.pickup?.villageName))?.name || 'المنوفية';
    const dropoffDist = MENOFIA_DATA.find(d => d.villages.some(v => v.name === order.dropoff?.villageName))?.name || 'المنوفية';

    const message = `*طلب مشوار جديد - وصـــلــهــا المـنـوفـيـة* 🚗\n` +
      `--------------------------------\n` +
      `📍 *الاستلام:* مركز ${pickupDist} (${order.pickup?.villageName})\n` +
      `🏠 *الوصف:* ${order.pickupNotes || 'لا يوجد'}\n\n` +
      `🏁 *الوجهة:* مركز ${dropoffDist} (${order.dropoff?.villageName})\n` +
      `🏢 *الوصف:* ${order.dropoffNotes || 'لا يوجد'}\n\n` +
      `💰 *السعر المقترح:* ${order.price} ج.م\n` +
      `🛵 *المركبة:* ${order.requestedVehicleType === 'TOKTOK' ? 'توكتوك' : order.requestedVehicleType === 'MOTORCYCLE' ? 'موتوسيكل' : 'سيارة'}\n` +
      `--------------------------------\n` +
      `📱 *رقم العميل:* ${order.customerPhone}\n\n` +
      `_افتح التطبيق فوراً لتقديم عرضك_`;

    window.open(`https://wa.me/201065019364?text=${encodeURIComponent(message)}`, '_blank');
  };

  const handleWhatsAppContact = (phone: string, name: string) => {
    const msg = `مرحباً كابتن ${name}، أنا العميل بخصوص رحلة "وصـــلــهــا".`;
    window.open(`https://wa.me/2${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      const orderData = {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_monofia_main', zoneId: 'zone_monofia_full',
        pickupNotes: pickupNotes.trim(), dropoffNotes: dropoffNotes.trim(), paymentMethod: 'CASH'
      };
      await addDoc(collection(db, "orders"), orderData);
      sendWhatsAppNotification(orderData);
      setPickupNotes(''); setDropoffNotes('');
    } catch (e) { alert('فشل الاتصال.'); } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div className={`rh-map-view absolute inset-0 z-0 flex items-center justify-center bg-slate-100 transition-opacity duration-500 ${activeView === 'MAP' ? 'opacity-100' : 'opacity-0'}`}>
         <div className="text-center opacity-30">
            <MapPin className="h-16 w-16 mx-auto mb-4 text-emerald-600 animate-bounce" />
            <p className="font-black tracking-[0.4em] uppercase">خريطة المنوفية المباشرة</p>
         </div>
      </div>

      <div className={`rh-ui-panel no-scrollbar transition-all duration-500 z-[100] ${activeView === 'MAP' ? 'translate-y-full opacity-0 invisible' : 'translate-y-0 opacity-100 bg-slate-50'}`}>
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-8 md:p-12 space-y-12 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between text-right">
                 <div>
                    <h2 className="text-4xl font-black text-slate-950 tracking-tighter">أهلاً بك في المنوفية</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">وصـــلــهــا لخدمات التوصيل الذكية</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl active:scale-90 transition-all shadow-sm">
                    <Bot className="h-8 w-8" />
                 </button>
              </div>

              <div className="space-y-12">
                <div className="grid grid-cols-3 gap-5">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <Coffee /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.8rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-400 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as React.ReactElement<any>, { className: "h-8 w-8" }) : cat.icon}
                       <span className="text-[11px] font-black uppercase tracking-wider">{cat.label}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-6 relative">
                  <HierarchicalLocationPicker label="نقطة الانطلاق" helper="أين سيتسلمك الكابتن؟" icon={<MapPin />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                  {pickupVillage && (
                    <input value={pickupNotes} onChange={e => setPickupNotes(e.target.value)} dir="rtl" placeholder="وصف دقيق للموقع (بجوار مسجد.. صيدلية..)" className="w-full bg-emerald-50/50 text-slate-900 border-2 border-emerald-100 rounded-[1.8rem] py-5 px-6 font-bold text-sm outline-none focus:border-emerald-500 shadow-inner" />
                  )}

                  <div className="absolute right-[45px] top-[115px] bottom-[55px] w-0.5 bg-slate-100 border-r-2 border-dashed z-0"></div>

                  <HierarchicalLocationPicker label="نقطة الوصول" helper="الوجهة النهائية" icon={<Check />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                  {dropoffVillage && (
                    <input value={dropoffNotes} onChange={e => setDropoffNotes(e.target.value)} dir="rtl" placeholder="وصف دقيق للوجهة (أمام محطة..)" className="w-full bg-rose-50/50 text-slate-900 border-2 border-rose-100 rounded-[1.8rem] py-5 px-6 font-bold text-sm outline-none focus:border-rose-500 shadow-inner" />
                  )}
                </div>

                <div className="space-y-5">
                  <label className="label-strong px-2 block text-right">وسيلة النقل</label>
                  <div className="grid grid-cols-3 gap-4">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v.id as VehicleType)} className={`py-7 rounded-[2.5rem] flex flex-col items-center gap-3 border-2 transition-all ${selectedVehicle === v.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-transparent text-slate-300 opacity-60'}`}>
                        {React.isValidElement(v.icon) ? React.cloneElement(v.icon as React.ReactElement<any>, { className: "h-7 w-7" }) : v.icon}
                        <span className="text-[10px] font-black uppercase tracking-widest">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

