                           <div className="text-center space-y-2">
                              <p className="text-3xl font-black text-emerald-700">{offer.price} <span className="text-xs opacity-40">ج.م</span></p>
                              <button onClick={async () => await updateDoc(doc(db, "orders", activeOrder.id), { driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone, price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now() })} className="bg-emerald-600 text-white px-8 py-2.5 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول</button>
                           </div>
