            {selectedVillage && <span className="text-[9px] font-bold text-emerald-600 uppercase mt-1">مركز {districtName}</span>}
          </div>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl transition-transform group-active:scale-90`}>
            {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: "h-6 w-6" }) : icon}
