const UserEditModal: React.FC<{ user: User; onClose: () => void }> = ({ user, onClose }) => {
  const [formData, setFormData] = useState({
    name: user.name || '',
    phone: user.phone || '',
    role: user.role || 'CUSTOMER',
    status: user.status || 'PENDING_APPROVAL',
    vehicleType: user.vehicleType || 'TOKTOK',
    walletBalance: user.wallet?.balance || 0,
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    if (!formData.name || !formData.phone) return alert('يرجى ملء الاسم والرقم');
    setIsSaving(true);
    try {
      const updatePayload = {
        name: formData.name,
        phone: formData.phone,
        role: formData.role,
        status: formData.status,
        vehicleType: formData.role === 'DRIVER' ? formData.vehicleType : null,
        wallet: {
          balance: Number(formData.walletBalance),
          totalEarnings: user.wallet?.totalEarnings || 0,
          withdrawn: user.wallet?.withdrawn || 0
        }
      };
      await updateDoc(doc(db, "users", user.id), updatePayload);
      alert('تم تحديث الحساب');
      onClose();
    } catch (e) { alert('خطأ'); } finally { setIsSaving(false); }
  };

  return (
    <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-xl z-[11000] flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-xl rounded-[4rem] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
          <h3 className="text-xl font-black">إدارة الحساب</h3>
          <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl"><X className="h-6 w-6" /></button>
        </div>
        <div className="p-8 space-y-8 overflow-y-auto no-scrollbar">
          <div className="space-y-4">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">البيانات الأساسية</label>
             <input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-50 rounded-3xl p-6 font-black text-sm outline-none" placeholder="الاسم" />
             <input value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-slate-50 rounded-3xl p-6 font-black text-sm outline-none text-left" dir="ltr" />
          </div>
          <div className="grid grid-cols-2 gap-4">
             <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">الحالة</label>
                <select value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})} className="w-full bg-slate-50 rounded-2xl p-4 font-black text-xs outline-none appearance-none">
                   <option value="APPROVED">نشط</option>
                   <option value="PENDING_APPROVAL">معلق</option>
                   <option value="SUSPENDED">محظور</option>
                </select>
             </div>
             <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">الرصيد (ج.م)</label>
                <input type="number" value={formData.walletBalance} onChange={e => setFormData({...formData, walletBalance: Number(e.target.value)})} className="w-full bg-slate-900 text-emerald-400 rounded-2xl p-4 font-black text-center" />
             </div>
          </div>
        </div>
        <div className="p-8 bg-slate-50 flex gap-3">
           <button onClick={handleSave} disabled={isSaving} className="w-full bg-emerald-600 text-white py-6 rounded-3xl font-black shadow-xl flex items-center justify-center gap-3">
              {isSaving ? <Loader2 className="h-5 w-5 animate-spin" /> : <><Save className="h-5 w-5" /> حفظ التغييرات</>}
           </button>
        </div>
      </div>
    </div>
  );
};

