  useEffect(() => {
    onSnapshot(collection(db, "users"), (snap) => setUsers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]));
    onSnapshot(query(collection(db, "orders"), orderBy("createdAt", "desc"), limit(100)), (snap) => setOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]));
    onSnapshot(collection(db, "villages"), (snap) => setDynamicVillages(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Village[]));
