                 <button type="submit" disabled={isSaving} className="bg-slate-900 dark:bg-slate-800 text-white py-6 rounded-3xl font-black text-sm shadow-xl flex items-center justify-center gap-3">
                   {isSaving ? <Loader2 className="h-5 w-5 animate-spin" /> : <><Plus className="h-5 w-5" /> إضافة المنطقة</>}
                 </button>
              </form>
           </div>

           <div className="space-y-4">
              {MENOFIA_DATA.map(district => {
                const districtVillages = getVillagesByDistrict(district.id);
                const isExpanded = expandedDistrict === district.id;

                return (
                  <div key={district.id} className="bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
                    <button 
                      onClick={() => setExpandedDistrict(isExpanded ? null : district.id)}
                      className="w-full p-8 flex justify-between items-center hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
                    >
                      <ChevronDown className={`h-6 w-6 text-slate-300 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                      <div className="flex items-center gap-4">
                        <span className="bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 px-4 py-1 rounded-full text-[10px] font-black uppercase">{districtVillages.length} منطقة</span>
                        <h4 className="text-xl font-black dark:text-white">مركز {district.name}</h4>
                      </div>
                    </button>

                    {isExpanded && (
                      <div className="p-8 pt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top duration-300">
                        {districtVillages.map(v => (
                          <div key={v.id} className="p-6 bg-slate-50 dark:bg-slate-950 rounded-[2.5rem] flex justify-between items-center group border border-transparent hover:border-emerald-500/20">
                             <div className="text-right">
                                <p className="font-black text-sm text-slate-800 dark:text-white">{v.name}</p>
                                <p className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">تحديث لحظي</p>
                             </div>
                             {v.id.startsWith('v_dyn_') && (
                               <button onClick={async () => { if(confirm('حذف المنطقة؟')) await deleteDoc(doc(db, "villages", v.id)); }} className="text-rose-300 hover:text-rose-500 p-2 transition-colors"><Trash2 className="h-4 w-4" /></button>
                             )}
                          </div>
                        ))}
                        {districtVillages.length === 0 && (
                          <p className="col-span-full text-center py-10 text-slate-400 font-bold">لا يوجد مناطق مضافة لهذا المركز حالياً</p>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
           </div>
        </div>
      )}
    </div>
  );
};

