                           <div className="text-center space-y-2">
                              <p className="text-3xl font-black text-emerald-700">{offer.price}</p>
                              <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-2.5 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول والمتابعة</button>
                           </div>
