              ) : activeOrder.status === OrderStatus.DELIVERED ? (
                // --- واجهة التأكيد والتقييم النهائية ---
                <div className="animate-in zoom-in space-y-8 text-center bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-500/10">
                   <div className="relative inline-block mb-4">
                      <div className="bg-emerald-500 p-8 rounded-full shadow-2xl relative z-10"><PartyPopper className="h-20 w-20 text-white animate-bounce" /></div>
                      <div className="absolute inset-0 bg-emerald-500/20 rounded-full animate-ping scale-150"></div>
                   </div>
                   <div className="space-y-2">
                      <h2 className="text-3xl font-black text-slate-950 tracking-tight">حمداً لله على سلامتك!</h2>
                      <p className="text-slate-400 font-bold">هل وصل {activeOrder.category === 'TAXI' ? 'مشوارك' : 'طلبك'} بنجاح؟</p>
                   </div>

                   <div className="bg-slate-50 p-8 rounded-[3rem] space-y-6">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">قيم الكابتن {activeOrder.driverName}</p>
                      <div className="flex justify-center gap-3">
                         {[1,2,3,4,5].map(s => (
                           <button key={s} onClick={() => setRating(s)} className="transition-all active:scale-75">
                              <Star className={`h-12 w-12 ${rating >= s ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} />
                           </button>
                         ))}
                      </div>
                   </div>

                   <button 
                     onClick={handleFinalizeTrip} 
                     disabled={isSubmitting}
                     className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4"
                   >
                     {isSubmitting ? <Loader2 className="h-8 w-8 animate-spin" /> : <><ThumbsUp className="h-8 w-8" /> تأكيد وإغلاق المشوار</>}
                   </button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-12">
                   <div className="bg-emerald-600 p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                      <div className="text-right">
                         <p className="text-[11px] font-black opacity-60 uppercase mb-2 tracking-[0.2em]">مشوار نشط الآن</p>
                         <h3 className="text-2xl font-black tracking-tight leading-none">الكابتن في طريقه إليك</h3>
                      </div>
                      <div className="bg-white/20 p-5 rounded-full backdrop-blur-xl">
                        <Navigation2 className="h-8 w-8 animate-bounce" />
                      </div>
                   </div>

                   <div className="flex flex-col items-center gap-6">
                      <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                      </div>
                      <div className="text-center">
                         <h4 className="text-3xl font-black text-slate-950 tracking-tighter">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-2 uppercase tracking-widest text-emerald-600 bg-emerald-50 px-6 py-2 rounded-full inline-block">كابتن معتمد</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-5">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all">
                        <PhoneCall className="h-7 w-7" /> اتصال
                      </a>
                      <button onClick={() => {
                        const msg = `أهلاً كابتن ${activeOrder.driverName}، أنا العميل بخصوص مشوار "وصـــلــهــا"، من فضلك شارك موقعك المباشر.`;
                        const phone = activeOrder.driverPhone?.startsWith('0') ? activeOrder.driverPhone.substring(1) : activeOrder.driverPhone;
                        window.open(`https://wa.me/20${phone}?text=${encodeURIComponent(msg)}`, '_blank');
                      }} className="bg-[#25D366] text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all">
                        <MessageCircle className="h-7 w-7" /> واتساب
                      </button>
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-[0_-20px_50px_rgba(0,0,0,0.12)] flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'خريطة'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 border border-emerald-100 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

