declare var L: any;

// --- مكون عرض آراء العملاء في الكابتن ---
const DriverReviewsModal: React.FC<{ driverId: string, driverName: string, onClose: () => void }> = ({ driverId, driverName, onClose }) => {
  const [reviews, setReviews] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchReviews = async () => {
      try {
        const q = query(
          collection(db, "orders"), 
          where("driverId", "==", driverId), 
          where("status", "==", OrderStatus.DELIVERED_RATED),
          limit(10)
        );
        const snap = await getDocs(q);
        setReviews(snap.docs.map(d => stripFirestore(d.data()) as Order));
      } catch (e) { console.error(e); } finally { setLoading(false); }
    };
    fetchReviews();
  }, [driverId]);

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[12000] flex items-end sm:items-center justify-center p-4 animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-lg rounded-t-[3.5rem] sm:rounded-[4rem] overflow-hidden shadow-2xl flex flex-col max-h-[85vh]">
        <div className="bg-slate-950 p-8 text-white flex justify-between items-center">
          <div className="text-right">
             <h3 className="text-xl font-black">آراء العملاء في الكابتن</h3>
             <p className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest">{driverName}</p>
          </div>
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl hover:bg-white/20 transition-all"><X className="h-5 w-5" /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar bg-slate-50">
          {loading ? (
            <div className="py-20 flex justify-center"><Loader2 className="h-10 w-10 animate-spin text-emerald-500" /></div>
          ) : reviews.length === 0 ? (
            <div className="py-20 text-center text-slate-400 font-bold">لا توجد تقييمات مكتوبة لهذا الكابتن بعد</div>
          ) : (
            reviews.map((rev, idx) => (
              <div key={idx} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-3 animate-in slide-in-from-bottom" style={{ animationDelay: `${idx * 100}ms` }}>
                <div className="flex justify-between items-center">
                   <div className="flex gap-1">
                      {[...Array(5)].map((_, i) => (
                        <Star key={i} className={`h-3 w-3 ${i < (rev.rating || 0) ? 'fill-amber-400 text-amber-400' : 'text-slate-100'}`} />
                      ))}
                   </div>
                   <span className="text-[9px] font-black text-slate-300 uppercase">{new Date(rev.ratedAt || 0).toLocaleDateString('ar-EG')}</span>
                </div>
                <div className="flex gap-3 text-right">
                   <Quote className="h-4 w-4 text-emerald-200 shrink-0" />
                   <p className="text-sm font-bold text-slate-700 leading-relaxed">{rev.feedback || "تقييم بدون تعليق"}</p>
                </div>
              </div>
            ))
          )}
        </div>
        <div className="p-6 bg-white border-t border-slate-100">
           <button onClick={onClose} className="w-full bg-slate-900 text-white py-5 rounded-[2rem] font-black text-sm active:scale-95 transition-all">إغلاق النافذة</button>
        </div>
      </div>
    </div>
  );
};

const PrecisionLocationPicker: React.FC<{
  label: string; helper: string; icon: React.ReactNode; iconBg: string;
  selectedVillage: Village | null; onSelect: (v: Village) => void;
}> = ({ label, helper, icon, iconBg, selectedVillage, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedDistrict, setSelectedDistrict] = useState<District | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const filteredDistricts = MENOFIA_DATA.filter(d => d.name.includes(searchTerm));
  const filteredVillages = selectedDistrict?.villages.filter(v => v.name.includes(searchTerm)) || [];

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2 text-right">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-white border-2 border-slate-100 p-5 rounded-[2.2rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-5 flex-row-reverse text-right">
          <div className="flex flex-col"><span className={`text-lg font-black leading-none ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>{selectedVillage?.name || "اختر المعلم"}</span></div>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl group-active:scale-90 transition-transform`}>
            {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: "h-6 w-6" }) : icon}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[200] max-h-[450px] overflow-hidden flex flex-col animate-in zoom-in duration-300">
          <div className="p-5 border-b border-slate-50 flex flex-col gap-3">
            <div className="flex justify-between items-center px-2">
              <button onClick={() => setIsOpen(false)} className="p-2 text-slate-300 hover:text-slate-500"><X className="h-5 w-5" /></button>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{selectedDistrict ? `معالم مركز ${selectedDistrict.name}` : "اختر المركز أولاً"}</span>
            </div>
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-black outline-none text-right" dir="rtl" placeholder="ابحث..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
            {!selectedDistrict ? (
              <div className="grid grid-cols-1 gap-2">
                {filteredDistricts.map(d => (
                  <button key={d.id} onClick={() => { setSelectedDistrict(d); setSearchTerm(''); }} className="w-full p-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse border border-transparent hover:border-emerald-100">
                    <div className="flex items-center gap-4 flex-row-reverse text-right">
                      <div className="p-2.5 bg-slate-100 rounded-xl text-slate-400"><Building2 className="h-5 w-5" /></div>
                      <span className="font-black text-slate-700">مركز {d.name}</span>
                    </div>
                    <ChevronRight className="h-4 w-4 text-slate-300 rotate-180" />
                  </button>
                ))}
              </div>
            ) : (
              <div className="space-y-2">
                <button onClick={() => setSelectedDistrict(null)} className="w-full p-4 bg-slate-50 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 mb-4"><X className="h-4 w-4" /> تغيير المركز</button>
                {filteredVillages.map(v => (
                  <button key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="w-full p-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse border border-transparent hover:border-emerald-100 text-right">
                    <div className="flex flex-col">
                       <span className="font-bold text-slate-700">{v.name}</span>
                       <span className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">إحداثيات المعلم دقيقة</span>
                    </div>
                    {selectedVillage?.id === v.id && <Check className="h-5 w-5 text-emerald-500" />}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [viewReviewsDriver, setViewReviewsDriver] = useState<{id: string, name: string} | null>(null);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const markersRef = useRef<{pickup: any, dropoff: any}>({pickup: null, dropoff: null});

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        driverPhoto: offer.driverPhoto || null, price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
      const msg = `أهلاً كابتن ${offer.driverName}، أنا العميل بخصوص رحلة "وصـــلــهــا". لقد قبلت عرضك (${offer.price} ج.م). من فضلك شارك موقعك المباشر (Live Location) لسهولة الوصول.`;
      const phone = offer.driverPhone.startsWith('0') ? offer.driverPhone.substring(1) : offer.driverPhone;
      window.open(`https://wa.me/20${phone}?text=${encodeURIComponent(msg)}`, '_blank');
    } catch (e) { alert('فشل قبول العرض'); }
  };

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      const orderData: Partial<Order> = {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_monofia_main', zoneId: 'zone_monofia_main', paymentMethod: 'CASH'
      };
      await addDoc(collection(db, "orders"), orderData);
    } catch (e) { alert('حدث خطأ فني'); } finally { setIsSubmitting(false); }
  };

  const handleFinalizeTrip = async () => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        status: OrderStatus.DELIVERED_RATED,
        rating: rating,
        feedback: feedback.trim(),
        ratedAt: Date.now()
      });
      alert('شكراً لتقييمك! تم إغلاق الطلب بنجاح.');
      setActiveView('NEW');
      setFeedback('');
    } catch (e) { alert('فشل حفظ التقييم'); } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewReviewsDriver && <DriverReviewsModal driverId={viewReviewsDriver.id} driverName={viewReviewsDriver.name} onClose={() => setViewReviewsDriver(null)} />}

      <div ref={mapContainerRef} className={`rh-map-view absolute inset-0 z-0 transition-opacity duration-500 ${activeView === 'MAP' ? 'opacity-100 visible' : 'opacity-0 invisible'}`}></div>

      <div className={`rh-ui-panel no-scrollbar transition-all duration-700 z-[100] ${activeView === 'MAP' ? 'translate-y-[75%] bg-white/95 backdrop-blur-xl' : 'translate-y-0 bg-slate-50'}`}>
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-8 md:p-12 space-y-10 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between text-right">
                 <div>
                    <h2 className="text-4xl font-black text-slate-950 tracking-tighter">مشوار المنوفية الذكي</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">تتبع دقيق للمعالم الحيوية</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl active:scale-90 transition-all shadow-sm"><Bot className="h-8 w-8" /></button>
              </div>

              <div className="space-y-10">
                <div className="grid grid-cols-3 gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <Coffee /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-400 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as React.ReactElement<any>, { className: "h-8 w-8" }) : cat.icon}
                       <span className="text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-6 relative">
                  <PrecisionLocationPicker label="نقطة الانطلاق" helper="مستشفى أو مركز شباب" icon={<MapPin />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                  <div className="absolute right-[45px] top-[100px] bottom-[40px] w-0.5 bg-slate-100 border-r-2 border-dashed z-0"></div>
                  <PrecisionLocationPicker label="وجهة الوصول" helper="المعلم المقابل للوجهة" icon={<Check />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                </div>

                {tripStats && (
                  <div className="bg-slate-950 p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl animate-in zoom-in border-4 border-emerald-500/10">
                    <div className="text-right">
                       <p className="text-[10px] font-black text-emerald-400 uppercase mb-2 tracking-widest">التكلفة التقريبية بالمسافة</p>
                       <h3 className="text-4xl font-black">{tripStats.price} <span className="text-xs opacity-50 uppercase">ج.م</span></h3>
                    </div>
                    <div className="text-left opacity-60">
                       <p className="text-[10px] font-black mb-1">{tripStats.distance} كم</p>
                       <p className="text-[10px] font-black tracking-widest uppercase">تتبع دقيق</p>
                    </div>
                  </div>
                )}

                <div className="space-y-5">
                  <label className="label-strong px-2 block text-right">وسيلة النقل</label>
                  <div className="grid grid-cols-3 gap-4">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v.id as VehicleType)} className={`py-7 rounded-[2.2rem] flex flex-col items-center gap-3 border-2 transition-all ${selectedVehicle === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-slate-100 text-slate-300'}`}>
                        {React.isValidElement(v.icon) ? React.cloneElement(v.icon as React.ReactElement<any>, { className: "h-7 w-7" }) : v.icon}
                        <span className="text-[10px] font-black uppercase">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                   {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin" /> : 'اطلب مشوارك الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-12 text-center">
                   <div className="relative py-10">
                      <div className="absolute inset-0 flex items-center justify-center"><div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div></div>
                      <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block"><Navigation2 className="h-24 w-24 text-emerald-600 animate-pulse" /></div>
                   </div>
                   <h2 className="text-4xl font-black text-slate-950 tracking-tighter">جاري جلب الكباتن...</h2>

                   <div className="space-y-6 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-8 rounded-[3rem] flex flex-col gap-6 border-4 border-slate-50 shadow-xl animate-in slide-in-from-bottom transition-all hover:border-emerald-500">
                           <div className="flex justify-between items-center w-full">
                              <div className="text-center space-y-2 shrink-0">
                                 <p className="text-4xl font-black text-emerald-700">{offer.price} <span className="text-xs opacity-40 font-bold">ج.م</span></p>
                                 <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-2.5 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول العرض</button>
                              </div>

                              <div className="flex items-center gap-5 flex-row-reverse text-right">
                                 <div className="w-20 h-20 bg-slate-900 text-emerald-400 rounded-3xl flex items-center justify-center font-black text-3xl shadow-xl overflow-hidden">
                                   {offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : (offer.driverName || 'ك')[0]}
                                 </div>
                                 <div className="space-y-2">
                                    <p className="font-black text-slate-900 text-2xl">{offer.driverName}</p>
                                    <div className="flex items-center gap-2 text-amber-500 font-black text-sm bg-amber-50 px-4 py-1.5 rounded-full justify-end">
                                      {offer.driverRating} <Star className="h-4 w-4 fill-amber-400" />
                                    </div>
                                 </div>
                              </div>
                           </div>

                           <button 
                             onClick={() => setViewReviewsDriver({ id: offer.driverId, name: offer.driverName })}
                             className="w-full bg-slate-50 text-slate-500 py-4 rounded-[1.8rem] font-black text-xs flex items-center justify-center gap-3 border border-slate-100 hover:bg-emerald-50 hover:text-emerald-600 hover:border-emerald-100 transition-all"
                           >
                              <MessageSquareQuote className="h-5 w-5" /> رؤية آراء العملاء في الكابتن
                           </button>
                        </div>
                      ))}
                   </div>
                   <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-xs uppercase tracking-widest hover:underline">إلغاء الطلب</button>
                </div>
              ) : activeOrder.status === OrderStatus.DELIVERED ? (
                <div className="animate-in zoom-in space-y-8 text-center bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-500/10">
                   <div className="relative inline-block mb-4">
                      <div className="bg-emerald-500 p-8 rounded-full shadow-2xl relative z-10"><PartyPopper className="h-20 w-20 text-white animate-bounce" /></div>
                      <div className="absolute inset-0 bg-emerald-500/20 rounded-full animate-ping scale-150"></div>
                   </div>
                   <div className="space-y-2">
                      <h2 className="text-3xl font-black text-slate-950 tracking-tight">حمداً لله على سلامتك!</h2>
                      <p className="text-slate-400 font-bold">هل وصل {activeOrder.category === 'TAXI' ? 'مشوارك' : 'طلبك'} بنجاح؟</p>
                   </div>

                   <div className="bg-slate-50 p-8 rounded-[3rem] space-y-8">
                      <div className="space-y-4">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">قيم الكابتن {activeOrder.driverName}</p>
                        <div className="flex justify-center gap-3">
                           {[1,2,3,4,5].map(s => (
                             <button key={s} onClick={() => setRating(s)} className="transition-all active:scale-75">
                                <Star className={`h-12 w-12 ${rating >= s ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} />
                             </button>
                           ))}
                        </div>
                      </div>

                      <div className="space-y-3">
                         <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block text-right">اكتب رأيك (اختياري)</label>
                         <textarea 
                           value={feedback} 
                           onChange={e => setFeedback(e.target.value)}
                           placeholder="كيف كانت تجربة المشوار مع الكابتن؟"
                           className="w-full bg-white border-2 border-slate-100 rounded-[2rem] p-6 font-bold text-sm outline-none focus:border-emerald-500 shadow-inner min-h-[120px] text-right"
                           dir="rtl"
                         />
                      </div>
                   </div>

                   <button 
                     onClick={handleFinalizeTrip} 
                     disabled={isSubmitting}
                     className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4"
                   >
                     {isSubmitting ? <Loader2 className="h-8 w-8 animate-spin" /> : <><ThumbsUp className="h-8 w-8" /> تأكيد وإغلاق المشوار</>}
                   </button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-12">
                   <div className="bg-emerald-600 p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                      <div className="text-right">
                         <p className="text-[11px] font-black opacity-60 uppercase mb-2 tracking-[0.2em]">مشوار نشط الآن</p>
                         <h3 className="text-2xl font-black tracking-tight leading-none">الكابتن في طريقه إليك</h3>
                      </div>
                      <div className="bg-white/20 p-5 rounded-full backdrop-blur-xl"><Navigation2 className="h-8 w-8 animate-bounce" /></div>
                   </div>

                   <div className="flex flex-col items-center gap-6">
                      <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                      </div>
                      <div className="text-center">
                         <h4 className="text-3xl font-black text-slate-950 tracking-tighter">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-2 uppercase tracking-widest text-emerald-600 bg-emerald-50 px-6 py-2 rounded-full inline-block">كابتن معتمد</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-5">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                      <button onClick={() => {
                        const msg = `أهلاً كابتن ${activeOrder.driverName}، أنا العميل بخصوص مشوار "وصـــلــهــا"، من فضلك شارك موقعك المباشر.`;
                        const phone = activeOrder.driverPhone?.startsWith('0') ? activeOrder.driverPhone.substring(1) : activeOrder.driverPhone;
                        window.open(`https://wa.me/20${phone}?text=${encodeURIComponent(msg)}`, '_blank');
                      }} className="bg-[#25D366] text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all"><MessageCircle className="h-7 w-7" /> واتساب</button>
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-[0_-20px_50px_rgba(0,0,0,0.12)] flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'خريطة'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 border border-emerald-100 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory, PaymentMethod } from '../types';
import { OrderStatus, VehicleType } from '../types';
import { District, MENOFIA_DATA } from '../config/constants';

// Config
import { DEFAULT_PRICING } from '../config/constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc, getDocs, limit, orderBy
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, ChevronRight, DollarSign, Star,
  User as UserIcon, Map as MapIcon,
  Car, MessageCircle, Loader2,
  Bot, Heart, History,
  Navigation2, Zap, Coffee, Pill,
  PhoneCall, ShieldCheck,
  Plus, X, Building2, MessageSquare, ThumbsUp, PartyPopper,
  Quote
} from 'lucide-react';

// Components
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import WalletView from './WalletView';
import ChatView from '../components/ChatView';
import AIAssistant from '../components/AIAssistant';

// Leaflet Global Access
declare var L: any;

// --- مكون عرض آراء العملاء في الكابتن ---
const DriverReviewsModal: React.FC<{ driverId: string, driverName: string, onClose: () => void }> = ({ driverId, driverName, onClose }) => {
  const [reviews, setReviews] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchReviews = async () => {
      try {
        const q = query(
          collection(db, "orders"), 
          where("driverId", "==", driverId), 
          where("status", "==", OrderStatus.DELIVERED_RATED),
          limit(10)
        );
        const snap = await getDocs(q);
        setReviews(snap.docs.map(d => stripFirestore(d.data()) as Order));
      } catch (e) { console.error(e); } finally { setLoading(false); }
    };
    fetchReviews();
  }, [driverId]);

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[12000] flex items-end sm:items-center justify-center p-4 animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-lg rounded-t-[3.5rem] sm:rounded-[4rem] overflow-hidden shadow-2xl flex flex-col max-h-[85vh]">
        <div className="bg-slate-950 p-8 text-white flex justify-between items-center">
          <div className="text-right">
             <h3 className="text-xl font-black">آراء العملاء في الكابتن</h3>
             <p className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest">{driverName}</p>
          </div>
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl hover:bg-white/20 transition-all"><X className="h-5 w-5" /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar bg-slate-50">
          {loading ? (
            <div className="py-20 flex justify-center"><Loader2 className="h-10 w-10 animate-spin text-emerald-500" /></div>
          ) : reviews.length === 0 ? (
            <div className="py-20 text-center text-slate-400 font-bold">لا توجد تقييمات مكتوبة لهذا الكابتن بعد</div>
          ) : (
            reviews.map((rev, idx) => (
              <div key={idx} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-3 animate-in slide-in-from-bottom" style={{ animationDelay: `${idx * 100}ms` }}>
                <div className="flex justify-between items-center">
                   <div className="flex gap-1">
                      {[...Array(5)].map((_, i) => (
                        <Star key={i} className={`h-3 w-3 ${i < (rev.rating || 0) ? 'fill-amber-400 text-amber-400' : 'text-slate-100'}`} />
                      ))}
                   </div>
                   <span className="text-[9px] font-black text-slate-300 uppercase">{new Date(rev.ratedAt || 0).toLocaleDateString('ar-EG')}</span>
                </div>
                <div className="flex gap-3 text-right">
                   <Quote className="h-4 w-4 text-emerald-200 shrink-0" />
                   <p className="text-sm font-bold text-slate-700 leading-relaxed">{rev.feedback || "تقييم بدون تعليق"}</p>
                </div>
              </div>
            ))
          )}
        </div>
        <div className="p-6 bg-white border-t border-slate-100">
           <button onClick={onClose} className="w-full bg-slate-900 text-white py-5 rounded-[2rem] font-black text-sm active:scale-95 transition-all">إغلاق النافذة</button>
        </div>
      </div>
    </div>
  );
};

const PrecisionLocationPicker: React.FC<{
  label: string; helper: string; icon: React.ReactNode; iconBg: string;
  selectedVillage: Village | null; onSelect: (v: Village) => void;
}> = ({ label, helper, icon, iconBg, selectedVillage, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedDistrict, setSelectedDistrict] = useState<District | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const filteredDistricts = MENOFIA_DATA.filter(d => d.name.includes(searchTerm));
  const filteredVillages = selectedDistrict?.villages.filter(v => v.name.includes(searchTerm)) || [];

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2 text-right">
        <label className="label-strong">{label}</label>
        <span className="helper-text">{helper}</span>
      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-white border-2 border-slate-100 p-5 rounded-[2.2rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm group">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-5 flex-row-reverse text-right">
          <div className="flex flex-col"><span className={`text-lg font-black leading-none ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>{selectedVillage?.name || "اختر المعلم"}</span></div>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl group-active:scale-90 transition-transform`}>
            {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: "h-6 w-6" }) : icon}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[200] max-h-[450px] overflow-hidden flex flex-col animate-in zoom-in duration-300">
          <div className="p-5 border-b border-slate-50 flex flex-col gap-3">
            <div className="flex justify-between items-center px-2">
              <button onClick={() => setIsOpen(false)} className="p-2 text-slate-300 hover:text-slate-500"><X className="h-5 w-5" /></button>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{selectedDistrict ? `معالم مركز ${selectedDistrict.name}` : "اختر المركز أولاً"}</span>
            </div>
            <input autoFocus className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-black outline-none text-right" dir="rtl" placeholder="ابحث..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
            {!selectedDistrict ? (
              <div className="grid grid-cols-1 gap-2">
                {filteredDistricts.map(d => (
                  <button key={d.id} onClick={() => { setSelectedDistrict(d); setSearchTerm(''); }} className="w-full p-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse border border-transparent hover:border-emerald-100">
                    <div className="flex items-center gap-4 flex-row-reverse text-right">
                      <div className="p-2.5 bg-slate-100 rounded-xl text-slate-400"><Building2 className="h-5 w-5" /></div>
                      <span className="font-black text-slate-700">مركز {d.name}</span>
                    </div>
                    <ChevronRight className="h-4 w-4 text-slate-300 rotate-180" />
                  </button>
                ))}
              </div>
            ) : (
              <div className="space-y-2">
                <button onClick={() => setSelectedDistrict(null)} className="w-full p-4 bg-slate-50 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 mb-4"><X className="h-4 w-4" /> تغيير المركز</button>
                {filteredVillages.map(v => (
                  <button key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="w-full p-5 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse border border-transparent hover:border-emerald-100 text-right">
                    <div className="flex flex-col">
                       <span className="font-bold text-slate-700">{v.name}</span>
                       <span className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">إحداثيات المعلم دقيقة</span>
                    </div>
                    {selectedVillage?.id === v.id && <Check className="h-5 w-5 text-emerald-500" />}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('TOKTOK');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [tripStats, setTripStats] = useState<{ distance: number, price: number, time: number } | null>(null);
  const [livePricing, setLivePricing] = useState(DEFAULT_PRICING);
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [viewReviewsDriver, setViewReviewsDriver] = useState<{id: string, name: string} | null>(null);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const markersRef = useRef<{pickup: any, dropoff: any}>({pickup: null, dropoff: null});

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setLivePricing(stripFirestore(snap.data()).pricing || DEFAULT_PRICING);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  useEffect(() => {
    if (pickupVillage && dropoffVillage) {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const mult = livePricing.multipliers?.[selectedVehicle] || 1;
      const price = Math.max(Math.round((livePricing.basePrice + (dist * livePricing.pricePerKm)) * mult), livePricing.minPrice);
      setTripStats({ distance: dist, price, time: Math.round((dist / 25) * 60) + 5 });
    }
  }, [pickupVillage, dropoffVillage, selectedVehicle, livePricing]);

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        driverPhoto: offer.driverPhoto || null, price: offer.price, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
      const msg = `أهلاً كابتن ${offer.driverName}، أنا العميل بخصوص رحلة "وصـــلــهــا". لقد قبلت عرضك (${offer.price} ج.م). من فضلك شارك موقعك المباشر (Live Location) لسهولة الوصول.`;
      const phone = offer.driverPhone.startsWith('0') ? offer.driverPhone.substring(1) : offer.driverPhone;
      window.open(`https://wa.me/20${phone}?text=${encodeURIComponent(msg)}`, '_blank');
    } catch (e) { alert('فشل قبول العرض'); }
  };

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage || !tripStats) return;
    setIsSubmitting(true);
    try {
      const orderData: Partial<Order> = {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        pickup: { address: pickupVillage.name, villageName: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng },
        dropoff: { address: dropoffVillage.name, villageName: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: selectedVehicle,
        price: tripStats.price, distance: tripStats.distance, operatorId: 'op_monofia_main', zoneId: 'zone_monofia_main', paymentMethod: 'CASH'
      };
      await addDoc(collection(db, "orders"), orderData);
    } catch (e) { alert('حدث خطأ فني'); } finally { setIsSubmitting(false); }
  };

  const handleFinalizeTrip = async () => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        status: OrderStatus.DELIVERED_RATED,
        rating: rating,
        feedback: feedback.trim(),
        ratedAt: Date.now()
      });
      alert('شكراً لتقييمك! تم إغلاق الطلب بنجاح.');
      setActiveView('NEW');
      setFeedback('');
    } catch (e) { alert('فشل حفظ التقييم'); } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewReviewsDriver && <DriverReviewsModal driverId={viewReviewsDriver.id} driverName={viewReviewsDriver.name} onClose={() => setViewReviewsDriver(null)} />}

      <div ref={mapContainerRef} className={`rh-map-view absolute inset-0 z-0 transition-opacity duration-500 ${activeView === 'MAP' ? 'opacity-100 visible' : 'opacity-0 invisible'}`}></div>

      <div className={`rh-ui-panel no-scrollbar transition-all duration-700 z-[100] ${activeView === 'MAP' ? 'translate-y-[75%] bg-white/95 backdrop-blur-xl' : 'translate-y-0 bg-slate-50'}`}>
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-8 md:p-12 space-y-10 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between text-right">
                 <div>
                    <h2 className="text-4xl font-black text-slate-950 tracking-tighter">مشوار المنوفية الذكي</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">تتبع دقيق للمعالم الحيوية</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl active:scale-90 transition-all shadow-sm"><Bot className="h-8 w-8" /></button>
              </div>

              <div className="space-y-10">
                <div className="grid grid-cols-3 gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <Coffee /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-400 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as React.ReactElement<any>, { className: "h-8 w-8" }) : cat.icon}
                       <span className="text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
                </div>

                <div className="space-y-6 relative">
                  <PrecisionLocationPicker label="نقطة الانطلاق" helper="مستشفى أو مركز شباب" icon={<MapPin />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                  <div className="absolute right-[45px] top-[100px] bottom-[40px] w-0.5 bg-slate-100 border-r-2 border-dashed z-0"></div>
                  <PrecisionLocationPicker label="وجهة الوصول" helper="المعلم المقابل للوجهة" icon={<Check />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                </div>

                {tripStats && (
                  <div className="bg-slate-950 p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl animate-in zoom-in border-4 border-emerald-500/10">
                    <div className="text-right">
                       <p className="text-[10px] font-black text-emerald-400 uppercase mb-2 tracking-widest">التكلفة التقريبية بالمسافة</p>
                       <h3 className="text-4xl font-black">{tripStats.price} <span className="text-xs opacity-50 uppercase">ج.م</span></h3>
                    </div>
                    <div className="text-left opacity-60">
                       <p className="text-[10px] font-black mb-1">{tripStats.distance} كم</p>
                       <p className="text-[10px] font-black tracking-widest uppercase">تتبع دقيق</p>
                    </div>
                  </div>
                )}

                <div className="space-y-5">
                  <label className="label-strong px-2 block text-right">وسيلة النقل</label>
                  <div className="grid grid-cols-3 gap-4">
                    {[
                      { id: 'TOKTOK', icon: <Zap />, label: 'توكتوك' },
                      { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                      { id: 'CAR', icon: <Car />, label: 'سيارة' }
                    ].map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v.id as VehicleType)} className={`py-7 rounded-[2.2rem] flex flex-col items-center gap-3 border-2 transition-all ${selectedVehicle === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-slate-100 text-slate-300'}`}>
                        {React.isValidElement(v.icon) ? React.cloneElement(v.icon as React.ReactElement<any>, { className: "h-7 w-7" }) : v.icon}
                        <span className="text-[10px] font-black uppercase">{v.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                   {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin" /> : 'اطلب مشوارك الآن'}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 py-4">
              {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                <div className="animate-in zoom-in space-y-12 text-center">
                   <div className="relative py-10">
                      <div className="absolute inset-0 flex items-center justify-center"><div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div></div>
                      <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block"><Navigation2 className="h-24 w-24 text-emerald-600 animate-pulse" /></div>
                   </div>
                   <h2 className="text-4xl font-black text-slate-950 tracking-tighter">جاري جلب الكباتن...</h2>

                   <div className="space-y-6 px-2">
                      {incomingOffers.map(offer => (
                        <div key={offer.id} className="bg-white p-8 rounded-[3rem] flex flex-col gap-6 border-4 border-slate-50 shadow-xl animate-in slide-in-from-bottom transition-all hover:border-emerald-500">
                           <div className="flex justify-between items-center w-full">
                              <div className="text-center space-y-2 shrink-0">
                                 <p className="text-4xl font-black text-emerald-700">{offer.price} <span className="text-xs opacity-40 font-bold">ج.م</span></p>
                                 <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-2.5 rounded-2xl font-black text-xs shadow-lg active:scale-90">قبول العرض</button>
                              </div>

                              <div className="flex items-center gap-5 flex-row-reverse text-right">
                                 <div className="w-20 h-20 bg-slate-900 text-emerald-400 rounded-3xl flex items-center justify-center font-black text-3xl shadow-xl overflow-hidden">
                                   {offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : (offer.driverName || 'ك')[0]}
                                 </div>
                                 <div className="space-y-2">
                                    <p className="font-black text-slate-900 text-2xl">{offer.driverName}</p>
                                    <div className="flex items-center gap-2 text-amber-500 font-black text-sm bg-amber-50 px-4 py-1.5 rounded-full justify-end">
                                      {offer.driverRating} <Star className="h-4 w-4 fill-amber-400" />
                                    </div>
                                 </div>
                              </div>
                           </div>

                           <button 
                             onClick={() => setViewReviewsDriver({ id: offer.driverId, name: offer.driverName })}
                             className="w-full bg-slate-50 text-slate-500 py-4 rounded-[1.8rem] font-black text-xs flex items-center justify-center gap-3 border border-slate-100 hover:bg-emerald-50 hover:text-emerald-600 hover:border-emerald-100 transition-all"
                           >
                              <MessageSquare className="h-5 w-5" /> رؤية آراء العملاء في الكابتن
                           </button>
                        </div>
                      ))}
                   </div>
                   <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-xs uppercase tracking-widest hover:underline">إلغاء الطلب</button>
                </div>
              ) : activeOrder.status === OrderStatus.DELIVERED ? (
                <div className="animate-in zoom-in space-y-8 text-center bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-500/10">
                   <div className="relative inline-block mb-4">
                      <div className="bg-emerald-500 p-8 rounded-full shadow-2xl relative z-10"><PartyPopper className="h-20 w-20 text-white animate-bounce" /></div>
                      <div className="absolute inset-0 bg-emerald-500/20 rounded-full animate-ping scale-150"></div>
                   </div>
                   <div className="space-y-2">
                      <h2 className="text-3xl font-black text-slate-950 tracking-tight">حمداً لله على سلامتك!</h2>
                      <p className="text-slate-400 font-bold">هل وصل {activeOrder.category === 'TAXI' ? 'مشوارك' : 'طلبك'} بنجاح؟</p>
                   </div>

                   <div className="bg-slate-50 p-8 rounded-[3rem] space-y-8">
                      <div className="space-y-4">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">قيم الكابتن {activeOrder.driverName}</p>
                        <div className="flex justify-center gap-3">
                           {[1,2,3,4,5].map(s => (
                             <button key={s} onClick={() => setRating(s)} className="transition-all active:scale-75">
                                <Star className={`h-12 w-12 ${rating >= s ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} />
                             </button>
                           ))}
                        </div>
                      </div>

                      <div className="space-y-3">
                         <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block text-right">اكتب رأيك (اختياري)</label>
                         <textarea 
                           value={feedback} 
                           onChange={e => setFeedback(e.target.value)}
                           placeholder="كيف كانت تجربة المشوار مع الكابتن؟"
                           className="w-full bg-white border-2 border-slate-100 rounded-[2rem] p-6 font-bold text-sm outline-none focus:border-emerald-500 shadow-inner min-h-[120px] text-right"
                           dir="rtl"
                         />
                      </div>
                   </div>

                   <button 
                     onClick={handleFinalizeTrip} 
                     disabled={isSubmitting}
                     className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4"
                   >
                     {isSubmitting ? <Loader2 className="h-8 w-8 animate-spin" /> : <><ThumbsUp className="h-8 w-8" /> تأكيد وإغلاق المشوار</>}
                   </button>
                </div>
              ) : (
                <div className="animate-in zoom-in space-y-12">
                   <div className="bg-emerald-600 p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                      <div className="text-right">
                         <p className="text-[11px] font-black opacity-60 uppercase mb-2 tracking-[0.2em]">مشوار نشط الآن</p>
                         <h3 className="text-2xl font-black tracking-tight leading-none">الكابتن في طريقه إليك</h3>
                      </div>
                      <div className="bg-white/20 p-5 rounded-full backdrop-blur-xl"><Navigation2 className="h-8 w-8 animate-bounce" /></div>
                   </div>

                   <div className="flex flex-col items-center gap-6">
                      <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden">
                        {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                      </div>
                      <div className="text-center">
                         <h4 className="text-3xl font-black text-slate-950 tracking-tighter">{activeOrder.driverName}</h4>
                         <p className="label-strong mt-2 uppercase tracking-widest text-emerald-600 bg-emerald-50 px-6 py-2 rounded-full inline-block">كابتن معتمد</p>
                      </div>
                   </div>

                   <div className="grid grid-cols-2 gap-5">
                      <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                      <button onClick={() => {
                        const msg = `أهلاً كابتن ${activeOrder.driverName}، أنا العميل بخصوص مشوار "وصـــلــهــا"، من فضلك شارك موقعك المباشر.`;
                        const phone = activeOrder.driverPhone?.startsWith('0') ? activeOrder.driverPhone.substring(1) : activeOrder.driverPhone;
                        window.open(`https://wa.me/20${phone}?text=${encodeURIComponent(msg)}`, '_blank');
                      }} className="bg-[#25D366] text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all"><MessageCircle className="h-7 w-7" /> واتساب</button>
                   </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-[0_-20px_50px_rgba(0,0,0,0.12)] flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'خريطة'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 border border-emerald-100 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;
